  (
    title: '谛深大师开示:人有没有来世！',
    date: '2019.2.24',
    body:
        '坐下弟子，及声闻善知识众、声闻知识众、声闻恶知识众：\n'
        '今者有人问请：人之来世有无，是事谛深已有多品讲说，因问者并非佛门中人，是故不懂，今者，为非佛门知识，讲说是品，以解有疑、不信。\n'
        '疑者，所谓疑者，有二种障：一者，不明；二者，不知其否。所谓不明，因未见、未用，不明个由，所以不明！譬如：科学之初，日心说者，因人不明或不信、或诽谤，以至杀真知者！是故，疑者、不信者，当以证明为宜，了却疑与不信，切勿凭乎判断、想象而断真知！\n'
        '不信者，所谓不信，乃愚痴之为，何故是说，因无所证明，即称不信，是称愚痴！譬如：蚂蚁，终日奔忙，与人之车船飞机能代之劳，而说不信！\n'
        '各种知识（善、恶、愚）者，吾谛深不为汝尊，但当告汝等，若己不知，莫断己之慧命，当求证之！\n'
        '各种知识众，吾谛深实告汝等，人之来世，实则有之，汝等当求证之！吾问汝等如下问题，汝等可参：1、植物如何诞生者？2、动物如何诞生者？3、动植物有何根本差别之本？4、何故诸多动物以植物为食？5、何故有动物以动物为食？6、各种生命起源之科学之说当否？7、譬如：进化过程，若人为进化之物，曰：一次性进化完了，还是不断地在进化？若一次性进化完了，世界应当无猴，何故有猴？若，不断进化，世界上当不断有大新闻，时有猴变之人下山为人！若进化慢哉，当今世界当有诸多人，半猴半人，否？基因工程已然证明，人之基因与猴有巨大差别，是者说明，人非猴慢变所成！若人乃基因突变所成，然者，一次突变一群尚有可能繁衍后代，然，猛禽走兽，狂奔世界，即使突变，人亦难存！等等！\n'
        '是故，若人非进化之物、若众生生处汝等不定，当知，有知众生来处者，汝等当求之而知！\n'
        '各位知识，吾谛深不假演说，汝等当认真仔细考究，获得所需！谛深为何不于是中说转世轮回，因汝等不信，是故不说！\n'
        '汝等，当善思维而后有得！得而未彻者可求吾谛深为汝等讲说转世！\n'
        '善知识，勿以想象为问者解，亦勿以推测、推理为问者解，当以实证为问者解！ 谛深2019、2、24，应弟子问！',
  ),
  (
    title: '谛深大师开示:修行不是条条大路通罗马',
    date: '2018.10.24',
    body:
        '坐下弟子及声闻善知识众：有披吾佛衣，假为佛门者，以自相为之，以譬如登山可从各个角度、各个道路登至顶峰为说，圆其邪道，成就魔群，是坏佛法说。\n'
        '善知识，无量众生，因各个因缘有别，故，修行所需段时有别；修行段时有别，故，其同时修行之法有别，如是同时较之法门有别，而总括较之法之完全无别，是故，佛法有种种果位，位之有别，并非其路有别。种果位，位之有别，并非其路有别。\n'
        '譬如：有人堕落于旁生之道，身为蝼蚁，其当于蝼蚁身修出蝼蚁道，后于蚂蚱身修出蚂蚱道，直至成人、成天人、成法王、成佛。如是，称其修法、亦称其门。由于时段有别，八万四千，故称八万四千法门，又因一门，故称八万四千法门终归一门，一门超出菩提路。\n'
        '善知识，若如邪魔外道说，条条大路通罗马，所有之路皆可及峰，则可十方众生之，种种为，皆成佛道！如是，何来佛道、魔道、邪道、善道、恶道之别？汝等何之学佛？如之学佛者，痴也！\n'
        '善知识，汝等当有知、有智，莫入魔塔，遭魔所缚，皈依佛陀，以己之因，确定修法！\n'
        '善知识，五百罗汉，于五百外道共证十地，虽皆十地，亦有差别，故，释迦牟尼佛楞严海会批注，果位无二，然其通各个！是故，不能直证佛果，是称大阿罗汉！\n'
        '善知识，当如是知、如是解八万四千法门！\n'
        '谛深2018-10-24',
  ),
  (
    title: '谛深大师开示:修行要关相说',
    date: '2018.10.24',
    body:
        '坐下弟子及声闻善知识，所谓因地、果地修行内涵谛深已说，今再说因地果地之相。\n'
        '善知识，因地之相，为受法被悲。于因地时，当悉心皈依佛陀导师，逐级受佛陀慈悲甘露，获得功德成种，所谓：出离功德、护法功德、为佛弘名功德、智慧功德，如是等功德成就来世梯次种报，修至十地于佛坐下获得开悟。\n'
        '善知识，开悟之后称为果地修行！果地修行为施法慈悲布施，有令众生信种种率众修行之德相。观世音菩萨慈悲住世，为祛尘累，清净庄严累劫修持，即是其表！\n'
        '善知识，修行之相如是，汝等当如是知，莫于因地行果地行，若于因地行果地道，即落魔障，成堕落种。善知识当知，十方众生皆因是行成众生相。切记谛深之说。谛深2018、10、24日应弟子缘！',
  ),
  (
    title: '谛深大师开示:不是什么人都可以称为“和尚”和“僧人”、“出家人”',
    date: '2018.9.1',
    body:
        '坐下弟子及声闻善知识众：何为“和尚”、何为“僧人”，吾已有说，不再为说。坐下弟子及声闻善知识众：何为“和尚”、何为“僧人”，吾已有说，不再为说。\n'
        '然，末世社会、末世广众，依然“以貌取之、以衣取之、以名取之、以寺庙取之、以鬼神祟取之、以为取之”。并言而“粉”，传以导轨，善说恶应，自取堕落！\n'
        '善知识，有佛住世以佛为师，佛灭度后以戒为师。是者僧耳，更之和尚。\n'
        '熟以众传名而也，匡己惑众，断灭、诽谤、凌辱佛菩萨者，世灭重罪。谛深入涅槃始，500载后，始，逐岁有别，旦之恶入灭，众合随灭，六岛延息水泛世终小劫尽，能出离者归。\n'
        '善知识，吾谛深以是警娑婆罪众，勿重罪灭佛、佯佛，却狂以为智为能为延明色业为！\n'
        '\n'
        '谛深2018，9，1示。',
  ),
  (
    title: '师父给朱XX居士的一封信',
    date: '2018.4.10',
    body:
        '朱XX居士收悉：\n'
        '听弟子说了你的事情，我很高兴！\n'
        '第一，你从重病中康复到能处理自己的事情了，这个是作为和尚的我所要的！\n'
        '第二，你为未来养老做准备，索要原供养款项，听起来不好听，但是，佛门本来就是给大众准备本世、来世资粮的，你自己准备养老，为我这个和尚减轻了承事负担，对我来说是一种享受！\n'
        '当然，里面可能是不信任主导，即使是不信任，也是因为现在的佛门令人信任的出家人太少了，这完全怪不了你！\n'
        '朱居士，关于我的在家弟子给你办退款手续时的情绪，我没怪罪他们，因为他们是在家修行，目前存在一些问题是正常的，需要慢慢的来！你也一样，如果你给真正的佛门办事，也会出现种种问题，所以，希望你理解他们！\n'
        '最后，师父告诉你，佛法是真实的，一般人无从知晓，我这里和寺院里一分钱不许进！\n'
        '出家人不沾钱，所有供阿弥陀佛！谛深令在家弟子转！2018，4，10日按缘！养都有在家大居士依据寺院规定管理，希望你理解我为什么不收你的供养，你如果想供养，可以继续在其他寺院供养结缘！\n'
        '阿弥陀佛！谛深令在家弟子转！2018，4，10日按缘！',
  ),
  (
    title: '谛深大师开示:智慧供养应当学',
    date: '2018.4.2',
    body:
        '坐下弟子及声闻善知识众，如来无上尊，教汝等获智，无智无以修！修之大根本，供养称之为！\n'
        '是故，释迦牟尼传法，文殊普贤而为上首，又称菩萨首！\n'
        '善知识，供养如来，智慧为道！譬如：有人欲供如来，却供了波旬，落入魔道，无智因者！\n'
        '善知识，无始劫来，无量佛出世，何至今者依然云云众生，罪苦轮回，皆因：十方一粒米，大如须弥山，吃了不了道，披毛带角还所致；皆因：十方债主怨，回报如火山，本来一粒米，却预万劫难所致，如是成就无始劫、无终难！如是有邪魔外道盛行！\n'
        '是是故善知识，应做当供，切勿做不当供，切勿受不当供！\n'
        '善知识，若欲供吾谛深、供妙湛寺建设，当如是知晓并做当供！\n'
        '谛深2018，4，2应弟子问！',
  ),
