  (
    title: '谛深大师开示:大众当共修（第二品）',
    date: '2018.3.13',
    body:
        '坐下弟子及声闻善知识众，汝等实修实证方能不负佛愿，所谓闻不负、解不负、修不负、破魔障不负、破魔咒不负、证不负至出离罪苦不负！\n'
        '善知识，佛说毗尼戒律汝信受，佛说禅那了脱汝信受，佛说念佛汝信受，佛说咒禁汝信受，佛说三藏十二部等等法汝信受，称为闻不负、解不负；\n'
        '善知识，若非佛说毗尼戒律汝信受、非佛说禅那了脱汝信受、非佛说念佛汝信受、非佛说咒禁汝信受，称为闻负、解负之邪染得！\n'
        '善知识，若汝等不负信解，依所信解修证，证得佛说毗尼戒律、证得清净法身、圆满报身、千百亿化身称为修不负、破魔障不负、破魔咒不负！如是称佛法正道！\n'
        '若有人、有众持戒遭恶称汝之所修乃邪魔道；若有人、有众念佛名号遭恶称汝之所修乃邪魔道；若有人、有众参禅遭恶称汝之所修乃邪魔道；若有人、有众诵咒、持咒、三观六印、诵经抄经遭恶称汝之所修乃邪魔道法！咒、三观六印、诵经抄经遭恶称汝之所修乃邪魔道法！\n'
        '善知识，汝等当知，佛法不思议，修之必离苦，不受丁点恶，如若戒不净，当受应之报！\n'
        '善知识，当如是知修行、修行、修！谛深2018，3，13示！',
  ),
  (
    title: '谛深大师开示:大众当共修！',
    date: '2018.3.12',
    body:
        '坐下弟子及声闻善知识众，汝等于群中听法，虽心得必然，却少有证！是乃修行大忌！\n'
        '何故是说？一切邪魔外道皆以是因缘，候其方便，飞精附体，口说经法，令众堕落！\n'
        '善知识，一切佛法皆实证门，故诸佛世尊，皆警告大众，凡有言说，皆无实义！\n'
        '善知识，吾谛深所说，皆实证说与，为令大众亦获实证！\n'
        '善知识，是故汝等当以吾说、诸佛世尊说为导，修之、证之，成佛之道！\n'
        '善知识，譬如：有大学教授授汝造车乘之法，汝若只知其道，而不为其道，汝所得法称为妄，汝所学之功，耗费汝生而废自命！\n'
        '是故，谛深号令弟子，结成道群，依法修行，获得道果！\n'
        '汝等如若不能依为师所说，修得所说，以听为实得，则获妄法而不得佛说！ 善知识，十方诸佛，皆视是等，以知说为得之学、之修道者为愚痴辈！\n'
        '善知识，实修实证法，可破十方天魔，可护十方诸佛！\n'
        '是故，汝等当以是说应之！\n'
        '善知识，如若求成佛，修而得之；如若求入十地，修而得之；汝若求无病，修而得之；汝若求极乐，修而得之；汝若求所应，修而得之，汝若求神通，修而得之；汝若求禅那，修而得之；汝若求了脱，修而得之；等等！\n'
        '善知识，汝等当依吾所说行于道！勿以吾所说行于说！\n'
        '谛深2018，3，12示！',
  ),
  (
    title: '谛深大师开示:如何不落佛门外道！',
    date: '2017.12.18',
    body:
        '智觉：修行入道师父有很多开示，你当悉心阅受！\n'
        '其所获境界与神通，乃业障所显，勿以是为得！\n'
        '智觉，佛法因地入门有三渐次，一者信 ，二者愿，三者行！\n'
        '所谓信者，乃生信之做，包括：因缘结合、佛菩萨施救、自己如说修行获得当证！以是因令信心从无到有，再到满、十足！生信之后，便要进入求道梯次，如果始终停在生信所得，即落魔道，是故，十方诸佛，皆以生信法，结成经典，令之因地起道，并皆呵弟子，莫着法相；n'
        '智觉，愿，分三等。一者，因地信心中发，成妄为愿！二者修道得道之后发道行愿！三者成就之后由清净心发慈悲愿！前两等愿，成就八十四种佛门外道！清净愿力成就无量佛种十地菩萨道！\n'
        '智觉，愿力之后，即入佛门行道，所谓因地行，道成地行，果位地行，是称修行！是三种修行前两种直成八十四种佛门外道！果位地修行成就诸多佛门果位！\n'
        '智觉，汝替声闻问是问，当令之皈依后，入戒律门获禅悦修行法，才能令其不落佛门外道！\n'
        '智觉，以是回复令其未来解脱！\n'
        '谛深2017.12.18日应弟子群中声闻问！',
  ),
  (
    title: '谛深大师开示:怎样得消灾！',
    date: '2017.10.22',
    body:
        '坐下弟子及声闻善知识众：\n'
        '所谓灾难，种类繁多！大分：横灾、病灾、命灾！由是成生老病死苦！\n'
        '善知识，所谓横灾乃体外力为，若无外力，不成横灾！所谓病灾，体内逆因为之，若无逆因不成病灾！所谓命灾，过程颤变，譬如：化学反应，要素集成，过程忽变，是为前所有物之命灾！众生命灾亦复如是！\n'
        '善知识，横灾皆自诽谤贤圣，或谤自因！所谓自因，乃指本体缘分！病灾皆自做道成，即：自作自受之道！所谓命灾成自缘分！\n'
        '善知识，十方众生因不入佛道故，或入假佛名号道故，遭诸横侵！是故欲求无横当皈依佛陀！\n'
        '善知识，若有人皈依假佛名号之道，诸横相随！\n'
        '善知识，谛深实言告汝等，若求消灾降福，勿入邪道，因其皆称佛法，难于鉴别，若未开悟，以戒判之！譬如：有恶僧称不沾金钱，却告之汝，发心捐助寺院，是乃邪魔罪子，知吾光耀，假佛戒名，骗取钱财！其等必遭大横！\n'
        '善知识，当如是消灾！谛深2017，10，22日应声闻问！',
  ),
  (
    title: '谛深大师开示:如何供佛!',
    date: '2017.8.30',
    body:
        '坐下弟子及声闻善知识众：供佛师父已讲说多轮，今者，声闻以欲以燃身供养问，故再为讲说一品！\n'
        '善知识，供养分多种层次，乃修行舍业舍罪之法，非一时之兴！汝等连己之少分尚不能供，说以身供养是为欺佛！\n'
        '善知识，若汝有万贯，持一钱供我，是称汝有亿分之一心舍罪，其余皆罪，汝说真心，是等幼儿笑汝！\n'
        '善知识，若佛建寺，大众合力建之，是称以身力舍罪供我，汝只以少许时、少许力为之，是称万分之一舍罪，余者皆罪！若汝如是做，却说全心、真心供养，傻儿笑汝！称汝愚痴！\n'
        '善知识，若汝等有业有罪，舍一分供佛，再不为供，不说自己功德，是称善种！若继而供之，不狂说自己修行、自己功德，称罪舍一分、善长一分，又称修行！\n'
        '善知识，当如是供养！\n'
        '谛深2017，8，30应声闻问！',
  ),
  (
    title: '谛深大师开示:关于物种灭绝',
    date: '2017，7，6',
    body:
        '座下弟子及声闻善知识众：世界到底有没有灭绝的时候？这个师父已经在劫难品中讲说多轮，今天，因有人提转基因食品安全问题故，师父再为你们以白话讲说一品！\n'
        '善知识，娑婆世界转基因与基因突变问题中：基因突变的诱因很多，转基因引发基因突变、衰变、亢变应该是生物学中物种变化的必然课题！所谓物种变化，包括物种变异与物种灭绝！\n'
        '善知识，娑婆世界物种灭绝不仅仅是生物链的破坏才会发生，一些特定因素为前提的量变导致未来质变，也一样会令物种灭绝！\n'
        '善知识，以凡夫科学眼观世界，其所能知晓的量变导致质变引起的物种灭绝尤为可怕，因为：对凡夫俗子来说，没人知道这种灭绝方式，会不会摊到人类头上！但是，我告诉你们，即使没有转基因，这种灭绝方式一样会摊到人类头上！记住，佛是实语者、不异语者、不妄语者！佛法真实不虚！\n'
        '善知识，导致娑婆世界物种量变引发质变而灭绝的因素，诸佛慈悲故，早已以种种方便，告诸大众！佛法入门的基础教程就是了脱生死，而生死，就包括物种的生灭！当然也包括世界的生灭！\n'
        '善知识，世界本自虚妄，师父为慈悲大众故，多轮讲说生灭法，为令汝等开悟！希望你们精进勇猛早出苦海，逃出生死险途！谛深2017，7，6示',
  ),
  (
    title: '谛深大师开示:如何为僧',
    date: '2017.6.1',
    body:
        '坐下弟子及声闻善知识，一切僧人皆以戒律考之为僧之道！为僧之道又有无量因缘法随其道缘！\n'
        '是故，为僧者不说僧之作，是为智者；若说僧之作，如何做，乃为罪者！为僧者知有僧破佛律仪，广传邪说而不说者，称为愚者；破斥邪说称为道者、亦称勇猛护法者、亦慈悲喜舍者！\n'
        '善知识，当如是为僧！\n'
        '谛深2017，6，1示！',
  ),
  (
    title: '谛深大师开示:世界在变，戒律是否也应该变？',
    date: '2017.5.31',
    body:
        '坐下弟子及声闻善知识众，今者有弟子因某比丘说是当者故，师父为汝等讲说！\n'
        '善知识，譬如：人生由幼变老、由贫变富、由小变大、由常变病、由病变康，等等等等人之不自主之变，汝之观人性变否，而汝之观性亦未有变，善者当知，人性无有变与不变！即使人类灭绝，人性不会有变！因若非人性其必非人！\n'
        '又譬如：人类社会种种发明之变，乃至电脑造人，等等玩物，人之难比，数字计算胜人之学，医学治病，大变世界，如是等等！是等虽变，设计电脑之本之图纸有变否？是等之变能变人之不造之变否？人若不造是等变物，其如何变？\n'
        '善知识，佛之戒律亦复如是！虽世界恒变，佛门戒律不之为变！是故，是种罪子，以世界有变说戒律当变，是等罪人乃于佛法修持盲修瞎炼故不知佛之戒律之本，于是以妄知见解析戒律恰似指鹿为马令自己以鹿称马丢失马本之者丢失戒律！因丢失戒律故，愚昧为智因大众钦仰佛法故诓骗大众，自求堕落成大罪恶！\n'
        '善知识，世界本自虚妄，五缊自转，世界恒变，而清净不变！清净不变，戒律不变！是故，佛门由古及今修持之道，戒定慧表，由戒生定、由定生慧，是称行定！\n'
        '谛深2017，5，31日示！',
  ),
  (
    title: '谛深大师开示:如何判断祸福来临！',
    date: '2017.5.17',
    body:
        '坐下弟子及声闻善知识众：是问并非佛门人当问，其乃邪道为之障问！\n'
        '善知识，何故是说？因如是福祸之道，实乃世间罪孽法道！譬如：大众所求之福，是何物者？\n'
        '何为世间之福？世间之福，无非所求即有，物品丰富，鱼肉荤腥皆充其食，呼风唤雨，官位亨达随心所欲，妻妾儿女各有所得，杀盗淫妄皆为所用，等等！\n'
        '是等凡夫之福，汝细观之，所求即有之物来之何处？必有奉献者，相对奉献者是为失去，名之为罪，若汝问吾如何判断祸福来临，汝之福者，别人之苦！别人之福，汝等之苦，如是判断！又如：有人见一女子姿色甚佳，追之即获，是为有福，是女实则有夫之妇，其夫为祸！又如大众食鱼肉谓之有福，被食之物视之为祸！又如汝驱车狂奔狂心获慰，被汝车伤亡者谓之为祸！又如有人入路遭塌方死伤谓之为祸，塌方之地实则鬼神为之，鬼神称福，反之亦然！如是判断福祸来临！\n'
        '汝之如是之问，谓之有罪，谓之愚痴，当行忏悔！恰如忏悔有狼问汝如何判断吃人时人是否带有枪支，我当如何防范、如何食之！\n'
        '大众当知，五浊恶世福祸一契，是故十方如来皆视六道称之恶世！是故，修学佛法当修出离！是故，汝等是问谓之有罪！谛深2017，5，17应有罪弟子代群中声闻问！',
  ),
  (
    title: '谛深大师开示:什么是有业障',
    date: '2017.4.28',
    body:
        '坐下弟子及声闻善知识众，所谓佛门业障泛指障碍、究竟无成虚妄毕竟有世界，之种种阻碍、妨碍、牵扯、牵挂、疑惑、愚昧、道理、理性、模式等等诸端碍旨所做！是等碍旨依业做而立故称业障！譬如遇诸等罪障即是！'
        '善知识，朴素 善知识，朴素 障碍指一切认知障阻碍：即六根所造六尘之眼障阻碍、耳障阻碍、舌障阻碍、身障阻碍、意障阻碍等！\n'
        '善知识，所谓道行慈悲大众之修行障碍，无量无边无数，需依佛依律乃能究尽知觉决了，或无始劫因缘果报禅那知觉自行稀有决了！是称修行业障知晓！\n'
        '是故，善知识，种种业障显现之处，恰汝修行当下关口进退，不进必退遭堕！\n'
        '善知识，是所谓佛门所说有业障！谛深2017、4、28日应弟子智虚因遭业障问！',
  ),
  (
    title: '谛深大师开示:佛门如何看有罪',
    date: '2017.4.26',
    body:
        '坐下弟子及声闻善知识，关于什么是罪，师父已说，今者因有罪者求师父施救故，再为汝等讲说什么是有罪！\n'
        '善知识，譬如有人被骗浑然不知，别人劝解，其不自省，反而恶语相向，是称受罪；譬如有人被打被骂，是称受罪；譬如有人病中呻吟是称受罪；譬如有人所求不应是称受罪；譬如有人备受欺凌是称受罪，如是等等。人受罪时称为有罪，何为人受罪时？人于受罪中不知觉醒，称为人受罪时，称为有罪。\n'
        '善知识，若人有罪不能信佛，只能因罪求佛，是故，佛陀住世善导大众，出离罪苦；是故，佛陀住世引导大众，入出离罪苦法。\n'
        '善知识，所谓引导大众入出离罪苦法，需为大众示现智慧，令大众步步有证，方能解除大众疑惑之罪；令大众入出离罪苦法。若有人说能令大众出离罪苦，或复有人设法设道，令大众入，称能出离罪苦，而大众实不能步步有证出离罪苦，则是说法人或设道人，称为魔王或邪道王。\n'
        '善知识，若有罪人入魔法邪道法，以是为道以是为修，以是称证，以是称圣，更甚有人以是称为佛法。如是人等，称有重罪，累劫难救。\n'
        '善知识，如是信解何为有罪。\n'
        '谛深2017.4.26示',
  ),
  (
    title: '谛深大师开示:求佛菩萨无需花钱',
    date: '2017.4.17',
    body:
        '坐下弟子及声闻善知识，求师父者本自罪苦，钱为其命，若无金钱，无以为生。师父住世，因缘所成，无缘不住，有求必应。因缘不具，钱财无用。一钵一餐，随处可化。若求师父，修行是应，我得轻松，你获福报，如是方便，汝当给予，切勿见我，金钱供奉。\n'
        '善知识，切勿遇急事难事跑来见我，发心修行，为我所期。谛深2017、4、17日为求师父者示！',
  ),
  (
    title: '谛深大师开示:如何求师父',
    date: '2017.4.17',
    body:
        '坐下弟子及声闻善知识众，今者吾弟子告知师父云，有声闻因之不信佛丈夫得癌症故，欲见师父，求师父设救！\n'
        '善知识，求师父治病，目的是治病，在家里求即可！如果在家里求无用，说明师父无此神力治病救人，你求他做甚？如果师父有此神力治病救人，汝之目的乃为求治又何须见他？关于如何在家求师父，师父已说，不再为述！\n'
        '善知识，若汝等信佛，求师父，即刻为应，若不信佛，第一次求师父，即为获应，获应当发心，发心皈依佛！若不发心，因罪孽深重故，必再遭报，遭报再求，少许获应！第三次不为之应！\n'
        '善知识，切勿获救后不发心修行，再行业为恶为，受大罪苦，无以为救！汝等当入解脱法，离开罪业！\n'
        '谛深2017、4、17应弟子问！',
  ),
  (
    title: '谛深大师开示:做一个真正的佛门人',
    date: '2017.4.6',
    body:
        '座下弟子及声闻善知识，关于修行师父已讲多轮，因诸多初受佛法者不解不能解释佛法故，今再为汝等讲说！\n'
        '善知识，譬如：指鹿为马，马必不存！因鹿乃马也，马名指鹿，马自不存！佛法错解讲说亦复如是，于凡夫所说称为佛法，佛法即失，由此不存！以是意故，凡非佛亲口所说，汝称佛法，实则邪道！是种法者，今震旦皆是，故震旦佛法已灭！是故，汝之所听受之佛法之佛道，并非佛法、亦非佛道！\n'
        '善知识，吾谛深所说并非佛法，非不佛法，未得者，因并非佛法故获得实惠，不遭堕落；得之者因非不佛法故获当果位入出离道！\n'
        '善知识，入得佛门，最少为求福报乃至更高！切勿未证谓证、未得谓得自入魔道遭大幻术！\n'
        '谛深2017、4、6日示',
  ),
  (
    title: '谛深大师开示:修行差别与佛号差别',
    date: '2017.3.19',
    body:
        '座下弟子及声闻善知识，所谓佛门修行，是指获得离苦得乐、出离六道智慧之！因种种道，包括：大众所称之邪道、外道、虚妄之道等等，亦需修行方能获得所成，是故，师父于修行之前加佛门二字，以令佛弟子、法弟子、吾和尚弟子声闻求道，闻无杂遑而精，阅不杂遑而精，修不杂遑而精，证不杂遑而精。\n'
        '善知识，所谓修行差别，有因差别，缘差别，果差别，报差别成层差别、道差别、无量无边无数之无一同之不同差别！\n'
        '善知识，所谓层差别，譬如大学中学小学之差别，所谓道差别譬如学校与工厂之别称为道差别。所谓无一同之不同差别，譬如大学之中之种种差别，科目差别，专业差别，分数差别:每个学生之间性格差别称无一同之不同差别。:每个学生之间性格差别称无一同之不同差别。\n'
        '善知识，佛门修行差别，因层差别成不同果位界，因道差别成不同门派界，因无一同之不同差别成不同修为行简称修行界！\n'
        '善知识，佛门修行差别如是成无量无边无数之佛门名号差别、佛之名号差别！\n'
        '善知识因修行差别故，大众不当因不同宗、不同门相互议论、相互诽谤、相互戏说、相互学习等，应因因缘缠缚，以修行之互相缘处为助，而相互议论、相互诽谤、相互戏说、相互学习！\n'
        '善知识，修行差别是五浊恶世之浊，是为不说同参道友过戒之根，大众应当持！谛深2017，3，19示',
  ),
  (
    title: '谛深大师开示:师父为什么不让弟子说邪魔外道过',
    date: '2017.3.3',
    body:
        '坐下弟子及声闻善知识众：佛门之邪魔外道是指：未证谓证、未得谓得之以佛法为名，广说自己种种知见、或以种种罪孽之心为名为利利用佛法威德行种种非佛戒律所允之道！佛门之外所有道，亦或有被尘世中人以是否符合相关个人、相关群体、相关宗教、相关政体利益而称为邪魔外道！\n'
        '善知识，我不允许弟子说佛门邪魔外道过，譬如：苍蝇落到汝之脸上，行种种脏事，汝随可轻打轻柔弗之令其离开，实则亦或多或少有伤于己！重击必重伤自己，只可用法回避或令飞之再做处之！\n'
        '善知识，佛门之中假佛名号诓骗大众之邪魔外道、如假法华经、楞严经、无量寿经等等广兴罪说之人；假观音文殊普贤乃至毗卢遮那佛、阿弥陀佛、释迦牟尼佛等等之人者，皆如佛面之苍蝇，不能评判，若评判必伤佛法！是故师父不允许弟子说佛门之邪魔外道过！\n'
        '善知识，非佛门内之邪魔外道，亦不能说，因其等道罪孽深重，若说即遭恶染，其等必在受罪不能忍耐之时，四处求救，求之佛门再行救度！是故，亦不能说其过！\n'
        '善知识，是故做吾弟子不说邪魔外道过，亦不说众生过！师父所说其等罪孽深重，是其报相，不是过！\n'
        '善知识，汝等入得佛门为求离苦，不当说邪魔外道过！但当以是为警精进勇猛持戒修行！\n'
        '谛深2017，3，3应弟子问！',
  ),
  (
    title: '谛深大师开示:魔子魔孙是如何成就的',
    date: '2017.3.2',
    body:
        '坐下弟子及声闻善知识众：我说魔道，是指佛门障碍道，若不为障碍，不成魔道！所谓佛门障碍之道，是指有法能令人以为是，而入道成就魔道！\n'
        '善知识，一切法皆因法相故，能成魔道！是故，不应着法相；因非法相自本为障碍，是故不应着非法相！是故，善知识，若有人自不明了，与人示法，其本于法中依法广说，是人则为波旬之身！如是成就魔王之身！若有人知法神奇、于中获法，以法为得，广示于人，法成障碍，是人乃成就法王波旬身！若有人能入人所说法并广为演说，是人成就魔子魔孙身！若有人入种种法，为法征服，以法为道，结缘修行，则是人、是道中众人成就魔民身！\n'
        '善知识，佛法乃令入道中人以是为用出离罪苦，非以是为得，若以是为得即乃以法为得！\n'
        '善知识，譬如以手示月，手乃法器，若以手为获、以手指示为得者，指月双丢 ！以法为道宏范三界者，乃魔道为！以法为用令众出离罪苦称为佛法！\n'
        '善知识，譬如船为舟乘，渡众往去彼岸！如何架舟行，讲说为令知，知之即可行，到岸成获得，是称为讲说；若有重罪人，以说为佛法，大罪成堕落！\n'
        '善知识，若于当世、来世有人未得开悟，以法为道，令众有证，广为传播，当知是人乃魔子孙！若复有人，狂妄自大，巧舌如簧，假佛名号，令众皈依，是人乃邪魔为！\n'
        '善知识，佛制戒律无理无据能令大众不堕法相、不落非法相、不落虚妄相直入佛座下，获得出离法直接行出离，是故我说戒乃真为佛法！佛说诸经典乃为用中物，只为当机用！是故不当着！\n'
        '善知识，汝等当以戒选师！切勿以种种法选师！谛深2017，3，2应声闻问！',
  ),
  (
    title: '谛深大师开示:如何解心',
    date: '2017.2.2',
    body:
        '坐下弟子及声闻善知识众，所谓心者八识体相，所谓体者乃缘正妄动之界形！所谓相者，形体之界！\n'
        '善知识，妄动八识乃造众生形体之本，无动无众生体相！譬如：众生死后尸体，妄识不存，不成其物！又如植物人识之难用，虽有其体，无能成人！\n'
        '善知识，传说中之人之灵魂实则不存，见鬼神之者，有少许为识之遭刺激变相，实则并非鬼神！多为识心堕落变异，与鬼神识相有同见之！鬼神因杀斗成识，罪孽深重，若无其相通识相，不能见之！\n'
        '善知识，当如是解心！\n'
        '2017，2，2日示！',
  ),
  (
    title: '谛深大师开示:什么是化缘',
    date: '2017.1.18',
    body:
        '坐下弟子及声闻善知识，关于化缘师父已说，因诸多相出家、在家道人 不知、不明、妄解、妄传故，今再为说之！\n'
        '善知识，所谓化缘乃指：以如来广大慈悲身、福报身为依，以众生本具善软为机，令如是机合而启成因缘种子，令是中众生得度之体相用相！简言之，就是将如法施舍变成佛门缘分称为化缘！譬如小河沟虽有少许水湾，但不能形成大水浇灌良田，长江大水滔滔，以长江为依令开凿渠道与之小沟相连，使小沟永久有水灌溉良田！托钵化缘即开凿渠道者是；众生即小沟者是；如来即江河湖泊大海者是！\n'
        '善知识，是故化缘乃结缘之法！能因众生一丝善心得佛陀无量大福！是故佛门称布施为种福田，称供养为种道田！\n'
        '善知识，普通大众之间慈善捐助、救助，称结缘来世，不能得更多福，但可获来世相应善报！\n'
        '善知识，若复有人以鱼肉荤腥施予化缘僧，是人行为为侮辱佛法罪，是做称种苦田！\n'
        '是故善知识，应知佛门化缘意，广种福田造就因缘早获解脱！谛深2017，1，18日应声闻问！',
  ),
  (
    title: '谛深大师开示:如何解福慧双修',
    date: '2017.1.11',
    body:
        '座下弟子及声闻善知识，所谓福慧乃组合、偏正双性词用，譬如体相一词，亦为组合、偏正双性词用！\n'
        '善知识，福与慧本自智者派生无智不福，有福之者体相所表之语言行为被趣者观“纳而称道“称之为慧；所谓福者乃指欢喜兴致之本，譬如有一群人饥饿难耐四处寻食，一人寻得兴高采烈，余者叹而称得者有福；而是者所得食物若被人强制令某已吃饱至不能下咽者强食之，是食者称之为罪！\n'
        '是故，善知识，若不令欢喜之得、之物、之一切不称为福！不能令得福之一切说一切做不称为智！无福之一切相说不称为慧！是故没有智慧福报不存！\n'
        '善知识，佛法本自所得智慧者因慈悲，教皈依者出离罪苦，即获无量福故称慈悲主、无上师、佛、世尊；入佛门者即为得福得慧，是故，诸佛世尊不说福慧双修！乃至正修行者不说福慧双修！\n'
        '善知识， 善知识， 所谓福慧双修者来自：以福为福、以慧为慧，不知福慧一契不能割离之非佛法正传体之佛法末世之修道说！譬如世间凡夫见有人吃喝玩乐、或财源滚滚、或权势招摇、或有求即得称之为福，入佛门求之，实则是诸凡夫所称福者并不一定为真福者，若非佛门之付并非福报！\n'
        '善知识，汝等来问如何福慧双修，当知汝等所修之法并非释迦佛传，亦非吾谛深传！\n'
        '善知识，入得吾门当皈依佛，以佛说为应！\n'
        '善知识，是称为福慧双修经，是经所说法为福慧双修法，实则无福慧双修法，因福慧双修并非佛法，因大众立福慧双修道称佛道故，有福慧双修法，如来是故说福慧双修法！\n'
        '谛深2017年1月11日应皈依弟子问',
  ),
  (
    title: '谛深大师开示:如何信解命终往生',
    date: '2016.12.6',
    body:
        '坐下弟子，所谓命者，缘分运行之名！一切命相，皆有终到了却之时，是称临命终时！譬如：生命乃指由生到死之间缘分运行名相，如是若临命终死前之刻！\n'
        '善知识，如何命终来至我处，当知，命之名相八万四千宗中分流，共成：福运命相、苦运命相、道运命相三大类别！\n'
        '善知识，众生诸多命相终了变换，称命终往生！譬如：有人无病享福时，欢颜笑语，福命临终，病苦来临，是称往生病苦！人之一生福苦诸命相缠缔造诸多临命终时、诸多往生处，是称无常！\n'
        '善知识，如何往生我处，若人舍弃世间福报，来至我处求诸果位，由六道轮回罪孽身转成清净道身，是称福报命终本世往生我处！若人罪苦缠身，舍弃尘缘来至我处，求诸道果，由重罪受身之命转成清净道命，是称罪苦命终本世往生我处，如是等等，称本世生身往生！若人死后往生极乐世界，称转世往生弥陀净土！\n'
        '善知识，毗尼寺院皆佛所住，譬如：大使馆乃本土窗口，乃国王辖！毗尼寺院亦复如是！\n'
        '善知识，如是信解受持往生极乐！\n'
        '谛深2016，12，6日示',
  ),
  (
    title: '谛深大师开示:如何修随缘',
    date: '2016.12.5',
    body:
        '坐下弟子，佛说随缘修法，并非佛教庸僧教传！关于皈依、随缘等法，师父已开示多次！今者因有弟子依然不能解我所说意故，为汝等再说随缘法要！\n'
        '善知识，随缘本于修行遇搅闹避之，我们称之为“由他去”、“离他去”等！是意乃说：若遇搅闹不能脱离即不理他、能脱离则离他而去，称随他的缘分、于我无关！是称佛说凡夫随缘！并非随他一起听他指令称凡夫随缘！\n'
        '善知识，释迦佛法末世，因罪众错解、错传、错用或盗解、盗传、盗用故，令佛所说法失却本意变成魔所说法故，佛法灭度！\n'
        '善知识，修行圣人随缘，只随自己的缘分中诸因、成就诸道因，因道因成就故，成就佛法妙果！是称佛说圣人随缘！\n'
        '善知识，入我坐下当如是入随缘法！\n'
        '谛深2016，12，5日示！',
  ),
  (
    title: '谛深大师开示:佛法末世名品（第四品）',
    date: '2016.12.5',
    body:
        '坐下弟子，所谓佛法末世指闻末世、思末世、解末世、知末世、见末世、讲末世、传末世、修末世、证末世；因末世、缘末世、果末世、报末世！以是成就佛法灭度因、灭度缘、灭度果、灭度报至无佛法住世！\n'
        '善知识，所谓闻末世，是指闻者不实，道理为辩，如是思维；所谓解末世，是指自己知见，科学量度，理律相扣，如是思维；所谓知末世，是指知见为实，虚妄成真，成就获得，如是思维；所谓见末世，是指累世罪业成就现实，所见为真，罪为真实，如是思维；所谓讲末世，是指自己知见成就缘分讲说，如是思维；所谓传末世，是指共鸣知见成就弘扬传承，如是思维；所谓修末世，是指因所得佛法不真故，修证所得法要，如是思维；所谓证末世，是指所证之道不及科学、乃至不及鬼神，以是因缘皈依世界法、皈依鬼神成就六道果位，成堕落果，如是思维！\n'
        '善知识，如是入：因末世、缘末世、果末世、报末世，佛法灭度！报末世中，戒律遭污，正修行人遭鬼神戏、遭罪众谤，娑婆世界急转入六道道法程式，佛法灭度！\n'
        '善知识，末世染污成就转世业种，大众入罪不能救拔！\n'
        '谛深2016，12，5日示！',
  ),
  (
    title: '谛深大师开示:如何带孩子修行',
    date: '2016.11.30',
    body:
        '坐下弟子及声闻善知识，修行缘分何时最佳？譬如：千年古树，年轮旋转，你剥掉最新一层，较早之层即成为显露！又如喷涂色彩，层层覆盖，剥掉一层，次层即露！佛门修行缘分亦复如是而更纷杂！汝若于某一世、某一劫遇佛住世未发心出离，死后轮转织罪苦缘分将佛法缘分覆盖！若于某世又遇佛出世，恰汝因罪苦缠缚求出离，汝礼佛足如遇故知，涕泪悲泣不知所以！若复有人偶发善心皈依佛陀，如色层破损露次色彩！如是等等！\n'
        '善知识，佛法缘分错综复杂，累劫与邪魔外道缘分相互熏染，是故，有人今日皈依邪魔，明日则回转皈依佛陀，若不被救转或又皈依外道成就堕落！亦或有人今日皈依佛陀因罪孽深重故，明日转或皈依邪魔成就罪苦灭转，等等！\n'
        '善知识，是称修行缘分之芽发与堕落机缘！是故师父常说当机为法，不说不当机为法！\n'
        '善知识，汝等修行缘分遇佛出世时，恰露佛门缘分时，称为最佳修行缘分！若未遇佛出世，汝之佛门缘分显露，则称道缘最坏！\n'
        '善知识，若复有人道缘最坏时，能以戒律为依坚定不移追求修证，是人乃普贤菩萨所显！若复有人道缘最坏时，为魔境界印证所困，难求佛陀印证了意，若以是为果，其乃波旬之化，若不以是为道，坚持禅那功夫，能以戒为师，其乃金刚菩萨所化！\n'
        '善知识，若有人养育子女遇佛出世，求修佛法，以戒为师坚持不懈，是人乃观音菩萨所化！\n'
        '善知识，养育子女修行缘分，当如下导引：\n'
        '一者，年幼之子若好好安求静，是子乃佛门缘分显露，可带入道场参入修学；\n'
        '二者，若年幼之子好动求染（喜欢歌声音乐）是子修道缘分尚远，应于父母身前多受佛法熏洗，道缘显露再入道场！\n'
        '三者，若年幼之子于佛门有污、有毁，是子罪缘显露父母当勿以佛法示之，其罪中有悔时再行教化！等等之十七条！\n'
        '善知识，六道众生之人道于佛法末法时母体分娩时，因罪孽深重故，万分之一者，不能不哭、亿万分之一者能念阿弥陀佛、万分之一者能于七岁前遇佛菩萨肉身之拜与不拜等等！更有罪使带孩子先礼佛陀后于生寿时段因种种缘分诽谤佛陀断灭佛种！\n'
        '善知识，若有罪使闻吾所说，心生怠倦，当以坚固心于佛法修证了意！若有大福报缘分者闻吾所说心生欢喜，当知是人于本世必获果证！\n'
        '谛深2016，11，30日应弟子问',
  ),
  (
    title: '谛深大师开示:我坐下居士如何共修结道',
    date: '2016.11.27',
    body:
        '坐下弟子及声闻善知识：近几日吾坐下居士弟子已成立了诸多共同结伴修行群，这是佛门一大幸事！因在家居士戒律难持或不能持故，如何共修结道，汝等当知！\n'
        '善知识，因地之修行第一应有修行智慧！\n'
        '所谓修行智慧：\n'
        '一要自知！自知即明白自己所依、所修、所行、所障、所得、所坏后，由是所证佛法当得段要！修行者若不自知，称门外汉不能入修行门！\n'
        '二要知共修者之证、之得，多行学习，以他人之证、之得寻自己之坏法处，一切入门者皆以是称修！\n'
        '三不要寻别人短处，若寻别人短处是称罪障！也不说别人长处，只自己补缺！修行人不论别人长短，若论，即堕罪孽缘分！善知识，以上三条称居士修行智慧！\n'
        '因地之修行第二要回避障碍，所谓回避障碍譬如自己未证却与人有说、或有人未证愿意教你，是称重罪因缘障碍！是故，当回避如是之者与自己共修！\n'
        '因地修行之第三要远离争论、争斗、辩论！若入是种法，修行即成邪道，断灭佛种成就魔道！\n'
        '善知识，若居士入吾坐下离苦共修结道，当如是做！\n'
        '谛深2016，11，27日应弟子问示！',
  ),
  (
    title: '谛深大师开示:戒律与经书',
    date: '2016.11.22',
    body:
        '坐下弟子及声闻善知识众，卢舍那佛戒律定义：当与不当称之为戒！所谓当与不当，譬如：当今阅兵式中，军委主席称同志们辛苦了！\n'
        '将士们一呼万应，是称为当；若一平民模仿军委主席在大街上称同志们辛苦了，是称不当！\n'
        '善知识，佛门戒律有应当做与不当做之本质条款！\n'
        '善知识，经书乃诸佛世尊住世之当机说！是于持戒弟子中以不同机缘为依之说！若有不持戒之人，不与为说！是故，一切经书皆自戒中立！一切佛门修行皆自戒中来！若无戒律，诸经不立！\n'
        '善知识，诸佛世尊皆责令弟子，不与坐高坐者讲法、不与有罪心者讲法，不与诸等皈依邪道者讲法即为戒律称本！\n'
        '善知识，释迦佛法末世，切勿令无戒之者阅读经典，若令，即成罪孽！\n'
        '谛深2016，11，22日应弟子问',
  ),
  (
    title: '谛深大师开示:妙湛寺建设不会雇佣工程队',
    date: '2016.11.13',
    body:
        '座下弟子及声闻善知识众，妙湛寺各个正体殿寮建设，均将责成我坐下弟子与戒中僧人建设，其余不结非信缘分，令佛法灭！\n'
        '善知识，寺院建设若有人不信、不敬、以罪孽眼、罪孽心参与，当知是人即坏佛缘，必于未来世假佛门福报，破坏佛法，断大众出离苦海种子！譬如：魔王波旬，福报甚大，能于佛前成罪障碍，只因其于法缘佛住世时，其受雇道昌法师，建设山既寺，释迦牟尼因地修行名曰意决，入住该寺，并于该寺获灭罪心，以是缘分，成就释迦佛成佛时，波旬成魔王伴道！\n'
        '善知识，燃灯佛给释迦佛授记时，曾嘱说是种缘分！\n'
        '善知识，是故妙湛寺建设不用非佛弟子！\n'
        '善知识，开山机械工程以后亦令坐下弟子安排居士做！欧洲、洋州妙湛寺，所有，均由我坐下弟子做！\n'
        '谛深2016，11，13日于妙湛寺示！',
  ),
  (
    title: '谛深大师开示:佛门如何看待无意伤害',
    date: '2016.10.31',
    body:
        '坐下弟子及声闻善知识，今天我皈依弟子请法，说有声闻问他无意中割断一只狗的腿，该如何处理！\n'
        '善知识，所谓罪恶乃六道之本，是故，称五浊恶世！是故，大众当修行出离六道！是故，修行人当知罪恶之道！是故，谛深今者为汝等开解罪恶之犯，以令一切道、邪道、不信佛道中之人因是得度！\n'
        '善知识，罪恶之道分善恶两相缠缚，师父已有讲说，今不再述！恶之又分主体、受体、心体、相体、妄体、用体、非相非用体等！所谓体者，顾名思义相形用三者一显，所谓相者，分为不一之意，于形体表征范围意！\n'
        '善知识，譬如：杀恶，屠夫为主体恶，被杀者为受体恶；有人兴杀心，成与未成是称杀恶心体；汝之见杀，不管是见实杀或画像杀或梦中杀等譬如影视杀皆为相体；有人于杀中不知有杀，是种杀恶称杀恶妄体，譬如汝煮水饮用，万虫遭杀，是称杀恶妄体；所谓杀恶用体，譬如人之存活，不杀不立称为杀恶用体！所谓不杀不立，譬如呼吸细菌入体亦有被杀，是称不杀不立！所谓杀恶非相非用体，譬如影视杀恶之体，若无影视杀恶其不成体，称非相非用体！\n'
        '善知识，五浊恶世，是故不住，若住必遭恶缠，是故汝等当修出离法！所谓出离法，佛法实称！\n'
        '善知识，汝问无意伤狗因汝有杀罪，当行忏悔，发心出离，方能不受杀恶缠缚！\n'
        '善知识，戒乃离苦法，无戒无出离，汝等当求当持！谛深2016，10，31应弟子代声闻问！',
  ),
  (
    title: '谛深大师开示:佛法末世如何产生（第三品）',
    date: '2016.10.27',
    body:
        '坐下弟子及声闻善知识：\n'
        '佛法末世师父已有多品开示，今者因有弟子于吾法中有失故，再为汝等讲说末法成因一品，名多摩罗巴旃檀香成，是品得者，能于罪根忏悔生香，于供养佛心，成初果罗汉！所谓得者，指获法涤心，因心生道，回佛宝莲座下，三七日中不闻杂陈，七七日中，毗尼严净之体！\n'
        '善知识：所谓末法成因，譬如：数学难题，诸多人冥思苦想，依理而做，却有诸多人皆不知思路，无能为解！又有诸多人理错、思路错，错解、错得！只有少数人理正思路对，结果正确！\n'
        '善知识，数学题目，乃有确凿结果、确凿理律为证者！亦即，人们解题正确与否，有确切答案阅批！\n'
        '善知识，佛法修持，知结果者甚为稀有，而其结果者，难思难解！譬如蚂蚁思维卫星电视者！若非佛住世，无有人能于所修、所得之道以确切印证之！是故，所有一切以种种法称呼大道、正道、佛道者，皆因不能为佛所印证故，各个皆称证无上道，实则，并非大道、正道、佛道乃至一切所称无上道！\n'
        '善知识，是故，如是种种并非佛道乃至一切道者，因不能证得、错证错得而得或无法证得故，诸多道体，自成体系，错修错练称佛法传，以是意故，令佛法名相因是并非佛法名相！佛法落至末法时代！\n'
        '善知识，今者娑婆世界佛法已如是落于末世！诸种以佛、佛说之名相并非佛法，诸如诸佛世尊名号，并非诸佛世尊名号！诸菩萨名号，并非诸菩萨名号！诸佛道场，并非诸佛道场！诸以佛法为名群体并非佛法群体！佛菩萨慈悲之用，已为罪苦之根！于现实中，表象为：戒律丧失，或即使讲戒律，亦只口说之用，并非真实持戒！戒律丧失之所谓僧众吃喝嫖赌坑蒙拐骗无所不为！\n'
        '善知识，吾为令佛法末世求出苦海大众设毗尼门为旃檀要，汝等当字字深辩，禅悦一门，获吾法要，超出罪苦！\n'
        '善知识，切勿妄修妄练、盲修瞎炼称为佛法，到头来自欺之后，又欺人者，落于大坑！\n'
        '善知识，汝等于是品当持之忏悔，必有大福大智！切勿口说经法落于魔道、邪道！谛深2016，10，27日示！',
  ),
  (
    title: '谛深大师开示:莫因佛门污而欺佛',
    date: '2016.10.25',
    body:
        '坐下弟子及声闻善知识众，今有弟子入某群遇邪魔妖道罪称自己乃佛祖、菩萨圣等邪说邪传！\n'
        '善知识，佛法是真实的，是故一切污佛重罪必当受报，如何报之，师父已为汝等讲说，今不再述！\n'
        '善知识，佛门诸多邪染众玷污佛门！汝等当闻知而却！\n'
        '善知识，因玷污佛门受报之众当今比比皆是。4年前有XX邪道弟子，赴某去世人家行超拔途中，一车六人妄称佛法，路遇车祸无一生还，故，来问吾何受是报，吾为其等讲说念佛品，令其等忏悔悬崖勒马！又有XX邪道弟子于东营为车祸横死，求吾施救，吾为其等讲说谤佛罪责章句，如是诸多！\n'
        '善知识，诸如藏传中邪道、净土中邪道、禅宗中邪道、律宗中邪道；妄称佛菩萨再来所成诸邪道、以佛法名词称佛法者诸种邪道，皆当于当处受地狱恶鬼畜生报！如是等等诸多罪众受报甚多，吾今开章句为令是等有悟，莫受罪染不自拔者！\n'
        '善知识，何故罪众受报贼首无恙？善知识，罪首于前世曾为佛门承事，有受罪重之众供养之福报，福报享尽，当因诓骗大众故，堕落于嗜血地狱受万众宰杀报！后经无数劫后，转于畜生身，难有出期！\n'
        '善知识，汝等入某道法为求所求，切勿因不信佛法兴诽谤做而种罪种！善知识，佛灭度后以戒为师，以是为鉴！谛深2016，10月25日应弟子问！',
  ),
  (
    title: '师父谛深大师座下的在家居士弟子共修日规！',
    date: '2016.10.16',
    body:
        '1、入位跪香忏悔罪业；\n'
        '2、顶礼三匝站立佛像两边共称念：无上甚深微妙法，百千万劫难遭遇；我今见闻得受持，愿解如来真实意。普贤菩萨行愿品一遍！\n'
        '3、听师父相关开示。\n'
        '4、入位正坐，坐香。坐香结束放香顶礼！称念佛号！2016，10，16',
  ),
  (
    title: '谛深大师开示:如何行居士道',
    date: '2016.10.4',
    body:
        '善知识，佛法本不分居士僧人受道，亦不分居士僧人行道，因出家乃获法得道之佛贤圣必为者，并因慈悲为导师之为故，分别为出家在家！是故，若有人获法得道不出家者，无有是处！\n'
        '善知识，于修道途中获法得道极为难得、甚为稀有，无获法得道者住世如同长夜，而有获法得道者住世则如同昙花一现之白昼，大众甚难有机会得度，更有长夜之高诸恶为乱，是故，如来为慈悲大众，为不令佛法断灭，设令凡夫众得：出离罪苦之不获法得道而能入出离罪苦地之佛制戒律，是称出家人者之于寺院者也！\n'
        '善知识，是故，我说居士不能讲法；出家而未成就人不能讲法。是故我说，遇佛住世以佛为师，佛灭度后无佛现前以戒为师！\n'
        '善知识，若有人因种种罪、种种业不能出家，但却佛法缘分具足，是种人可行居士道！居士道者，按我谛深说之，当为如下之做，一者护法，二者持菩萨戒，三者随善知识学，四至十三者为普贤愿望！\n'
        '善知识，如是之作者，能为福报种，做佛门因！吾说是人乃佛坐下大居士道者！\n'
        '善知识，当如说行居士道！\n'
        '谛深2016，10，4日应弟子问！',
  ),
  (
    title: '谛深大师开示:天人为什么难度',
    date: '2016.9.26',
    body:
        '坐下弟子及声闻善知识，六道分为天人阿修罗地狱恶鬼畜生！于是六道中，人最好度！天人则比人难度！\n'
        '善知识，地狱重罪之者，因罪重不知有福故，不信有福、无病之道，何况佛道！是故难度！譬如递弱为食（生物链）被视为公理，若狼不食兔、鼠，兔鼠泛滥成灾如是大小克制，世界得以平衡稳定！若于是自然理律说不杀戒，自无道理！是律称罪重之道，于是道中不能生不杀善种，若有人于是种必然之生道中能信不杀之道，实乃奇人或愚痴人！地狱恶鬼畜生重罪之道不能令善种种亦复如是，是称难闻佛法，是称难度！于是种道中，闻说有乐，恰如有人于人群中说能不假器具往来诸天，令人难信！因难信故，善法不住，何况不可思议之佛法，闻之不能！是称罪苦之道！\n'
        '善知识，天人之道，福报甚大，病苦极少，病能有医！于是人群中说福报法、清净法信无皈依，因自有之！是故，于说佛法，难令皈依！不能皈依，则不能度！是称天人比人难度！譬如有人家产万贯，汝为令其出离其家，说与此人能令其受尽艰难获得财富，是人必即使信之亦不随汝，何况疑惑或者不信！\n'
        '善知识，人道之众最为易度！因，人道苦乐一契，正反成道。是中之人受苦之时，能观无苦之人，以是因攀缘之心求出苦心常驻，是种人中易播善种，易于皈依！是故，人道之众易度！\n'
        '善知识，因人道之人易于以善、以福、以道等令皈依故，邪魔外道亦易假善、真善；假福、真福；假道、真道，假神通、真神通；假除病、真除病等等之道，成就种种理律之典令人道之众皈依，入堕落道！\n'
        '善知识，是故汝等当依佛说，请佛住世，示现不思议法，令汝等获出苦海！谛深2016，9，26日应弟子问法示！',
  ),
  (
    title: '谛深大师开示:什么是善',
    date: '2016.9.22',
    body:
        '坐下弟子及声闻善知识众：今天师父得知坐下弟子所设群中声闻已达五千多，师父为释迦佛法末世，娑婆世界有如是众之智慧之善知识高兴故，为汝等讲说善等诸法！\n'
        '谛听，善思念之！\n'
        '善知识，所谓善者，大分世间善与出世间善，而是两种善中又分多种、多层善种善缘善相！\n'
        '善知识，譬如：狼虫虎豹，怜子之举，夺他物之命，令人丧子丧父苦之过甚，于己之群体互爱有加，以此类推多少凄惨大小有别之善说善用，称之为世间之善！若有人舍一切、不思善恶、离诸法而施之于人，是人称出世间善！\n'
        '善知识，出世间善，慈悲是也！若复有人于人前狂妄称说，显示自己善心爱心，称慈悲者，是人实则玷污慈悲之罪说者！\n'
        '善知识，若复有人以：于种种法各自理解不同，断吾慈悲法，是人乃直接堕落金刚地狱难有出期！\n'
        '善知识，何者为福、于佛法有授皈依佛说、做佛子孙有福，若人以邪道知见称于佛法不同理解之说，称为不授福报，不授福报称为无福！无福者即罪！不管汝以佛、佛说为号如何精进，其罪必受！\n'
        '善知识，戒律乃诸佛世尊所传，譬如：喝水不渴，渴需喝水，不存在不同解，戒律不存在解不同，受之既即得！福报亦复如是，受之即得，无需解释！\n'
        '善知识，佛法不能解，若解即丢！若复有人以不同理解为己开脱，是人乃邪魔子，不能获福报，更何见如来！\n'
        '善知识，切勿以自己知见妄说佛法，开脱有罪！\n'
        '谛深2016，9，22应弟子问！',
  ),
  (
    title: '谛深大师开示:如何不落邪教',
    date: '2016.9.12',
    body:
        '坐下弟子及声闻善知识众，谛深不欺诳，慈悲为嘱托，汝等当闻受，以护己有福！释迦末法时，因戒荒废故，诸道兴于世，凡夫愚痴者，神鬼诸妖孽，假种种缘分，因众难知晓，或以为神奇、或以为大力、或以能救己，或以能出苦，或以能升天，或以能得愿，或以某佛名、或以某法相，遭遇邪挟持，令己失判断，落于魔掌中！譬如：诸教派，基督天主者，藏秘伊斯兰，佛门无戒派，天道鬼神所，恶鬼称神使，等等又等等，因贪嗔痴妄加，无戒垂范故，成就神鬼传！如是被利用，造邪种子生，化成诸邪教，因众不能识，相互说神奇，堕落于其中，遭受地狱苦！\n'
        '善知识当知，譬如：有农夫，广开肥沃土，善于农耕做，成为大富豪。其子略有传，因福承蒙故，懒于农规矩，广田几夜间，杂草丛生耳！又于是种相，欲归其父德，更需多费力，方能重成田！其子子孙孙，福中难有志，再显族辉煌，因于是等荒，需舍一代命，方能略除治，需舍几代命，方能回归田，然者如是众，因福久长故，已无能力做，故无愿除草！如是延三代，广田成荒野，荆棘灌木生，乱象统世界！\n'
        '善知识当知，佛法亦如是，末法之世界，种种乱象生，因无有净土，大众归乱象！所谓净土者，戒中成就者！诸佛如是说！而于法末世，地狱恶鬼众，成就种种教，乃至于佛门，亦如是成派！\n'
        '善知识，释迦佛法末世，娑婆世界会出现诸多邪魔外道，令大众堕落遭罪恶报！汝等当以吾是说为镜，令自己不堕落其道，遭大罪苦！\n'
        '谛深2016，9，12日示！',
  ),
  (
    title: '谛深大师开示:在家可不可以诵楞严咒',
    date: '2016.9.8',
    body:
        '坐下弟子及声闻善知识众，楞严咒是护持佛之护法金刚与菩萨的！若汝无有护法金刚与护法菩萨护持，你诵楞严咒会护持周围其他修行人之护法的！若汝之所做违佛之戒律，汝诵楞严咒则会受制！譬如：有小偷偷到一副手铐，送与一个他遇到的人，殊不知其人是一反扒警察，恰好自食其果！\n'
        '善知识，佛门弟子诵楞严咒亦复如是，若汝不持禁戒，诵佛说楞严神咒必遭反制！\n'
        '善知识，佛之戒律分大戒小戒，每一根本重戒戒持，均有五位护法来应！大戒者为天龙八部护持，小戒者为善持鬼神护持！若持两条根本重戒，则有相应十位护法护持 ！以此类推！ ！以此类推！\n'
        '善知识，譬如：官员按职位配备卫兵，每高一级，多加五位士兵，每到一定数额则加一位军衔之于班长、排长、连长乃至军团司令护卫等！佛之护法按持戒大小、持戒数量多少至金刚王护持等！\n'
        '善知识，若汝等出家为僧，不持禁戒因寺院有持戒道者，则获护法供养，因无德获福故，临命终时，必遭直堕金刚地狱难有出期！若汝等在家修善皈依佛门，一戒不持，则受相应制报！若汝等能持一戒，则获一戒护持报！\n'
        '是故，善知识，汝等当以毗尼法量自修行，相应量度修持楞严神咒！\n'
        '谛深2016，9，8日应弟子问诵持楞严咒示！',
  ),
  (
    title: '谛深大师开示:什么是供养、布施（第二品）',
    date: '2016.9.4',
    body:
        '坐下弟子及声闻善知识众，所谓供养与布施分尘缘供养与布施与佛门供养与布施。尘缘供养与布施乃：以自身愿望为依，或自身目的为导力所能及之为称为尘缘供养；无目的、因某种缘分偶遇之给予，称为尘缘布施！\n'
        '所谓佛门供养与布施乃指：皈依佛后，以佛为自己生命所依，将一切奉献于佛之为，佛门供养有诸多类别；而不以佛法为命，以自己某种职业为目的和终身追求之愿，仅因所需、有求、有用、有想等，或因感召等给予钱财者，称为佛门布施！\n'
        '是故，善知识，佛门供养获福，布施有罪得消！\n'
        '善知识，譬如：有人不皈依三宝，予僧财物，称为佛门布施！有人出家为僧一生一文不耗，严净毗尼，菜叶不弃，延佛慧命，称为佛门供养！\n'
        '善知识，汝等当知佛法难闻，莫自狂为！\n'
        '谛深2016，9，4日因有重罪之网站示！',
  ),
  (
    title: '谛深大师开示:如何消除嗜睡业障',
    date: '2016.8.16',
    body:
        '坐下弟子及声闻善知识，嗜睡有多种因缘，其中有因缘为修行道障，有因缘为休息，有因缘为应当，有因缘为罪感，如是等等！\n'
        '善知识，若有人不修行不瞌睡，修行则昏昏欲睡，称为道障；若有人疲乏之后睡意绵绵称为休息；若有人因疾病罪苦嗜睡称为应当；若有人业障现前则清醒，无业障则睡觉称罪感，如是等等!\n'
        '善知识，譬如：罪感，嗜睡者遇有老虎现前，必不睡狂奔，是为罪感相，而病重昏睡者，即使老虎现前亦不能醒者！\n'
        '善知识，什么是睡觉，师父今日为汝等开解！睡觉者乃众生无始劫来由妄生妄死故，成就动静摇业，相摇成劳，劳久发尘，尘缘成体，体别成段分别，以段分别故，成就业世间动静，业世间动静之业又造就明暗转换，明者应动，暗者应静成众生体相缘分，以是因缘，成就众生种种醒、种种睡者！\n'
        '善知识，汝等当于修行途中，把握缘分，若遇道障嗜睡，当明自己缘分，精进于戒获得道体，如是破障！切勿盲目求解！谛深2016，8，16日应弟子问！',
  ),
  (
    title: '谛深大师开示:什么是精神病',
    date: '2016.8.15',
    body:
        '坐下弟子及声闻善知识众，前几日因有弟子亲属学某念佛法门得重度精神病送精神病院看护，师父讲说修道人修行得精神病之因！由于诸多弟子及声闻善知识并非知晓着魔理律故，谛深再为汝等讲说精神病与着魔理律以助大德修行成道！\n'
        '善知识，所谓精神病，凡俗定义为：妄想症与精神障碍症！佛法称之为着魔！\n'
        '善知识，若有人、有道、有门派以意念、妄想为导授之于人，而无善道分制者，则是道修行者最高境界就是极度妄想、或纯正妄想！纯正妄想，即重度精神病或不治之精神分裂症！另有道、有派、有门设秘密、神通、讲说与言语等道理令众入道，实则是等秘密或神通、或道理即是思维障碍！若入是种道理，修道精进坚固信心而无善道分制，获得所谓成就者，即是坚固精神障碍症者，亦即：重度精神病患者！\n'
        '善知识，是故释迦佛成佛第一句话：善哉善哉，十方世界乃至草木蝼蚁皆具如来智慧德相，只因妄想执着（坚固精神）故而不能证得！是故吾谛深住世，以宣示佛戒为法实证实修，破诸魔国土，救拔魔子魔孙令其等脱离罪缠！是故，佛于楞严经说凡有言说皆无实意！是故，我令弟子广修毗尼法令其等不遭魔幻！是故，我为释迦如来之娑婆世界末世设五百年正法舟乘令有福者离苦！\n'
        '善知识，虚妄与执着虽乃修行妙用，以虚妄执着法为制式不加妙用道即是邪魔外道，譬如：核能若按不同形式积聚可发电亦可成摧毁人类的核弹，只差分制！佛法妄想执着之于修行之道无善道分制亦复如是，若无戒律、无途分、无证分，即成毁灭修道者之道！\n'
        '善知识，诸佛世尊皆以慈悲法布施大众，令众出离罪苦！若有人以种种罪苦道，慈悲说、 善说，令大众着魔，是人即乃魔王、邪王、罪苦之王！其累世不能超脱！ 善说，令大众着魔，是人即乃魔王、邪王、罪苦之王！其累世不能超脱！\n'
        '善知识，汝等当知，佛法修持以戒为师，做是说者乃十方诸佛说，做是修证者，乃诸佛世尊弟子亦乃吾谛深弟子！\n'
        '善知识，切勿堕落邪途自造苦途！谛深2016，8，15示！',
  ),
  (
    title: '谛深大师开示:有的修行人为什么得了精神病',
    date: '2016.8.9',
    body:
        '弟子智纳电话请法，问其亲婶娘皈依邪师修持一句佛号、一部无量寿法门者，因严重精神分裂被儿子送精神病院！是为什么？\n'
        '坐下弟子及声闻善知识众，念佛法、阿弥陀佛名号、寿量缘分等法师父已有开示，不再解说！汝等当以是等讲说为导善思念之；诸等法师诸等罪人不持佛制戒律之未证谓证、未得谓得、未悟谓悟之尘缘开解之佛门事要，皆能令修持者堕落罪苦着魔难救！师父已有诸多开示！汝等当以是为镜，导自修持！\n'
        '善知识，佛法非世间道理、非神鬼示现、非种种神通、乃至种种奇异法者能知少分！更非邪魔外道道法、世间罪染、实用技术、思想意识所能悟知尘许！\n'
        '善知识，佛法因众生罪孽故，虽真实不虚殊圣圆满，大众亦累世累劫难遇！所谓难遇，不能知晓称之难遇！\n'
        '譬如：蚂蚁行走造汽车之书籍之上寻觅甘露，虽于上行因不知不解或错知错解故称之难遇造车之术！善知识，以是意故释迦法末世，已难有人遇佛之慈悲法！\n'
        '善知识，吾谛深所说亦复如是，大众难遇如是善解！善知识，修持一句佛号法并非佛法，乃罪重开解诸佛所说，是故遭罪恶之报！善知识，若有人于释迦法末世能明吾谛深所说乃至一句，如是之人甚为稀有难得！\n'
        '善知识，汝等当于卢舍那佛之毗尼法中精进勇猛修行，获出离罪苦之道！谛深2016，8，9日应弟子问！',
  ),
  (
    title: '谛深大师开示:菩萨如何示现',
    date: '2016.8.9',
    body:
        '今日有声闻问，比丘比丘尼不捉金钱，若有人以菩萨示现为由称可以捉金钱，如何应之？\n'
        '善知识：十方果位菩萨皆不作是种示现，若有人以是说解捉钱堕落，为诽谤三宝诽谤戒法堕落地狱重罪！善知识，菩萨不做种种断灭佛法之断因、断缘、断果、断报之示现！不做错解、错用、错传佛法妙用之毫发事、毫发为、毫发思！若以断法缘分做，乃波旬弟子假成菩萨，看似度人实则害众之举！\n'
        '善知识，若有人以佛门三宝名，乃至居士名行破灭佛法事，称为菩萨行事，其乃罪孽不救之做！谛深2016，8，9日应声闻问！',
  ),
  (
    title: '谛深大师开示:一件衣服',
    date: '2016.7.23',
    body:
        '有人问我你一个和尚怎么能穿凡夫衣服呢？大德，你凡夫能穿僧衣四处破佛戒律，坑蒙拐骗，坏佛名声，令佛法灭，我和尚就能穿凡夫衣到你们哪里弘法利生！比丘戒，僧衣说中，佛法末世，头陀木叉百纳所成品中，凡一色两色乃至千百色衣染，一条、五条、七条至九条主衣褶，每褶当知千万大众衣之成分汝皆应而缘之，令是名有分成体，缘而度之！\n'
        '善知识，我之衲衣无数大众缘分所成，你不认得了脱褶，我可认得你罪中痴！\n'
        '善知识，一件衣服，纳万水千山，度十方大众！汝等当以是为知，获佛法惠！谛深2016，7，23日为头陀示！',
