  (
    title: '谛深大师开示:什么是药',
    date: '2016.7.22',
    body:
        '今天是观世音菩萨的吉祥日，恰逢有弟子问什么是药，故师父当予讲说，令大众破疑！\n'
        '坐下弟子及声闻善知识，所谓病者，谛深已有开示，不再为示，所谓药者，化灭对症因缘之因称之为药！譬如：铁锈，因氧化称之为铁病，以还原剂令之还原成铁，称还原剂为药！\n'
        '善知识，众生之病与药亦复如是！\n'
        '善知识，十方罪苦众生皆因愚痴故，难能于佛法生实信之心，难于实信中听佛号令，是故，常于病苦不能有拔！\n'
        '善知识，若汝等欲脱离病苦，实信佛法殊圣，当于戒律之中修行获得！\n'
        '善知识，切勿以盲从盲信之信以为实信真修！\n'
        '谛深2016，7，22日应弟子问！',
  ),
  (
    title: '谛深大师开示:关于堪布修改法华经引发争论的开示',
    date: '2016.7.11',
    body:
        '坐下弟子及声闻善知识，吾弟子问及有名堪布修改法华经引发汉地僧人斥责一事，师父如何看待？\n'
        '善知识，师父说是堪布与斥责僧众皆乃修行人也！师父赞叹如是大德之为！\n'
        '何故是说？譬如：有人为某学术问题争论，说明是等争论中人皆乃学者，所谓学者非常人所能称之，如是之人若得问题结论，必皆获成就！\n'
        '善知识，是类事者吾谛深已有开示，汝等细研，莫再问请！因是事于吾所住时代显诸道场，以诸多大德修行所显故、因需于释迦末法诸相变坏佛法中延续佛命故，谛深再为汝等以是事为体简说法要！\n'
        '善知识，关于佛陀名号人人称之有异、人人知之有异、人人得之有异，是故堪布或研经论教者以己之所得判经改字，其乃修行缘分所为，不称其过！诸位斥责其之大德亦乃修行缘分之为，更无有过错！是等争论中人若当未来遇佛出世自当决了！\n'
        '善知识，佛门修行以八万四千法门为譬喻，实则无量无边无数！\n'
        '善知识，修行梯次因六道缘分不同，亦无量无边无数，是故十方世界诸大菩萨慈悲故，住于各有罪修行道界中为修行人做大证明功德主，开悟大众，令其等等修行转界升迁，最终成佛！善知识，地狱之中地藏菩萨于处救众，是中受法大众因火等诸罪因缘所成修道缘分，常因诵经气呼不齐互殴互咬、乃至互啖，生之再咬再啖，以示各自修行，最终归于地藏，获出地狱，于人道或神道继而修行，再获梯次升迁！\n'
        '善知识，人道之中，修行佛法，虽比地狱显诸高层，亦会因知见缘分有争斗相者，于是之者各种缘分归于相应菩萨，当处获出人轮，或生极乐、或往兜率、或往恩施以继续修行！\n'
        '善知识，以不同逻辑意之，又譬如日光照耀大地，万物皆有所获，亦有炎热之行路者咒骂太阳过毒者；亦有拿帽子遮掩阳光者，如是等等之人虽有异动，皆不离太阳也！是等皆以阳光为因行当做事，其做虽违虽谤虽避太阳之普，实则不离阳光也，是故咒骂或遮挡阳光照射者有过乎？若无阳光，是做皆无。是故谛深说如是人等亦太阳之后无有丝毫之过！\n'
        '善知识，有修道人修改法华经者之作亦复如是，其实无过！诸大德斥责其愚痴之做亦无丝毫过错，是僧人其感恩佛法之圣为护佛法故，行呵斥做，其等皆如我之所说，恰如大众感恩太阳当于获赞之作耳！\n'
        '善知识，吾谛深不令弟子议论佛法，不令弟子有争斗，凡议论佛法者，于修行途中有争斗者，实乃修行梯次之别相，以罪为应，无罪不修，是故，不令入吾门下。是故，是等修行大德，所处修行层次尚不能入成就道，尚需于受罪中修，是故，吾说是等有罪，因入吾坐下者已脱离罪中修行，因梯次差别，分别令升迁故，我说升迁之前为罪孽，是故不说其为修行人，是故不说其为佛门人。实则其皆为佛门人，实则其皆为修行人，实则其皆为所住罪障之高僧大德也，是故吾皆赞叹其等也。\n'
        '善知识，非吾谛深巧言，实则如是！其等乃真修行人，其等真实无过当于因缘行赞许！善知识，若复有人以吾之是说为修知之无过，获修行要，我说是人必于佛法末世获无生法忍成就道果！谛深2016，7，11日应弟子问！',
  ),
  (
    title: '谛深大师开示:什么是堕落',
    date: '2016.7.8',
    body:
        '坐下弟子，譬如：一锅水，汝等烧开喝，水中落狗粪，称之水变坏！善者当明了，变坏称堕落！佛法堕落称，亦复如是耳！若汝不知杀，有人领汝知，汝心由无杀，如是变有杀，是称堕杀界，是故有僧众，引用杀视频，言语说杀恶，以警示大众，令之勿有杀，看似发心好，护持佛戒律，实则大罪恶！我呵斥其恶，说其罪恶重，乃波旬之孙，玷污佛名号，永不入我门！不令闻有杀！闻杀乃堕落！善众如是知，种种堕落道！所谓堕落者，即乃受其报！所有修行人，因堕受诸罪！造就罪苦道！坐下弟子众，十方修行人，若闻谤戒者，急躲避而去！\n'
        '善知识，佛制贪嗔痴杀盗淫妄等等诸戒可令汝等于修行途中不入堕落道！汝等当矜持！谛深2016，7，8日示！',
  ),
  (
    title: '谛深大师开示:会不会有冷冻人',
    date: '2016.6.30',
    body:
        '坐下弟子及声闻善知识，今日有人问冷冻胚胎与冷冻人等的科学问题！\n'
        '善知识，释迦佛关于四生九有已有广泛开示，师父不再为述！而诸多邪魔住于寺庙，为名为利贪嗔痴杀盗淫妄以护持狂妄故，邪说邪述邪解佛说经典，令众有失堕落尘缘，是故，师父为汝等以佛法再讲基因、冷冻胚胎、冷冻人等令生命再续之凡尘科学！\n'
        '善知识，佛法乃世界之无碍智慧，早于燃灯佛就有因弟子观解凡尘生命再续特为之说！\n'
        '善知识，众生有胎卵湿化四种生相，无常乃众生生命之相！种种缘分令生命有变、变坏、不住！种种障碍形成种种学科科学！所谓冷冻胚胎、冷冻人等，因人生不长久成障碍故，诞生发展，以令人，虽经数年乃至数千年可再生者！实则被冷冻者，于漫长冷冻之中亦慢慢变坏！只因内里缘分因冷冻因缘而慢于多年！是故善知识，冷冻胚胎、冷冻人必为事实，然亦有变坏年限！\n'
        '善知识，佛法殊圣难遇，汝等当精进勇猛，于毗尼法中，早获出离！师父将在妙湛寺般若殿专讲无常、转世等法！谛深2016，6，30日示！',
  ),
  (
    title: '谛深大师开示:禅宗是段次所属',
    date: '2016.6.28',
    body:
        '坐下弟子，师父关于禅宗是不是法门已有开示，今再为汝等略说！\n'
        '禅那不是法门，但以禅那为修行要领的大德因累劫修习净土、密咒、动静等诸要缘分，需修习禅那段次缘分故，入禅门段次修行，聚之成宗！实则，禅宗不是法门门派，但可称宗称乘！\n'
        '善知识，净土也不是法门，以如说缘分称净土宗净土乘；密宗也不是法门，以如说缘分称密宗密乘！\n'
        '善知识，是故，所谓禅密净本自各门所集，因修行段次入分别宗！\n'
        '善知识，所谓八万四千法门是依据各自缘分所需，分别修习，入不同宗门修各渐次！\n'
        '譬如：加工馒头，一者将小麦晒干、二者将小麦磨成面粉、三者将面粉做成生馒头、四者将生馒头入笼蒸熟！是四过程每每又分若干不同工序！\n'
        '善知识，佛门不同宗门，乃不同缘分渐次者！实则，禅门亦含净土、密咒等等，净土亦含禅悦、密咒等等！\n'
        '是故，汝等不当分别禅净密等等宗派于道途，当视缘分渐次修行！谛深2016，6，28日应声闻问！',
  ),
  (
    title: '谛深大师开示:莫把慈悲当罪孽',
    date: '2016.6.27',
    body:
        '广大声闻：我谛深不需要你们去尊重、更不需要你们去理解！你们不知道师父从苦中醒悟那一刻心是个什么样！人获得了佛法，正譬如：一只小鸟获得了人中皇帝一样的福报与人的智慧！他最想做的不是如何让自己的同类高呼万岁、高呼伟大、高呼圣贤！更不是如何去在同类中有名望、亦不是要让兄弟姊妹拿着自己捕捉的虫子来供养！它会可怜它的同类，给它们留下如何出离悲惨鸟运的智慧！\n'
        '广大声闻，我要以最简单的方式，令依然在罪苦世界中摸索的人们，和我一样获得之前他们永远都无法明白的东西！这是慈悲，不是有名望、有权力、有钱财的人所能做到的，更不是宗教信仰中的人所能知道的！\n'
        '师父告诉你们：佛法是真实的！所以佛法以证得为本！佛法是必须累劫修行才能获得的真实的福报智慧，不是以玄奥、神秘、神通为本所能知道点滴的慈悲法！所以，十方诸佛皆以慈悲法布施还不能明白过来的大众！\n'
        '广大声闻，广大沉沦于种种宗教、包括沉沦于以宗教为本的佛教里的为名为利以玄蛊惑人心的大众，你们当听吾谛深所劝，切勿以种种罪孽之心去衡量佛法！我谛深不以名为求开示大众、不以利为求开示大众、只因慈悲！希望我能带你们出离你们依然受罪苦的世界或给你们出离罪苦世界的启迪！\n'
        '谛深2016，6，27日因弟子罪问开示！',
  ),
  (
    title: '谛深大师开示:何为外戒体',
    date: '2016.6.24',
    body:
        '坐下弟子及声闻善知识众，佛制戒律以救度大众为本质，譬如：有狼群出没某树林，汝告诫幼子之，切勿去树林玩耍！实则，只此处树林不能去也！是称外戒体范围！佛制戒律亦复如是，佛制不杀戒，不杀戒范围、不杀戒内容、不杀戒前提等，称佛制戒律之外根（相）、外本（相）、外体（相），受戒比丘皆当知、当明、当解、当用！若不知、不明、不解、不用，是称愚痴！譬如，佛观一钵水，八万四千虫，若不懂戒律，以为喝水即杀生，实则，喝水不犯杀戒！\n'
        '善知识，所谓不杀戒外戒体，不杀即为外戒体，眼不见之水中小虫不在杀戒外戒体之中！所有食品中小虫，均不入杀戒外戒体！若眼能见之水中虫，饭中虫，则于不杀戒之外体中，是故当将可见之虫放之之后，以火净食！又如有人落水，汝等欲救，称你必须抓住绳索，不抓即堕落！是时当抓！上岸以抓绳为救号令大众是称愚痴！\n'
        '善知识，人之体内亦有多种虫子，乃至可见之蛔虫，如是之虫亦不于杀戒外戒体中，若予以药除不称为杀！如是等等！\n'
        '善知识，另有76类可见众生于人道中侵害佛制比丘道人，当灭之不称犯杀！\n'
        '善知识，如若不出家为僧求出六道，不当问戒、不当持戒！若问若持佛说戒律即重罪愚痴做！\n'
        '谛深于2016.6.谛深于2016.6.24日应智安问示！',
  ),
  (
    title: '谛深大师开示:活着的人可不可以与死去的人沟通',
    date: '2016.6.21',
    body:
        '坐下弟子及声闻善知识，譬如：知了猴与知了，知了猴蜕变成知了后，是可以与依然是知了猴的祖先们相见的！只是相见不相识罢了！又如面粉与馒头，亦可相见！亦相见不相识者吁！人与死后之人相见沟通亦复如是！\n'
        '善知识，十方众生皆于六道中轮回转世，入法修行者能由罪重智短者，流变成福报智慧者；不入法修行或邪魔外道者，流变成罪重智短者，如是微细变承！\n'
        '善知识，由于生死场中，大多死变因缘之差别，足以令互不相认，而极少死变差别小者，或能因流变延续互知互认，故，极少有人能与死后之人沟通！诸多人生前好友沟通却不自知者也！\n'
        '善知识，譬如：有记前生者，即为其证！善知识，佛法超度亡灵者，譬如：有人之友远行，其组织人们把酒宴别，更与礼物者！为逝去者做超度，因佛法殊圣故，能予死者转世途中获应当福报变！亦有罪重之者，因贪嗔痴杀盗淫妄缘分假佛法超度者，令死者更获罪苦变者！\n'
        '善知识，谛深慈悲告汝，切勿未证谓证乱解佛法，其罪自作！\n'
        '善知识，汝等当以戒为师求出生死罪孽，祝汝等早离罪苦！谛深2016，6，21示！',
  ),
  (
    title: '谛深大师开示:如何获了脱生死',
    date: '2016.6.16',
    body:
        '坐下弟子及声闻善知识，所谓了脱生死，是指因缘果报化尽，无生灭相！\n'
        '善知识，若汝等以居士身说了脱相，乃以有说无、以恶称善、以臭称香者是；若以不持戒身称能了脱，乃以假称真、以魔称佛、以地狱称极乐者是；若以讲说种种法譬如讲说了脱法、讲说往生极乐法、讲说秘密法，而不假以戒律称能了脱，恰如骗子之道，听似予之所求，实则予之痛苦之令人堕落称圣之做者是！\n'
        '善知识，了脱法非说而得之，修之有成耳！吾之声闻中有诸多盲修瞎练者道中迷人，师父说汝等切莫执之为道，成堕落果！\n'
        '善知识，了脱自戒中道来！譬如：大雨自云中来！\n'
        '善知识，了脱生死者，真佛之圣子圣孙也！\n'
        '谛深2016，6，16日示！',
  ),
  (
    title: '谛深大师开示:什么是用相禅',
    date: '2016.6.12',
    body:
        '坐下弟子及声闻善知识众，用相禅乃禅那梯次果位佛法之用者，譬如：学生上学学习，所学专业知识融会贯通后，于现实中使用所学知识解决实际问题，称为知识用相！佛门所谓用相禅亦复如是，禅那获得后，成就相应果位，果位报身之应界体相所适用之所得佛法、于天人鬼神等中用以救度大众之法，称为佛门用相禅！善知识，用相禅分为多种梯次，每每梯次所获禅那、所证之于天人阿修罗地狱恶鬼畜生之用相禅各不相同，为分别故，称为禅门之用相禅！\n'
        '善知识，若不能禅那获得，后成果位，则所说一切皆为虚妄，若无用相禅传承，不能救众！\n'
        '善知识，十方诸佛所说经典，以致吾谛深所说，皆佛之果位用相禅之后所成之言说，是故称经，不称用相禅，是故，经典为佛法正象末之象法！善知识，汝等当勇猛精进于戒中禅那，获得各个梯次果位之用相禅，以度大众！谛深2016，6，12日应智安代声闻问',
  ),
  (
    title: '谛深大师开示:什么是报身成就',
    date: '2016.6.12',
    body:
        '坐下弟子及声闻善知识众，所谓报身成就指修行所得之报！\n'
        '譬如：天人身、人身、牛身、恶鬼身乃至种种邪魔外道身，皆为其相应修行所得之报身成就！善知识，佛法修证之不同果位成就，称为佛门报身成就！比如：紫金光身、阿罗汉身、比丘身、变化身、圆满报身、优婆塞优婆夷身皆为佛法报身！\n'
        '善知识，祝汝等早证佛果！谛深2016，6，12应智安代声闻问！',
  ),
  (
    title: '谛深大师开示:佛法如何传来中国',
    date: '2016.6.6',
    body:
        '座下弟子及声闻善知识众：诸佛世尊住世，皆先为世间眼，解世间障碍，令众归仰为诸多经典；再布令大众破灭障碍获取出世间法之戒律，再于修出离法大众中显慈悲德成身率众出离！\n'
        '善知识，佛法弘扬亦复如是，先闻佛名后闻经典，再闻出离戒法皈依得戒法识戒法后入出离道，再随如来出离六道成就果位！\n'
        '善知识，释迦佛法传于中国亦复如是，中国有智之者先闻佛名，后得经书，再得戒法入出离道，随佛修行成道！譬如：当今诸多名人之粉丝，先闻其名，听其歌声为其折服，再行归仰，再于追逐名人过程中见到名人，有极少粉丝能随名人学习，获得真传后亦成名人！\n'
        '善知识，佛法不思议，非邪魔外道研究分别所能知晓少分！\n'
        '善知识，佛法灭时，戒律先灭，后经典被灭！诸多邪魔外道亦以灭佛戒律为导，诓骗大众令大众于其罪孽法中不能自拔！\n'
        '善知识，若遇有邪魔外道以罪孽眼破坏佛法，以是为应令其自退！谛深2016，6，6日于途中应智安问！',
  ),
  (
    title: '谛深大师开示:什么是神通',
    date: '2016.6.5',
    body:
        '神通如何修炼？座下弟子及声闻善知识众，所谓神通乃指不用眼耳鼻舌身五根即可以意对六尘知之、为之、用之等之相！\n'
        '善知识，神通有三种，一者清净，是种神通一切无碍；二者共业，是种神通能于共业体相知晓尘缘；三者，应体，是种神通以罪业缘为用，离业缘不立！\n'
        '善知识，清净神通共分九品十二体相，需持戒修行方能梯次获得！是种神通乃持戒修行之表现，不持戒开悟者不能获得，譬如：开水沸腾，火为根本，沸腾为必然表象，清净神通亦复如是；共业神通共分两种体相，一者皈依受用体相，二者共业意用体相！是种神通体相，多以种种魔道、邪道、外道法修习而成，譬如假传密宗、基督中意象等神通表象即乃共业神通；应体神通多为邪恶缘分所成，以意态挟持为用！譬如：附体，即乃应体神通！\n'
        '善知识，是故，莫以神通为度，选择修行之道，当以戒为师选择道途！\n'
        '谛深2016，6，5日示！',
  ),
  (
    title: '谛深大师开示:什么是宗教',
    date: '2016.6.4',
    body:
        '座下弟子及声闻善知识众，今天有人问什么是宗教？佛教与其它宗教的区别，因是问为娑婆生灭之历程生活故，当为汝等讲说是意！\n'
        '善知识，佛法并非宗教！所谓宗教乃美丽说相为内涵，传承弘扬为教育之社会群体意识形态一致性活动之名称！宗教的形成共分为两种源，一种是意造源，一种是实造源！是两种源流传起始成：不同名相之，共同形态之妄想执着相体，如是相体形成宗教！\n'
        '是故，善知识，人类生活于有限意识中，对无限意识之认知，为妄想行为！譬如：蚂蚁爬至电脑屏幕，虽绞尽脑汁不能认知为用！人之于十方世界之认识亦复如是！人类于不能认知范畴下之种种假说、妄说、不思议说、狂说、用说、种种受体以妄想解授体说传承于世，形成共鸣体量，乃世界所有宗教之体！\n'
        '善知识，譬如：基督教，乃以妄说为源，成就妄意，以共鸣妄意为导洗脑大众，成就妄群！妄群既成，能为妄事，以妄想执着受用世界！因是妄想执着不断加入美丽梦想故，造就于己善用之群、之国、之世，以如是善用愚弄大众！令大众不能认知当知之世！更令大众脱离佛陀智慧慈悲救助，断灭慧根堕落三途！\n'
        '善知识，佛教亦复如是！诸佛世尊驻世不令成教，为表智慧！显示智慧！令大众修行得智慧，宣说种种法，令大众悟！\n'
        '善知识，一切宗教皆以故弄悬虚，编造美丽谎言而令大众所住世界自成美丽，如是成就各类宗教！善知识，佛法不思议，并非宗教相，若称为宗教，断灭佛种子，汝等当修行，莫入邪道体，难救难获福！善知识，若遇有人问佛教与其它宗教异同，以是为镜令其自退！谛深2016，6，4日示！',
  ),
  (
    title: '谛深大师开示:什么是精进',
    date: '2016.6.1',
    body:
        '坐下弟子及声闻善知识众，今天深夜11点，智安代群中声闻问，什么是精进？善知识，这是个常识性的问题，这与有人问什么是说话没有太大区别，但如果修行人，在参悟“念佛是谁”，照顾话头的过程中，参悟到什么是说话，并被障碍住的时候，这个“什么是说话”，就是修行问题，而不是常识问题。所以师父会根据修行人的现实状况，给与开示。\n'
        '师父很累，坐下弟子这么多，应该好好修行，在修行过程中遇到障碍的时候，可以问。如果不是修行中遇到的障碍，而是不懂这个词的意思，就是常识问题不是修行问题，问谁都可以解答，不用问师父。现在师父的眼睛因为长时间的疲劳，连手机屏幕都看不清了。所以善知识在遇到修行障碍的时候问师父，师父一定会给与解答。\n'
        '什么是精进，顾名思义，“精”就是于所道合，就是说在人的行为状态中，没有瑕疵，称为“精”。“进”就是前行与途，这是常识解释，师父劝诫弟子于修行途中精进勇猛，是指于佛法道合，并尽最大努力，尽早获得相应果位，这就称做精进勇猛。\n'
        '善知识，人生昂贵，寿命短暂，时刻精进勇猛，亦难到彼岸，何况放逸自己，所以汝等当精进勇猛修行，慎勿放逸。\n'
        '谛深2016年6月1日凌晨',
  ),
  (
    title: '谛深大师开示:什么是盗法',
    date: '2016.5.28',
    body:
        '善知识，所谓盗顾名思义，不予而取称之为盗！若予之而取，不称为盗！所谓予之共分两类，一类为直接予之！即：直接给予！另一类称间接予之！即：不用见面即可给予！\n'
        '师父所说诸法，为救大众，如同天降大雨，予之十方！是故，受师父之法不称为盗！师父所说各种秘密之法，并非不予之于大众！只因大众诸多罪重之者，因机缘未到，若予之会令其生种种罪恶之心，是故，需要其具受是种法时，再行予之！\n'
        '譬如：有人黑夜之中行至狼虫虎豹充满其中之山中一处，见远处灯火通明，眼前一微光小径通于灯火之处！并不时有呼唤之声，称赶紧上路来至明处！是微光小径实则乃于无底深渊之上，吾设一独木桥耳！远处之声乃吾呼唤其来之吾处，以脱离险境！桥下深渊其自却不知，吾告之大众，是人于深渊之上行于独木之桥，汝等当呐喊鼓励竭尽全力为营救之，令其速至吾前，但不令其知之其悬于万丈深渊之上！\n'
        '善知识，佛法末世犹如狼虫虎豹世界，邪魔外道错解佛法令大众痴迷如同万丈深渊！吾所说之一些法暂且不令一些声闻听，为不令堕落耳！是称之已皈依者可听，未皈依者不可听也！恰如不于身有残疾者前说瘸子事！若说，其必生心！若欲救皈依邪道之中毒极深之众，若于其前说邪法重罪，是人不仅不能得救，还会伤汝！当其于邪道中受罪哀嚎求救时，慢慢设救！\n'
        '善知识，吾所说法，除未皈依者因有重罪不当听者之外，所有法皆为布施大众予之之法！若大众引之、用之、广为弘之不称为盗！不令公之于非皈依者之法，若传称之为盗！谛深2016，5，28应声闻问！',
  ),
  (
    title: '谛深大师开示:皈依邪师与盲修瞎炼之罪',
    date: '2016.5.27',
    body:
        '今日群内有人问法，曰：既然佛说人人都具佛性，为什么有人能成佛，而大多数人没有成佛……\n'
        '善知识，是问乃修行大障碍问！因是问乃疑惑佛说之障思、之罪想者！释迦佛开悟时说，善哉善哉！众生皆具如来智慧德相，只因妄想执着故，而不能证得！\n'
        '善知识，因佛法末世佛法难遇故，师父当与汝等解说是事！\n'
        '善知识，譬如世间法中，人人都具获得诺贝尔数学奖的潜质！但，中国十几亿人至今无一人获得过这个奖项！又如：一幼儿问大学教授：人人都可以上大学，为什么那么多的人考不上大学！是意与汝之所问之如来说有异否？\n'
        '善知识，世间法尚且需终身学习方能有得，何况较世间法不仅难遇、且更为难思难解之佛法者？！何者称为佛法难遇？错解佛法令大众因信受奉行是错解后，未来不能知晓佛法，种断灭佛法种相故，称佛法难遇！何者称为难思难解？譬如：蚂蚁或老鼠爬到人之获得博士学位之书籍上啃食之后，有人以是，说是等获得博士学位！凡夫俗子以种种知见解释佛说乃至我谛深所说亦复如是，是称难思难解！\n'
        '善知识，世间法尚且需十年寒窗苦读，众生学习努力方能有所成就！何况凡夫俗子难思难解之佛法者？\n'
        '善知识，何故有罪者以是说疑惑之问？当知是问法者有如下重罪，一者为魔所缚诽谤佛法罪，二者愚痴妄说罪，三者恶叉不救罪！如是问者因汝于累劫障碍中，以障碍心问法故！\n'
        '善知识，譬如：有人砌墙，以遮风雨，因人很多，是故，墙亦砌了很多！过一些年后，由于时代变化，是种墙宇挡住新时代之需，因人不愿意拆掉故，是处发展甚慢！是故，是处有人埋怨为什么别处能建现代建筑而咱这个地方不行？\n'
        '善知识，汝之问亦复如是！汝之同类累劫以来诸多罪业成就障碍，不能破除故，令自己修行之路断掉！\n'
        '善知识，又如有人身患绝症，痛苦哀嚎，谓之曰：何故吾得此绝症而多众人无此绝症，实则，因汝本自重罪，不思悔改，却恨别人不公、天地不公故！汝以罪心学佛无缘遇法，是故汝有是种罪孽深重之问！\n'
        '善知识，修行之道，当入戒法，以戒为师入门再修，且勿皈依共鸣知见之邪道王，亦勿以自己罪孽知见乱解佛法！谛深2016、5、27呵斥！',
  ),
  (
    title: '谛深大师开示:为什么出家人要持戒！为什么以戒为师',
    date: '2016.5.23',
    body:
        '善知识，所谓在家人不能持佛制比丘戒律、亦不能持佛制樊纲菩萨戒律、亦不能持佛制沙弥戒律！何故是说？\n'
        '善知识，世界众生递相为食，转换为生！亦即：如若猫、蛇等众不杀食鼠类，鼠即成灾，主宰世界，断人生命！如是乃至若无刺猬蚁兽不捕杀蚂蚁，则蚂蚁成灾，最终殃及人命！等等！凡世间称其为生物链！众生物种数目若无平衡，人之无存！而人之杀生亦复如是！是故善知识，生于尘世若不依递相为食之相应娑婆众生轮转规律杀生，世界终灭！\n'
        '善知识，淫心亦复如是，若无淫心，娑婆世界众生不能为存！\n'
        '善知识，譬如：汝之喝水，水中细菌亦为众生，喝水即杀生！是故，若有人不离开娑婆世界，却称持佛戒，是为愚痴！若有人，欲出离罪苦，又不舍罪苦，称出离前导，称居士做！善知识，吾今为汝等讲说，佛制戒律之因、之缘、之果、之报！\n'
        '善知识，譬如：汝之喝水，水中细菌亦为众生，喝水即杀生！是故，若有人不离开娑婆世界，却称持佛戒，是为愚痴！若有人，欲出离罪苦，又不舍罪苦，称出离前导，称居士做！善知识，吾今为汝等讲说，佛制戒律之因、之缘、之果、之报！\n'
        '善知识，佛制三坛戒律皆如是之制，若出家需持，不持不称出家，称罪孽做，称大愚痴；在家不能持，若在家持，必被伤害，亦称大愚痴、坏佛种大罪孽做！\n'
        '善知识，所谓以戒为师，指：持佛戒之比丘，乃从罪恶尘世出离行之人，其经过发心、初行、中行、后行，获入佛之天龙八部护持之地，上接如来、下接罪苦众生，是故可为罪众之师！率众修出离法！\n'
        '是故，善知识，在家居士当受居士之戒！居士之戒称为当处小戒，比丘之戒称为大戒！因居士只受五戒、十戒、四十八戒，与比丘之二百六十戒、四百一十三戒，梵众应转之七百圆满戒比，称小！而每一戒之差别亦称小，是故称小戒居士！\n'
        '譬如：居士受之不杀戒，只不故杀，即为不杀！比丘所受之不杀戒需不故杀、不见杀，见杀即坏！而梵众圆满之不杀，乃不知有杀、乃至闻有杀名、见有杀字，即为坏戒！善知识，所谓不淫亦复如是！居士不淫，不能与妻子之外女人行淫，是称居士戒不淫；而比丘戒不淫，乃至不与女人非救护语；应转圆满戒，则不知有女人，女人不知男女别、不知自己为女人！若知即坏！是故，比丘戒称大！\n'
        '是故，出家人需持佛制戒律！现前无佛以戒为师！善知识，切勿乱讲戒律、乱用戒律！当依诸佛所教！当知、当受、当解、入法修行！谛深2016，5，23日为新入门弟子示。',
  ),
  (
    title: '谛深大师开示:不要错解因缘果报',
    date: '2016.5.20',
    body:
        '善知识，关于因缘果报，有诸多未悟讲说，自迷迷人！\n'
        '师父今日为汝等简说因缘果报！以令有悟！何故讲说是事，汝等不闻百丈老人救度野狐之事？一僧人因错参因果，死后落500年野狐身！何况凡夫乱讲佛法、乱说因缘果报！是故当说！\n'
        '善知识，所谓因缘果报，乃十方世界存在根本！种种心生种种法生，种种法生种种心生，种种心种种法相互为应，应之称缠，生之称缚，缠缚成段，段之个体依法为用，成就世界，世界生心，吸纳心用段连成体，体成众生，是诸等缠缚，其相名曰因缘果报！\n'
        '善知识，生老病死，皆依附于因缘果报辗转为之！\n'
        '善知识，譬如以面为食，其段因为面，以水、盐、及诸多辅料为缘合和成团，置之火之器具是称缘之，缘成之后，成就饼物，是称果报！\n'
        '善知识，十方世界、器物含灵之山川草木，虫鱼鸟兽无非如是，皆因缘果报！\n'
        '善知识，虚妄成体，体应诸心，宽泛分别，分别成相，相缠濡替，识心穿越，成就众生！以是分开含灵器物！所谓器物世界因缘果报以心为造；所谓含灵世界因缘果报心性为体！\n'
        '善知识，切勿妄解因缘果报自寻堕落，害人害己！汝等当以佛为师，现前无佛以戒为师，获早离苦。 谛深2016，5，20日示',
  ),
  (
    title: '谛深大师开示:不舍一求道者',
    date: '2016.5.18',
    body:
        '善知识，为什么不给过五十岁的人受戒？\n'
        '因为人之寿命分三大六根受用部分，第一，少年部分，1到22岁之间，诸根未成，正生长期。这个时期入佛门修行能于生长途中，改变前世缘分延续，成就佛法各种果位基础！善知识，譬如：果木，虽种子已定，或苹果、或桃子本性不能为变，但，能于幼苗做种木嫁接，令其变成新品物种，并改良之！善知识，佛法度众之年龄规范亦复如是！年少可期，易于教化，奠定基础！于年少时受佛法熏染，乃大善者！\n'
        '第二，青壮年时期，23至50岁时期，六根正盛，若与浇灌维护，易于修道证果！譬如果树，园丁勤恳浇灌，能产美味果实！佛法授戒讲法救度大众亦复如是！人于青壮年时令授戒闻法，能获修证果位！\n'
        '第三，老年时期，51岁至70岁之间，六根逐一退化，至不能为用！眼根花变难于阅经，耳根变聋难于听法，鼻根舌根退缩不利辨味分，身根落魄难于行道，意根虚脱不能锐思记忆等，是故，年过四十不与授圆满戒，年至五十最多予其沙弥戒。\n'
        '第四，71至寿终正寝为转期实为，不能以学修为做，可以信第四，71至寿终正寝为转期实为，不能以学修为做，可以信心教之成种，恰似变换基因令种性变，来世为道！心教之成种，恰似变换基因令种性变，来世为道！\n'
        '第五，半路夭折获被横祸则于本世不能为救！\n'
        '善知识，若人已过半百，当思师父所教，或于因缘思佛所教化获应当报！善知识，诸佛世尊不舍一众生求道，乃至临命终时一念转或！是故，诸佛与广大声闻开结缘门，令大众无论年老长幼皆可皈依，以令年幼者获成道缘，青壮年者获成道果，令老年者获来世种！\n'
        '是故，善知识，汝等当于当处年龄修当处法，莫于年老时段修年少法！吾谛深将于汝之当处年龄授于汝等应所道！\n'
        '谛深2016，5，18为老居士求道开示',
  ),
  (
    title: '谛深大师开示:正反两方面是不正说！先有鸡还是先有蛋',
    date: '2016.5.6',
    body:
        '坐下弟子及声闻善知识众：很多年以前就有人问净居寺的僧人，应问僧人XX因愚痴罪孽故，称佛住世时不让问类似问题！实佛并没做如是开示，乃罪众出家为表狂妄故做如是说！\n'
        '善知识，是种问题，师父于当机处已做讲说，前几日因有人问及是事，师父已有开示，因弟子中有人不知故，今者师父再为汝等文字开解如是之问！\n'
        '善知识，鸡与蛋是一起有的！众生共分胎生、卵生、湿生、化生四类！而每一种众生，都有这四类生处体！鸡也一样！目前我们地球人用科学所知道的只有胎生与卵生这两种体相，所以，在先有鸡还是先有蛋之问中糊涂！是问有诸多不明盲说，诸如：先有蛋需受精蛋才能生之；先有鸡亦需一起有公母两鸡才能传之！实则，众生之起始说本自虚妄乱想，以见为证，称证为实名称科学，以是为最，坏佛种子，实乃愚痴罪孽之无始狂为，实乃为业识做，毕竟罪缠！\n'
        '善知识，更有罪众以贼心、迷心、狂心、妄心出家，不求道法，却被法服，以法师号，诓骗为道，坑害大众，是等为波旬子孙，信之遭堕！\n'
        '善知识，有人以正反两方面之辩证论看问题，实则不正！比如圆球高速运转则无正反，原子分子亦皆无正反，随转之有相，前后有相，虽亦有反之，更有善知识，有人以正反两方面之辩证论看问题，实则不正！比如圆球高速运转则无正反，原子分子亦皆无正反，随转之有相，前后有相，虽亦有反之，更有不动相，是等皆无有正反！即使地球之相、太阳之相亦皆无有正反！云何有人以矛盾、辩证说世间本，诽谤佛法？云何有贼道，假佛经典辩论为本称活佛名？实乃罪众愚痴狂为以为道耳！不动相，是等皆无有正反！即使地球之相、太阳之相亦皆无有正反！云何有人以矛盾、辩证说世间本，诽谤佛法？云何有贼道，假佛经典辩论为本称活佛名？实乃罪众愚痴狂为以为道耳！\n'
        '善知识，佛法不以种种所知、所见、所闻、所明、所有、所无为道！不以种种规律之证为道！佛法之道不能以十方众生之所有知见思议！佛法非大众能思意少分！\n'
        '善知识，譬如：蚂蚁王竭尽群族力累世共思意人之科学事，不能知少分！佛法亦如是！假若满世间皆为观音身，若于佛智慧，不能有知晓！是故，观音说，我为佛之子，承佛之托付，慈悲大众故，住世为救度！不说观音主！\n'
        '善知识，十方世界乃至每一微尘，皆佛之智慧化现！勿如缸中鱼、瓮中鳖不尊主人，狂妄为道，主去自灭！\n'
        '善知识，吾谛深再劝汝等，以佛、以戒为师求道获救！勿以种种智、种种道、种种说、种种知、种种神、种种通为道求出罪孽，更何况种种相！善知识，祝汝等佛住世时，以佛为师；佛灭度后以戒为师，早出苦海！2016，5，6日应弟子问！',
  ),
  (
    title: '谛深大师开示:阿弥陀佛名号',
    date: '2016.4.28',
    body:
        '（群中有人问：大家都在念阿弥陀佛，为什么有的能往生，有的不能往生？）\n'
        '座下弟子，阿弥陀佛名号于不同世界有不同名号，乃至于一世界也有不同名号，乃至不同名号之下有不同发音。譬如有人，生来有乳名、青年有大名、上学有外号，虽各种称谓不同，实皆其一人也。阿弥陀佛名号于诸多不同称谓皆阿弥陀佛本尊亦复如是。\n'
        '善知识，何故有人同修同念阿弥陀佛，却有的能往生、而有的不能往生者，因所念之人虽皆称阿弥陀佛名号，但应者不同，有的是阿弥陀佛来应，有的非阿弥陀佛来应，乃邪魔外道来应。何故是说？\n'
        '阿弥陀佛名号，于不同世界，有不同应体，也就是说虽皆为阿弥陀佛语言称谓，但所指本体不同。譬如：中国话中，路西是指路的西面，英语中的“路西”是指透明的意思，而“路西”还指人名，没有意思。是故，当有人在中国称路西的时候，人们以为是指路的西面，在国外的时候，人们以为是指透明。是故当人们念阿弥陀佛的时候，因自己的因缘不同，最后所成的果报也不同。\n'
        '善知识，十方世界之中，释迦牟尼佛弟子称阿弥陀佛，乃极乐世界阿弥陀佛本尊是也，有世界称阿弥陀佛，乃大树也；亦有世界称阿弥陀佛，乃山丘也；亦有世界称阿弥陀佛，乃水粉也；亦有世界称阿弥陀佛，乃白云也；如是等等，无量无边无数阿弥陀佛名号，乃无量无边无数之人之物等等称谓。\n'
        '是故善知识，入佛门修行，莫以罪孽障碍为应，当知凡有言说皆无实义之本质也，当知凡有言说皆有实义之本质也，当知虽一称呼有万千差别，当知万千称呼一门超出。\n'
        '善知识，莫于种种邪魔外道，以愚弄大众故假佛所说法诓骗众生，当知佛所说法皆当机说、当意说、当因缘果报说。\n'
        '善知识，云何有人，错解阿弥陀佛四十八愿，错解无量寿经，以是称法，称末世唯一救众之本，自己愚痴又愚昧他人之做也。\n'
        '善知识，汝等当知，戒律为修行之道，非说非不说，道为其本。是故佛说：佛灭度后以戒为师。善知识，若于佛法末世，若有人以某种法、某种名、号称佛法者，当以是为镜，令其有悟。谛深2016,4,28日应弟子问示。,4,28日应弟子问示。',
  ),
  (
    title: '谛深大师开示:勿修断法灭知见',
    date: '20谛深大师开示:16.4.26',
    body:
        '所谓断法诸用皆为邪魔外道相，若要出离苦海，不于种种法说断相、灭相、修行诸相，于法不说断灭相。于法说断行、灭行、修行诸相者，乃修行遇障，不能开悟，为障所累，罪业所表。称修断法者，随断法罪于累劫地狱恶鬼畜生界受诸多劳苦重罪而不能出。譬如：地狱恶鬼畜生所思所用之物，皆为修断法者成，是故大众切勿入是等邪魔外道修道大坑，令自己堕落，汝等当知断法如断首。\n'
        '善知识，鬼道中有一鬼王，因与累世佛门缘分故，于离垢佛住世时，曾受佛之布施，以花掩项跪问佛曰：我何故无首？佛曰：汝于吾有意佛法末世，为人修行时，愚痴故认断法魔王为法师，于其座下为灭执见修断法，成就断法魔王果位，布施断法魔道，诓骗大众，福报享尽，堕落成无头鬼。汝当于十万亿大劫中修有法、住法并受法中苦，方能在十万亿劫后获得有头之身。无头鬼王因无头故不能顶礼，自尽其身谢佛，并于万亿劫中护持佛法，获法行王果位，其缘分大众随其修道，不敢妄称法与非法，十万亿劫后获得有头之身，有头之后修头陀行，成度天人菩萨。\n'
        '善知识，亦有无头鬼王与佛缘分浅薄，因修断法堕落成体，至今受罪难有出期！故，当以戒为师，修诸法门！莫以神通等相为导，落于魔掌，于非佛说法中自行其道；善知识，莫以种种邪魔外道法布施大众，做重罪堕落因缘，当以佛之戒律为师，修诸法要，方能成就。谛深2016、4、26日应弟子代修断法声闻问！',
  ),
  (
    title: '谛深大师开示:什么是执见',
    date: '2016.4.17',
    body:
        '所谓执见是指人之诸业所成转世缘分所表之本性，之对眼耳鼻所见事物之反应！所谓执见差别，是执因诸业所成因缘差别依所见事物所表之见差别！\n'
        '是故善知识，人之种性千差万别，对事物之理解受用亦千差万别！\n'
        '善知识，所谓知见是指自性执见用后所得！\n'
        '善知识，凡夫俗子之所以是凡夫俗子，而难以证圣，只因自己执见成就见地范围坚定,知见不能突破故！是称执着于迷途不能有拔！是故，修行之途，于如来说法时当放下执见，受用佛说；于邪魔外道法处，当坚固执见以避魔着堕落！\n'
        '善知识，莫于未悟时以某种法自以为是佛法者与人解说，若说即堕落邪魔外道遭罪苦缠敷！\n'
        '善知识，于释迦法末世，当持戒修行，熏染梵众天道，成就梵种，获得出离道途，以有救！莫于种种佛之名相、种种法之道相，以自己执见讲说，以自己执见鉴别所传，以相似执见受用所传成相似知见,成就共鸣执见法，以共鸣知见成就罪孽法道，以是成就邪魔外道体相妄称佛法，并弘扬传承如是之知见讲说修成堕落！谛深2016，4，17应弟子问',
  ),
  (
    title: '谛深大师开示:何为梵行',
    date: '2016.4.16',
    body:
        '若知所谓梵行，当知梵行出处。梵行出处来自梵众天，梵辅天。所谓梵行是指以梵众天人心性做规则的行为方式，这种行为方式称为梵行。\n'
        '善知识，因六道轮回种子依据众生熏染所成习业成种，是故，佛菩萨住世，均令弟子熏习成佛所需所应不同层次福报天之种子，以令弟子步步成就。譬喻梵众天与相关天中极乐世界。\n'
        '所谓梵众天，乃卢舍那佛座下修证圆满报身之一层天，是娑婆世界修证千百亿化身之因缘天，是十方诸佛开示大众，领大众修证了义清净法身之道行天。是故十方世界广大众生皆以修行梵行者为师，入门学习修道入各自缘分之种种佛住之天。往生第一层极乐世界之大众随阿弥陀佛修行，最终亦需往生梵众天修梵行，才能修证佛之报身果位。有诸多极乐世界修道大众受弥陀引导，于诸层升至高一层极乐世界，需经数十劫乃至亿劫。念阿弥陀佛一心净念，需得初级梵行加持，若没有初级梵行就是菩萨戒与沙弥戒，是往生不了极乐世界的。\n'
        '善知识，梵众天与极乐世界于无量意处有互通界，能令修至佛之三身果位者直至梵众天，转而成就圆满报身果位与千百亿化身果位，等正觉，明行足，善逝世间解，无上师，调御丈夫天人师佛世尊，赴当土成佛。梵众天亦分多种层次修行果位。\n'
        '善知识，娑婆世界虽五趣杂居，诸罪相缠，因此乃释迦摩尼佛舍身成就之佛土，亦有众生能于罪孽相缠之国土中成就佛果；更有大众，听佛号令，修行梵行，念倾往去梵众天听自己因缘诸佛教诲，修证佛果；亦有众生，罪孽深重，不能严修梵行，但能于梵行修持一二，十分一百分一千分一乃至万分一，于是少许梵行中，精进念阿弥陀佛，便能在舍弃罪业时于当处获弥陀四十八愿接引，往去阿弥陀佛极乐世界，培植功德福报，获得梵行。\n'
        '善知识，有关梵众天，师父于此不多做讲说，仅梵众天种种道行界，就有无量之多，每一道行界均有是界梵众天经典记载，是中只有一部由释迦佛依据娑婆缘分传于娑婆，娑婆世界大众知之甚少，因不修梵行，不当知之故。\n'
        '善知识，当以佛所说，持佛戒律，精进修行，方能修证了义诸佛所说。\n'
        '谛深大师口授开示应群中声闻问，弟子智贤智慧智依记录2016，4，16。',
  ),
  (
    title: '谛深大师开示:如何看待佛门护法',
    date: '2016.4.14',
    body:
        '座下弟子及声闻善知识众：所谓护法有三种体相。\n'
        '一者，护持施法、用法体相，\n'
        '二者，护持应法、受法体相，\n'
        '三者，护持法生、法灭体相。\n'
        '所谓施法、用法体相，指法布施者与用法者所应因缘；\n'
        '应法、受法体相，指应法者与受法者所应因缘，譬如，教师与课本等乃施法用法者所应因缘之喻。学生与所造机械乃应法、受法者所应因缘之喻。\n'
        '所谓法生、法灭体相是指法生因缘与法灭因缘所应缘分体相，譬如，建筑设计与数字进位规则称法生因缘，图纸变成建筑与计算机软件成体称是法生缘分之灭因缘缘分。\n'
        '所谓种种护法，当以譬喻令汝等有悟。\n'
        '善知识，种种法：佛法、魔法、善道法、恶道法、正用法、邪用法乃至虚妄乱用法等等，皆有相应天龙八部与种种鬼神之菩萨、天神、恶神、乃至种种应法众生相应护持。\n'
        '善知识，譬如恶狼凶残，伤害有生乃至威胁人类，然，其依然受狼父狼母博爱有加，善软为救，忠心护持。之于狼崽其父其母实乃大爱大善为之。\n'
        '是故，善知识，善有善使，恶有恶应，十方世界六道众生，善恶相济，不能分离。\n'
        '善知识，所谓菩萨护持与魔道护持之别，譬如，人之军队护国与狼虫虎豹护群之比，狼虫虎豹之群，虽为凶残 ，若其有员攻击人员，虽受狼群护持，必遭人之相关部员之剿杀。\n'
        '是故，善知识，若汝等信受佛法，依佛依律，入道修行，则必受十方诸佛法脉相应之菩萨，大智大慧，大慈大悲，大行大力，梯次之，恰应天龙八部乃至相应鬼神之护持，若汝等修行，误入歧途，亦会遭邪魔外道加持，成就相应罪孽缘分加持护持。\n'
        '善知识，汝等亦是护持汝之自己缘分之护法，若信守所传不正，则落旁道，于未来世受诸罪所缠，落于尘途，不能为救，罪苦缘分自迷中去；汝等若欲获救，须当入戒，出离果位自戒中来。\n'
        '谛深2016.4.14日应弟子问护法事示。',
  ),
  (
    title: '谛深大师开示:法师是什么',
    date: '2016.4.1',
    body:
        '坐下弟子及声闻众：所谓法师，顾名思义，是教佛法的老师，简称法师。由于佛法极其难证，所以，只有证得佛法的人，以佛说传承，依佛所嘱，令弟子们听佛所传法要、经典，按佛说的去做，成就佛子佛孙，是称为佛门法师之用。不是什么人都能称为法师。法花经中的法师品不是任何人能看，看后可用。只有戒圆满了的人能看，听此号令能做法师。若戒不圆满，以为佛法，遭大堕落。譬如：高空跳伞，前提是身上背着伞的人按指令跳，若人身上不背伞包，按指令跳，即为堕落。\n'
        '所以，佛说：佛灭度后，现前无佛依戒为师，只因佛法难证故。所以，戒是佛法之表，得戒传戒者，以佛所传弘扬称为法师。若有人证得佛法，诸佛来应，称为导师。\n'
        '若有人，戒有缺漏，以自己知见讲经说法万言，以为佛法，令大众丢失戒律，大众以其为师，这个人就是波旬住世。\n'
        '若有人，崇拜法师，他就着魔了！\n'
        '所以，大众不要执着法师名相，应依戒选师。谛深2016年4月1日示。',
  ),
  (
    title: '谛深大师开示:修行靠谁',
    date: '2016.4.1',
    body:
        '坐下弟子，先看谁修行。每个人要修行，是自己要修，所以，修行根本是自己，既然修行根本是自己，那么修行归根结底靠自己。\n'
        '修行过程需要路，这个路你走下去的每一步都有种种因缘，这个因缘里面有自己的老师，有自己的罪苦，有种种邪魔外道，等等，师父仅仅就是你这些个缘分中的一个点，未来你成佛的一个组成部分，如果你执着在某一位真正的师父身上，会掉进大坑。所以，师父不允许弟子着师父的名相。\n'
        '当然，一个修行人，碰到的师父修行果位越高越好，因为那样，你的修行之路就会更平坦。若佛住世，拜佛为师，当然最好，因为那样可直接成就。所以，普贤菩萨十大愿望中心，是请佛住世，并行供养。若有人不持禁戒，你称之为师，必为堕落之修。不管什么人，哪怕佛之再来，也必定戒定于世，因为，无戒法遭灭。\n'
        '望弟子们以戒为师，早证佛果。谛深2016，4，1日示。',
  ),
  (
    title: '谛深大师开示:在家菩萨如何供养',
    date: '2016.3.31',
    body:
        '坐下弟子及声闻：\n'
        '五浊恶世善知识难遇，佛更难遇，释迦佛法末世，邪魔外道盛行，佛门之中未证谓证、未得谓得者坐佛法坐，令佛法变意故，佛法甚难闻。是故，在家菩萨发心供养，发心请佛住世，若认假为真，即落魔民。\n'
        '善知识，若以在家身，欲做修行人，当学善才童，多行参拜法，以戒为导师，寻求己之缘，以佛之嘱托，行诸供养法，戒如大明灯，能做指路人。若以自执见，指引做供养，必为魔所获。如来住于世，皆赞清净者，无戒不清净，当做如是行。\n'
        '谛深2016, 3, 31',
  ),
  (
    title: '谛深大师开示:令皈依大众成道',
    date: '2016.3.24',
    body:
        '坐下弟子及声闻善知识众：佛法真实不虚，然，因末世罪孽魔主入于佛门，为名为利，以共鸣知见广为假乘演经、演密、演教，演修等，成欺骗道，令大众皈依堕落故，吾谛深为汝等或说戒、或予法宝、或临于面前剥离，破是等魔障，令大福报者，留下佛种，或令入我门下，以如来法，直成就诸等果位。\n'
        '善知识，若有人于佛法笃信，于我缘分甚远，必能持佛说戒律，获得出离法，或于当世，或于未来世成道。\n'
        '若有人于佛法笃信，至我坐下，吾必于本世令之有证，或直接成道。\n'
        '善知识，吾谛深于本世缘分，将为坐下弟子设三转殿，设禅定处，亲临引导，令是等得证佛之妙果；为声闻弟子设阿弥陀佛极乐转处，以弥陀愿力令如是缘分等有救。\n'
        '声闻善知识，听吾谛深劝言，以戒为师，十方诸佛为之救度。切勿听邪魔波旬穿吾佛衣，以汝所应为应，善说善道令汝等堕落，罪至深处，不能自拔成大罪本，累劫难救。\n'
        '善知识，汝等当乘佛戒律，以证佛说为导，导自修道，莫于戒律荒废中，以法师说、种种令汝不能自拔之道理说为导令自堕落。是称：自性众生誓愿度者。\n'
        '谛深祝汝等如佛说修行，早成佛果。谛深2016，3，24日应弟子问示。',
  ),
  (
    title: '谛深大师开示:如何广修供养',
    date: '2016.3.22',
    body:
        '坐下弟子及声闻善知识众，师父再三讲说，出家不收供养，那么为什么普贤菩萨的十大愿望，讲要广修供养呢？\n'
        '善知识，所谓广修供养，是指供养诸如来，与如来坐下持戒之修道弟子。供养物中有七宝与道场常住，僧人衣物、粮食及生活必需品，及财物。\n'
        '如何广修供养，若有如来住世，则应全身心供养，请佛久住，若现前无佛，当以戒相供养。若寺院中行，多于佛像做捐建。\n'
        '善知识，切勿乱施乱供。乱供害人害己，若僧人切记：十方一粒米，大如须弥山，吃了不了道，披毛带角还。如若，不信因果，是等当知，不信因果就是不信佛，都不信佛了，你还供他干嘛？因果不昧。谛深2016，3，22。',
  ),
  (
    title: '谛深大师开示:不要上当受骗',
    date: '2016.3.22',
    body:
        '坐下弟子及声闻众，今吾出家弟子智蓉，被人假称警方，设局诈骗，智蓉被骗，后，师父亲赴，令报警结局。\n'
        '善知识，佛法法界内，种种法师、种种寺院，若不持戒律，以讲说佛法、治病救人为依，求大众供养、施舍，或以之化缘为要，皆假佛诓骗大众，令皈依者耗散家财，入于歧途。\n'
        '善知识，谛深再告诫于汝等，入于佛门，以实证佛说，渐次为导，若无实证佛说，当以戒律为导，仅听演说善语即皈依供养，实则入诓骗道。\n'
        '善知识，大凡骗局皆以语言编造，假以“编造事例”或以魔术，令听者信。汝等当知，入于佛门，若汝等不能实证佛说，其必为邪魔王。\n'
        '是故，善知识，释迦牟尼于金刚经云，若人说我有法可说，是人则为谤佛。楞严经云，凡有言说，皆无实意也。\n'
        '善知识，谛深不欺诓，汝等入门当以实证或戒律为导，听如来语，莫以名声传闻，某法师名号为导，听其柔软善语以为佛法，若听，即落大坑。\n'
        '善知识，切勿于佛门上当受骗。谛深，2016，3，22日示。',
  ),
  (
    title: '谛深大师开示:无钱谁当和尚',
    date: '2016.3.22',
    body:
        '广大声闻：僧人皆无钱，有钱非僧人。无钱者亦不一定为僧人。是故，若有出家人与汝等收取种种名义钱财，其非佛门出家人。\n'
        '大众，出家人以戒律之受，信守如一为鉴别证，并非以衣服判别证，亦非以戒牒为鉴别证。\n'
        '大众，切勿以名声判定修行。无钱，贤圣当和尚。谛深，2016，3，22日示。',
  ),
  (
    title: '谛深大师开示:如何修供养(第四品)',
    date: '2016.3.22',
    body:
        '善知识，如何修供养，师父已经简说多品，因大众因缘有别，故，再为讲说一品。\n'
        '善知识，什么是供养？所谓供养是指以三宝所需，为之提供，以令三宝久住。提供者，以是获取三宝因缘，成未来大福报果。提供者，称之供养。\n'
        '善知识，供养佛法僧三宝，之一，供养佛宝，所谓供养佛宝，是指：为佛提供传承之地、之物、之相，譬如：如佛所说之寺院等。为什么说寺院等？因为：若遇佛住世，请佛住世，以种种宝物供养之，是为供佛之最。另外，焚香、供宝等均称为供佛。\n'
        '之二，供养法宝，为佛印发各类佛说经典，弘扬佛所说法，令法久住，称为供养法宝。若有人，以自己所解各类经典，以自己名号冠，广为传说弘扬，是为诓骗戏，为波旬住。\n'
        '之三，供养僧宝，所谓僧宝乃依佛所传之戒律为本，之修行道人。因僧宝为传承佛法之主，能率大众，为大众消去修行障碍，率大众出离罪苦，是故，当供养之，称为供养僧宝。\n'
        '善知识，若人以公众认知之僧人之相，却不持戒律，或以自己知见解说经典，后受大众信施，或以大众信施为本，行敛财道，是波旬化身破坏佛法行诓骗之为，大众当谨慎鉴之，切勿因此堕落。谛深，2016，3，22日示。',
  ),
  (
    title: '谛深大师开示:妙湛寺为什么封掉帐号',
    date: '2016.3.20',
    body:
        '坐下弟子，师父不允许任何人，以任何方式，借兴建寺院广纳钱财。为结善缘，建设妙湛寺，设时纳香缘，所谓时纳香缘，是指过时不用，譬如过午不食。佛法信施戒律为之，若无戒律，即为诓骗。是故，不是每个僧人都能收受救度信施与大众结缘，令结缘者入出苦道；不是什么情况都能收受信施与大众结缘，令结缘者入出苦道。若有人、有鬼神，以种种名义乱收信施，当世断灭累劫佛种，其罪不赦。佛制戒律，沙弥戒即断财受，不沾金钱。\n'
        '善知识，师父公布如下信施规矩，以令末世众生有救入有救出苦道：\n'
        '收供养缘分\n'
        '1、若有出家比丘，能于所受戒律严净，戒腊12以上，无一漏缺，可于当处结缘，纳大众信施，转为救资。\n'
        '2、若有出家比丘，不持所受戒律，乃至有一戒缺漏，不能收受大众信施。若受，即成诓骗，或入有漏缘法，于未来世于于漏处，令大众堕落。\n'
        '3、若有人未入毗尼法，身着僧衣，或有人假称佛法等建设寺院，或以信缘建设寺院，或以信施经营寺院，或入于寺院，大众因地域因缘故，广为支持，成信施缘分或世间攀缘缘分。是等场所，均为罪孽波旬应，乃为波旬与子孙住持处，结缘信施者，直入魔坐下成堕落道。\n'
        '4、若有人，因财富故，建设庙宇、寺院模样，塑佛形象，聘请僧人住持，是等，非佛法寺院，若以是称寺院者，报尽堕落，不能为救。\n'
        '坐下弟子及声闻众，若想求道，或生极乐，莫以钱财为用。吾谛深能讨饭，汝等一样能讨饭，是为净行一用，能救大众；吾谛深能上坡、行香、站香不受一财延佛寿命，汝等一样能种地、行香不受一财等延佛寿命，是称净行一用，能救大众。\n'
        '善知识，妙湛寺建设时，为令缘分大众结道缘故，只以相关用物时、以时结缘，过时时灭。是故，妙湛寺已将时段缘分账户挂封，不再为用。若于大殿请立佛像时段，再设缘分。谛深2016，3，20日示。',
  ),
  (
    title: '谛深大师开示:不要与饥人说食',
    date: '2016.3.19',
    body:
        '善知识，现在有诸多僧人以自认为法说之为乐；诸多罪人因罪入佛门转而自以为法，说与大众，更有罪人一生研教立身，广为演说自己所见与大众共鸣，或假僧相广为论著，令大众信而盲从。是等，乃佛法最不能救之者。\n'
        '善知识，现在有诸多僧人以自认为法说之为乐；诸多罪人因罪入佛门转而自以为法，说与大众，更有罪人一生研教立身，广为演说自己所见与大众共鸣，或假僧相广为论著，令大众信而盲从。是等，乃佛法最不能救之者。\n'
        '善知识，佛法与如上比喻之食物，更为难得，实证者，从释迦时，至于现在凤毛麟角，极其难见，云何却有诸多罪人以自己所解，以善恶说，以世间博士、佛门法师名号，洋洋万册，敢称佛藏？胆大耳、愚痴耳、累劫不能被救也！\n'
        '善知识，吾谛深实言告汝等，修行之道，依戒依律，跟从有证之者，实证为导，切勿人云亦云，盲从盲信，以说为食，以为法喜。\n'
        '善知识，师父不与汝等讲释迦经说释迦法，因是事释迦牟尼如来，等正觉，无上士，佛，世尊已说。因末世大众罪孽法故，师父补施成末世罪孽业中之路，说出离罪苦之径法。\n'
        '善知识，切勿以说为师，乃至吾谛深之说。谛深2016，3，19日示。',
  ),
  (
    title: '谛深大师开示:什么是使无畏',
    date: '2016.2.21',
    body:
        '坐下弟子及声闻善知识；佛门诸圣中，有使无畏菩萨，而使无畏菩萨之法，今当为众讲说，以令罪重之者，不能于佛制道场破坏使无畏法。\n'
        '善知识，所谓使无畏法，乃令大众无畏，若有人打着戒律旗号，令大众因听生畏、因见生畏、因知恶生畏，等，是称使人畏惧罪，是罪为修道重罪之一，为破坏佛法道场之地狱因罪。\n'
        '善知识，若有人见罪说罪之当报之实证者，是称救度。若有人见罪，将所见之罪说于无见之者，称为使罪于人，断灭善种之作。\n'
        '善知识，佛门非有罪者能传，譬如：有人喝甘露时，汝与之说喝粪之感，是人必断纯甘露缘。若有人喝粪，汝当与之说喝粪之臭。\n'
        '当今诸多罪众，不知佛法，却处处以重罪之见于佛门兜售，实如于甘露门兜售大粪，令甘露门染臭。\n'
        '今日弟子群中有人以诛杀之相说于佛门戒律亦复如是。佛门本无杀染，因汝等传播诛杀之相而遭杀染，汝等有重罪。\n'
        '善知识，佛制戒律，非不识戒之根本者能传，是故汝等当于得戒者得戒后，以智慧传。\n'
        '佛门救度大众，于作恶处说恶报，于做罪处说罪报，不于无罪处说罪报，更不于无恶处说恶报。谛深2016，2，21日示。',
  ),
  (
    title: '谛深大师开示:人生之苦',
    date: '2016.2.21',
    body:
        '坐下弟子及声闻善知识众，人类以种种科学令社会进步，但，解决不了根本问题：人生的五大苦。\n'
        '人生具：生、老、病、死、离五苦。所谓生苦，是指人生之始其苦甚重，痛楚难言是称为苦；所谓老苦，是指人之老变，令躯体难以为用，风光不住，用与意相悖，恰如梦境落悬，不能自助，是称老苦；所谓病苦，是指众之常态，遭受逆因，疼痛交加，是称病苦；所谓死苦是指，众生不知死后何物，以死为变灭，诸多生之所取、所愿、所知、所享等等所求一并消散，是故恐惧之至，加之死苦多于生老病离诸苦相连，是故称之最苦；所谓离苦乃合而分者，所谓合而分者之苦，愈合，若分极其苦堪。若不合，则无离别之苦。是苦，分眼耳鼻身意五种合而分苦，若是五种只一种合而分者，其苦为一，若二若三，若五种皆合而分者，其苦胜死。是故，有夫妻分者以死而抗。\n'
        '善知识，佛法殊胜，当持戒律，入如来蔵，方能脱离是等苦楚。谛深2016，2，21示。',
  ),
  (
    title: '谛深大师开示:佛法不是美丽的谎言',
    date: '2016.2.19',
    body:
        '坐下弟子及声闻善知识，很多所谓的名僧、大德、大师、法师，以种种善说、种种神通、理说解释佛法、传承、弘扬自己知见而非佛说清净法之实证，是称善心欺骗。\n'
        '善知识：譬如诈骗者所说，皆令听者听之为实，听之为善、听之为好，是故信之以为能得，于是上当受骗！\n'
        '佛法弘扬传承亦复如是，诸多以种种手段、种种神通、种种道理、种种善说、种种善做，令大众信，而非佛所说法实证之为，乃至于道场修为、建立道场率众修为以为佛法，实非佛说证之者，皆为最终成诓骗道令大众受骗堕落，无有能救之善说。\n'
        '此，以称之美丽的谎言、真实的谎言。\n'
        '是故，佛法末世寺院，出家之众，因诸多皈依是种谎言，不能证得佛说殊胜清净境地故，丧失佛种，成堕落体。以是因缘佛法末世道场，显逐名逐利法相，蔑视佛制戒律，而令佛法实成就魔道。\n'
        '善知识，佛法不是诸等宗教所宣示的：美丽的谎言。更不是以种种神通、种种世间法实证善说宣教的、真实的谎言，是故师父出世，为令大众后五百岁有救。\n'
        '善知识，汝等若出家以是种说入道，当知入堕落道。当以戒为戒，方知正途。谛深2016，2，19日于匈牙利。',
  ),
  (
    title: '谛深大师开示:修行不讲地位',
    date: '2016.2.15',
    body:
        '坐下弟子及声闻善知识众：\n'
        '修行人需认识两种既成心性，一者六道所成攀缘心性；二者清净世界虚妄立相求所成求自清净之修道心性。\n'
        '善知识，六道心性轮转有道，诸法随心起，诸心随法显；诸法生诸心，世界如是。是故，佛门修行者不讲地位，世间大众修道不修出离者，讲究权势地位。\n'
        '今者，遇有一会长讲究地位故，特为吾弟子宣示，佛制戒律中所称尊重大沙弥，依戒分长幼，并非地位大小之制，乃先后之制。\n'
        '善知识，若有僧人以官宦大小地位之于佛法名声，是称堕落道，不称修行人更不称僧人。谛深2016，2，15日示',
  ),
  (
    title: '谛深大师开示:不是什么人都能求开悟',
    date: '2016.2.10',
    body:
        '坐下弟子，开悟是佛门修行由凡至圣、由六道轮回至佛地涅槃的出离刹那，是故，往生极乐世界者并非开悟，极乐世界广大善众，亦日夜精进于戒，受弥陀甘露，求于开悟。 若人不持佛之禁戒虚妄乱想说开悟者、若人不持佛之禁戒以种种解说经典说开悟者、若人不持佛之禁戒以种种修、种种神通、种种瑞祥说开悟者，均如瞎子说见光明之痴！ 若人不持佛之禁戒虚妄乱想说开悟者、若人不持佛之禁戒以种种解说经典说开悟者、若人不持佛之禁戒以种种修、种种神通、种种瑞祥说开悟者，均如瞎子说见光明之痴！\n'
        '善知识，诸多邪魔外道，以狂妄利益自私者，假成佛、开悟之累劫难见之事，妄说、妄称：如是修能悟、如是思能悟、如是知能悟等等兴自欺欺人之骗了自己亦骗大众之痴做痴为，令佛法断灭！佛法甚为难得，若以世间科学比喻，造核弹如一个原子，而得佛法却如银河系，一个人让你造核弹你知道你一个门外汉做不到，谈论佛法却说获得，师父实言告汝等，是等罪众无有岀期！\n'
        '善知识，切勿以某种说称能悟，开悟有条件，戒律为根本，若说罪能悟，是人如瞎子说日，不如蚊蝇知日耳！\n'
        '善知识，入佛门为求离苦，为求获福，如汝等罪为，自刎称活！\n'
        '谛深劝汝等：堕落之人不知堕落以堕落以为证圣才能堕落，若人知道堕落，其不会堕落！祝汝等忏悔获福！谛深2016，2，10日示！',
  ),
  (
    title: '谛深大师开示:春节师父为什么不祝贺',
    date: '2016.2.7',
    body:
        '坐下弟子及声闻善知识众，尘缘各大节日，均以鬼神为导，杀业罪业极重，是故，师父多于尘缘节日行慈悲善导，不做祝贺。\n'
        '善知识，佛法乃慈悲表之道，常以众说用词说善，非世间众说之善，虽于世众中称善。\n'
        '善知识，于元旦，当说劳尘罪业，令众有悟；于春节当说农耕尘累令诸有悟；于耶稣祭日当说罪报尘缘令诸有悟；于宰杀节当说众生堕落罪业令诸有悟；如是等等，世间罪业皆当以慈悲故，并行反观忏悔，所做诸业，观以则修，以是为导。\n'
        '坐下弟子，师父于春节中令弟子行香更鼓教诸鬼神，令之获佛救度法，入离苦道令诸等生有救根、发有救芽若当来世入获救道。谛深2016，2，7日示。',
  ),
  (
    title: '谛深大师开示:不要来问如何盲修瞎练',
    date: '2016.2.1',
    body:
        '今日有声闻请法，说：打坐时总是出现问题。\n'
        '善知识，关于修行师父已做讲说，关于如何打坐师父亦已讲说。若汝等依据自己罪孽缘分，依据邪师所说错乱修习，必于所愿不能有证，更或修成成罪孽缘分成罪果罪报。\n'
        '善知识，如若汝等有心修道，当以佛说为依，莫以世间所传种种名声在外之者所说、所解之为依。\n'
        '若汝等欲皈依吾谛深当依吾之所传为导，以普贤愿力为依入求道法。若已皈依于我，当以吾所说精进持戒修道。若吾没传汝等修证法要，当知因缘不到，应洗心革面精进于求师父传与汝法。\n'
        '善知识，佛法不思意，大阿罗汉尚难思难解，是故，切勿盲修瞎练。2016，2，1日示。',
  ),
  (
    title: '谛深大师开示:令人生信的功德',
    date: '2016.1.20',
    body:
        '今日智安电话请法，问：有菩萨发心360元资助妙湛寺建设，其妻子因怀疑妙湛寺建设是骗局故，来信询问。此事该如何处理。\n'
        '师父开示如下：\n'
        '坐下弟子及声闻善知识众：如是之事乃大善机缘所显，汝等当依师父嘱托为依，慈悲令应。立刻将所收360元退还施者，称第一有慈悲智慧者。\n'
        '善知识，令一人于佛法末世，生信于佛陀，比建十座末世寺院功德大甚。 何故是说？\n'
        '1、释迦末世寺院缘分已灭尽。\n'
        '因末世寺院建设，诸多缘起者非僧、非戒只以功德名利为发心故。是等寺院因初心有罪，必于世间成罪孽地，成就坑蒙拐骗诸罪孽相，令末世寺院有相实灭。重罪大众亦必观：重罪之人建寺院乱受信施敛财、或建寺院狂行、或本来无恶不作却建寺院为求福报、或寺院僧众因不持戒律吃喝嫖赌故为众唾骂，等等，于是诸罪重之者中无可救者更假僧依，亦有谎称建庙而广为骗钱者。于是末世佛之道场缘分灭尽渐渐。\n'
        '2、末世诸多寺院皆非清净比丘住持，更别说大德高僧住持了！如是之辈，不以戒为师，广行波旬诓骗法，以师父法眼观之，佛法已于虚云倓虚住后，遭诸多邪魔破坏，释迦法已灭。我亦已于诸多缘分中将佛说经典以智慧灭尽，释迦所传已不复存世。大众所观之经典亦不能为立。吾所说者，当于五百载后，大众因缘不能救后，自相灭尽。\n'
        '3、现行末世佛门已为尘世各等主者统辖，佛门长老和尚皆为世间国王、大臣、权势之者之属，已非皈依佛之僧相。\n'
        '是故师父令建妙湛寺不广征香主，因佛之道场已灭尽。师父令智安发立香公告于坐下群中而不广发，是慈悲吾于挲婆之、能于如是罪孽末世中生实信之、累世稀有缘分，令种善根故。\n'
        '善知识，是故汝等不当因妙湛寺建设缘分资金匮乏而违师父嘱托，广纳非信之施，若纳汝等有重罪。\n'
        '善知识，若能退360元令赎罪者有信，是称真吾弟子，胜百千万亿世间重金之建庙信施所做。\n'
        '坐下弟子，由今以后，不允任何人于群中再化庙缘。谛深2016，1，20日应弟子问。',
  ),
  (
    title: '谛深大师开示:什么是须弥山',
    date: '2016.1.17',
    body:
        '今天是释迦佛成道日，是日缘分吉祥，为了这些缘分师父便忙，由于末法时妄法炽盛，毗尼难续故，师父怕他们，今年就没与大家一起海会布法。明轮至时，妙湛寺毗尼灯殿落成，师父再与菩萨祥会。\n'
        '因妙湛寺有一阁殿是从须弥甘露顶阁殿抄建，今日又有皈依弟子问及须弥山，师父一并给菩萨们讲说须弥山事要。\n'
        '善知识，须弥山乃于释迦佛因地修道之万亿大阿僧祗之处时，由善现如来起，圆满照分，照分之后，所成之十方世界之中，识心分别有相体相之总廓体，已由人之算数无量大劫至于当今之，十方世界之依成缘分。\n'
        '善知识，以吾谛深净眼观之，须弥山之大，若以人眼求视，恰如细菌求见宇宙之见而难见之见。\n'
        '善知识，譬如：人道之当今世界科学所探之宇宙，仅银河系恒星数量便难以计数，实则，每一日月，称为一个世界。而须弥山下方之南詹部洲，就有十万八千上土州别，一百零五万中土州别，一十二万下土州别。其南阎浮提位于南詹部洲西南。\n'
        '南詹部洲业相体，呈上两边高中间低，平缓顺势；下边呈中间微凸，两端一端扁削一端三旋状。是州各方，以阿僧祗劫记日，日有所变。\n'
        '善知识，是中之南阎浮提，则多处均有日月草木世界，每一世界均有山川河流，大海冰凌。\n'
        '善知识，南阎浮提中处，是释迦如来所成挲婆国土。挲婆世界多处大海，山川相映。\n'
        '善知识，须弥山正峰，有甘露寺，日夜甘露倾海下施，至于四天王天处，已无豪分。而至于山下方，若以人心思量，无始劫难思至。\n'
        '善知识，佛法真实不虚，若以罪孽想，判别佛说法，是人狂妄辈，不能见真谛，更何知有佛。若于佛说事，静心受佛教，断灭罪孽想，一念随所见，十方刹那现。无须求知之。\n'
        '善知识，放下诸罪，严净毗尼，弹指能见佛。谛深2016，1，17日示。',
  ),
  (
    title: '谛深大师开示:什么人能留下肉身',
    date: '2016.1.14',
    body:
        '今日有善知识问，僧人肉身是怎么留下的，故师父为汝等讲说肉身菩萨。\n'
        '善知识，汝等所问，因是事未来将破灭佛法故，当为汝等讲说。\n'
        '善知识，得道者不留肉身。修道者不一定留肉身，留肉身者也不一定就是修行人。\n'
        '释迦如来为最上第一得道者，未留肉身；像世间罪孽之众，如法老及诸多世间人一样能留有肉身。九华山地藏菩萨化身为令大众钦映其智慧故，留有肉身。佛门肉身并非僧众习俗，单传取奇之为者传耳。\n'
        '善知识，譬如白骨，诸多人乃至畜牲都能留下，若见白骨，人为之哀。所谓肉身留住亦复如是，观之可怕，是为不善者也。是故僧人留下肉身不称为证，更不称为圣。\n'
        '善知识，若欲留肉身者，当如是做：\n'
        '1、于潮湿环境，碱性体质为最。人于命终前勿于进食，或少进食，过世后可置于缸中，或不透气棺中，以布层裹，置石灰块等吸湿物即可保留肉身。若体内微生物过多，则难于保留。\n'
        '2、若于干燥环境，人过世前排净残物数日，过世后身涂净药，身布松干麻衣，于风口处藏，亦可保留肉身，等。\n'
        '善知识，修行之道莫以诸等相为宣、为传、为敬，当以戒为师，以佛说诸要证之为修。\n'
        '若有人不以戒为师，修证佛所说事，以是种相称之为道，愚痴之做耳。谛深2016，1，14日应弟子问。',
  ),
  (
    title: '谛深大师开示:出家为道',
    date: '2016.1.2',
    body:
        '善知识，出家吾已解说，修道亦解说，出家为道庄严道途，今因善知识问故，再予解说。\n'
        '善知识，1、金刚经云，若色身见我，是人行邪道，不能见如来，欲解是意，当于万八千劫中，世世有佛陀善导因缘。是所谓：信心定因缘、苦行僧因缘、毗尼净因缘、禅悦住因缘，波罗蜜因缘等，若无是等因缘，说能解金刚经意趣者，恰如鹦鹉登基称皇，欲统人道天地者。汝今问之，应于吾说如下法中，闻受心应。\n'
        '2、分别执着，乃修行法宝，当知为用，如何能知之为用，先入毗尼法，后承因缘大善善导方能成证，莫以有少许戒之漏缺，求所求导。\n'
        '善知识，吾谛深因汝能问法故，为汝讲说如下出家为道缘分，善思念之。\n'
        '善知识，先说以色身见我，是人行邪道，不能见如来。\n'
        '一，大众求观世音菩萨救度，诸多以：观音菩萨慈悲，帮我去除病苦，吾定信观音菩萨为心，或以观音菩萨保佑我发财，发财后定来酬谢等为心求佑。殊不知，是做乃污佛灭佛之为。其人因何得病，乃因杀盗等业得病矣，若观音菩萨救之，而其不能立断色缘，出家为道，观音即与之共罪业，因被是等杀害为食者，亦求观音菩萨慈悲，令其杀食求观音之杀之者，当如何者也？\n'
        '二，所谓色身，乃攀缘万业之本，若不能开悟，破灭攀缘，色身即是罪恶，求见如来，如来无有罪业，圆满清净，若见，清净便无，如来即不是如来，乃邪道王。\n'
        '以如上两意故，佛说，若以色身见我，是人行邪道，不能见如来。乃至以音声求，亦罪于缘结。\n'
        '善知识，汝所问威仪法，因无毗尼净行故，不成问本，当以毗尼法为依修道为师，称出家为道，居士供汝等俗家衣，为破毗尼要，是汝等为师之过，应多教之。若天天执着相道，当知，应堕落道。所谓，天天以不执着于相为道，当知，亦应堕落道。善知识，若见诸相非相，则见如来。\n'
        '善知识，若有为道者，能于毗尼法，有一百六十证，吾谛深令之入天道获福，灭其疑惑。善知识，出家为道，受佛法命，吾期盼之。谛深2016，1，2日应问。',
  ),
  (
    title: '谛深大师开示:居士应修离苦',
    date: '2015.12.28',
    body:
        '今日吾弟子智依为群中声闻问事，因是事关乎在家居士修道故，师父为汝等解说，谛听，善思念之。\n'
        '善知识，譬如有恶人与汝纠缠，是人极其凶恶嚣张，能伤人命，汝引是人入宅会伤及汝等家人，或汝讲说穷凶极恶之相，会令自己胆小之子夜不能寐，汝会否将其人领自家中，求汝父评判与说之恶，或讲与幼子令其身心因惊吓受虐？\n'
        '善知识，又如有群狼于旷野曾与汝有害，汝当否引狼入室请家人评判之？\n'
        '善知识，佛门居士当修离苦，若修离苦，莫与罪恶有思，与罪恶之人有缠、有争。因若汝等与罪恶之人有思、有判、有评、有争，即与罪恶成缠，不能舍弃罪苦，而成就罪苦之道。\n'
        '是故，善知识，如若汝等为罪恶所伤，不舍其主，并请师父判其善恶，是称愚痴。恰如汝为狼所害，入于狼群引之入自家室，请父亲评判狼恶。汝等若是做，或思狼之恶，称不舍罪恶。\n'
        '善知识，居士修行，因乃罪苦中行，入吾净地，当放下诸恶成思，勿将尘缘引入净土，更何况求师父评判。若是做者，当自忏悔玷污净地重罪，若不忏悔，不能出离罪苦。善知识，五浊恶世诸罪互缠，是故，当出家修道，不思、不沾罪恶，方能脱离罪苦。\n'
        '谛深2015，12，28日应弟子代群中声闻问。',
  ),
  (
    title: '谛深大师开示:为什么不与瞎子论道',
    date: '2015.12.27',
    body:
        '刚才有人于吾讲法时，传信给我弟子智依欲与师父论道，是人因盲修瞎练故，师父为其做如是开示。\n'
        '善知识，譬如有瞎子于汝等门中，以盲人道指责于汝等，汝等如何回之？\n'
        '汝等若与之论明眼人道，汝等不慈悲也。汝等当以如下法为其开脱。\n'
        '第一，为其说汝眼有疾，令其信服，为其治眼令其解脱，是称无上慈悲法；\n'
        '第二，若其不信汝说，能令其不受盲法之困，汝等为其讲说路途障碍之处，令其少遭伤害，是称下等慈悲法。\n'
        '是故，善知识，非吾谛深不与之论道，乃其狂妄于罪孽所成盲人瞎法之其证之之说，吾不当论也。未来汝等侯其受罪有忏，再行救拔。\n'
        '善知识，若复有人以罪孽法，与汝等争当以师父所说做如是观，能令汝等于罪孽缠敷中不生嗔恨，生慈悲愿力。谛深2015，12，27日示。',
  ),
  (
    title: '谛深大师开示:被人嗔恨会怎么样',
    date: '2015.12.27',
    body:
        '坐下弟子，人有六根，其每一根都有无始劫来所成体相。体相有界体，与非界体。譬如有人思念你，你有所感，是称非界体触动。\n'
        '若有人嗔恨汝等，汝等随自之不知，亦会遭伤或害。\n'
        '是故，佛门设诸多咒禁，以令罪孽嗔恨恶骂杀意灭除，而当持诵，并令弟子不与大众中多于尘累。\n'
        '善知识，并非人之嗔恨，汝之不知即为不害。譬如诸多病人，不知己之病得，皆如是造也。\n'
        '善知识，是故，吾亦令弟子广教大众，莫行嗔恨，嗔之伤己，亦伤别人。若无端遭谤，当多持咒禁。\n'
        '善知识，戒律为咒禁依，譬如城墙，卫兵为咒禁类，咒禁护城，汝等方能得到安身自在。若无戒律只兴咒禁，譬如有人街坊与人打斗，或两军对阵肉搏，互为伤害也。\n'
        '是故，汝等当听吾所劝，莫自行主张，说世间道理，断灭佛根。\n'
        '善知识，所谓佛说智慧，乃圆满明彻之菠萝蜜，非大众赞叹之知见道理。谛深2015，12，27日于弥陀圣诞应弟子问。',
  ),
  (
    title: '谛深大师开示:不要把托儿所称无上',
    date: '2015.12.27',
    body:
        '坐下弟子众，今天是阿弥陀佛圣诞，师父很高兴有这么多人聚会，行赞。\n'
        '佛门是普适门、慈悲门、智慧门、离苦门、自在门、神通门、甘露门等无量意处种种门。\n'
        '善知识，无量因缘种子，入于佛门，当如是知晓佛法殊胜，所谓：闻殊胜、传殊胜、修殊胜等大福报之相。\n'
        '善知识，阿弥陀佛成佛以来广布因缘令大众得如上所说福报故，众等当皈依受法。何为皈依受法，指身心勿以自己知见为导，当以佛说为导，是称皈依受法。\n'
        '善知识，挲婆世界乃释迦佛累劫施身所成，所有佛说法，皆为释迦佛亲口所宣，汝等当知，阿弥陀佛乃释迦佛赞叹弥陀大愿，引导广众出离罪苦之慈悲用相。是故，汝等于挲婆世界，当以释迦佛所说为依，莫以种种说为依。\n'
        '善知识，师父何故以是说演义，因诸多邪道于释迦末世兴起，断灭佛种故。\n'
        '善知识，譬如：有人闻释迦如来说清净法身毗盧遮那佛，为清净总持，便立此佛像称之为最，成就教派广为流传，是人实则乃狂妄自大所使，因狂妄故成大魔障堕落苦海不能为道。\n'
        '善知识，又如有人以极乐世界弥陀愿力为导，不说、不赞、不听释迦如来所传戒法，而称往生为最者，恰似有人于鱼缸养鱼，令鱼多念龙王施水令其有活，是鱼闻知便舍弃主人，以去龙王处称赞，主人走后，鱼缸无人添水水干众鱼遭灭。\n'
        '善知识，是故吾谛深为汝等讲说弥陀愿力时，皆以七遍释迦佛号为导，称弥陀圣号。\n'
        '善知识，莫于汝等未证之说，施于大众。若有人称某法最上、无上，当知是人乃狂妄辈，如托儿所受教后，听教师称其，宝贝乃世界最棒之赞，便以是为确，毁谤大学教授之愚痴之为。\n'
        '善知识，修行渐次，当依戒律证之有进，莫以某时、某说、某为、某证为最，方能于佛说法有果。若不如是修，称罪孽法，不能见如来。\n'
        '善知识，汝等当以释迦所教，以戒为师修往去极乐，必依弥陀四十八愿获自所愿往生。\n'
        '谛深2015年12月27日示。',
  ),
  (
    title: '谛深大师开示:为什么妙湛寺不广征香主',
    date: '2015.12.18',
    body:
        '近日有弟子问及妙湛寺是否应征香主，以资快速建设，师父否之故为解说。\n'
        '善知识，所谓道场，乃弘扬佛法之缘，若建道场需上有佛缘具足、法缘具足、道缘具足；下有佛传承缘具足、法传承缘具足、道传承缘具足。\n'
        '善知识，所谓佛缘具足者，乃佛住世、或戒住世。因妙湛寺于我坐下缘于戒律故，已具足佛缘；所谓法缘具足者，是指两相，一者，成就者传法，二者，求道者应法，因妙湛寺具足是两相者，法缘具足；所谓道缘具足者，乃修道者修为之相，吾坐下弟子已有少许具此相者，是故，道缘具足。\n'
        '善知识，所谓佛传承缘，乃指大众所知、所受佛之体相者，即是否见过佛，闻过佛说等。因释迦佛已灭，大众依未得之空、依未明本有、依自思形象做之称好，而妄立佛之体相故，称佛传承无上之体相缘灭；\n'
        '所谓法传承缘者，乃佛出世之本传承者，共两种法传，一者，佛住世机缘救体；二者，佛灭度后，戒律救体。所谓佛住世机缘救体，乃佛于当处所说，令众得救体，是体有正像末之分之经典者。是传承者，若佛灭度，不为法传，只为悟后证用。因诸多罪孽众生以狂妄、利智、神通之为讲说经典以为佛传故，是种法传承灭。因虽为指路之用，已为大众奉为所得之用失去根本。\n'
        '戒律救体，乃佛灭后救众之本，戒不圆满，称为不救。而佛灭度后，末世大众不依戒为师，即使受戒，亦不明戒体，妄传妄受，以种种大众心理共感共鸣之道、之神通、之说教为师，故，佛传之戒律灭。\n'
        '以上二体，称法传承灭。\n'
        '所谓道传承者，乃以佛传承灭、法传承灭中，以灭传之法入于佛门求道之者，不以戒为师，称道传承灭。\n'
        '善知识，因于大众中，佛、法、道已灭，而少许、稀有有传承者，难能成就佛所说事，而假佛名相成就诸多邪魔道派者，已令大众不能入佛毗尼法。我不令弟子于佛法末世广为征香，因于末世缘分中，征者甚难得应，应者亦邪，于妙湛寺启建成就五百岁中，必有佛陀缘分，接踵救护缘分大众，最后，至后十三岁妙湛寺灭。\n'
        '妙湛寺共有三处，中国一处、欧洲一处、洋州一处约于二百岁成体。于妙湛寺因缘中发心添砖者，累世佛缘，邪道不应。中国之处，释迦缘分、地藏缘分居多，欧洲释迦缘分、弥陀缘分居多，洋州释迦缘分与吾谛深缘分居多。是中所有大善助道者，均为女子身相。中国缘分，多为火成；欧洲缘分多为神成，洋州缘分，多为光成；如是等等。\n'
        '善知识，是故吾不令弟子于为魔所害，成就大众罪孽想于佛法末世传承中，告示征诸香主。\n'
        '善知识，于吾坐下，多行忏悔，持佛戒律，出离罪苦六道，勿行知见。谛深2015，12，18日示。',
  ),
  (
    title: '谛深大师开示:如何做供养（第三品）',
    date: '2015.12.9',
    body:
        '善知识，所谓供养乃修行道，是故当说。\n'
        '善知识，如何做供养，诸佛所说，然凡夫未得有传，何故未得有传，因凡夫行故，不能为传。今吾于释迦末世传之，为救大众，为驱诸邪、破魔幻。\n'
        '何故是说，善知识，譬如有波旬，假佛衣服，住于道场，汝若供他，即落魔着，受其困缚。\n'
        '又如有重罪之者，因有杀人重罪，盾于寺院，不思悔改，元气恢复，必再伤人，是种罪人亦假佛说，诓骗获资，图大罪恶。若汝供养，共成罪业，功德未得却成罪业。\n'
        '等等，等等。十方诸佛，视魔所为，愚弄狂骗，残害大众，是故吾于释迦末世出兴于世，为慈悲故，宣说破魔要义，令众不害有救。\n'
        '吾说供养经，汝等当知是法宝，释迦末世之最上入门之要。\n'
        '善知识，如何做供养，有六供养道，一者戒为垂，行大供养者。若无戒为范，不成为供养。诸多邪魔王，假慈假称法，以佛说为说，是为第一尔。\n'
        '二者供道证，以证为供依，每证一法要，即行令得法。汝之自分别，若依诸佛说，经证无有别，得法即行供，诸魔不得便，是供称法供，必能渐成道。\n'
        '三者缘分供，是供分二途，若能如供子，汝以所求观，能于所求处，获有佛加持，是为一途者。二途入魔道，共成魔罪业，累世难得出。\n'
        '四者盲供养，末世邪魔道，多于牦牛毛，住于诸道中，万者无一正，供者万难得，若于听说道，道道有其道，是故供着痴，闻道而供之，护之称护佛，实者护邪魔，成就大堕落。\n'
        '五者罪供养，以自己知见，分别善与恶，供者皆魔幻，自己耗家财，直接成堕落。\n'
        '六者凡夫供，诸魔缠其舍，世间以其圣，断灭佛之缘。\n'
        '凡所有行脚化缘者，以种种说道，或称建庙，或称救人均欺诈者，有大罪业。建庙于正处化缘，不行脚求，求者犯戒。凡所有以种种由称当供者，必为魔为。\n'
        '善知识，供养若无法眼，以戒为师，必不落罪。若听信善说，亦或堕落，汝等当以是为依行于供养。汝等不闻世间名人为魔术师欺骗，种种僧假僧欺骗乎。汝等莫以为神通兴大供养而破财买罪者。是故，吾实言告汝等，小乘戒法，尚不沾钱财，何况大善乎。皈依吾谛深者，若无所证，欲施供者，亦愚痴为，是故，吾不受无名之供，因无名吾不能当世救之故。所有取财取物非为常住者，若未开悟，均魔道也。开悟者必不为名利而护戒法，是故汝等皈依谛深，当以此为导，行于供养能获所求，能获成就。谛深2015，12，9日应欲供者问。',
  ),
  (
    title: '谛深大师开示:楞严经缘分',
    date: '2015.11.16',
    body:
        '善知识，一切成道者，皆以毗尼法，能入楞严门，佛法灭度时，毗尼法灭度，毗尼法灭后，诸经逐遭灭，楞严先行灭。何故先行灭，楞严为道初。譬如种庄稼，种子为基础，种子入土地，发芽为根本，楞严亦如是。毗尼如天气，毗尼荒废时，恰若遇寒冬，种子之发始，发之即死之，是称芽先灭，芽灭种亦灭，遍野荒草住，草之不成果，荒芜成落寞。释迦法末世，佛戒不成器，戒律遭妄传，何者为妄传，传者与受者，不知毗尼要，实则不得戒，是称为妄传。妄者如秋风，秋风扫落叶，种种落地果，当自求坚固，如同坚果壳，护自过严冬，来春再发芽。佛法入末世，毗尼法遭灭，种种罪恶相，科技与知见，均不适应修，修之生疑惑，疑惑芽即死。是故善知识，释迦法灭时，当入于温室，如同阿罗汉，寻道于深山，世间事不谙，能成大果位。又如我弟子，金盔金甲挂，护持修道人，令其芽不灭。\n'
        '善者应当知，所谓佛芽灭，实指真修心，非指盲修心，更非邪魔道。因诸毗尼灭，不受护持故，菩萨难住世，诸多修道障，不能得解破，以是因缘起，真修生疑惑，疑惑为灭法，是称佛芽灭。譬如当今世，法王如意王，XXXX辈，皆因不持戒，难于法证道，滋生疑惑心，为名为权故，以世间法要，假称证佛法，令自佛芽灭，以是为法要，诳骗诸大众，终成邪魔王，堕落入罪苦。\n'
        '各位善知识，诸多罪重人，入于于塔庙，争权与夺利，不入佛戒法，手持众生物，电脑与手机，以是假称道，假说弘佛法，实则入邪途。我今为汝说，佛法大神通，何须是等物，传递佛说法，大众重罪障，是故无神通，因其无神通，不能知佛法，是故吾令众，用其所用物，慈悲予其法，令其有所悟，脱离大苦海。若其有修行，获得少许道，我于一念间，传其菠萝蜜，令其成大果。释迦末法时，其等皆堕落，何故皆堕落，落于世间道，成就宗教门。\n'
        '大善应当知，谛深不欺诓，我问汝等事，若汝能知晓，以是入佛门。何者为汝心，汝之死之时，心之何处去。何者为世界，世界灭尽时，汝之为何物。何者为空门，若世界为空，汝之何须修。何者为因果，世间多少魔，如何成其事。何者为正邪，如今旁生类，已遭人道灭。若欲讲因果，汝食众生肉，来世其食汝，何故藏活佛，广食众生肉，却受众追捧。更有狂妄者，诽谤佛法师，却受大福报，成就自魔道，魔者又为谁。善者自听了，何者为科学，何者为社会，何者为宇宙，何者为数字，何者为化学，何者为病苦，何者为星系，何者为父母，何者为寺院，何者为密宗，何者为净土，何者为戒律，何者为宗教，何者为医术，何者为修行，何者为善者，何者称为恶，何者称梦境，何汝梦不持，何者为分别，何者不分别，何者为草木，何者为五谷，何者为众生，何者为慈悲，何者为大小，何者为多少，何者为虚空，何者为微尘，何者为生命，何者为天道，何者为地狱，何者为寿命，何者无量寿，何者为世间，何者为空间，何者为包含，何者不包含，何者为果位，何者为修道，何者为现在，何者为过去，何者为火焰，何者为土木，何者为水者，何者为狂妄，何者为生者，何者为死离，何者为极乐，何者为弥陀，何者为观音，何者为文殊，如是等等问，总有一万三，善者应知晓，知晓如是等，称能于末世，入我甘露门。\n'
        '善知识，楞严灭后，诸经不立，最后佛法灭尽。\n'
        '谛深2015，11，16日应声闻问。',
  ),
  (
    title: '谛深大师开示:心正法正心邪法邪并非佛说',
    date: '2015.11.7',
    body:
        '善知识，所谓心正法正心邪法邪者，乃凡夫之因缘法道，并非佛说，亦非佛道！十方邪魔外道皆因如是等法，令其众皈依故，成就其道！\n'
        '善知识，虽佛法中有凡夫僧因令众皈依，假罪孽言说使用正邪说教，其若未证，直入邪道！因佛法不说正邪！善知识，以理证之，无邪则无正，邪正为一耳！说正者必邪！\n'
        '善知识，正邪言说乃六道与所含种种道者立相之本，佛法乃出六道法，是故其非佛法！譬如：恶狼群落，团结如一，可屠戮余者大众，如是群中服从群首规则法度者称正，不服从群之法度者称邪，诸狼皆驱逐之，或撕咬之！\n'
        '善知识，有人入我坐下广传心正法正心邪法邪，破坏我开甘露门、破坏令大众有出之做亦复如是，其乃重恶之举必受重罪之报！诸邪魔外道皆以未证之者却富含世间大众公认之理之说，假佛之名破坏佛传！\n'
        '善知识，诸佛住于世，皆以慈悲法布施广大众，虽有诸魔王为护自己业，或为名为利，入于佛之门，破坏佛所说，其者罪重者，亦可因诽谤，时时思我说，忽然心开朗，是者称开悟！善者听师训，所谓开悟者，罪障忽然灭，是为其之相！\n'
        '善知识，所有罪孽深重之人，皆因受罪之道而于苦中无有出期，若罪苦无道，无有众生能受其罪！是故诸佛释尊，不以丝毫道理宣示传承，只以戒律宣示传承！\n'
        '善知识，是故，以戒为师能获成就！\n'
        '谛深2015，11，7日因弟子请法问说群中有最重诽谤者开示！',
  ),
  (
    title: '谛深大师开示:什么是方便法门',
    date: '2015.11.4',
    body:
        '善知识，所谓佛说方便，乃救众之径耳！非邪说方便！亦非凡夫方便！\n'
        '所谓邪说方便，乃为令大众受魔摆布，令众遭幻。譬如：饿狼欲食一人，汝持枪阻止，令其有退。一人说汝，汝乃佛门人，当行方便也！是称邪说方便！又如一贼盗人财物，令人家破人亡，遇汝阻拦，狂骂汝不解佛法，当行方便！亦是意耳！\n'
        '善知识，何为凡夫方便，乃大众当行做人之道！譬如：有羊肠狭路，汝于路中，有人迎面汝与相让，是称凡夫方便！又如汝于关位，能事大众，有人遇事汝可遏之、亦可不为，而汝却为者！是称大众方便！\n'
        '何为佛说方便，譬如：有人念佛不知所以，而汝以譬喻而令知之，又如有人遇障，汝以一事而令破障，又如有人诵咒，不知其用，汝以其用示之等是称佛法方便！若有人不知方便所以，而说方便乃愚痴为，或魔故作！\n'
        '善知识，如何不落诸魔所累，当持戒律以戒为师，莫以说、以道理为师！谛深2015，11，4日于匈牙利应弟子问',
  ),
  (
    title: '谛深大师开示:如何修供养（第二品）',
    date: '2015.10.13',
    body:
        '善知识，关于修供养师父已开示一品，今再为开示第二品。\n'
        '善知识，释迦如来于涅磐时说，有佛住世以佛为师，佛灭度后，显前无佛以戒为师。\n'
        '善知识，所谓供养三宝亦复如是。若有人欲修功德、欲却病灾、欲却烦恼、欲得修行而供于三宝，是人应以以下之则行于供养，必得获求所欲。\n'
        '一者，能供佛住寺院。\n'
        '何者为佛住寺院。\n'
        '善知识，并非建筑古典，置之佛像，所谓剃头出家之者朝钟幕鼓，焚香缭绕者为佛住寺院。\n'
        '若佛住寺院，戒律严净，不以种种名目故收钱财，自己耕种，或自有缘分予以资粮。\n'
        '若佛住寺院，无有僧人常于居士说诸等事，多于戒律诵经念佛。\n'
        '若佛住寺院，无有僧众做法收钱。只有为大众做救度而不公布求财。\n'
        '是故，善知识，莫以说教兴供养心，当以自己受慧或有德布施后，行于供养。\n'
        '二者，供养僧宝当以戒选供。\n'
        '若复有人称自戒律为守，则是僧并非持戒比丘。若遇僧人予之有道，不与汝等求草介小物而去，是称持戒比丘。所谓持戒比丘，于自住寺院，不单行见居士，均于和尚引见居士。所谓和尚，乃寺院方丈。\n'
        '善知识，寺院方丈，亦不随便见于居士，当以法浴，或开法会，沐浴甘露于到修居士求救凡夫等。若复有人，以比丘身随见居士，并受供养，若非檀越，其为不持戒僧，不当供养。若是僧穷困，居士怜之，予以钱财，是称布施。\n'
        '善知识，供我谛深，汝等当以持戒称供为最，是称法供。若复有人不持佛戒，称能供养于我，如幼儿教父。吾行于世居所不定，虽建妙湛寺，汝等亦不能见我。若汝等能持一戒，吾谛深即为汝等做大证明功德主，令汝等有大获得，何况有人能听吾说，持具足戒。\n'
        '善知识，若复有僧能于当今末世戒中修道，我必为之讲法，令其成就。谛深2015，10，13日示。',
  ),
  (
    title: '谛深大师开示:什么是不具听相',
    date: '2015.10.9',
    body:
        '善知识，所谓不具听相，乃大众因着法相与邪魔外道染污之后，不能听受佛说救度之法之相。\n'
        '譬如有尿桶已满外泄，汝若欲注之清水，是做虽能稀释，但所注之清水亦臭。\n'
        '善知识，遭邪道熏染之满腹经论之人亦复如是，其等自行讲说邪道害众之法恰如粪尿外泄，汝予之甘露虽是者有得，却亦与粪尿稀释成臭。\n'
        '善知识，因诸多邪染罪众不能救却时常盗法为罪故，吾弟子于群中所发开示，遭重罪者诽谤，是故，师父今日起之后种种开示，将转以微信或专设网站。未来师父所有开示或以文字书页，传承弟子，令弟子以严格形式传于所有有心、有缘者。故，有心者当多与设群大善结缘求道，以令自己有福、有智更缘是之者得无量福。\n'
        '善知识，谛深不欺诳，为说破灾障。汝等若能听如是言说，所有灾障必破。谛深2015，10，9日为声闻善知识示。',
  ),
  (
    title: '谛深大师开示:如何修供养（第一品）',
    date: '2015.10.7',
    body:
        '善知识，所谓供养乃大众为请佛住世故，所做功德以令自己有机会随佛修行，是故，供养为在家人修行之要。善知识，供养显心，是心用相，并非虚妄。如若有人打妄想供养，称之用心，恰如打妄想吃饭称能吃饱。\n'
        '善知识，所谓供养出处，今当为说之。\n'
        '供养之者分为上中下三等，上等以宝物，中等以凡物，下等以用。\n'
        '所谓上等之宝又分上中下，之上七宝、中七宝、下七宝。所谓中等之物，亦分上中下。所谓用者，亦分上中下。\n'
        '善知识，上七宝者，人间无有，譬如龙珠为天龙之命根，乃上七宝之一。\n'
        '中七宝者，譬如女宝，仅一十六岁之前，净女有之，为中七宝之一。\n'
        '所谓下七宝者，譬如黄金为下七宝之一。\n'
        '善知识，中等之物，之上中下中，上等之物，为供养之人难得之作，譬如、天人饭食、人参、木棉僧衣、精品画作等。\n'
        '所谓中等之物，譬如常住器物等。\n'
        '所谓下等之物，譬如日常用品等。\n'
        '善知识，所谓用者，譬如为佛承事，称之为用。用亦分上中下等。\n'
        '善知识，供养乃修行根本，若不供养，不成佛道。\n'
        '善知识，供养之物来处有大差别，譬如：小龙女摘珠供佛，是称以命为道，当下成佛。又如：悔云道菩萨，盗取皇家重金供养，死后成道，。。。。其因偷盗受报，于监牢度过半载，被打死于牢中，只字不提黄金所去。其刚死，僧人便抬黄金称其所为，皇帝见其为做功德，便将黄金赏赐于斯。当日大雨，其直证10地果位，称，吾忏悔累世偷盗罪业，以将手脚请人捆绑，求皇帝处置，并将于九日后，还皇宫黄金。。。。。后皇帝以其所还黄金，建造寺院，称悔云寺。\n'
        '善知识，佛门供养，均为供者之业，供养修行，时常忏悔于诸戒所赢，于修行途中必有所获。谛深2015，10，7日因有人问供养说。',
  ),
  (
    title: '谛深大师开示:出家人如何得退转',
    date: '2015.10.7',
    body:
        '善知识，所谓退转，指步步不如当下。譬如下坡，动则必落，每况愈下也。\n'
        '何者能成退转之途，善知识，大众诸多不愿成退转修，却成退转修，皆为不知是为退转之途者。\n'
        '譬如有人入佛门时因某种说、某种证、某种鬼神遭遇、某种思维认可、某种逻辑演绎而种信心，出家之后，却因无有良师益友引导，不能于佛制戒律严于日常，多于无证言说，多于咒禁护恶，其必于佛所说法不能证得。\n'
        '善知识，若修行者，终日于佛说之法不能证得，却于罪孽行为有所心得，其必损坏对佛法信心。\n'
        '若修道之已无信心，其必于佛法成罪为。如是堕落。\n'
        '善知识，若有人多于佛门常用经典打击有道者为慈悲故善劝，是人则为第一堕落之相。若复有人、有比丘不知咒禁经典本意，却以其谗曲毁戒，是人必于本世恶疾加身，并以疾首重病为地狱索命而死。譬如：灭定业真言，有人不知其本意，却以是为本讥毁戒律，以令戒律难住，又如有人以戒律说，某人舍命护戒得见于佛，有人为修延命却遭佛舍弃，令道者有退，是人必于尘缘堕落恶途，遭罪众追杀。\n'
        '善知识，是故，莫于未悟知识学辩学讥，莫于佛门学于言表，应于戒律有严谨修，以是，必不堕落。谛深2015，10，7日示。',
  ),
  (
    title: '谛深大师开示:吃鸡蛋为杀戒戒障第一',
    date: '2015.10.7',
    body:
        '善知识，关于吃鸡蛋犯杀戒，师父已说，但诸多僧众受XX妄说，依然以吃鸡蛋为不杀戒，师父故再做开示。\n'
        '善知识，地藏之母因食鱼子，堕落地狱，受大罪苦，地藏功德方难能施救，何况重罪比丘？\n'
        '善知识，广大游鱼惯腹鱼子，均为体外受精，体内鱼子为未受精卵，地藏菩萨之母食之受报，未受精鸡蛋比未受精鱼子如何？\n'
        '善知识，末世波旬为自己攀缘名声故，假于种种妄说诳骗机构，包装打造以获私利，令诸多未悟之者断佛种子，汝等当按佛说戒律如说修行，否则，不获修证、不获福报、不获所求。\n'
        '善知识，莫以邪说为道，当以戒为师，方能获证佛说。谛深2015，10，7日因有罪众以邪说谤戒示。',
  ),
  (
    title: '谛深大师开示:什么是修行（第二品）',
    date: '2015.10.3',
    body:
        '善知识，所谓修行顾名思义。种种法、种种道、种种有、种种无、种种思、种种妄，皆以修而得，称为修行。\n'
        '善知识，譬如有人行骗，却骗术不精，伸手被捉，是称罪修不到，或修学之道不对，而有罪人修得技术精湛，一骗即得，是称罪恶修行成就。\n'
        '善知识，譬如有人欲修学佛法，却于说相，热衷言表，众因愚痴故跟随修学，无有所证，不成佛说，却称圣人终成教派，令称佛教。善知识，诸多言说，为令大众生信拥护，假说慈善，广为传说，以假为真，大众皈依，虽不证说，却得拥护，以是因缘成就各个宗教信仰，分化成派，是称宗教门派。是称波旬法道,是中之人称佛弟子修行实则被诓骗耳，是者称为被骗修行。,是中之人称佛弟子修行实则被诓骗耳，是者称为被骗修行。\n'
        '是故，善知识，种种道，乃至假说妄称，所成教派，于其派中，修学罪众无有计量，累世累劫，如黄河之沙，不尽其数。以是因缘，称污浊恶世。\n'
        '善知识，如若闻我谛深所说，以自己罪孽，乃至以佛说经典，有疑惑不信，或有罡骂，当知是人其罪难书。是故，吾教弟子，勿随意传阅，因大众罪孽执见故，于不当机处，得阅成谤，由是堕落，当于当机，传阅我说，能救得者，不令堕落，知是意者，称为佛法末世修行能成道者。\n'
        '善知识，不当机者，称为听法之者，不具听相、不具教相、不具说相乃至不具一切当机相。\n'
        '善知识，若当未来，弥勒住世，令广大众生得度，皆以如是因缘佛前获成果位。若复有人，以种种未证之说，自用施人，是等罪重，不能生天上，更何生佛前。\n'
        '善知识，我谛深法于诸佛末世传承延佛缘分救众不分贵贱。\n'
        '善知识，吾不欺诳，吾所说者，虽予弟子，实则广传，称救罪众。听之者，若以判研，即成罪孽。汝等当严净毗妳，证得佛法，称为佛门修行。谛深2015，10，3日示。',
  ),
  (
    title: '谛深大师开示:进佛门应如法行为',
    date: '2015.10.3',
    body:
        '坐下弟子及声闻善知识：\n'
        '昨日智蓉发心出家，皈依群有声闻弟子恭喜师父，是做与称为邪道染说，并非佛门人之为。\n'
        '一者，发心入我坐下出离苦海者，乃其自身福报，与我和尚没有关系；二者，入我坐下，我须教之、助之、担当其业，令其解脱，乃我谛深之业，吾悲其不争、力其不悟，吾无众说之喜；三者，吾谛深本自清净无喜无优，若说有喜乃忧中凡夫愚痴之表，何称吾喜？\n'
        '是说可于尘缘共修共祝以祝出尘，不可以凡说，祝圣意，断自智慧种子。\n'
        '故，汝等当罚三月承邪教受之过，跪香忏悔。\n'
        '望汝等知耻而后勇，入正法道，修行出离罪苦六道。\n'
        '谛深2015，10，3日示。',
  ),
  (
    title: '公告: 随谛深大师出家的条件',
    date: '2015.10.2',
    body:
        '今日QQ群中谛深大师的声闻弟子XX发心出家。因其为谛深大师坐下弟子所建群中的发心出家弟子，故，于群中特此公示！\n'
        '另，一并转发谛深大师给发心出家弟子XX开示如下:\n'
        '出家不是一个人一生中最大的事情，而是他无始劫来最大的事情。\n'
        '众生从无始劫来的种种罪苦、种种罪业、种种身、种种报中走出来，以种种身向无量福，无量光，无量寿迈出第一步；向清净法身、圆满报身、千百亿化身，迈出的第一步的时候，就是所谓的随诸佛世尊出家。这当然也是离开六道罪苦的最后一步，因为从此以后你就不再是六道中人。\n'
        'XX，你在家的时候所接触的一切佛所说法，师父所说法在佛门称之为信受，你在家做的一切功德称为出离资粮。当你累世累劫所种的福报种子在你积累的资粮中发芽时，你就迈出了这十方世界众生中最为重要的一步！\n'
        '无始善种缘中发，一步舍弃罪苦家。\n'
        '以下是谛深大师所定出家的条件:\n'
        '一、需要或父母，或妻子，或丈夫，或儿女或岳父母所写的同意书各一份，有以上全部缘分的共计五份，无全部缘分的，有几个缘分需交几份，并须当缘人员签名。\n'
        '二、需要同意书中所有人一起将发心出家的人亲自送到妙湛寺来，寺院才能同意考虑其先在寺院承事，考察具不具备出家缘分。考察两年后，寺院最终也不一定允许同意在妙湛寺出家。\n'
        '三、需要将属于自己的财物交与寺院，包括衣服。\n'
        '四、需要入沙弥戒戒学三年。\n'
        '五、需要将自己的生命交与师父。\n'
        '六、需要当地派出所或者政府部门予以认证。\n'
        '公历 公历 2015年10月2号燃灯精舍客堂、妙湛寺客堂于群中公示。',
  ),
  (
    title: '谛深大师开示:不要把加持迷信化',
    date: '2015.10.2',
    body:
        '座下弟子及声闻善知识：今日智安问法，什么是加持？大众皆因是问，听闻是法后，修行途中不遭魔幻。\n'
        '善知识，所谓加持，乃皈依用相！所谓皈依，师父已说，今不再讲！\n'
        '善知识，加持分：菠萝蜜加持、体加持、相加持、用加持、意通加持、共鸣加持、反意加持、正义加持，令众因声名追随，却不解其意之自感迥异而身心追随之迷信加持！\n'
        '所谓神通加持，为迷信加持之垂范！譬如：有人于大众之中利用宣传，包装心用造势，令大众产生追随心态，若追随者久而希望得见却今得见，是人便用手摸体令其有感，浑身发热，通体顿时血液流动，令很多不适之感消缺，后是人问有感觉或体热否？其人必万分激动更生信心！实则，其人自性心动所成尔！其人过后，更感是人大圣！实则，上当受骗，堕落成魔民耳！若复有人，能发大慈悲心，不以有求，不以贪欲，戒律严明，只以救拔予拜之者行迷信加持，当知是人乃大善、大德、圣人住世，当拜之为师！\n'
        '善知识，佛说加持之意乃令异体有变！何为令异体有变？即：譬如汝等手持木块，木块温度升高，此称木块被汝之热改变，自身温度升高，是称体温加持！\n'
        '又如有人说话，令你改变思绪，是称言语加持！\n'
        '佛门加持之：般若密加持，是指受佛说善言，得到自身改变，由恶变善，由愚变智，由穷变富，是称菠萝蜜加持！若复有人，假称佛法，以诸多玄而不语，以诸多妄说自制成秘密，不令汝知；或以他心智迷惑汝等，不令汝智，令汝心服口服，当知是人为邪魔加汝，令汝愚痴，是称邪魔外道罪孽加持！\n'
        '善知识，若遇邪魔外道罪孽加持，而汝心皈依之，汝等必耗福报，或破财福，或受诸多罪苦奴役！\n'
        '善知识，释迦佛灭度时，嘱托大众：佛灭度后以戒为师，而沙弥戒中即有不捉钱戒，何故释迦佛不说以加持供养为师者！是故，我教弟子住山种地；若有众生显示修行，供养于我，我即建寺为之妙用，或以司常驻、或以司僧众、或以司行住如是等等，为佛传承！\n'
        '善知识，密法因大众不能开悟知晓佛法真谛，又要传之佛法令其获得，故称之以密，若汝等能知晓之，实则非密。因佛法凡夫难能知晓故，诸多罪人以其大众不能知晓而假密成骗，坑害大众！师父今日实言告汝，密法戒律严明。\n'
        '善知识，祝汝等勇猛精进于戒律之中，获得修证！谛深2015-10-2日应弟子智安问！',
  ),
  (
    title: '谛深大师开示:诵咒念佛之相',
    date: '2015.9.27',
    body:
        '坐下弟子及声闻善知识，是所问者，是为修行之障，当为说之。\n'
        '善知识，诵咒、念佛之体相有三，一者口称；二者意称；三者体称。\n'
        '1、所谓口称，其虽来自意旨，却口意一脉，根于意用。譬如有人欲得到某物、某人心思口说，是称口正而称，若复有人心欲得之，却口称不欲不求，是称意之反用；又如有人人云亦云，似鹦鹉学舌如是称意之妄用。口称之根另有多相，师父不多于应法予示。\n'
        '善知识，口称之相分为口舌发声之相，意口一体之相，意体体应之相，譬如有人讲话，自有手势而不自知，其，实则为意体体应相。诵咒、念佛若有体态应相，亦复如是，实则为意口一体或意体体应之相者。\n'
        '2、所谓意称者，指心意称说以是为念，而体另所用无有所表。譬如：倓虚老法师手持念串，一日不停却口为弟子言事，是称意称法用者。又如诸多凡夫均能心三口四，其心三者与体不用亦称意称。如是等等，师父不多做示。\n'
        '3、所谓体称者，为诵咒念佛途中之最有功夫之相。是相若不开悟，即遭魔用。善知识，若复有人能于身口意或不需言语体能述说者，是称体称。譬如卓别林所成之者，即为体称；又如猫和老鼠无言令明者，亦为体称。\n'
        '善知识，佛法修行于各种说，各种道，各种境均有体称之相。而佛法不着一切相，是故，若修行途中有体应之者，体称之者均为途修之相，若以是为过，不落其道，是称修行，若着其相即遭魔着。\n'
        '善知识，切记，离一切相，即一切法，不以种种相说称法，亦依种种相说称法，如何以是为得，以是两相之含为眼，当机为本方能得道，是乃修行之要。\n'
        '善知识，佛法修证，以佛为师，佛灭度后以戒为师，方能获当下得，成就佛果。谛深2015，9，27日应弟子代群中声闻问。',
  ),
  (
    title: '谛深大师开示:什么样的人能入师父座下道场修行',
    date: '2015.9.21',
    body:
        '今天有几个修密、修净、修禅、修道的问：想入师父座下道场修行，需具备什么条件才能行。\n'
        '师父开示说：十方众生种种因、种种缘、种种果、种种报，成就种种因修行法门、缘修行法门、果修行法门、报修行法门，并因此成就种种成就相。譬如观世音菩萨，因耳根圆通修行成道；譬如地藏王菩萨因地愿力圆通修行成道；譬如药王菩萨果地罪苦报圆通以自身燃油点天灯供佛转佛报修行成道，如是等种种因法门、种种缘法门、种种果法门、种种报法门中成就种种因缘果报中大修行人。\n'
        '进我谛深座下就一个条件：持戒。于我座下于种种因缘果报法门均可修证了义佛法。若密宗、若禅宗、若净土宗及诸等不明宗派，只要持戒，我均有问必答、有障必除助其成道，直至成佛。\n'
        '佛法不思议，若汝等于自己缘分法门所拜法师、法王、导师座下未竞所得，未证法要，乃至未证欺诈果欺诈报，均不当入我座下以未竞所学延修其法。未竞者入我座下需洗心革面，依据自己所住因、缘、果、报中选修精进。祝所有有缘人、所有声闻、所有见到我给弟子所做的助道讲说的人，于自己当处因缘证得所应果报。\n'
        '弟子根据师父所讲记录于匈牙利。2015年9月21日',
  ),
  (
    title: '谛深大师开示:进门就是要成佛',
    date: '2015.9.20',
    body:
        '坐下弟子及声闻善知识：佛法殊胜，非说、非不说能得少分，须当机得之。\n'
        '进佛门的人很多，进佛门者的用心五花八门。有求消灾的，有求延寿的，有求发财的，有求却病的，有求减轻罪苦的，有求女人的，有求男人的，有求子孙的，有求偷盗的，有求作业的，有求破坏佛法的，有求破坏道场的，有求佛法为自己用的，有求僧人为自己使的，等等应有尽有。\n'
        '于如是种种求者，因如是求所成因缘种子出家为僧者甚多。所以，出家人亦形形色色。\n'
        '进我谛深坐下道场之门，就许一求者入，就许求成佛的人入。\n'
        '佛法末世，如果一个人不想成佛，有自己之求，可以根据自己的求，到种种根所成的僧人那里去找自己的缘分。所谓自己的缘分，是指：若你求去病，有某法师因求去病剃头出家，其不以戒律假以禅说、假以密修、假以净说魔辩讥讽诽谤贤圣，与你一拍即合，其所说与你的执见形成共鸣，令你为他倾倒而被获：他必因自根不正未证所求，修成自己新求所需、知你心要你却要不到的东西，亦罪孽降伏于你令你着魔；若求女人、男人，亦求自己的因缘师开导，有人因得不到女人出家，你求男人，正中下怀，你求女人被其娓娓动听表述，正和你的意，或得或不得你都高兴，如是等等道场乱相横声。于于末世，少有因故真修行人，劝说你放下罪愿，引导你入于佛道。\n'
        '善知识，如果你真想成佛，就进诸佛住持的道场，必获成佛。谛深2015，9，20日于匈牙利为坐下弟子示。',
  ),
  (
    title: '谛深大师开示:莫把愚痴当修行',
    date: '2015.9.16',
    body:
        '坐下弟子及声闻善知识，智依于斋堂承事，师父见其认为做饭容易，便令其主厨饭头。\n'
        '切菜等俗称改刀，结果其切土豆与菜根皆粗如剁块，而且耗尽时辰不能成饭，故，师父开示如下。\n'
        '智依，如此之、汝日见、日用之简单手工之作，尚且难成，何故当今大众，于博大精深之、难知难解难遇之、无上甚深之、修证了意之佛法，敢狂说狂解并以是称法？愚痴也。\n'
        '善知识，佛法末世之人，未知佛法毫许，便讲说议论，师父只为吾弟子说，汝等莫笑其愚痴，因大众罪苦深重者，汝等当发慈悲心予之引导善解，莫急莫燥。师父常说，三车祖师能于定下耗几万年等佛出世，汝等亦当效之，等缘分至下，有众能皈依于汝等，而令获救。\n'
        '善知识，切勿未证谓证，未得谓得行愚痴事，汝等当于戒法精进勇猛修行于初，必获无上至宝。谛深2015，9，16日于匈牙利示。',
  ),
  (
    title: '谛深大师开示:如何往生极乐世界(第二品)',
    date: '2015.9.2',
    body:
        '坐下弟子及声闻善知识：有人请法曰：往生极乐时，到底该投向手持莲花的阿弥陀佛还是投向一团光明？\n'
        '善知识：譬如有人因没去过北京也没去过上海，硬要问在通往上海的方向上如何到达北京？是问该如何回答他？\n'
        '善知识，往生极乐大分共有九品，每品都有不同的往生境界。所谓境界并非尘世所说。境是指修行缘分转地，就是说若当一个人临命终时，其本世所造诸业成就自己的缘分种性胎本，命终之人就在此胎上。所谓界者，是指胎中成体，与死前生后之中间相。\n'
        '善知识，往生极乐之九品生相师父今略做讲说，以令广大修行者因是问得福。\n'
        '一者，上品上生者，若临命终（没终还活着），极乐显前，弥陀与诸圣众，于千叶宝莲上，前来迎接，是时，命终者往去极乐，莲花中生。\n'
        '所谓上品上生者，一者须戒相清净，早已舍下尘缘，无杀盗淫妄诸业。二者，须一生不做口业，无诽谤三宝之过，只念佛号。\n'
        '中品中生者，若临命终前，大德高僧助道，菩萨海会随喜功德。境界中，弥陀持金台灯，观音、势至坐于莲台，虚空之中三圣接引，随去后，三七日内，极乐显前莲花中生。\n'
        '所谓中品者，是指虽戒相有赢，但决无口业大过。一生信心坚固，决定性强。\n'
        '下品下生者，若临命终，共有多种途延。七七四十九日之内，分为三途者，一者舍业随去途；二者，因缘助道有悔途，忏悔后舍业随去；三者，于戒赢重过处忏悔舍业途，于忏悔处成体，自己缘分僧宝贤圣与观音势至导引，极乐显前莲花中生。\n'
        '所谓下品者，虽有戒相，但有于佛门争执口业，一生精进念佛，舍命求道者。\n'
        '善知识，往生极乐为修道捷径，严净毗尼最为重要。而往生时并非跟着莲花还是光明去。所谓往生者，于一年之内已经有所知晓，时时于清醒中观见贤圣与之讲法开圆通章句，令其莲胎成就。若不能于年内有所知晓，并为大善观音势至所导引，除上品者自行证道，其余不能往生。若一个人，连诽谤三宝、恶杀捶打众生，食众生肉的重罪都舍不下，天天谈论往生无贪嗔痴杀盗淫妄的三宝积聚地：极乐世界，他能往生吗？\n'
        '善知识，好好念佛，勿做口业，严持戒律，坚定信心，若求往生必能获去。谛深2015，9，2日应群中声闻问。',
  ),
  (
    title: '谛深大师开示:如何判别自己的修行',
    date: '2015.9.1',
    body:
        '坐下弟子及声闻善知识，之所以师父以坐下弟子开章，是因为这是给皈依我与我的缘分弟子做修行机缘辅助用的！\n'
        '为什么加声闻善知识，是因为有很多修行是已皈依其他法师，却有缘分与我弟子共修佛法的求道者。\n'
        '又因佛法需要当机普洽，一些法若不是求法机缘易成修证着相，是故，吾于吾弟子所结缘分群与圈子中，因有问法者求法做讲说时，均以坐下弟子与声闻善知识开演。\n'
        '善知识，佛法修证了意，非说非不说，只以当机为判。若不当机，说之种罪业种子，听之受害。若当机，说之为大慈悲、大智慧、大光明，听之为大福报、大因缘、大修行。而不说之说亦复如是。\n'
        '是故善知识，入佛门修行可以当机为因，以戒与开戒为相判自己之修为成就。细说如下。\n'
        '1、初闻善法，盲修瞎练时。此时段中人，多不明戒律，只听名声名望以为大德，甚至连什么是皈依都不知道，多与佛法表自执见，多于法师做评价说，多于神通为望为求。是时称为初闻善法与盲修瞎练时段。\n'
        '2、正修证得信心坚固，或盲从盲修着魔坚固分别时。此时段中人，因第一时段盲修瞎练中或遇善知识助道，或遇恶知识助道而分成两部。是两部众，依佛法正象末而有差别。\n'
        '佛之正法时，善知识部，大众广布，戒律大众占主导位。恶知识众人数极少，多以神通能住世自成一家。\n'
        '佛之相法时， 佛之相法时， 善恶相持，成多种名相道法，正修者亦有多门多派。恶知识所成邪魔道法分占国土成自体系，佛法难立。\n'
        '佛之末法时，除已成体系之邪魔外道，多恶知识或以知识、或披袈裟以佛法为衣，假佛法为表行自杀盗淫妄与种种道理之恶，传播灭尽佛法。\n'
        '3、证得精进时。是时大众，分为三部。\n'
        '一部因证得佛说故，严净毗尼，入佛法初乘成佛子佛孙，从小乘至大乘步步为证，得佛法次第妙果。\n'
        '一部虽不舍业因有证得，却不舍业故，成来世佛法种子，入佛法缘分轮转修证。\n'
        '一部又分多部，虽有所证，但于自缘分以罪孽有别故成有修部、自成一家堕落部，因罪孽深重不遇大善助道于佛法三时成堕落相。\n'
        '4、获得果位不退转时。是时之大善者，因证得佛说信心坚固毗尼智慧故，于佛法缘分证诸等相应果位，自知自明，赴缘分佛相国土受教修行证道。\n'
        '善知识，如何评价自己修行，师父略做是四类综述讲说以令大众于修行途中常观照所行所为以为道用，以令其不落障碍，入法正途，辅佐有福人修道。众生缘分千差万别，释迦如来已于各大机缘经典有说。\n'
        '善知识，祝汝等严净毗尼，能于释迦如来法之末世修证得果。谛深2015，9，1日示。',
  ),
  (
    title: '谛深大师开示:什么是供养',
    date: '2015.8.27',
    body:
        '坐下弟子，所谓供养三宝是为结佛法僧缘以求度脱。师父已有开示中做过机缘开示，今因声闻善知识有问：如何如法供养，再为汝等讲说供养。\n'
        '坐下弟子，供养之本为自之因业或罪耳有求所行结善缘起。是故，供养实则为与佛法僧三宝结缘之作。如何才能如法供养，若欲与三宝结缘，须知三宝之本，佛法二宝须遇佛住世，或遇佛之藏身住世，或遇圣僧住世方能正结善缘，或当下解脱、或转世解脱。下尊佛出世须大劫之后，故，遇佛出世实为甚难；佛之藏身多于种种形象藏于法界而不说法，故，欲遇佛之藏身住世，须有大修行与大因缘，若无修行，佛之藏身比甚难遇之更难，若为语言说之称不能遇。欲遇圣僧住世，需累劫缘分，若有人以自己执见判定僧众，不能见贤圣。\n'
        '善知识，欲如法供养，若无法眼、佛眼能知圣贤，当依戒律行于供养或布施，所谓布施乃自行缘分，始于慈悲种子。如若不能依于戒律，所行供养多为做自己累劫佛法正象末缘分之有业、有罪缘分，难于成就。\n'
        '善知识，当如是知入供养或布施法，称为如法。谛深2015，8，27日应群中声闻问。',
  ),
  (
    title: '谛深大师开示:少林寺的罪孽是个好事',
    date: '2015.8.16',
    body:
        '坐下弟子及声闻善知识：少林寺及其密宗中一些人员所涉及的种种罪孽公诸于世，是个好事，因为它能让身着袈裟或口说佛法的波旬不再诓骗大众，令盲从迷信之众不再为诸多邪魔外道坑骗。师父已对邪魔外道有过诸多开示，在此不再多赘。 师父讲过不以佛制戒律为本的种种宗、种种派都是邪魔外道。并因此遭到邪魔道民诽谤攻击。少林寺是一座皇家传承道场，因达摩祖师于洞内示法，为皇家利用至今，本不是佛门寺院，出什么事情都不奇怪。现在所有以权势为根所立寺院，都不能称为佛门寺院。 师父讲过不以佛制戒律为本的种种宗、种种派都是邪魔外道。并因此遭到邪魔道民诽谤攻击。少林寺是一座皇家传承道场，因达摩祖师于洞内示法，为皇家利用至今，本不是佛门寺院，出什么事情都不奇怪。现在所有以权势为根所立寺院，都不能称为佛门寺院。\n'
        '善知识，佛法因难思故，难于解说，因难解故，凡夫俗子难于生信。恰恰，邪魔外道因以执见解释佛法故，易令大众因执见共鸣，成信解相，接受邪解成信仰根，并以是生信断灭佛法。善知识，佛门一切寺院、一切道场若戒律不清净当入之示戒，不当赞之称圣，亦不要以寺院为居。一切宗派中人，一切出家僧人，一切号称法王、讲说经法之人，之妄称高僧大德等等不持戒之人，皆不是佛门中人，更何况称圣，若以其称圣必受其害断灭佛根，是故，善知识，当以少林寺及各种邪道寺院讲经之人为警，多行头陀，以戒为本，证得佛法。諦深大师于2015.8.16开示',
  ),
  (
    title: '谛深大师开示:学佛不要叶公好龙',
    date: '2015，8，14日',
    body:
        '坐下弟子及声闻善知识：叶公好龙乃凡夫寓意于相说，而着相痴迷于法不能见佛者，不如凡夫。是故师父以叶公好龙警示大众，莫如凡夫之喻之修行之道之不如凡夫者也。\n'
        '善知识，所谓妄说、妄用、妄修，于修证了意不求者，于佛说戒律不持者，皆不如凡夫之者。是故，善知识，汝等勿于佛法成叶公好龙之愚痴之相。\n'
        '如若汝等广传汝之非证之说、编造欺诈之传，汝等为不能被救之人，恰如：叶公高者，绘画诸龙，形象胜似真龙，其日夜思念真龙显前，而真龙至时，其抱头鼠窜。\n'
        '善知识，今者佛法末世，诸等罪人甚是猖狂，假叶公好龙之能，自持佛说经典，诽谤佛法贤圣，或持邪魔道法以治病、道理、世间法理等传妄称佛法，诽谤贤圣，其罪之过，难比叶公高之愚痴。如叶公愚痴之者不过求之不得，而诽谤之者，却有堕落地狱恶鬼畜牲之罪。\n'
        '是故，善知识，入于佛门戒律为本，证得所修为要，切勿叶公好龙。谛深2015，8，14日为皈依三宝者训示。',
  ),
  (
    title: '谛深大师开示:佛门如何看待治病',
    date: '2015.7.26',
    body:
        '善知识，众生罪苦种种，其病亦五花八门。大类共分两类，其一，自己因缘所成病苦报，其二，共业因缘所成病苦报。而每一类又分相似因缘所成同名病苦名相，差别病苦名相等。\n'
        '善知识，因病之因缘不同，治病救人亦有多种名相类别，有：行医者依病相理性治病之大众医院医师、有以鬼神缘分治病之巫师、有以前世病之有缘若无缘不治之行到者、有邪魔道法假佛们名相、种种道法名相欺侮乱求医者治病之邪师等。\n'
        '善知识，有求医者因与某巫师或、或鬼神、或种种道法、或种种功法或假称治病实则诳骗者，若其病因前世食所求者肉、污所求者体等等缘分所成，其中若子因者，其之一求便好，若几人共因者，几人求其即好。而若以是称其所求巫师、法师、鬼神为大师圣人者，乃诽谤佛法道，虽现病除，种累世苦根，必受更大罪。\n'
        '善知识，诸多邪道以能治病某病故，招摇撞骗于市，有称大师者，有称法师者、有称老师者，乃至巫婆、巫师神汉，如是等等，若执其为圣，令众迷信，更宣弘于世，即成魔道令众堕落。\n'
        '善知识，大众医学理性治病救人不假欺诈乃治病实道，若遇病灾当以种种实道为依求除病苦，莫以罪重之者，为求利养故，趁病人求出苦心切，容易上当之时，以种种宣传欺诈，另愚昧者上当，成就罪孽之邪魔道法，是等罪众，必于当处堕落于地狱恶鬼**。**。\n'
        '善知识，若有病大众有佛法缘分，能持戒律或能行大供养，吾谛深能治所有病苦，令有病罪众离病得乐，若无佛法因缘，说吾能治病如视月说日，日之有痒，求者愚痴，是称一病不治，乃至毫毛病苦亦不能治。若以吾能治病广布大众，乃愚昧皈依，实乃侮辱诽谤佛法，诽谤吾谛深也。\n'
        '善知识，若有病苦，当多行善法，以种善种，矜持戒律，以获佛种，得佛法护持灭罪离病，是为智者，若假治病以为佛法，实愚痴之道耳。\n'
        '谛深2015，7，26示',
  ),
  (
    title: '谛深大师开示:莫以着法相与法师相',
    date: '2015.7.15',
    body:
        '坐下弟子及声闻善知识：是法已说，今再说之。因佛末法时期，诸邪魔外道皆以大众着法相为道，诳骗、奴役、欺侮大众故，令大众落于魔障。\n'
        '善知识，一切教派若以神通、道法、说教、经典为依而不以戒律为依传承弘扬，其等皆为邪道染污。\n'
        '善知识，譬如有人以吾谛深说为依传承佛法，其乃诽谤吾谛深，吾谛深之法，若不能以戒律为本，即为魔障。善知识，佛法不思意，戒律为根本。\n'
        '善知识，一切以某经典、某法师、某宗门为依据传承佛法者，皆为邪师。譬如有人以华严经、法华经、楞严经、无量寿经等等诸大经典为依，创办诸多宗派，或以神通、以秘密修、以净土、以禅修为依说能成佛而不以戒律为依传承诸法，其等皆行诳骗魔道。释迦如来成佛时如是说，涅磐时亦如是说。吾等庸僧于佛法有证者，皆如是说\n'
        '善知识，若有人以某经、某法师、某佛、某人说佛法为说，而不以戒为说者，当知是人乃欺佛，污僧，诳骗大众之必堕地狱之罪人。\n'
        '善知识，若有人行邪道事，以是为鉴，令魔自退。\n'
        '谛深2015，7，15日示。',
  ),
  (
    title: '谛深大师开示:切勿与余乘争',
    date: '2015.7.13',
    body:
        '坐下弟子及声闻善知识：佛法不思意，诸乘有因缘，因缘不同者，各自有道处。因道处异者，自相有差别，是故勿争斗，争斗即堕落。佛之诸弟子，汝之乘之余，即称为余乘。勿与余乘争，更勿谤余乘，若谤余乘者，即成邪魔道，是做成大障，累世难逾越，是故我今说，为令汝入座，佛之因缘宝，千叶千宝连，汝等若能知，即坐宝莲上。如是悟佛法，必获得证法。\n'
        '善知识，诸佛如是说，如来不欺诳，若人于塔庙，一称南无佛，皆已成佛道，若人闲静处，于法有思维，皆以成佛道，圆通能见佛，乃至鹦鹉戏，南无阿弥陀，必能得见佛。何故如是说，善者应当知，譬如汝朝山，道路已确定，若汝于是路，行之有一毫，是已成其路，不管何种法，只要于此路，行之一毫里，一毫一毫行，必得至终点，是称朝山路。佛法亦如是，种种修道之，必能得成佛。\n'
        '善知识，何故吾为说，不令有争斗，争斗非佛法，若于争斗者，即成反行道，所谓反行道，譬如于行路，汝当前行者，却反行为道，看似于一路，逾行逾远之。虽不离其道，却远求之果，欲求逾远之。\n'
        '善知识，皈依三宝者，应当于自道，精进勇猛证，以是为自道，莫观道友行。譬如登山者，己之不努力，却以余者说，余者已至顶，说者却未动，是称为愚痴。\n'
        '善知识，切勿于法争斗，更勿诽谤余乘，我说余乘者，实乃有罪人，假佛所说道，行断佛说法，为吾弟子故，为延佛寿命，吾为弟子说，为令脱争斗，为令脱法缠，不为余乘说，是故不为说。实吾不说之。譬如有妇人，有童教其幼，舞剑为自卫，因子于幼年，正咿呀学步，路还不会走，学剑必为害，伤己不能避，为子说勿近，并令其远离，更勿与童争，因其教幼剑，吾称其邪师，以是意故，吾令弟子远诸邪师。所谓邪师，于其自道，不称为邪。\n'
        '善知识，切勿于余乘争斗，戒中行道，必获证佛法。谛深2015，7，13日示。',
  ),
  (
    title: '谛深大师开示:看什么经能成佛',
    date: '2015.7.7',
    body:
        '善知识，佛说一切法，皆为令众生出离苦海成佛之，当机说。所谓当机者，即为因缘和合。若人与佛说某一经典因缘和合，则当下获出离，成就三身。\n'
        '尽管佛说之每一部经典，均有所指、所住，但因大众因缘不同故，各有所当机处，是故，佛说的所有经典，都是成佛的经。有人所传开悟的楞严成佛的法花，其乃是修道人之自修道说，或乃修道人因分别所成之执见说、或因狂心分别研判之罪孽邪见之说，实则佛未说。\n'
        '善知识，譬如：有修行人因问‘佛是什么？’其师答曰：‘干屎厥’而见性成等正觉；有人因诵一遍地藏经而见性成等正觉。\n'
        '譬如：吾行脚于青岛燕儿岛大街时，见一头戴红花，手捧法花经之精神分裂症者，问其兄后方知，是人因以法花为成诽谤余乘，致使自己当世堕落。\n'
        '又如：吾行脚于江西永修时，遇一苏州赴真如寺拜山老妪，以居士身于吾僧身不敬，声称其师父是佛，并为吾讲说妙法莲花经者，吾避之不及，其当下口吐鲜血后，为人送南昌医院者。\n'
        '又如：吾于莱州行脚，一居士因强行推销邪道经典，自落地狱，粪便为食。\n'
        '等等，善知识，佛法殊胜，汝等当知，依佛说为说，切勿以自己执见所解经典为说，今虽佛法末世，但诸度天人菩萨，常住世以戒为传救度大众。\n'
        '善知识，释迦如来佛何故临将涅磐，告诫大众：佛灭度后以戒为师！而不说以佛说经典为师？因若不当机，机缘有别，佛说经典即被阅者之亦执见为解，诳骗大众，令佛说成魔说者。\n'
        '善知识，佛所说法意趣难解，非常人所能思意，汝等切勿无佛或无自己皈依之大善知识有证旨意，自行翻阅。吾谛深因于佳木斯行脚处，获韦陀菩萨空中用檀香棒，奉无字真经翻而令阅，于一百天人诵经阁处，听受法花经后方阅金刚经、法花经而获印证。\n'
        '善知识，吾谛深与汝等无有一草之求，只因吾弟子说，有人遭诸邪染不能自拔之相隔数劫之不谋之缘，而为劝说：以戒为师乃佛法必获成就之传，余者于法，皆为不定报缘。谛深2015，7，7日应弟子智依问',
  ),
  (
    title: '谛深大师开示:如何护佛种',
    date: '2015.7.3',
    body:
        '善知识，所谓种性，因缘果报之圆满报身体相，所谓诸相者，皆能于诸多缘分中有界，所谓界者，我相之说，所谓我者，诸多功德成体，分别功德与我相成界。\n'
        '善者，是故十方含令皆因故成众生相。佛说无我者，乃包含所有众生之令众生悟知大界者说，是故，众生种性有无数之多，无上佛之种性最大，包含一切；其余皆以功德福报界体比拟，分别说之大小。各个种相，递相为种，含小缘分，缘小性微，不变种性，成种差别。缘大变性，成新种子，以是成众生世界。\n'
        '譬如：植被大小之分，含所成缘分数多少称为大小。动物种性大小，以植被为用基础，思维大小分别为界，成天地人之相，以其包含大众之种种人乃至地狱恶鬼畜牲多少分别大小。是故，众生之为大小，多以智慧为判相体，以肉身相为依着体。人之智慧能容诸多恶鬼畜牲，则人之为大，等等。\n'
        '善者，所谓佛之种性，十方世界之父，所谓虚妄，十方世界之母。大众因有成于妄起因缘，因缘圆满和合分别内外成种故，不能于佛之缘分知毫许少分，但于佛缘分中，皈依佛后因佛恰如暗遇光明，种性自变。而诸多大而罪重种性者，因罪大业大故，假佛名号令所含众生种性成自性种，恰如谷物留种，一种成本复制传延，断灭佛之种性，令佛法入末法至断灭。是故，佛法难遇之说，缘自佛法难遇而自认为遇，亦即，自称佛法者，却非佛法，所谓佛种实非佛种即佛种灭度。\n'
        '善知识，佛法末世，自称佛法而非佛法者，成佛法主流，佛法灭度。是故，吾令弟子严净毗尼，以护佛种令种能出。谛深2015，7，3日示。',
  ),
  (
    title: '谛深大师开示:把握因缘把握道途',
    date: '2015.7.2',
    body:
        '善知识，因缘果报分毫不差，因缘中人不断改变自己，便会形成新的因，造就未来新的果报。是故，大众于种种法中，有升有堕。是故，诸佛教诸大众，诸善奉行，诸恶莫为；是故，我教弟子，严净毗尼，莫行愚痴之作。\n'
        '善知识，一切有为法，诸众受制之，若无证出离道，须得随缘行，所谓随缘行，行即成新因， 成诸相缠法道，造就因缘变相，所谓相缠法道，凡夫因缘之变诸为应之，我今为说，以令汝等明凡夫道。善知识，若不明凡夫道，即为凡夫，若明凡夫道即为圣人。 成诸相缠法道，造就因缘变相，所谓相缠法道，凡夫因缘之变诸为应之，我今为说，以令汝等明凡夫道。善知识，若不明凡夫道，即为凡夫，若明凡夫道即为圣人。\n'
        '善知识，因缘变相，有两种生处，一者，无中生有生处；二者，前因后果，由果生新因之生处。\n'
        '无中生有造因者，譬如有人妄想肉身能飞，于梦中忽然漂浮于空，梦醒思之有道，一生为此不懈努力，而造种种因，是因虽不能报其初衷，但却生成新业果报。是事生于无中，却以有报，称无中生有因缘变相之因之生处。\n'
        '前因后果之新因之生处，譬如：有人诽谤与你，你甚气恼，本应诽谤其者，为其之报，然汝怒火生起飞拳砸之，令其人重伤，此过之余者，成新因缘，其又寻报汝，如是恶而复始造就恶业，如是之者，称为前因后果、由果生新因之生处。\n'
        '善知识，修行出离法，无中生有者共八万四千类，每一类又有八万四千种，细分还有种种至灭。\n'
        '譬如：有人未证空性，思维证之，是称妄空，妄空之者于所住因缘不怕因果，实则未空，堕落金刚地狱，难有出期。是种堕落就有八万四千堕落之相，多为破戒妄成。\n'
        '又如六通畜牲道，因虚妄故，成就种种妖魔鬼怪，未证谓证、未悟称悟，于其类别，八万四千再八万四千者，如是堕落成体，又回成体，缠缚于人，徒众甚多，成难救道众。是等亦多称自己为佛法、法王。\n'
        '善知识，修行之人前因后果，称大道体者，因因果明确，成世界本，种种显前诸相令众生折服成体，不信佛法多于诽谤，造就佛法难度因缘。譬如：哲学、法学种种科学，气功异象种种难解之相，皆为前因后果推理思维之本。是等，成大众之依，难于救拔。\n'
        '善知识，诸佛所说法，是为凡夫说，令凡夫有悟，令凡夫能于未悟前有福报。所谓有悟者，实为证之妙，唯佛与佛乃能究尽，一切天、人、阿修罗不能知少分。一切大神通阿罗汉，乃至十地菩萨所不能知。是故，佛说为善因缘，于道途严净毗尼，汝等当做，莫自愚痴于空、愚痴于妙有、愚痴于禅定、愚痴于神通而使主张，善知识，谛深只一名相，实无谛深，只为令末世众有能救者，称其谛深。汝等当以信受教，获得解脱，自知汝等为真谛深相也。谛深2015，7，2日因弟子智偌于因缘果报有悟示。',
  ),
  (
    title: '谛深大师开示:入了佛门不要入飞蛾投火道',
    date: '2015.7.1',
    body:
        '坐下弟子及声闻善知识，凡入佛门者，皆为出苦，生老病死、烦恼五浊、杀盗淫妄诸相之苦众生皆具。\n'
        '为出苦海，大众因不能了却种种因缘果报故，以自己执见判别出苦之路，因自己执见本自苦缚故，是为以恶量恶，聚之大恶成世间诸等宗教信仰、诸等层次之道。所谓天人阿修罗入人道所成教，鬼神妖孽所成教，地狱恶鬼畜牲所成教，人之用相道理所成教等。诸等教派因缘果报自成其报，生老病死杀盗淫妄一应俱全。\n'
        '善知识，如是之众教派，于佛法成诽谤相，以诽谤佛法故，不获救应，逾修逾苦，罪苦为道，不能出离。\n'
        '善知识，佛门亦有罪苦之道，譬如：有人因苦出家，获佛福报，却以尘缘判别佛说，或以思维未证传法，或以种种宗教方式愚昧信众，或以种种世间法道，科学之说、社会应道称佛法者，或以佛说、经典说、祖师说自己未证予以施人等等之道，如是之道、称为佛门罪苦之道之等等说教。\n'
        '善知识，如是说教之下之种种大众，譬如飞蛾投火，飞蛾观其光明照耀，以为日光飞而奔之，却因自己无有辨别智慧，以自己执见以为智慧故，假火为日而为火灭。佛法修证亦复如是，诸多善众因假自己执见量度道而选师，却不以戒选师故，恰如飞蛾投火遭邪魔外道法害。\n'
        '善知识，谛深不欺诳，戒乃大渡船，若不以戒为本，所有宗派族、法王、道王尊皆为邪魔道，不能救大众。若有人以禅，若有人以密，若有人以说，若有人以净，若有以开悟，若有以神通，等等善软说，皆如骗之术，令众遭堕落。汝等入佛门，当以戒选师，必能不遭骗。\n'
        '善知识，入了佛门为求出苦，切勿以自己执见入邪魔外道法，断灭佛种，出苦无期。谛深2015，7，1日示。',
  ),
  (
    title: '谛深大师开示:什么是僧宝',
    date: '2015.6.30',
    body:
        '坐下弟子，什么是僧人、什么是和尚师父已说，今为汝等讲说什么是僧宝。\n'
        '善知识，所谓僧宝者，放下尘缘，严净毗尼法者，称为僧宝，不能持佛制圆满戒律的，称之为诸等僧人乃至假佛法衣四处行骗为大众称之为假僧人者亦称为僧中劣等之恶僧，如是诸众称为僧众，但不都称为僧宝。\n'
        '所谓皈依僧宝者，称皈依僧。而于尘世罪孽众生，无有天眼、法眼，随因缘漂游者居多，实不知皈依僧宝之圣。是故，为有罪大众能皈依僧者，称皈依全部僧人为皈依僧。为令大众能入佛门获法故，令大众得种种道法但不堕落而不为邪魔外道俘获故，令大众入门后能沙里淘金获得皈依僧宝必有救故，令大众获得包括恶法方能圆满故，吾说皈依全部僧人为皈依僧。\n'
        '善知识，皈依三宝必获救度。谛深2015，6，30日应弟子智缘问。',
  ),
  (
    title: '谛深大师开示:什么是皈依僧',
    date: '2015.6.30',
    body:
        '坐下弟子及声闻善知识众，近期有很多居士因皈依了某法师、某人就不受我的法了，故给你们讲一下什么是皈依僧。\n'
        '所谓皈依僧者，指出家人全体，一个出家人不成全体。若皈依者以某法师为僧，其余皆摒弃，即落大坑成诽谤僧宝故落魔道。\n'
        '因大众于法分别，难于道理出离故，如来说邪魔外道，实无邪魔外道。我之弟子皈依我后，听我如是教诲，不允听彼邪知邪见，是：令汝等能包含邪魔外道之邪知邪见而不以邪魔外道之邪知邪见为依屏蔽、诽谤大众所分别的正知正见。而邪魔外道之邪知邪见恰以自己执见为道之正知正见，是故称狂妄。\n'
        '善知识，譬如：屎克郞认粪为佳肴，实则其见实，其见于其道，称为正知见，其谤人中尊，是称屎克郞。而于诸人等，能明屎克郞，以其为道理，是称包含之，是故人为上，若以粪为媒，人则不能比，是故能为人。\n'
        '是故善知识，世间一切法，不当说其过，因缘如是者，其实亦无过，如是悟吾说。\n'
        '所谓皈依僧，亦复如是也，是僧当敬之，只敬吾谛深、只敬某僧人、不敬某外道不敬诸外道，不称为修行，不称吾弟子，以是吾为说，十方如来说，有诸邪魔道汝等当敬之，若不敬之者，于法有却漏，不能证佛说。\n'
        '是故，若有人以某法师、某僧人、吾谛深、某祖师为最，而不以所有法为最，而于是法有悟，即为其所称、所屏蔽之邪魔外道。\n'
        '善知识，吾之弟子于于末世当知福报甚大，能囊括十方世界所有法、所有道、所有法、道之正象末，而不以某法、某道、某人之道为道者，称佛弟子。而以某人、某法、某道更何况某法师为道者，不称佛弟子。\n'
        '坐下弟子，汝等当如是悟、如是解、如是用如来所说。谛深2015，6，30日因有出家人为拉居士狂妄说法故特做开示。',
  ),
  (
    title: '谛深大师开示:如何看待自己的修行',
    date: '2015.6.30',
    body:
        '坐下弟子，每个人的缘分不同，修行渐次、修行法道亦不相同。正坐下弟子，每个人的缘分不同，修行渐次、修行法道亦不相同。正所谓差之毫厘失之千里。是故，诸佛世尊住世，广施甘露，滋润沃土，戒如大地，万物生长各有法则，各有导师播种呵护，令之硕果累累也。所谓差之毫厘失之千里。是故，诸佛世尊住世，广施甘露，滋润沃土，戒如大地，万物生长各有法则，各有导师播种呵护，令之硕果累累也。\n'
        '吾为汝等今日讲说三大分别，以助缘分大众修行证道。\n'
        '第一，无上如来如意法宝，譬如天降大雨，令万物生长也。如来说法，大能以永，然个人种性有别须各个须别有天地，如来亦一应俱全应之，是称佛宝、第一如意法宝。\n'
        '第二，各种缘分之机缘法宝，譬如：雨后农夫能以种种技巧劳作，令所种种子生长发育，佛法住世，度天人菩萨及各个法王、导师恰如农夫是也，是称第二如意法宝僧宝。\n'
        '第三，各个同门同宗缘分，种性差别如意法宝，譬如：农夫耕耘，植被生长亦各个微细差别，农用技术员工为各个除虫除病，是等乃第三如意法宝僧宝是也。\n'
        '善知识，虽三宝住世能令诸等得度，然，自己缘分确定种性，譬如：玉米稻谷种性有别，虽经农夫技工调服哺育而令成熟，然果实不同。是等称自性修行耳。\n'
        '是为譬如，只谓之理，实佛法三宝、三道皆可令大众于当处证一称果位，譬如：罗汉之粥为万米所成，虽米之有别共成一粥，是称一门之乘。\n'
        '善知识，汝等既入吾门，各自种性，切勿以一法而判同参之修，当于戒中，自性精进，于我佛法中勇猛证自己之果位。谛深2015，6，30示。',
  ),
  (
    title: '谛深大师开示:法师应当持',
    date: '2015.6.30',
    body:
        '善知识：佛法真实不虚，是故我为诸大法师说劝。\n'
        '所谓讲法、延法、示法者，若未证以思维所得谓证讲法，是称妄证。妄证之说，称为诳骗大众。若是种法师信佛，不敢妄说也。因妄说佛法，诳骗大众其罪若以人为界，正说向上，妄说向下，名声欲大，其罪欲殊。若不信佛，是做定不怕因果报应，而吾谛深实言公告，佛法真实不虚，诸法佛说，吾均有证，其必被报。\n'
        '善知识，入于佛门为脱苦缚，现实报苦、未来苦、六道苦是也，而于佛法福报，再造大罪实在不应当。\n'
        '善知识，切勿以未证之说，施于大众，或以六道法则，令大众共鸣称之佛法，而自寻堕落，是劝应当持。谛深2015，6，30劝示。',
  ),
  (
    title: '谛深大师开示:为什么邪魔外道能灭佛法',
    date: '2015.6.18',
    body:
        '坐下弟子，为什么波旬能住道场释迦流泪？何故邪魔外道能灭佛法？因世界罪苦有道故，因诸法法而罪苦故，因众生之因法而生、又生心力，诸法之道成诸所求、应诸所用，心能为得，即使成罪亦必趣而求之，而佛法难思难解难证须佛住为师方能示现故。\n'
        '善知识，譬如：猪牛、刍狗、鸟兽、蚂蚁诸物，若以理喻但以食教，是等必为食之为俘获者，种种驯养之道应运而生，后为人宰割者，若其等寻食之暂，汝等为说上当，其等必攻击汝等甚更伤害汝等，其实其等乃为上当遭屠戮奋不顾身也。\n'
        '善知识，佛法住世终为邪魔外道灭，汝等弘吾佛法遭以假佛法衣之波旬法众以罪孽嗔恨之心诽谤于吾亦复如是。\n'
        '善知识，譬如：有鲜卑之人饲养狗群以食其肉，汝等欲入狗群令诸狗有出得救，汝等必遭狗群群起攻之，甚至遭分而害之。\n'
        '善知识，佛法末世波旬之子孙将住于道场，不执戒法，以种种世间大众公认道理令大众服而为得，破灭佛法令佛法灭。\n'
        '善知识，汝等当严持佛戒，勿落道法。谛深2015，6，18日示。',
  ),
  (
    title: '谛深大师开示:师父的法为什么很多人不能接受',
    date: '2015.6.16',
    body:
        '善知识，六道众生之所以地狱恶鬼畜牲能成其道，皆因界内罪苦有理有据。譬如：世间法认为人之有病乃固有规律，凡人生老病死乃其必然，无有病苦乃瞎说之句，医学科学皆论之必然，吾说人能无病，亦能无生老病死，世间医学、科学乃受罪之理之律，人之不信，因不合其理。大众以生老病死寻其理律令之有救为道，而此即是六道，因其为六道成因，是故，如是信众，不出六道。实则，若真心皈依于佛，能如佛说修行者，吾皆令其无病，亦令其得无生老病死乐，更令其出离六道罪苦。\n'
        '善知识，譬如：有人终日被打，日日啼哭，国王大臣皆奴役之，累日成习。若有人说能令其终止受苦，其会顿生疑惑，虽心存感激，因其信所住之国王大臣，而其欺之。是故，其不信是人之说，更不信令其获救。以是意故，是人认为受罪即是世间道理。地狱恶鬼畜牲之道，累劫罪恶，成罪恶规律，恰如1加1等于2者，若复有人说其不等于2，大众蚩之。实则，1加1等于2是有条件的，10进制下等于2，2进制下等于10。\n'
        '善知识，有魔王假佛袈裟说是等罪重之道，大众以其有道故，皈依崇拜，实乃罪孽之道之合世间规则之应堕落地狱之举，以是法令众以为必然，大众罪孽深重遭此法幻，于意识认知罪恶成佛法堕落成界，集体奔地狱不能为救。\n'
        '善知识，佛法末世如是罪法极为盛行，如水中漩涡，入之不能自拔，必遭溺死。汝等当精进持戒，莫听恶法。善知识，佛法不思意，持戒能得之，并非辩证道。谛深2015，6，16日因有皈依声闻遭邪道染示。',
  ),
  (
    title: '谛深大师开示:不杀戒戒障第一、第二',
    date: '2015.6.16',
    body:
        '善知识，所谓戒者守之为得；所谓受戒，为得而应；所谓持戒守之有障，破障之举。\n'
        '善知识，所谓戒障，乃不解而持，持有诸侵，侵而破戒，再而持之。\n'
        '善知识，是故吾今为汝等讲不杀戒第一、第二之戒障。\n'
        '善知识，不杀戒戒障，师父今日为说，善思念之。\n'
        '所谓不杀戒戒障第一，若受戒后杀者为疑惑无戒欺佛罪，见杀为道途过，而于是障，若无证得，难以逾越，是故称障。譬如：老虎恶狼雄狮猛兽，其遇牛羊之群，汝之为戒清净者，为慈悲故，以心为用，以眼为观。若猛兽不杀，其不日毙命；若猛兽杀者，牛羊毙命。因猛兽猛禽獠牙外露，内脏脾胃于血肉合，若汝为救牛羊令猛兽食草，其脾胃受损不化，不日因故病之，后而毙命，实汝杀之者也犯重罪。如若不问不闻，令牛羊遭屠，为见杀不救，有地狱落相重罪，汝等如何处之？是称杀戒戒障。若有人称吾视而不见是为修行，是人即犯妄说重罪、杀过重罪、道途魔着重罪者。\n'
        '善知识，谛深为汝等讲说戒障破灭法，如今谛听，善思念之。\n'
        '善知识，六道罪众，轮回为报，若不皈依三宝，着佛袈裟，诳骗大众获受福报，其乃重罪之身，不能为师，而若为师者，即魔道王。师父何故讲说邪师之做，因是法与戒障破灭之教授阿闍里第一为因。\n'
        '善知识，譬如：极乐世界无有恶鬼畜牲，以是意故，其众无有罪染，更不知有杀业，是故，善知识，皈依三宝，僧宝师长为最，若无如来应世，汝必遭戒障，若遭戒障，不能离杀盗淫妄罪孽轮回。是故，汝等欲破灭戒障，获得无漏清净戒师第一。\n'
        '善知识，六道轮回，众生递蒻为食，互制、互用，互转，今者，称生态平衡，实则，各受罪苦，以是为道，有理有据，是称不杀戒戒障第二。\n'
        '所谓不杀戒戒障第二，若无狮群牛羊泛滥，草之难生，万物濒绝。如是之者，又如人群暴增，物种灭绝皆与破坏生态平衡有关。若不制止，令杀者见杀，必遭大患。又如所谓不杀戒戒障第二，若无狮群牛羊泛滥，草之难生，万物濒绝。如是之者，又如人群暴增，物种灭绝皆与破坏生态平衡有关。若不制止，令杀者见杀，必遭大患。又如计划生育，若无计划，人之悲惨不能为活，如是等等，皆称不杀戒戒障。是等戒障令诸多凡夫与出家无有明师僧人于戒成谤，妄说妄为破灭佛法。计划生育，若无计划，人之悲惨不能为活，如是等等，皆称不杀戒戒障。是等戒障令诸多凡夫与出家无有明师僧人于戒成谤，妄说妄为破灭佛法。\n'
        '善知识，破灭是等戒障汝等须得获明心见性，方能知晓。师父告诸汝等，六道之道为其道者，有其六道必然，是故，入地狱恶鬼畜牲道者，若不皈依佛者，不能有出。\n'
        '譬如：汝于泥潭累世博生，吾呼之者，与之绳索，汝当依泥潭之道，静候片刻，执吾绳索，吾为救之。若吾不救，汝于泥潭久成道理，不信有救，必累世遭泥潭报。杀戒戒障第二者，亦复如是，汝等虽有罪孽道理，然让汝等明白汝等愚痴，须得皈依于佛，明心见性，吾为汝等讲说破此罪障法，汝等方能悟之罪障。否则，恰如对牛弹琴，愚痴之为，所谓罪障者，罪孽之道成汝之障碍耳。\n'
        '善知识，谛深不欺诳，汝等当听劝，切勿落杀贪，其道如泥潭，道深罪亦深，落之难有出。释迦善知识，谛深不欺诳，汝等当听劝，切勿落杀贪，其道如泥潭，道深罪亦深，落之难有出。释迦因地行，遇虎饥饿食，其道为之也，舍身饲之耳。善知识，汝等切勿落佛戒法道障，遭大堕落。谛深2015，6，16日示为末世僧众不持禁戒者说。因地行，遇虎饥饿食，其道为之也，舍身饲之耳。善知识，汝等切勿落佛戒法道障，遭大堕落。谛深2015，6，16日示为末世僧众不持禁戒者说。',
  ),
  (
    title: '谛深大师开示:什么是世界末日',
    date: '2015.6.15',
    body:
        '善知识，挲婆世界乃释迦如来累世累劫施身成就，尽管有种种外道道法、种种教派不信佛法，诽谤佛陀道人，但，若佛法灭世界即灭。若世界有佛法在，世界便不遭陵灭。\n'
        '善知识，譬如：汝身之中种种疾病，不尊汝之说教令除，狂妄自大，不信汝死其灭，最终占据汝之整个身体，汝随气绝身亡。其等因不信汝灭，其亦必灭之病者即遭灭顶。佛法灭后世界不存亦复如是。\n'
        '善知识，吾谛深末世出世，实言告汝等，佛法真实不虚，若佛法灭，世界即灭。种种邪道假称佛法，其亦必不能存留。种种邪魔外道诽谤佛法狂妄自大，自以为为世界主，实则恰如人身之病，若其为主者，人之苟延残喘不日即毙，是等病者亦随之灭。以是意者，是等罪众于佛法灭后，与世界一起自然遭灭。\n'
        '善知识，汝等为我弟子，当发大慈悲心，修行证道令佛法住，为佛留气延息，延佛寿命，以是救世。否则，世界将于佛法灭后，后500岁灰飞烟灭，无所征兆。\n'
        '善知识，吾谛深住世为延佛寿命，汝等当以是为效，莫以诸多未证谓证罪人、诸多邪道为效，汝等当依我所教法，持佛戒律，证佛所说方能延佛寿命。以是为悲请佛住世，令世界延寿。谛深2015，6，15日示。',
  ),
  (
    title: '谛深大师开示:什么是口业 (二)',
    date: '2015.6.15',
    body:
        '坐下弟子，所谓口业即因不当之语令自己受害、或遭恶报、或遭其累、或获有求反应之直接或间接或延时堕落之因缘果报。\n'
        '佛门弟子于种种行中，口业重者，多为罪重之者，以自己执见入佛门求善报，却自己因狂妄自大故，成相修道实作业作恶之者。\n'
        '善知识，佛之正法时，受戒弟子戒行清净，信心十足，因戒律持守故，少有口业者堕落者，多有修道成就者。佛法末世，诸多所谓入佛门者，其种种行为因戒律丢失故，多有口业堕落者，求应不定，受为人劳苦、或有钱招恶、或为官难通遭馋，或贫困穷苦等。口业重罪，死后遭地狱罪苦报。\n'
        '吾之弟子当知，汝等切勿图一时心快，无意之中造大口业。汝等当知，入于佛门为求修道福报，因言语口夸，造业受报实乃愚痴。是故，汝等当矜持佛戒，早获离苦。谛深2015，6，15日因居士狂心兴诽谤法训示',
  ),
  (
    title: '谛深大师开示:佛法末世与佛法灭度之相之罪',
    date: '2015.6.15',
    body:
        '善知识，所谓罪者，乃众生因攀缘心生，贪嗔痴恨所知诸业道理所成自己执见所表之相。\n'
        '善知识，因不持佛之禁戒披佛袈裟故，大众以是为僧宝皈依受教，以其所表罪孽执见以为佛法，成就妄知罪孽为德受护法护持；因妄知罪孽为德护法护持故，成大众信奉佛法之假相实波旬门；大众入波旬门以为佛门佛法故，佛说诸经皆为波旬用，成罪业法。\n'
        '善知识，因罪孽大众住持佛之道场故，佛法由末世转入灭度之相，佛法灭度有如下罪孽之相：\n'
        '1、道场住持亲近权势、亲近施主，不持禁戒，杀盗淫妄诸多有加。\n'
        '2、道场僧人不持禁戒，吃喝嫖赌为众人恨。\n'
        '3、诸多罪重之者，非佛门人却身穿僧衣、或被袈裟于世间化缘行盗。\n'
        '4、诸多罪众为罪孽故假于寺院受皈依法，实则不皈依三宝、听波旬使者不持戒僧众狂妄说法，或以方丈身四海张扬，以贸易、利益、权力、妄说、参学等等为说，灭末世佛法之最后残留，令大众以罪道以为佛法。\n'
        '5、来真实之意，于是成就波旬教，因大众不能分别故，皈依受教，成就波旬之身，佛法灭度。\n'
        '6、佛法由末世成灭度相，世间福报大于寺院道场福报，罪业大众住高楼大厦皆高于佛殿，受罪大众皆不自修德，多于观音地藏求其哀佑，弥陀药师求其加倍，常于佛相塔庙诉说罪苦，恨佛慈悲。而寺院僧众多因妄解观音、地藏慈悲愿力故，自将观音地藏置于公墓，或于墓地兴建地藏殿堂，污佛污法，令大众堕落。\n'
        '7、佛法灭度之相，罪重之者，多于厕所茅坑粪便之臭处，燃香去臭实则引因罪众传法护持有罪之鬼神住于臭处，成堕落侮辱之道。\n'
        '8、佛法灭度之相，广大在家修道之者，有累劫缘分，却于一朝破法堕落。或将佛相供于犄角、供于偏室，甚至供于污浊之处，自己住于大室、干净之处。\n'
        '9、佛法灭度之相，诸多罪众不持禁戒称佛法者，或称密乘、或称极乐、或称禅法，以是成就佛教之门，实则佛法已经灭度。\n'
        '10、佛法灭度之相，权力之者、罪孽之者诽谤佛法，因鬼神早已为僧众欺侮故，佛法护持难分真伪，是故，罪重之者，难受显前罪报，令大众不信，佛法直灭。，佛法直灭。\n'
        '11、佛法灭度之相，广大在家出家道人，多于佛法成交易想，若我信佛，先让我病好、或所求应，否则不信。如是等等，成根本罪，难能助。\n'
        '12、佛法灭度之相，罪重之者，因累世佛法缘分，却于世间法寻求与佛法相提并论之道，种种道理假佛所说，以种种法，解释佛法，灭度佛经。\n'
        '13、佛法灭度之相，多有娱乐以佛法为点，成娱乐演绎演艺之用，以世间罪苦间歇乘善，灭尽大众心中善根。\n'
        '善知识，吾之弟子当如是知晓佛法灭度之相，知晓如是重罪之世已经到来。师父灭度后，世间会先起风灾，宰杀诸相，再起水灾粉碎诸相，最后火灾灭尽罪世。\n'
        '善知识，汝等当精进勇猛持戒修行，当世成就脱离险宅。谛深2015，6，15日示。',
  ),
  (
    title: '谛深大师开示:护法功德',
    date: '2015.6.13',
    body:
        '善知识，佛法真实不虚，非大智、大行者所不能有悟；非大愿、大力者所不能传承；非大慈、大悲者所不能布施；\n'
        '善知识，佛法有无量功德福报皆因护持有得，所谓：相护持、法护持、用护持、音护持、修护持、传护持、悟护持、说护持、体护持，分护持、涵护持，如是乃至一切有名之命护持。\n'
        '善知识，断灭佛法有无始罪孽堕落之道，所谓未证谓证之：说法破、护法破、用法破乃至种种我慢、自我名相之称谓成佛法破、一切鬼神诽谤道派成佛法破相者等等。\n'
        '善知识，佛法末世天龙八部居士有相护持佛法，以罪业愚痴故，成护破佛法相，破佛法相称为护法，是故佛法随灭。善知识，佛法末世天龙八部居士有相护持佛法，以罪业愚痴故，成护破佛法相，破佛法相称为护法，是故佛法随灭。\n'
        '善知识，佛法不思意故，诸多罪众因不能证得而以自己执见分别量度佛所说法，护持有罪法，令波旬住。\n'
        '善知识，因众生累世罪孽知见，无有智慧分别正邪，故，只护戒为护。是故，若有人以钱财、权力入佛门行功德却不知戒行，则是人不获功德却遭罪业显前。若复有人能因戒律，施于道者一分一毫，乃至微尘小物，其功德胜于大广众聚之诵经功德福报万倍之上。\n'
        '善知识，若复有人为护佛说戒律故，舍命为之，是人福报不能祥尽。\n'
        '善知识，吾谛深因护佛说戒少许获步步有证。是故，汝等莫以说求，当以戒应，方能获佛法证。\n'
        '谛深2015，6，13日示。',
  ),
  (
    title: '谛深大师开示:在家菩萨最不容易',
    date: '2015.6.3',
    body:
        '坐下弟子，在家修行者为出离前修行段，最不容易。譬如：治病救人，最痛时刻乃药治与刀切之做。佛法救人亦复如是。出离之前种种业障需要剥离，是为最为痛苦之做。是故，吾说在家修行最不容易。\n'
        '善知识何故普贤愿王为修行说，亦因断罪业相用，是称修行。如是十大愿王为菩萨依止。\n'
        '善知识，若有人称在家成道者，实乃以病称康。善众当知，此乃慈悲之缘，若无愚痴，无有智慧；若无罪苦不成慈悲。\n'
        '坐下弟子，是故汝等当兴善软心于种种在家菩萨之行，乃至邪魔道诸罪之众，亦当慈悲成智，以令获福。谛深2015，6，3日为皈依弟子示。',
  ),
  (
    title: '谛深大师开示:什么是方丈',
    date: '2015.5.24日',
    body:
        '坐下弟子及声闻善知识：什么是出家、什么是末法时期，师父已说今不再讲。\n'
        '出家之后的人，称出家人，出家后以戒为师，依佛说修行者，乃佛法正传。若并非看破放下者出家，称相出家，出家后，分为种种层别，有诸多层别会因此堕落。其中，于佛法正法时期之是种僧侣，多能遇大善知识慈悲救度，获证佛法。而于佛之末法时期，是等多能于道场中，以贪嗔痴杀盗淫妄等罪，住持道场，并因此堕落不救。\n'
        '善知识，即使是等不持佛戒，住持道场，亦能传承佛法。譬如：皇帝外行，有种种车乘，有人抬之轿，有神驹宝车，亦有驴车。皇帝身乘驴车时，是驴所至之处，鸣而不寂，大众闻其音即知皇帝驾到，因故虽其叫声难听，大众亦不说其过，其驴亦倍受大众爱护。其驴因大众爱护故，并以良食供养之，以为自己乃万众之圣，于是，忘乎所以。皇帝启车而去卸车后，其驴或被大众牵走以其为皇帝用过而饲养之，或遭大众奴役、或遭大众杀食。\n'
        '善知识，佛法末世，住持道场之种种方丈中，若不持禁戒未证谓证未得谓得者，亦复如是。是等罪众于佛道场住持杨威，虽于己无益于大众有害，获受大众唾，却能传法，其等死后依所做功德，分类转世堕落。\n'
        '善知识，莫因一些寺院方丈罪行罪说而蚩之。因缘果报分毫不差。汝等当精进修行证佛所说。谛深2015，5，24日示。',
  ),
  (
    title: '谛深大师开示:怎样能证得佛说',
    date: '2015.5.20',
    body:
        '入佛门最重要的是如何证得诸佛世尊所说。\n'
        '若人未出家，不行皈依法，亦不持当戒，能诵诸咒禁，能终日念佛、能天天诵经，为佛慈悲故，令获毫许得，以令生信心，若以是称道，是称灭佛法，不能证佛说。若以白衣身，或以僧相身，不持应当戒，讲说佛经典，虽已成佛道，却为道中邪，譬如人身病，虽为人身肉，称为身中邪，须当令除之，不除人必死，是故不持戒，行佛所说事，恰如人身病，其乃断佛命，虽获眼下福，不能证佛法，罪重成堕落。\n'
        '若人未出家，已行皈依法，能持应当戒，于诸三宝前，多行大供养，是等白衣众，能获佛加持，或见护法显，或见韦陀尊，或见伽兰圣，或入如来处，听受佛说法，渐渐生大信，入佛出离道，不日于死后，能入佛坐下，成就三宝身，获得出离境。\n'
        '若人已出家，不持佛说戒，是称为波旬，讲说三藏法，不证佛所说。出家戒为本，能持佛说戒，必得见如来，亲口承佛教，得证佛说事，成就佛妙果。\n'
        '善知识，入佛门以戒为师，必获成就。谛深2015，5，20日示。',
  ),
  (
    title: '谛深大师开示:如何往生极乐世界(第一品）',
    date: '2015.5.17',
    body:
        '坐下弟子：\n'
        '譬如：有人从来不思、不想、不念我谛深，是不会到我这里来的。若有人不念阿弥陀佛说能往生极乐，以是意故如同痴人说梦。是故，念佛是入佛门的基础，若人不念佛说佛门事，恰如饥人说食。\n'
        '坐下弟子：\n'
        '譬如：有人于千里之外想念我谛深，欲赖我之住所拜见我者，其需越过千山万水，克服种种障碍，方能得见。若有人说，只要想念我，不用行路就能来至我所，得见于我，是人愚痴否？\n'
        '入佛门只说念佛，诽谤戒律、禅法诸乘说能往去极乐者，实乃愚痴之者。入得佛门，念佛为本，需入持戒、参禅、诵经、发愿持等等法方能往生，恰如行路之间耳。释迦如来不说，念佛一定往生，只说，一心不乱称佛名号，若一日、若二日、……若七日一心不乱，佛则接引往生极乐。\n'
        '如何能一心不乱？戒为根本也，定为根本也，愿力纳界为根本也！\n'
        '是故，念佛乃入佛门修行之基础，而持戒、参禅、入定、诵经等乃往去极乐获得一心不乱之过程矣。虽然，这个过程因因缘不同，人之各个有异，然，当世念佛往生者，已经累劫持戒、参禅、诵经而今已功到果成也。\n'
        '坐下弟子：\n'
        '譬如：有人已经千山万水，来至我住处山门，我率左右开门迎接其入门。念佛经持戒参禅获一心不乱，弥陀接引往生极乐亦复如是。恰如经努力克服千山万水来至我门前我为接应者，弥陀托灯，观音势至坐莲台接引极乐以是意故。\n'
        '云何有邪师不解佛所说意，断章取义以念佛为法门，并诽谤余乘？\n'
        '是等邪师，看似善软，实则重罪。讲说，世间法都修不好，修戒律、禅法就更不行，只有念佛是唯一出路。这是邪魔假佛名号，断佛法种的罪知罪见罪解。\n'
        '当年憨山大师为证佛道，提笔忘字，连走路都糊涂，当他证得海印三昧，即为证耳。\n'
        '善知识，依佛所说，切勿未证谓证诳骗大众。于法末世种种邪道盛行世间，假佛门某个名相诽谤佛法余乘者甚多。汝等当精进勇猛持戒，于禅定功夫舍命修道方能证道、证得佛所说法。\n'
        '谛深2015，5，17日应弟子为有魔民问法示。',
  ),
  (
    title: '谛深大师开示:供请大德',
    date: '2015.5.13',
    body:
        '坐下弟子：\n'
        '今日午时又有修行大德圆慈归寂，自师父住世一来，其已是道果有成之第四位！其徳行心镜，于佛门无名更少有知之，即使其同参道友亦不为知；是故，远隔万缘，不曾道及，如是大德精进修证之行力、慈悲法施传承，为佛门辉。\n'
        '善知识，佛法末世有是等大行者住世，乃众生之福报缘分。\n'
        '善知识，是四位高僧，皆无名于所谓佛教，有道于兜率、有道于极乐、有道于梵众。\n'
        '善知识，吾与汝等共度出沉沦大缘结处。与汝等于是者所有乘愿不住相之德所应、与是者慈悲海中受洗所缘，于当处滋长所道，成所佛种今发芽之相共成一脉。是故，为之应供，为当度缘分应供，为之道时应供，为无量众生应供。\n'
        '善知识，汝等当以是等高僧为师效，严净毗尼，精进勇猛出离罪苦。阿弥陀佛！谛深公历2015，5，13日为圆寂大德高僧供示。',
  ),
  (
    title: '谛深大师开示:莫污僧尼',
    date: '2015.5.7',
    body:
        '善知识：佛法僧三宝乃佛法主体，缺一不可。是故，佛于普照大众之阿弥陀经中说：‘闻是音者，自然皆生念佛、念法、念僧之心。’所谓僧者，持戒沙弥比丘身是也。所谓持戒沙弥、比丘，乃于一戒二戒三四五戒至全戒修持中受戒出家人之称也。\n'
        '若有人以某种自己知见不受之事、某种所谓道或之所谓之佛道、等，或以居士身、或以僧相身、或以某道行者身、或以宰官身、或以术士身诽谤出家僧人者，是人若不忏悔，必断智慧种、佛种、福报种等。是故，善知识，莫假僧相毁谤余乘，更勿以种种说诽谤僧相。\n'
        '善知识，为教众获福故，吾呵斥审判入我法中，假佛赐法衣，宣扬波旬法重罪之者，实则，乃判障道罪障。与其所假僧相无有关联，若有人以是说者诽谤与汝等，乃行堕落法。\n'
        '善知识，皈依三宝，清净戒法，为汝等当学。谛深2015，5，7日示。',
  ),
  (
    title: '谛深大师开示:佛门修行的几个关键',
    date: '2015.5.6',
    body:
        '坐下弟子：佛门修行段次师父已说，今再为汝等讲说关键之机，以令汝等有的而定。\n'
        '善知识，大众修行过程累劫沉浮，难于定夺自主，不知生前为谁，不识自身何物，不明死后乃谁，只于听说而论自说、自论、自是者，不知生死之本。是故，汝所有修行寄予经书所说，自不能证，是称盲修瞎练，因自不知所，却寄予闻说，以是为盲。\n'
        '善知识，佛说经典乃实语之表，但非因实语即汝为实。譬如：世间法中，汝等上学学造飞船技术，学者如云，诸多国家倾举国之力，亦未能成器。原因乃学者，虽知其理但未有其实。\n'
        '佛法修行亦复如是，更何况佛法较世间法，更为难证。与佛法比，科学易通、易解、易懂、易知、易见；而佛法则难知、难解、难闻、难见、难证。\n'
        '于佛所说法，即使看懂、搞通、知一、见二，都不一定当生能、当世能，何况有人以世间法解说佛所说法？诸多罪人，因狂妄故，以世间法道，用攀缘竟比，狂妄讲经，最终因不能有所得故，为了名声，不肯认罪忏悔，便以科学、哲学而为定义无上佛法。是故，师父常说汝等，当精进勇猛，或方有所少得。\n'
        '是故，善知识，吾今为汝等说佛法修行关键有三：\n'
        '1、入般若门于佛、法、定心舍命，择贤圣僧宝皈依定缘。\n'
        '是皈依大善，为佛法累劫缘分所能为表。若有人以疑惑、信仰说之，恰如蝼蚁说人行车事耳。\n'
        '2、入禅悦道修行遵从师父所嘱，严守佛制戒律，是称修行量度。能是做者，乃成精进。\n'
        '3、入涅磐法，多于自己所修之处之生死问题向皈依师父请法。\n'
        '于此三关键处，最为首要，一者皈依，二者，师父导师，三者涅槃果位。\n'
        '善知识，如何皈依？切勿饥不择食，应多行参学，寻求自己因缘良师行定皈依。若选师不当，乃自己因缘罪业深重故，难能有出。是故，为稳妥故，佛说以戒选师，以戒为师。\n'
        '善知识，若汝等欲舍命求道，可于自己缘分中行此关键，必不堕落。谛深，2015，5，6日因有声闻愚痴故再做开示。',
  ),
  (
    title: '谛深大师开示:佛门诸宗与诸罪孽派系分别报体',
    date: '2015.5.5',
    body:
        '善知识：佛法以佛说为体，弘于佛土；以戒为本，住于道界；以慈悲为相令众皈依；以解佛所说意后，种种因缘证得为用，令众解脱。\n'
        '是故，佛门群体以戒为本，分为多种传承体相。\n'
        '1、于戒清净中，第一类别，乃菠萝蜜教相，净土即是。\n'
        '（a正）佛说诸经，于戒中讲说，令大众获解如来所说意，而不自成体，是称净土。净土宗皈依大众，因缘转世入极乐世界，于弥陀坐下修行，于层层极乐步步证道。\n'
        '（b反）而于戒律荒废体相中讲说，以经典为用，自立门户者，为坏佛菠萝蜜体，波旬住，恰如：蜜中施毒，皈依者，于因缘转世成苦海求囚，于一层铁围山外就住。是等修行中因无戒律故，嗔心、慢心、诽谤贤圣心极重。堕落苦海，即成诽谤佛陀，断灭佛种。\n'
        '2、于戒清净中，第二类别，为累世善根缘分之禅悦相。禅宗即是。\n'
        '（a正）修行之道，戒清净中，杜绝诸业侵扰，修证了意诸佛境界，禅悦为食，步步证得佛所说事，是称禅宗。因缘转世，成智慧体，多于一禅天、二禅天、三禅天、四禅天、兜率天住，于如来种种化现地，做道众。能于诸天，来往其中。\n'
        '（b反）于戒荒废中，视四禅八定为所求境，虚妄成证，或自立门户，或假种种传承，令禅法成业道种。是等，多为妄成之道，野狐禅定。是等类别，多于金刚地狱，成就罪恶道理，于六道之中，以地狱恶鬼神仙之道成就罪智，难于救度。\n'
        '3、于戒清净中，第三类别，天龙护法，护持诸佛传承体相。律宗即是。\n'
        '（a正）护法之道，戒清净中，戒传为之。于戒中修证戒根，了意佛说，护持诸佛因缘道场，为诸如来做慈悲舟乘。戒宗德行者，能于诸佛刹土坐宝莲座，能于诸大众中，护持修道，成功德庄严相。\n'
        '（b反）戒荒废中，相传戒律，能成就多种罪苦执持，于诸苦海中成不坏体相。譬如：铁围山中，以苦海为界，众中科学为其纲绳。常以戒法诽谤贤圣，有理有据，破坏慈悲，于是处，断灭佛种。落于不能救相。\n'
        '4、戒清净中，第四类别，皈依为道，不于非皈依者，行法布施，多于言传身教，体相修证。是称密宗。\n'
        '（a正）言传身教，戒清净中，佛菩萨功德相体，身体力行，不令有失，皈依之者，唯命是从，成一体像。 是等大众，成就宝刹福报住相，于圆满报身之中，成大慈悲种子，地狱大众，皆能于当处获救。密宗修道者，能于天道成道体功德。譬如：寺院佛相，工匠为之，是等多以密传者功德所成。\n'
        '（b反）戒荒废中，种种妄像传承，种种佛菩萨意中成相，实则魔境，于中修行，诽谤为道，断灭佛种，成就诸等罪业，因缘转世，成地狱恶鬼畜牲之中执着罪苦体，难于以善法救拔。\n'
        '善知识，佛法诸宗又成多派，以戒为判。汝等当知，诸等宗派，是否正邪，以戒为判，切勿盲修瞎练堕落歧途，成不能救者。用了功，反遭堕落。谛深2015，5，5日示。',
  ),
  (
    title: '谛深大师开示:不要诽谤邪道',
    date: '2015.5.4',
    body:
        '坐下弟子：我说邪道，乃为坐下弟子修诸佛出离罪苦法，而因其等道障吾弟子修行故，实相说之，令欲出离者有悟，并非以其自道为依说其有过、说其邪魔。而有邪师于诸佛法中假佛所说，因大众未悟，立其法相，令大众破灭出六道法，吾说其以邪，谓其诽谤佛法，乃为灭其所立障碍，令弟子获道出离。\n'
        '善知识，所谓邪魔外道，皆于本体罪孽中，有理有据有证。是故，于其法体不称邪道，只于出离六道法不能相容，而于误导吾之弟子修出离法成吾法障碍故，我教弟子远离是等。\n'
        '譬如：屎克郞，本自粪土，以粪为家，以粪为食，其理其据皆有实证，其者本身，实粪为香，闻者皆趣。而为人身者以其为臭，吾为说之勿落其法，其法实乃臭道，汝等莫近其者。\n'
        '是故，我说诸等邪道亦复如是，汝等因修出离六道法故，莫以其罪道称佛道而首欺骗以其为道。亦勿以为其无道，因其自有其道，当以是为警。是等所谓邪道者，于其法中皆入理入法，自不为邪。\n'
        '善知识，是法我已讲说多轮，今再为说，以令入我门者有悟。是故，我所说法，勿无缘外传，因所遇缘分罪重不能解我所说意故，而生嗔恨堕落大坑，是称秘密。\n'
        '汝等于我所说法，当于有缘处传。\n'
        '善知识，汝等应发勇猛精进持戒修行心于我法中证得诸佛所说。谛深2015，5，4日示。',
  ),
  (
    title: '谛深大师开示:莫以邪师承戒乱传戒法',
    date: '2015.4.27',
    body:
        '坐下弟子及声闻善知识众：\n'
        '佛法是福报之法，十方诸佛皆以福报布施大众，佛制戒律皆以令入门大众不受罪孽缠缚为本。\n'
        '有魔子魔孙，未获戒传，不知戒用，假佛所说乱施戒法于迷途中人，实乃断灭佛法之为。\n'
        '譬如：有人有某病，须得苦药方能却病，于是医生开苦药以治。若复有人以医生所开之药令无病大众使用，即令大众中毒死亡。\n'
        '善知识，佛传戒律亦复如是。云何有罪重之者，不知戒用或无有传承却说戒法？是等，愚痴、罪重不能救度耳。\n'
        '善知识，修行人于深山老林修头陀行，乃当应戒法，非所有人所应效仿。所有入佛门者，切勿上当受骗于言说邪师。损伤福报，生身堕落罪苦途中。\n'
        '今日闻吾弟子传，XX邪师教唆迷信大众，舍弃良院住入草棚，实乃亵渎佛法、奴役信众之为。信之者，当立脱其缠缚，直奔善知识坐下。\n'
        '善知识，极乐世界，黄金为地，昼夜六时雨天曼陀罗花，为大福报之地。是故，大众当皈依求道。切勿皈依，打着净土法门旗号，以世间道理令众折服，之波旬道法。\n'
        '善知识，一切戒法皆有依止障碍，称为道病良药，大德高僧皆依自己皈依三宝之子，据病布戒。若复有人，拿佛说毗尼法，无端施众是称盗戒，诸护法菩萨所不护之。\n'
        '善知识，若遇邪道假传佛法，当以是为依破邪魔道。谛深2015，4，27日示。',
  ),
  (
    title: '谛深大师开示:如何看佛陀缘分',
    date: '2015.3.31',
    body:
        '广大善缘众，诸佛住于世，为度众生故。如何度众生，为显佛智慧，以智统帅众，令众得解脱。如何众解脱，令众获佛智。而于于神通，其乃用之具，若令众生着，则为邪道使。如是种种法，如是种种说，如是种种应，如是种种道，皆为用之具，不乃为实相。\n'
        '善众善听说，汝等乃佛使，当于所住处，以修示于众，戒行为依止，莫以说为要。当说即说之，当机布施法，是称菠萝蜜。是称佛陀缘，文殊行之道。\n'
        '若人于行走，一称南无佛，是人成佛道，为佛所差遣，汝等当赞叹，于于当机处，点拨令得证。是称善知识。是称弥陀愿，观音慈悲应。\n'
        '若人于罪苦，念佛求哀佑，是人虽罪重，难于一时救，汝等为佛使，当自以智慧，广行慈悲法，步步令脱罪。切勿因其罪，其行愚痴行，则为斥责之，应于佛所说，当机布施其，令其有所悟，最终得解脱，是称弥陀缘，地藏愿力道。\n'
        '善众应当知，何者乃波旬，若人于佛经，自解以为得，并以成执见，狂妄评判法，不求修证意，诽谤佛戒律，如是之作为，乃波旬道成。波旬为罪使，诸报皆两相，善恶为一契，若获大福报，皆依罪恶立，报尽转地狱。\n'
        '善众汝等为，当以戒律依，诸事多善软，勿以恶求福，若以饭食业，求于养生道，饭店勿沾荤，众生肉不施，即使生意淡，来世即获救。诸业皆如是，杀盗淫不沾，是称佛弟子。\n'
        '若人于罪途，称念阿弥陀，是做乃谤佛。波旬令为之。\n'
        '若人有病苦，出家为僧尼，以求佛哀佑，是人又以病，不持佛禁戒，其为为罪使，波旬欢颜之，当受大恶报。\n'
        '若人知佛悲，苦中求佛佑，并以最爱物，供养于三宝，是人乃能救，汝等多用心。善众当知晓，大众皆有罪，度众乃己任。\n'
        '广大善缘众，诸佛智缘分，实乃最殊胜。种种智慧应，为因所住处，是故阿弥陀，挲婆道众主，于法界藏身，能于诸罪孽，化智成甘露，行大慈悲力，令罪众解脱。\n'
        '各位善知识，诸佛世尊众，住世度罪苦， 师父略说一，以表无量法，是称佛陀缘，汝等当发心，持戒为根本，若不持佛戒，诸法不能立。\n'
        '坐下弟子及声闻善知识众，汝等若能严净毗尼，必获成就。谛深2015，3，31应弟子问事说。',
  ),
  (
    title: '谛深大师开示:在家居士如何修道',
    date: '2015.3.31',
    body:
        '今天有弟子因尘世罪业，烦恼生起，发短信问师父，说自己很渺茫，佛法看不见、摸不着。师父因其不具问法相，开示如下：\n'
        '吾之在家弟子，汝等因罪孽深重故，不能舍弃尘世因缘，是故师父为汝等讲说在家修道法，以令汝等有缘有悟。\n'
        '六道罪苦，为诸多罪众所依之用，所谓：体用、心用、相用等等。\n'
        '所谓苦之体依用，指体苦之用。体苦之相为生苦、老苦、病苦、死苦。\n'
        '所谓苦之心依用，指心苦之依用。心苦之相为痛苦、烦恼苦、惊吓苦、攀缘苦、无明苦、意障苦如是等等。\n'
        '所谓苦之相依用，指杀相、盗相、情相、舍相、离相如是等等，而是等诸相，多以淫为因。\n'
        '是故，汝等当知，在家修行为与佛结缘以为有救。若要与佛结缘须得皈依，皈依之后需要持在家居士戒，持戒之后需要供养。如是修福修慧。\n'
        '坐下弟子，若不能出离罪苦，当如说在家修行，因缘具足，定能出家成道。谛深2015，3，31日因在家弟子智闻因苦问事说。',
  ),
  (
    title: '谛深大师开示:如何修信心',
    date: '2015.3.17',
    body:
        '坐下弟子及声闻善知识：昨日吾之皈依弟子，因其母身患癌症手术后，求师父用神通令其伤口立即复合以表佛法，而令在场诸等生信皈依。故师父今为汝等说于佛法末世，如何修信心。\n'
        '善知识，众生罪业广，累世集成习，因于不适应大众显前缘分境地所知所见故，于佛法成不思意障碍而不信，亦故，佛法末世非以神通就能令罪众当下生信舍弃广大罪业，而生信心。是故，观音地藏于世间久住兴拔，我之弟子亦当知而发心。\n'
        '譬如：吾今世率弟子于崂山中显神通救人，现场有十几人，其中有智缘、智遇、佛门弟子女众徐某均在现场。时茶场场长金某被马蜂蛰于其项，瞬时蹲地痛苦嚎叫，正值时之前几日有其员工为马蜂蛰伤，差点丧命，虽住院治疗数日后归，但其面目依然青紫肿胀，似一猪头，其时亦在现场。\n'
        '师父见状，立令智缘持神咒施救，几秒钟内其痛苦难耐厂长立马恢复，无任何被蛰迹象，并口称大师顶礼膜拜，然，当师父令其皈依念佛时，其等却至今未能皈依。而吾之弟子智缘，至今仍不能完全相信。在场眼见为实者徐某，却因罪孽深重故，于世间诽谤师父并持强辱骂师父乃邪僧也。徐某本人也曾因下台阶摔成腰椎骨折，医院难以短期救治，求师父后顷刻即好。是罪人师父不会加之令罪，只未来世因诽谤佛法自作自受后，寻机再行逐渐救拔。是人亦为今者师父不于因缘罪众，遇有灾难时，立令无罪而步步施救者，于其所表能于师父不立令脱苦之法而生信心。\n'
        '是故，善知识，广大众生罪众难救，累劫重罪，不能单以神通为救之者，当于其受罪途中，如解绳索之做，步步为救，令其获救。\n'
        '又如释迦佛坐下大目建连尊者，施救眷属亲族，虽神通第一，却被族人用乱石砸成了肉酱，时其族人无一获救；\n'
        '又如吾于大广幢佛时，飞行救人，为欲救之众，毒枪中体，肉身遭害；\n'
        '又如轮值住挲婆之中国之当今虚云和尚，因率弟子修戒参禅故，遭罪政之众谋害，二十几位僧众，被当场乱棍打死，虚云虽自以神通活命，但亦于血泊自拔几日，其坐下徒孙至今仍有诽谤者；\n'
        '又如：释迦佛住世时之波旬，为害释迦不惜发广大毒誓，如是等等。\n'
        '是故，善知识，若汝等不能有罪生信，当于自罪孽中勇猛于渐渐破罪，步步生信，切勿，以师父如果怎怎怎么样，吾便生信、吾若求佛，佛满足吾条件吾便生信，而重罪成痴。实则，是等犯以罪孽执见落愚痴大坑使佛、污佛。\n'
        '善知识，譬如：汝参加考试，汝向老师说：老师若给我一百分，我就答题考一百分，否则，吾不答卷，是做能行否？\n'
        '善知识，求吾谛深与求诸佛、求诸菩萨亦复如是，吾之智慧汝不能思意，却以汝若能做到某事而生信于我之罪孽愚痴之作来求于吾，恰如汝先让老师给一百分，汝才答题耳。\n'
        '善知识，汝等于佛法末世，入吾门下，当如吾所教持戒修道，于却罪之中逐一生信，能于来世生大信心成就果位，否则成堕落相。若有大善，累劫修持，于戒无缺，则乃无量劫中却罪生信之者，似小龙女当下成佛，即为其率。\n'
        '善知识，于佛法末世，于吾坐下当如是修信心，方能出离罪苦。谛深2015，3，17因弟子有罪做故说。',
  ),
  (
    title: '谛深大师开示:不能单提放下',
    date: '2015.2.23',
    body:
        '坐下弟子及声闻善知识：所谓看破放下乃一主题，若不看破却称放下，或单提放下以是为法，乃邪道之为。\n'
        '善知识，如何说放下自在，须以看破为导，说放下法。譬如：未成就者，与成就者共住，忽遭火灭，成就者谓，吾已放下，未成就者亦谓，吾已放下，是中未成就者成道否？若未成就者能以是成道，十方含灵芸芸众生，皆有死时，死时是等不放也得放，如是则，死为必放，以是意故，凡人皆有死时，皆以死称成佛者，以是意故，杀盗淫妄重罪之者，皆无需戒自，死后皆佛，以是意故诸佛所说皆诳骗大众之作也。善知识，佛法真实不虚，佛陀住世，不以有漏说布施于人，是故，汝等当以佛说为导，莫以有德者以某修获得为导称佛法者，若以是为导为说，乃罪孽做。\n'
        '汝观求食者，不求称放下，若不求者死，不称为修道，只称为愚痴。汝观过江者，游泳为过者，若于江中游，不动称放下，死即当临头，不称修道人，只称愚痴做。以是种种罪，令当有知晓，放下之为道，看破为其依，未破世间道，却称放下者，恰如自尽者，实则为重罪。\n'
        '善知识，如何看破，须得依佛说修行，若不修行，不能看破。汝等当精进勇猛持佛戒律，以获证佛道诸乘妙果。谛深2015，2，23日为弟子示。',
  ),
  (
    title: '谛深大师开示:什么是现身说法 (第二品）',
    date: '2015.2.22',
    body:
        '坐下弟子及声闻善知识众：\n'
        '所谓现身说法是佛菩萨住世现所用相，以适应所住因缘相用。\n'
        '譬如：有大慈悲者入狼群设法救重伤之狼，其若以非狼身入群，狼群不能受其，而以异己攻击之，是故，假狼身入群，令狼不排之或归之实则非狼也。\n'
        '是故，观音菩萨现种种身而为说法，其非所说种种身，其所显种种身者，乃假相 实相乃观音菩萨也！是故，善知识，所谓种种身莫以假相为依判说佛法，更勿以其为道，所谓，种种身者，一道具用耳。\n'
        '坐下弟子及善知识，若遇有人以佛说经中相关章句，诽谤与汝等传吾所说，以是为境令其有悟。谛深2015，2，22日应弟子管理员问。',
  ),
  (
    title: '谛深大师开示:如何面对因地与果地',
    date: '2015.2.13',
    body:
        '坐下弟子，所谓因地是指证果位之前之修道途，所谓果地是证得果位后之道途；二者不是一个东西，不能作比较，因地修道之道与果地修道之道有不能相互参照之别。师父已为汝等讲说因地修行，汝等当以其为依做修行之导。\n'
        '善知识，譬如：蠕虫檀变成飞蝶，有虫欲寻求其异同以导自己如何成蝶，是为愚痴之做。因虫与蝶随于一身之道，却并非一物。其所食、所做、所用皆不能相互为据、相互借鉴。是故，若虫寻求其所变之蝶为考实为愚痴。\n'
        '是故，善知识，因地修道，莫思维乱飞、虚妄乱想、东求西问，若如是乱为浪费生命，难得证道，必多受罪。譬如：其虫见众皆檀变成蝶，不加紧身为却自寻飞路，整日思变，因自身所集檀变资粮不能为变故，遭寒冬降临或天灾人祸灭杀，永无蝶变。\n'
        '善知识，佛门修行亦复如是，若自己不成，未于佛说得果位实证，切勿以有证者之相为说为道，当知自己修为不够，应皈依三宝奋力精进，不丧失机会。否则，六道罪恶，诸魔狂舞，稍纵即堕。\n'
        '善知识，汝等当知，诸佛世尊慈悲，只与不证者讲如何修证了意，不与不证者讲证者之作。汝等当依诸佛所说，精进修行早出六道。谛深2015，2，13，应弟子因群中声闻问。',
  ),
  (
    title: '谛深大师开示:什么是修道中的忍',
    date: '2015.2.10',
    body:
        '坐下弟子及声闻善知识众：所谓修道忍辱，是于诸业障中出离之做。佛说忍者，乃过而有道、有所求、有所得称之为忍。若过而无道、无所求、无所得，称为愚痴，不称为忍。\n'
        '譬如：有青蛙生于诸恶井底，蛇于虹倪随时斗杀欲啖，是蛙因故寻求逃离，逃离之做为蛙之修道，为逃离故，遇所有害不与之争斗，只奔出路，最后得出，以故不予理睬、不予争斗者，如是之作，称为过而有出，称之为忍，若是蛙与之争斗则不能出离，不称为忍，若是蛙不求出离，却又不与之斗，随遭命丧称为愚痴；又如有人欲求金银，其路凶险，忽落悬崖命悬一线，是人虽身为荆棘划伤流血，亦不能分离荆棘，若分离荆棘必落谷底死于非命，是人为求活命故不理睬荆棘所害，之一心求出，最終活命，于是之做称为过而有出，称之为忍。\n'
        '善知识，佛说得成于忍者，乃为皈依三宝修道出离者说，乃具大众为求大义之，舍却诸所受小害，不与为破，得所求之事之意。\n'
        '坐下弟子，汝等当知，入吾门下，为求佛道，诸事若与汝等成害或障碍，当以过之为法，必获成道。切勿与之纠缠，不能成过而之相，当忍辱得道。谛深2015，2，10日应弟子代群中声闻问。',
  ),
  (
    title: '谛深大师开示:什么是染污',
    date: '2015.2.7',
    body:
        '智安于群里发XX关于2012世界末日前往生的邪说，意在告诫大众勿上XX之当。师父呵斥智安开示如下：\n'
        '智安，汝有罪，当背染污净地因果。何故是说，智安，若有人不知有杀，未见有杀，汝却于其前杀猪，以告之可怕，是人心中有杀者无杀者？是人本来无恐惧之心，因汝之善心示杀，今者有恐惧无恐惧？智安，其人必因为汝之愚痴之作，而心内有杀、心生恐惧。是故，汝之有罪。智安，又如：净水之中，汝放沙子演示，以示是水清净，其做，因汝放沙子故，水之清净丢失。虽汝之为示有罪众不知何者为不清净，实乃汝坏水清净。是故，于清净水中，诸事不做称之净水，若做，即称染污法。是故汝等不能做。是故，汝等为入清净世界故，不能于师父坐下评说种种法、种种道、种种欺种种诈。\n'
        '智安，若汝等欲为罪重示法，当如是做称为入法：所谓于罪重众中令其修道获得无罪，称之慈悲入法。譬如：汝见有杀猪者，花钱买下欲被杀之猪，养其归灭，是称慈悲法。若于无罪清净大众之中，说有罪者如何有罪，令不知罪苦者知道罪苦，称背因果之愚痴慈悲之作，必成大众之心染污相，而成道果堕落，汝等因此须做罪孽报还。\n'
        '智安，是故于清净众中，凡有言说皆无实意。\n'
        '智安，汝等当因于群中所做跪香忏悔，以获道缘，于因果报来之时能获解脱。谛深大师于2015，2，7日为弟子智安开示，弟子智安有罪忏悔发于网上与大众共勉。',
  ),
  (
    title: '谛深大师开示:什么是心法',
    date: '2015.2.5',
    body:
        '坐下弟子及声闻善知，所谓心法者师父已说，不再做述。法与心之关系，因声闻未证妄思，是之妄思造知见障碍故，而成修证虚妄，以修证虚妄故，成是种问。\n'
        '善知识，譬如果木逢春开花，随一木之花有前后开，实则其春与木无前后分，佛说妄心者亦复如是，是故，虚妄无有前后，若不证得，无以为修。师父开坛，布毗尼法，为令闻者入门修证诸佛所说故。善知识所谓法者乃：虚妄起后种种心生，因种种心生故，种种法生；因种种法再生种种心，如是展延。心无法性，心生之后，诸法兴起，诸法再生心者，法为其依，心具法性，由诸等法，依法生成诸心，是称心法。所谓证得心法者，皆十地以下诸等果位，因所证心法之要，分成种种果位分别。如是种种，勿以知为得，当以佛为导，若现前无佛，当入佛说戒法方能精进修行证得。\n'
        '善知识，若欲证得佛说诸事，听吾良言，严净毗尼，若汝等有信于谛深，以种种身依吾所教，亦能证得。祝诸善知识戒中精进，早证佛道。谛深2015，2，5日18点20分于行脚途中应弟子代声闻问。',
  ),
  (
    title: '谛深大师开示:我就是个要饭的',
    date: '2015.2.3',
    body:
        '今天有师父尘缘豪富、高官之同窗让家人捎口信，说想师父了！并说，师父好不了天理不容。师父给回了个口信，说：\n'
        '我就是个要饭的，日子没有好坏！没什么好怀念的。当年在学校给大家做了那么多的事情，理所应当，因为任何事情都有前因后果。大家得到实惠，也是理所应当。今天你们事业有成，兴此善念，我无以回报，就送你们一句佛号吧，因为与其他一、二、三等的大德比，我只能算是等外的和尚，除了佛，什么都没有。\n'
        '我之讨饭为结缘，一钵米菜化法牵；来世汝等若有难，我必赴汤为设船。昔日同窗皆如是，一粒米成富今天；吾之所有皆众舍，众之所有吾皆含。汝等有待病老时，执此善念能升天。祝愿天下有情人，多做供养为福传。吾乃累世佛缘僧，佛化慈悲种于天，今者能于众中住，烈火金刚乃等闲。是故诸多诽谤起，是故诸多咒骂添，汝等当感佛陀恩，莫于佛法生罪嫌！\n'
        '坐下弟子，师父将此回复发给你们，汝等当知，因缘果报丝毫不差，吾谛深所有，皆为众生供养，供养之者当持佛戒律，有障碍有问题便问，莫只做功德成来世福报而不有出，来世又落轮转苦途。谛深2015，2，3日。',
  ),
  (
    title: '谛深大师开示:什么是火',
    date: '2015.2.1',
    body:
        '坐下弟子及声闻善知识，今日智偌问曰：师父，我想知道火究竟是什么，感觉只要与自己想法不一样就会有火。\n'
        '智偌，所谓火者，乃因缘之变化之相。即当因缘变至可见火光时，以不能入其因缘变化之视之之人便称之为火。亦即：实则火为妄尘所成之、妄因妄缘变转之相，世界本自虚妄，是故，性火真空性空真火，随众生心应所知量。\n'
        '譬如温度，实则相差，即不同因缘之差。干柴烈火为百度之外即能与氧气成缠，转化为另物，转化时相为烈火燃烧。钢铁之物须千度之外，与氧及其它等物相缠转化成另物，其相为燃烧火焰，如是等等。\n'
        '是故，世间万象皆因缘和合，成种种果报，种种果报以大众造业成转世之因，流转相缠成种，造就变化。\n'
        '善知识，是等诸法、诸相皆因缘果报转换之体，为世间轮转法道，看似变化，实则每每都有定式，是故，诸佛世尊能为世间眼，知大众若于执见诳骗大众，恰如干柴遇氧被火星点燃，不能恢复成体，之去处必然。是故，有人诽谤三宝，必堕地狱。善知识，切勿以世间法谓得，若执之谓得则成外道典集，不能见如来。汝等当知，诸法空相，不生不灭，不垢不净，若以此为悟，知世间无常，为佛法表，能种佛种，于未来当机处，入诸相非相，获得开悟成就佛法妙果。\n'
        '坐下弟子，汝等当精进持戒，以获成道。谛深2015，2，1应弟子智偌问。',
  ),
  (
    title: '谛深大师开示:什么是言语道断心行处灭',
    date: '2015.1.31',
    body:
        '坐下弟子及声闻善知识，所谓言语道断心行处灭为罪孽众生因诽谤佛法故，断章取义之未悟之说，若有人未得开悟以是说者宣示于大众，即为重罪。\n'
        '善知识，若言语道断，佛如何传法？若于心行处灭，众生杀盗淫妄亦于心行处灭，若如是说，佛陀说法即为欺众，佛说之因缘果报即为妄说，佛所传承戒律即为诳骗大众，佛说经书与咒子即为邪魔外道典集。是故，是种说者，若比丘，必断佛种成地狱火，若世间人，必遭地狱恶鬼畜牲之大不幸。是说之者，为谤佛、谤法、谤戒体相，为不能救人。\n'
        '善知识，若未得开悟，即以种种断章取义之文，诽谤大善，乃至诽谤诸有，为大罪孽因缘。譬如：一大善为慈悲众生制刀令众获福，却有人偷刀断人生命。于群中说言语道断，心于行处灭者乃如是辈。\n'
        '善知识，佛说诸法为度大众，称菠萝蜜，若以佛说诽谤余乘，乃鸠毒泼幼子，为无始恶。坐下弟子，若遇罪孽深重之人诽谤汝等，做如是说以破其恶。谛深2015，1，31日23点32分应弟子智弘因有重罪者问。',
  ),
  (
    title: '谛深大师开示:为佛祝吉祥',
    date: '2015.1.27',
    body:
        '坐下弟子及声闻善知识众：\n'
        '今日是释迦牟尼佛的成道日，善知识们正率弟子或自起香于其宝刹、其道场、行道处做佛法事，于释迦末法时段为佛祝吉祥，令众获佛光照，获罪中救拔。\n'
        '善知识，所谓为佛祝吉祥，已传承无始劫数，虽大众知其名，却有诸多不为所知其内涵意。今吾谛深为汝等弟子讲说少许，令之有知。\n'
        '善知识，何故吾于祝吉祥前加释迦末法而修之，因佛法真实不虚故，所谓佛法真实不虚，乃说不虚、用不虚、证不虚也，是故佛之末法即亦是佛法，只佛之末法耳。释迦佛出世至今，已如其所说，其法步入末世。其法末世表象如说已显，分毫不差，证佛说不虚也、证佛乃实语也、证佛不异语也、证佛不欺众也！唯邪魔外道不以实说耳，是故，若有人于是说有异说者，是妄中说实之邪魔道也。\n'
        '既佛法末世，吾今为说祝吉祥者，乃告诫坐下弟子，汝等有福、汝等有累劫功德、汝等与佛有累劫因缘，故能于释迦佛法将灭时，力拨末世邪魔术士，以其罪想加以所谓历史考证，解说佛说经典成盛行之势之佛法荆棘；能破波旬假佛法衣坐佛法宝座做大障道道法；能过种种邪魔外道于汝等缘分中以共鸣执见所成之修行坎坷道途；能于广厦琉璃倒塌之际，入佛之大船，持佛说戒律修证了意佛说诸法，出离罪苦。是故吾为汝等说祝佛吉祥也。\n'
        '善知识，所谓祝吉祥之内涵，汝等应首要知晓。\n'
        '若佛陀慈悲之法，为波旬教所用，是称佛法不吉祥也，汝等能破波旬教法，令佛法干净，是为为佛祝吉祥也，如何能破波旬诸法，持戒是也；是故，汝等能持佛说戒律，为佛法大吉祥者。而以是为导做祝愿者，称祝佛吉祥。\n'
        '若有人不持禁戒，却为人讲说三藏十二部，是人即是波旬之长子应身；若人不持禁戒行使神通，以佛法自居，行使种种法，广收门徒，以获名声私利者，为波旬二子应身；若有人或于外道诽谤三宝，或于道场身穿袈裟互为讥讽，或于佛法派别讥讽余乘者，是等人者为波旬三子之应身者。如是等等，波旬另有三百女儿于佛法末世兴种种教，破坏佛法令佛法灭。\n'
        '善知识，若佛法无传承，是称佛法不吉祥也。是故，若有人能于佛法末世，出家为僧，虽为世间法所害，难以生存，但依然能受佛戒律、持佛戒律，传佛戒律，是人乃如来以头陀身应世，为佛法大吉祥。而以是为导做祝愿者，称祝佛吉祥。\n'
        '善知识，若佛法不能为人护持，处处遭坏，称不吉祥也。\n'
        '是故，若有人，能以居士身于商人位、学者位、官宦位、宰相位乃至王位，持菩萨之一戒两戒至二十八戒，不以执见与众说法，却常行大供养，大护持，虽为人或魔道讥讽所害，依然能令佛法于末世灭尽前住，其等乃十地以上菩萨摩诃萨为慈悲大众故，于佛法末世显宰官商人居士身，护持佛法，是称佛法大吉祥。而以是为导做祝愿者，称祝佛吉祥。\n'
        '善知识，若佛子比丘、比丘尼、优婆塞和优婆夷为人轻贱，称佛之不吉祥也。\n'
        '是故，若比丘、比丘尼、优婆塞、优婆夷能严净毗尼，为人敬重，是称佛法未灭之佛光普照，为世界之佛法大吉祥。而以是为导做祝愿者，称祝佛吉祥。\n'
        '善知识，若有人因佛法故，行事知悔，常做跪忏，称为佛法吉祥，以是为祝者，称祝佛吉祥；若有人能常诵佛说经典，称为佛法吉祥，以是为祝者，称祝佛法吉祥；若有人能于人前赞佛而说，称为佛法吉祥，以是为祝者，称祝佛法吉祥；若有人能于非议于佛法，充耳不闻称为佛法吉祥，以是为祝者，称祝佛法吉祥；若有人能称念佛号称为佛法吉祥，以是为祝者，称祝佛法吉祥；若有人能赞叹恭敬三宝称为佛法吉祥，以是为祝者，称祝佛法吉祥；若有人能挂诸佛法相，称为佛法吉祥，以是为祝者，称祝佛法吉祥；若有人能参禅静坐称为佛法吉祥，以是为祝者，称祝佛法吉祥，如是等等，乃祝佛法吉祥之内涵。\n'
        '于佛道场海会祝仪，佛法久住，为祝佛吉祥之典，吾等于是庆典祝愿诸佛住十方世界，肉身道身吉祥，佛法吉祥。\n'
        '善知识，祝愿汝等为释迦佛祝吉祥。谛深2015，1，27日为坐下弟子示。',
  ),
  (
    title: '谛深大师开示:什么是析境智慧',
    date: '2015.1.26',
    body:
        '坐下弟子：所谓析境智慧是指识心无障碍用。若不开悟，不会获得析境智慧！汝等当精进勇猛持戒修行，于我坐下直获开悟，证得佛法。\n'
        '谛深2015，1，26应弟子不解相关名词问。',
  ),
  (
    title: '谛深大师开示:不要把迷信当佛法',
    date: '2015.1.26',
    body:
        '坐下弟子及声闻善知识众：\n'
        '迷信中的迷是糊涂的意思，信是认可和接受的意思，迷信，就是糊涂的认可与接受的一些事情，在佛门称之为愚痴。这个师父已在了解佛法之中讲过了！今天给你们再做简说佛法之意。\n'
        '善知识：佛是明白、彻底明白十方世界种种法后，脱离十方世界罪孽与苦难缠缚的实证之人，若佛不清楚十方世界种种法，是出不了世间的。如何去搞明白十方世界的一切法，佛陀们是过来人，他们因为慈悲大众故，将自己所证一切以有限经典的形式将分适应某界大众的少许部分记载入所应世界之册，其国土大众称其为佛经，以此让大众能早些出离罪苦缠缚。所以入佛门学佛修行就是学着如何去明白与彻底明白并实证十方世界所有法，然后脱离世界罪孽与苦难缠缚，这也称为出世间法。总之，佛法不是让你稀里糊涂的去迷信，恰恰相反，佛法是让你明明白白的去实证。所以，如果有人以鬼阿、神阿、神通阿，等等你目前没有办法弄明白的事情去让你信服，这就是把你向魔道、邪道里推。虽然鬼神是真实存在的，天人阿修罗地狱恶鬼畜牲也都是有的，但它们均为六道中的众生，若皈依他们，就会与其同流合污而成其体相，这在佛门称为堕落。\n'
        '所谓宗教，实际上是讲究实证科学的人们对无法证明或已经证明了的，历史传承中的胡编乱造的说教教体，而这些教体又有庞大的群体愿意去信、去皈依之人文基础的愚昧与迷信教派的统一名称。\n'
        '所以，善知识，你们切勿以某种修道、某种宗教教派称为佛法令众皈依，若以是做，其罪为破灭自己出离六道之堕落做。所以，坐下弟子与诸位大德，佛法不是迷信，更不是邪魔外道能用的法，希望你们拨开云雾见青天，能于自己的缘分中，一门深入的去获证，如果不能获证诸佛所说，却以自己的想象与理解称为佛法，就是自欺欺人的堕落重罪。若有人说，佛法是一种宗教，并称不能实证，吾谛深今告之汝：汝等为不能救辈，诸佛所说皆诚实实证之说，没有暇眦，我已全部实证，所以，祝你们精进勇猛修学，早获佛法实证，切勿自欺欺人自寻堕落。谛深2015，1，26日应弟子因群内比丘狂妄言说问。',
  ),
  (
    title: '谛深大师开示:什么是随喜功德',
    date: '2015.1.26',
    body:
        '坐下弟子及声闻善知识众：有声闻问什么是随喜功德，所谓功德师父已说，所谓随喜今为汝等分别讲说。\n'
        '善知识，随者有与有道者之道行意，譬如：有人明白路之去处，汝欲去者却不知去处，便于其后行，是称为随；随者亦有与前者之后紧而不舍之意，譬如：前者行后者跟，称之为随。所谓喜者，乃高兴所表之相称之为喜。\n'
        '是故善知识，所谓随喜功德，是谓：为做功德者高兴于色，并向有功德者学习，或与之共做功德。\n'
        '善知识，修行之者，赞叹功德、随喜功德当知什么是功德。若不知什么是功德，于之赞叹随喜称为盲从。而汝等所说，不知其何者用心，是为不明功德为何者所成之问。汝等当知，种种心生种种法相，种种法生种种心相。汝等之疑惑问，为皈依邪师之法成用后，所生之心相。谛深于此与汝等简说诸心所生法相与诸法所生心相以解汝等之惑，以是汝等便知其是否为功德者。\n'
        '善知识，譬如：青岛湛山寺有居士因XX诸邪师所教，于寺内以鸟放生，一边放一边有人捉回再以50元一只与放生者询价而卖，是法相所表，令诸多围观之人，因是而生：佛法无用或乃迷信或不辩善恶，或恶者猖獗不能为报，或因果报应不对之不信不敬佛法之心；或于其相生：嗔恨做恶者之心。是故善知识，是种所为乃愚痴于佛法之相，是故，其非为功德。又譬如：1998年一江西集市有人正欲杀牛买肉，为老僧所遇，老僧以1600元将行将被杀之牛买下，牵回寺院放于山坡，昼日呵护回槽喂养六年有余，至老牛老死于所养处，其相所表，所知之人，皆赞叹其僧，令知之者，生恭敬佛法信，即使不信佛法，因罪孽深重故，以是相生鄙视老僧并称愚痴者，其亦会为老僧之毅力之举与慈悲用心而生赞叹之想，以是生一善念成未来种。善知识，老牛自被救放生之日，不再受宰杀报所困，只受善护而终，是称放生并成功德。善知识，有关什么是放生，师父已说，今不再述。\n'
        '是故 善知识，如上所表，于六道罪苦，当以智慧才能随喜功德，若无智慧，观其功德是否真实，亦能随喜功德。善知识，欲获智慧修行之者，先以戒为师，早获开悟为正法道，否则，处处有障，诸魔设伏，一不小心便中魔套。祝汝等解诸佛所说，早出苦海。谛深2015，1，26日应弟子代声闻问。',
  ),
  (
    title: '谛深大师开示:你能我不能',
    date: '2015.1.24',
    body:
        '坐下弟子及声闻善知识众：六道大众之道，道之有道，道道有法，法法有别，是等乃其道相。所谓天道、人道、阿修罗道、地狱恶鬼畜牲之道，皆道中有道，以道为得，以得道为修所成。\n'
        '善知识，妄有虚空，虚空为造，妄起圆满为无量心，十方含灵为诸道之心，以大含小，小以显大，成就诸种国界。种种心生，种种法生，种种法生，种种心生，造就种种世界，种种道法如是行于十方世界。是为今日说相。\n'
        '善知识，种种道成就种种相，天人相、人相、阿修罗相、鬼相、地狱相、畜牲相等。而于每种相中，有以各自修行道别，成就种种界内差别，以是造就种种个体之相。\n'
        '善知识，是故谛深为汝等讲说诸道所成，而令汝等有悟，并能破诸邪魔之道。\n'
        '道成鸟能飞，大小皆如是，高飞于吾顶，吾坐于草座，问吾能飞否，你能我不能；\n'
        '恶道为人者，其道落犬齿，奔跑寻道者，四蹄为罪者，加之嗔恨爪，化生转肉身，落种成猛兽，畜牲为其身，追害互啖之，你能我不能；\n'
        '聪明于道中，处处依道行，世间器物等，一点便能通，其道能成风，生灭转亦道，成就鬼魅身，蚩笑我无能，不能造器物，你能我不能；\n'
        '恶之有恶道，其律为可明，即使偷盗法，分毫不能差，于我所住处，寻道能成偷，以道蚩笑吾，不能以道为，你能我不能；\n'
        '草中万物鸣，名之皆有道，以是蚩之吾，不能为之道，你能我不能；\n'
        '十方世界中，乃至一微尘，生命皆依道，吾之皆知晓，其道成诸相，你能吾不能；\n'
        '善知识，谛深不能也，有为吾不能，无为吾不能，一切皆不能，是故吾讨饭，获得施舍身，父母因施舍，成胎吾为子，是故吾生于，钵磬叫响后，住世于释迦，法将灭度时，身着万人衣。攀缘为造者，谓吾乞讨僧，欺吾于权杖，个个显诸能，诸犬亦欺吾，吾却不欺众。\n'
        '善知识，汝等若遇有人、有权力人物、有假佛法名者诽谤于汝等，或于汝等有污做、毁做、道理等做，汝等当思谛深今日所说，谤做者一切皆能，而汝等为吾弟子，一切皆不能，令退却烦恼嗔恨获得出离罪苦。\n'
        '谛深2015，1，24日因妙忠法师问',
  ),
  (
    title: '谛深大师开示:何如报应',
    date: '2015.1.22',
    body:
        '坐下弟子及声闻善知识众：吾弟子因有声闻众被邪道以：若做因者，报其子孙为理问请师父开示， 善知识，做因必有报，是事师父已在因缘果报品中为汝等讲说，今特为汝等说报应之相。\n'
        '善知识，诸多邪魔外道假佛门名词恫吓大众，以谋控制被恫吓者，是故谛深特与汝等讲说报应。\n'
        '善知识，所谓报应顾名思义，若汝之有做，必有应之之报，是称报应。\n'
        '善知识，报应有多种相分，其中有共业报、自业报、大势报、道报，如是等等。其所有报相皆因缘运行所为，其中以因缘行进过程为相，又分来世报、现世报，如是等等。\n'
        '善知识，所谓共业报，乃汝之所做，乃诸多缘分众之共因所成，汝之为表，乃荷担应当份额之称。譬如：借刀为恶，为恶者占九十分罪报，借其刀者占五分罪报，造刀者占三分罪，运刀者占一分罪报，而其中成其事途者共占一分罪，如是等等。是故善知识，若汝之有过，其共业之报能如是分而报之，汝之家人会受所应共业份额报应，是称牵连之应。为善者其所获份额亦同。\n'
        '所谓自业报，乃自作善恶所获报之称谓。譬如：有人因故行恶，不假诸缘，所获罪报称之自业之报。若人有是报相，莫于其有染，染之之后，即成共业。为善者亦之。\n'
        '所谓大势报，乃大势所含诸众生所应劫难。是等为吾谛深与十方诸佛秘密之传，不与大众公示。\n'
        '所谓道报，乃以道为之，大众共应之报。譬如：科学，若汝发明，即承担四十分总报，余者以每自所用获报。譬如：汽车，发明者占四十分报，以汽车作恶者，其亦占四十分者。\n'
        '所谓现世报，指若有所做，其因因缘和合恰于现世报应。所谓来世报，指其之所做因缘和合成来世报相。\n'
        '善知识，汝等莫为罪孽之众所吓，称其魔民，当精进持戒修行获出魔境。\n'
        '谛深2015，1，22日应弟子智安代声闻问。',
  ),
  (
    title: '谛深大师开示:什么是人生难得、佛法难遇',
    date: '2015.1.21',
    body:
        '坐下弟子及声闻善知识众：\n'
        '生命可贵，人身难得，佛法难遇，是故，汝等当日日精进。\n'
        '所谓生命可贵，乃六道众生依止之本，得之不易，日日有变，由因缘定，不能自控，是故称之可贵。既然可贵，汝等当自重，亦当尊重一切；既然不能自控，由因缘定，汝等当时时警戒自己，多做善事，多以智慧救助大众，莫有恶为烦恼以获福报。\n'
        '所谓人身难得，乃大众于罪孽海中，因无始劫中种种因缘和合于今，获得人身，若不皈依三宝，于修道途中，稍有不慎即随种种因缘而去，于苦海之中落于无量劫中之轮转。汝等，当处处戒骄，莫有狂为，以保人身不失，若以自己罪孽执见解佛说经典，即成堕落。切勿为满足自己一时名利脸面而堕大坑。\n'
        '所谓佛法难遇，乃遇佛 出世甚难，譬如：汝等路遇蚂蚁，蚂蚁不知汝等乃吾之弟子，此称遇相，并非遇体。佛法难遇亦复如是，诸多罪重之人，虽见佛陀，虽见经典，甚至讲经说法，更有过者，以佛为表，以状自己名相。实则，其只见佛相、只知经典所说，不知佛体，不知经典所实所用所证，是称不遇佛法。譬如：经典所存之处，老鼠横行无忌，啃书为食者，虽将经书吞于腹内，亦不能称之遇经。所谓佛法难遇亦复如是，有人若不能获佛说真实意，即使将释迦佛之三藏十二部倒背如流，亦不名遇佛法者。\n'
        '善知识，汝等当精进持戒，修证了意诸佛所说，称吾弟子，否则，必落邪知，为诸魔所获。佛法难遇，人身难得，谛深祝汝等获证佛法。\n'
        '谛深2015，1，21日示',
  ),
  (
    title: '谛深大师开示:女众月经期能否烧香拜佛',
    date: '2015.1.20',
    body:
        '坐下弟子及声闻善知识众，是问为:为恭敬佛故而问，是故当说。谛听，善受。\n'
        '欲说是事，须与汝等讲说月经事宜。所谓女众之月经，乃天、人、阿修罗、地狱、恶鬼、畜牲之色身众中、人道特有之、转世因缘之相，是相称善恶界。所谓善恶界者，乃人之种性具善恶两相。人于善恶界中，诞生之始，其初始恶缘，先由母亲自行置换，置换后体分为两部，一部为净血动体，孕育胎本，七日之后胎本成体，今科学称之卵子，七日之后，或于5日内胎本会为因缘感招，游于宫内以与父本胎种成供血体，又经七日种子以胎本之缘附于母体，扎根为脉成发芽体，此称净血换善；另外一部，携带恶缘污浊，被母亲抛弃体外称为月经，是故女众月经来时，身体不适倍感焦虑，小腹有痛皆因抛弃恶缘为鬼魅所憎恨导致。又因人之善恶，于明处多于业思，多于以善为表，即使不愿意，亦能表面伪善，而于夜中多于恶表、恶为，恶鬼畜牲多于黑夜行于杀戮，而月亮为夜中灯，众罪据之为导，是故，人之女众之血，抛恶以月。月经过后，身识为导，慢慢梳集业缘至月轮转而用，因因缘有别，故有用初一，初二，至三十各不同者。如是等等，谛深只于略说。畜牲简于一言，其等生儿育女本于罪恶之大，种种因缘各有差别，不舍种种污浊，是故并无月经洗恶抛舍。\n'
        '善知识，人之生后，感恩母亲远胜父亲。虽父亲为种，种成缘分令八识者有命体者，但母亲为依以是因缘者成。\n'
        '是故，善知识，女众月经之时若无外泄污血者，可以烧香拜佛但当心净拒恶，若有外泄者禁；若身体不适者不当，若烦恼相害者不当；若持恭敬心者不记。是故，善知识，入门修行，以心为本，其余量行、量相而为，若有为、有相能令佛法不庄严者，不当为，为者重罪。祝女众以小龙女为范，修行成道。谛深2015，1，20日应弟子问。',
  ),
  (
    title: '谛深大师开示:佛法末世是怎么形成的(第二品)',
    date: '2015.1.15',
    body:
        '坐下弟子及声闻善知识，佛法末世师父已说，形成因缘今日为汝等有福有智者说。\n'
        '善知识，诸佛住世度众，因众生有罪、罪孽有差别故而有救度差别，所谓因差别、缘差别、果差别。因大众与佛缘分有别故而有佛法正像末。\n'
        '所谓正法时乃佛住世时，依大众因缘果报不同予以施救，被救之人以佛为师，因佛之教诲引导，即获出离六道罪苦；\n'
        '像法时乃被度成道众生之因缘延续，其因缘大众因自己父母兄弟姊妹、或法因缘 、道因缘众之依者于佛前有成证得而有信心，于是以此信心尊佛嘱托以戒为师，因无佛师导极少能成道，却能恭敬熏修佛说经典而有所悟得，以是所延佛法之相；\n'
        '末法时乃因缘大众因于相法时之缘分者悟中说道，少于得证，成说相法，而相法之中所传承戒律无佛为导大多无证而丧失信心，于是于自己因缘祖师所说虽有恭敬却难生实信，只于自己知见有所获得成罪孽执见，罪孽执见共鸣为道成共鸣执见，成就诸多以佛法与经典为因之执见之众说诸法典，成就邪魔道法，佛法显末世灭相。所谓佛法灭相，乃看似以佛法名、佛经名之说，实非佛说，乃罪孽说。譬如：假货，虽名相与真货同，实则假货。以是成就佛法末世波旬。\n'
        '善知识，汝等应严持戒律，切勿以自己执见思维佛法，当以佛说为说，能如是做称为有救。谛深2015，1，15日应弟子问。',
  ),
  (
    title: '谛深大师开示:什么是记忆',
    date: '2015.1.14',
    body:
        '坐下弟子及声闻众，今天有声闻因自己记忆不好问是不是业障，故与汝等讲说佛法修证中之记忆。\n'
        '善知识，佛法修证与佛法缘分及累劫功德有关，记忆不是主因。记忆不好的确为罪业所致，若能发心修行，于佛信心十足皈依佛陀一样成道。释迦佛住世时，一记忆极差之人终生以打扫茅房为生，听佛住世便皈依了释迦佛，后来佛教他念佛他听前字忘后字，后来他证大阿罗汉果位。是故，记忆不好不足为虑，用心皈依一样获救。\n'
        '善者，记忆乃1200记忆功德所成，若记忆有失为诸多罪业缘分所害。其中每一记忆功德有两支相缠成12到16格体，一支为知见另一支为析境智慧功德，若知见功德胜过析境智慧功德，其记忆功德不成，若析境智慧功德大于知见功德，其每大一格，其记忆功德就优胜一格，若所有析境智慧占有格数第一，则记忆力极强。\n'
        '善知识，欲获得析境智慧格数，须累劫遇佛修道，若于佛法有自己执见，其不获析境智慧。是故善者，若记忆不好，与自己累世于佛法有自己执见有关，汝等本世皈依三宝于吾坐下，当严持戒律，放弃自己知见，沐浴佛法甘露方能获得多闻强记，师父祝汝等早获成就。谛深2015，1，14日应弟子智依代群中声闻问。',
  ),
  (
    title: '谛深大师开示:什么人最难度',
    date: '2015.1.14',
    body:
        '坐下弟子，所谓众生难度，是指不能受佛说法之所有含灵之六道沉沦受罪相。\n'
        '众生大势之类有若干，其中天人阿修罗为上品，地狱恶鬼畜牲为下品。为什么畜牲列下品之末，因为大部分畜牲，皆为不能听受佛法缘分。有少部分畜牲像狐黄属，则与佛法有能听受缘分。是等难度之类，若不转善道，难能为度。\n'
        '最难度者，莫过于为人身时，于佛法以错解错用以为佛法，成就来世堕落种子，逐步堕落成重罪之属，失去缘分。是等均因不知佛法，自以为是，堕于大坑。释迦佛住世时，弟子问蚂蚁何时能度，释迦佛答，七佛出世是等为蚂蚁身，吾出世其依然为蚂蚁身者。百丈老和尚住世时，一狐狸身听法者，只因其为僧人时错参一句因果而落五百年野狐身，虽为狐狸但却不舍初心，能于百丈面前听法，受百丈教化，得以脱身畜牲。\n'
        '善知识，诸多罪重之者，以自己执见解佛所说，妄说成体，误导大众，是为最难度者。其未来世之种种罪苦，不堪观视。是故，师父谓其最胆大者、最难度者。\n'
        '善知识，莫于佛法做不证之法表，莫以自己执见议论佛所说法，若遭堕落十分可悲，汝等若因钱财、若为名声于佛法表自己执见、或表大众共鸣执见以为佛法，实为太过愚痴。谛深祝大众声闻善知识早证佛法！\n'
        '谛深2015，1，14日示。',
  ),
  (
    title: '谛深大师开示:什么是证得佛法',
    date: '2015.1.13',
    body:
        '坐下弟子及声闻善知识众， 所谓证得佛法是指：\n'
        '1、往生证得：若汝等修净土，生身能见弥陀能见极乐，并于死后由弥陀接引往生极乐世界安住，称为净土证得，若生身不能见弥陀见极乐，能于死后往生者，死时弥陀显前，显种种瑞，并于空中显极乐光明，此称往生证得。若生时不得见弥陀，死时无人为证弥陀接引，无人为证显往生瑞，则不称往生。吾之弟子若修净土，皆能如是获证。\n'
        '2、禅悦证得：若汝修禅定法，获得明心而后见性，此称禅悦证得。若人不能于禅门明心见性，能于禅定功夫中获见种种识心住境，此称定中境证得，定中境又九大次第定境现，亦称九次第定。若人不能明心见性，或获定中境证得，只于种种梦境、种种妄境，或种种外道典集中有知，不称禅悦证得。吾之弟子皆当如是获证。\n'
        '3、本尊证得：若修大日如来加持法，能于所应法持中，获得肉身直转愿力身，并于现前放大光明。若不能现前放大光明，能于自己所修本尊中，常以咒禁化若干种瑞，亦称密法消业获证。若不能放大光明，又不能以咒禁化种种瑞，不称密宗证得。如是等等，吾之弟子皆当如是获证。\n'
        '善知识，以上为佛法传承之三大修行证得之说，戒律不称宗派，所有宗派，戒为根本，只修行缘分有别，是故，所谓律宗者，实非律宗。另外，其余诸门所证，皆以是为依。善知识，修证了意佛法，乃入门修道之根本，若不证得佛法，汝等所修之法即为诳骗之戏，祝来者获证佛法。\n'
        '谛深2015，1，13日应弟子智依代群中声闻问。',
  ),
  (
    title: '谛深大师开示:师父都讲什么',
    date: '2015.1.12',
    body:
        '坐下弟子，师父所讲皆以罪苦众生为诸魔所困为体，破邪魔道法，令皈佛之众于邪魔外道能辩、有认、有识、有知而不被诸魔所害。\n'
        '释迦佛法末世，诸邪魔外道兴起，戒有戒魔、禅有禅魔、密有密魔、念有念魔智有智魔如是等等，皆以令大众不解其意而遭魔害。于魔害之中如何修行获救，证得为本。若于佛法不能证得，一切说教皆为魔做。是故，善知识当以证为照，修证佛法。吾谛深弟子皆当以证入门，否则，不称谛深之弟子。\n'
        '谛深2015，1，12日示。',
  ),
  (
    title: '谛深大师开示:莫妄说戒法',
    date: '2015.1.12',
    body:
        '善知识，今者吾弟子呈师父阅，有人于群中妄说破淫戒报应。是者看似护戒，实则坏败佛法传承之为。因，妄说之者，若为人信，信之者必不获证，若不获证，应戒之人必于其戒生不信心，若于戒不信，佛法即成假说，以是成断灭佛法相。戒律修持时，如何证得，是得修行信心的根本。是故，师父为汝等讲说破戒之相。\n'
        '关于戒法师父已讲说，今不再说。所谓破戒之相，譬如：有人欠债逃之夭夭，追讨之者愈追愈气，忽有一天自投罗网被抓，必遭更重怨报。破戒之相亦复如是。\n'
        '善知识，不持戒者，乃六道罪苦大众，随缘轮转受报，淫心实乃六道罪孽功用，有人说淫之恶报，实为妄说。佛说一切戒律，只为出离六道者用，若不为出离六道，所有戒律皆无能持用者，因为六道就是戒所避者。\n'
        '是故善知识，莫于戒相添油加醋，妄说妄用，否则，为坏灭佛法重罪。祝来者矜持佛说，早证佛道。谛深2015，1，12日。',
  ),
  (
    title: '谛深大师开示:',
    date: '2015.1.12',
    body:
        '善知识，佛法以实证而不灭，若无实证，即遭断灭。入吾坐下，莫以妄说为之，若以妄为，断灭佛种。譬如释迦佛时，有人妄说淫者无罪生身起大猛火堕落地狱即是谤戒实证。\n'
        '是故，善知识，若有人以讲说成名却无实证，是人乃重罪者，若以是宣传即为邪魔道法。望坐下弟子及声闻善者多于佛法修证了意，莫落妄说。谛深2015，1，12日示。',
  ),
  (
    title: '谛深大师开示:佛法不离世间觉',
    date: '2015.1.11',
    body:
        '坐下弟子及声闻善知识众：\n'
        '佛法不离世间觉，何故是说？善知识，所谓修佛道者，乃于迷中有悟、悟、彻悟，是故，悟依迷立；所谓迷者，乃世间法体、法相、法用；所谓悟者，乃出世间法体、法相、法用，无世间法，无悟可说。以是，佛法乃从世间出离者，若离开世间法则无佛法。是故，佛法不离世间觉。\n'
        '善知识，出离六道后，清净世界圆满自然，无任何法可表，但于慈悲中，依世间法表佛法而兴救度罪苦大众。谛深2015，1，11日应弟子智安代群中声闻问。',
  ),
  (
    title: '谛深大师开示:什么是因缘果报',
    date: '2015.1.11',
    body:
        '坐下弟子及声闻善知识众：\n'
        '汝之所问，为听信邪师妄说后不能有证之问，是故，汝所说以因缘果报法观照世间，实乃盲修瞎练之为，非诸佛所说之传承佛法。\n'
        '善知识，师父已讲说多品因缘果报法，今再为汝等有修行心大众说因缘果报道法，谛听，善受，善解，善思念之。\n'
        '善知识，六道乃因缘果报所成，世界一切，皆因缘果报。\n'
        '譬如：1、器世间中，化学，汝予干柴，吾使火种，燃成新物。其中，炭氧为因，温度之相火种为缘，水与二氧化碳、一氧化碳等为果报也。物理、数学、乃之社会科学无不如是；\n'
        '譬如：2、人之善恶、众生六道轮回之中，汝若被骂自有回骂或有机会行更过之举，骂者为因，机会为缘、骂他或打他杀他为其果报，反之亦然。\n'
        '恶鬼畜牲所受诸罪，皆因缘果报。\n'
        '有人以：某人行恶，却未见遭报为见，谓因果有差，实，是人未明因果。因为，恶行分大因缘小因缘，诸多小因缘因大因缘之报未到，不能于因缘中人有知，能知。譬如：国家之恶，须百年才报，国家中强人假国家大势，欺侮百姓，更有杀人越货无恶不作者横行霸道；更有为权强势者，欺男霸女胡作非为，是等皆依种种大小缘分之时长时段受报。\n'
        '善知识，无始劫来，因缘果报丝丝相扣、缠缚辗转、纷繁复杂，是称五浊恶世。五浊恶世之大因缘称劫浊，众生因不能于自一生知见明了，称见浊；大众因不能于大势因缘有所作为，必障碍重重，烦恼四起称烦恼浊；因于种种因缘果报中，迷途不返获诸种罪体之、天人阿修罗地狱恶鬼畜牲，称众生浊；众生因于大势因缘不能改变称命浊。\n'
        '是故，五浊之中，不同之者，于定处同时作一种因，所获果报各不相同，获报世间亦不相同。譬如有三人同时行抢银行，一个被当场击毙，第二一个则被追逐擒获，第三个则逃之夭夭，皆因其各自所处因缘有别，报处、报时不等耳。\n'
        '善知识，入吾坐下，当放下种种末世佛法染污，洗心革面持佛戒律，做吾弟子，精进勇猛获证佛法，切勿以自己熏染执见行修佛法，耽误因缘沉沦六道。谛深2015，1，11日应弟子智依代群中声闻问。',
  ),
  (
    title: '谛深大师开示:佛门怎么看堕胎',
    date: '2015.1.11',
    body:
        '坐下弟子及声闻善知识众：今者吾弟子呈阅群中有邪道以堕胎为宣，诳骗大众，故吾为众说堕胎所犯。\n'
        '善知识当知，胎之形成为众生因缘果报之轮转表，乃妄识与业和合攀缘成体之始。妄识与业和合攀缘之前，男女因业互染缠缚相拥互用，互用为情，相拥不分成难分相，难分为爱，于是情爱成种，业之明暗、动静根于其中生成芽体，成就受体，是为卵子。受体暨成，合适于识根卵子之因缘种子与识根缠成二根业流成体，生成八识根体，根体于因缘中生长成相，乃世间所说之胎。\n'
        '善知识，人之胚胎生成，均七日为段，男女交媾七日之内相互受用为始，一七为拥，二七为合，三七为六根立，四七为六根分，五七为六根互分互用成芽，六七为长，七七为成体时。\n'
        '是故，所谓堕胎，于不同时段有不同果报。若于怀孕半月堕胎，为一七之时罪，其罪与食用一鸡蛋之罪通也，因人之缘分福报大于畜牲，是故所受业报稍大食一鸡蛋者；若于怀孕月内堕胎，乃二七之时罪，其罪与食一口众生肉通也，但人之报大，其罪略大；若于怀孕四十天堕胎，其罪与食一口人之肉通也，因此时胎为旺用，其罪略大；若于四十天之后堕胎，与杀生等同；若于三个月后堕胎，为其因缘初用，其罪报与直接断人命者有三分重罪，若于七个月以上堕胎，半于断人生命重罪。而怀孕之人于是诸罪分，亦按二分或三分于丈夫、大夫堕胎共业。\n'
        '善知识，莫于堕胎做过于重罪宣传，若过于宣传，乃邪魔道者，为自己名利恫吓信众，令无故信众因惊恐故，堕落地狱，断灭佛法道缘。是等不解佛法戒律之人之愚痴妄为，会令诸多并无过重之罪者不安，甚至导致一事多命之邪道教义为害佛门、为害尘世，切勿上当。\n'
        '善知识，若于尘世难脱大势因缘所究，当少事淫欲，谨慎欲行欲为，以避免堕胎之苦、之罪。谛深2015，1，11日应弟子智安问。',
  ),
  (
    title: '谛深大师开示:世界劫难',
    date: '2015.1.9',
    body:
        '坐下弟子及声闻善知识众：\n'
        '世界之存，乃妄生妄灭过程。妄生妄灭乃妄心之表，于是，圆满无分妄因成风，成就十方世界无量造相，和合分离为其相别，以是造就十方世界。诸世界界内分别攀缘成世界诸体造相，相别离合，成就世界万物，每一世界，皆以大小诸体成含造就体相，无量妄识以自己所造体相为用，成就无量众生世界，每每世界众生皆因福报恶报等等而有差别，所谓相差别、识差别，种种差别，每一世界之每一众生，皆有类差别、种差别、体差别、相差别、如是等等。所有众生又生种种妄尘而聚成各个世界与世界生灭变迁。\n'
        '善知识，世界生灭变迁即为世界劫难，劫难量度尺度乃因缘果报延续计量单位称谓，称世界劫数单位，不同世界单位有别，大小不一。所谓：阿僧祗劫乃所称有世界一大缘分量度，挲婆一劫为一挲婆生灭缘分量度长度单位，小劫为挲婆生灭缘分量度再分单位。\n'
        '善知识，十方世界因因缘果报有别，大劫之度亦所以各不相同。\n'
        '善知识，世界劫难为不能变定式，诸世界虽各个不同但其劫难变灭之相相同，谛深今说挲婆世界劫难变灭时相。善知识，挲婆世界，释迦佛住世为壮年时，逢劫之中期，人道因缘至盛，其中地球饶日一周集一像，一百周集一记，一千周集一劫毫，一万周集一劫捺，一万捺集一劫分，一万劫分集一小劫，一万小劫集一大劫。\n'
        '善知识，挲婆每一劫毫，其相变换一次，于八万四千劫毫处，成体差别变化、种差别变化一次，如是变化不断至大劫来临。\n'
        '善知识，挲婆世界先有诸类杂居，小劫来临，诸类变化，人道逐渐成主，诸生相貌变化极大，界内众多旁生依人而立，过万小劫，诸生相变不断，种类数目以人而定，届时人道与鬼道相通成堕落体；人道变化以由善至恶，先乱后道为道，其相为：劫初人心多以情道为依，互爱互善，劫中人心多以道道为依，善恶皆依，劫末人心多以道道为判，恶不为逆称为有道、有能力等为人赞叹，世间欺诈盛行，广以虚妄善思为道，引导大众，而实善则遭欺凌，是时，人王国王皆以是法，行于世间，于大众中，说恶者善，大众即认为其善，实则不善，恶者受人爱戴吹捧，善者遭恶者欺凌。于是，大众之中，恶种为实，虚妄善种成虚妄种种于来世，世界已无善种能种。\n'
        '善知识，世界无有善种，其世界相，常有无名灾难无兆发生，常有不治怪病无兆发生，人道、畜牲道、旁生道，因人之生杀罪重熏染故，疾病亦能相互为害，人之怪病能传畜牲，畜牲怪病能传与人，等等。大劫来临时，诸多人已不能为生。随后，风毁，水毁，火毁令世界灭。劫尽无人之肉身能住挲婆，仅诸鬼神能于中来往。世界灭后，经数亿劫数，世界方能再生，成就当处众生。\n'
        '善知识，当于佛法末世，精进勇猛持戒，获得出离六道罪苦火宅。\n'
        '谛深2015，1，9日',
  ),
  (
    title: '谛深大师开示:念佛关口',
    date: '2015.1.7',
    body:
        '坐下弟子及声闻善知识众：\n'
        '今天是阿弥陀佛圣诞，日子吉祥。\n'
        '如何念阿弥陀佛往生阿弥陀佛极乐世界，是十方众生之当知、当学、当应。\n'
        '何故是说，善知识，因诸多邪魔外道皆因自己罪孽深重故，愚痴虚妄，于大众不知念佛关口因缘处，嫁接自己执见，令大众于念佛途中受诸等罪侵，丧失念佛信心，断灭阿弥陀佛愿力佛种，令佛法断灭。\n'
        '是故，善知识，吾今为说念佛关口，善思念之。\n'
        '善知识，所谓念佛关口，乃念佛往生极乐途中因缘转处，分为四大因缘受转段次关口，一者生信关口，二者皈依关口，三者一心净念关口，弥陀接引往生极乐为最后受转关口。\n'
        '善知识，所谓生信关口，乃初入佛门，受用佛法为其关口，受用佛法获得多证有四大类，皆能生坚固信心，称信心生。是四关口，有正关、背关、侧应关、背侧关。四大关口成处，有正念、谤念、妄念、邪用念为其根本四类，此四类念佛之相所成，来自念佛心用，是法师父已说，今不再讲。过信心关口后，若自妄自大，以自己执见行解佛法，称皈依自己执见，是等有二歧路，一者因皈依佛故，获证佛法成善知识，二者因于佛法有解故，不获佛法道证，入邪道体，不于佛前皈依三宝，获魔道证，成魔国土，魔之福报来临。所谓魔之福报，譬如有人杀人越货，虽成其货，实则提心吊胆享之，最后锒铛入狱而终。魔之福报亦复如是，享之福报实则罪报，最终堕落地狱。\n'
        '善知识，念佛生信，于法正路，便入如何皈依关口。修皈依法，亦有四门为关，其分别为，正信皈依关口、邪信皈依关口、妄信皈依关口、缘使信皈依关口。所谓正信皈依，乃累世大缘分所成，是等多为诸佛授记缘分，是等因缘能成护法大菩萨为；所谓邪信皈依关口，乃邪用念佛生信所成，是种皈依能于佛陀坐下，获信心化转，成多神通应相；所谓妄信皈依为妄信所成，是等多能累劫修行，于佛所说法，以自己执见成解说道相，而自己却持种种疑惑于法证，是种皈依最难亦能受佛化转；所谓缘使信皈依，乃于一上皈依缘分中，因缘直入皈依之体相，是等皈依能成大善，能为邪皈者反证，令其化邪成法，入佛法藏。\n'
        '善知识，皈依三宝后，入念佛往去极乐成就关口，于是关口，受转途中依自缘分，决定三种道途往去，一者肉身往去阿弥陀佛极乐，二者命终往生阿弥陀佛极乐，三者转生天上随缘往去极乐。善知识，欲获是三种往去往生极乐，第一要关，为一心净念，何为一心？欲获一心净念，当过三个修行关口，一者，汝等参禅，念头层生，是不为一心念佛之相，一念不生乃为一心之相，如何获得一心，持戒为用，是称一心关口；二者汝等口称佛号，却遇邪道以种种法搅闹，此为因缘杂缠，不为净称佛号，无邪道搅闹，称能净称佛号，如何获得净称佛号，持戒为用，何者搅闹，戒不清净，譬如，汝正称佛号，却有人言、或有人唱、或有物闹；三者，汝若妄念，汝之僧导与汝有累世共业罪，成妄念种，看似一心，实则妄用，不能往生。\n'
        '是故，善知识，念佛往生若不持戒，一切枉然。祝来者精进持戒念佛早生极乐。谛深2015，1，7于阿弥陀佛圣诞示。',
  ),
  (
    title: '谛深大师开示:什么是现身说法(第一品）',
    date: '2015.1.2',
    body:
        '座下弟子及声闻善知识众，所谓现身说法有两种内涵：一种尘世与未成就内涵；另一种是开悟或再来菩萨内涵。\n'
        '一、尘世与未成就人以自己亲身经历，验证、辅助证明所说道理，称为尘世内涵；佛门未成就人以空、有、神通等等为用所得之知见，并以亲身经历验证为道理为说，称未成就内涵！\n'
        '二、开悟或再来之度天人菩萨，诸如：观音、地藏、文殊、普贤、金刚王等等之摩诃萨或十方如来于尘世以种种身：化身、应身、加持身等等为说，称为开悟或再来菩萨或如来应世内涵！\n'
        '是故善知识，若遇善知识，不知姓与名或以比丘相、或以居士相令汝获甘露，其本非比丘、亦非居士者，乃观音是也；乃地藏是也，如是等等。若有人立名相打造诸法道，波旬之住也！谛深非谛深，落发名不宣，汝之获实惠，乃称谛深者，乃为破诸魔留有非名相，是故佛称之，非相为谛深！\n'
        '善知识，当严净毗尼法，获得佛法证，谛深赞叹之、谛深护持之！谛深2015-1-2日。',
  ),
  (
    title: '谛深大师开示:居士不能讲法',
    date: '2014.12.29',
    body:
        '因弟子智依问：居士为什么不能讲法，师父呵斥开示如下：\n'
        '智依，居士为尘世中人，乃六根受用之道人，若于说佛法，即成诳骗。\n'
        '譬如：瞎子国中瞎子们为行路，根据实际经验编辑了很多如何拿着棍走路的法，比如说，这里有块石头别绊倒，那里有条水沟别掉下去，瞎子门也都在实践中因有证得而深信不疑。如果明眼人来到瞎子国里与他们说：这里有块石头，哪里有条水沟，让他们生信，然后跟着他走，瞎子们会听？明眼人让他们生信的目的，是为了给他们治眼，而他们则会因为自己的法，舍弃明眼人。如果明眼人说，你们的这些真实的法会害你们累世累劫的子子孙孙，他们会问，我说的与你说的有区别吗？你就是一骗子！\n'
        '我拿这个譬如，告诉你们，若不舍六道种种业，这些业是叫六道，也就是，六道中人以六道说出六道法，就如同瞎子国人，以瞎子执见谈明眼人事。\n'
        '又譬如，有极少数的瞎子，因种种原因跟着明眼人走了，这就比喻皈依佛后的出家持戒比丘，他们尽管还没明眼，但如果听持戒比丘所讲的法，也会得到治眼，最后明眼。不开悟的非持戒比丘，亦不能讲法。\n'
        '所以，智依，居士不能讲佛法，而持戒比丘可以讲，居士们讲的越好，所起的坏作用就越大。为什么讲持戒比丘？因为持戒比丘是跟着佛走的佛子，不持戒比丘，则不是跟着佛走。居士戒为种子，什么时候发芽发心出家，什么时候才能开始得救。\n'
        '智依，大众不舍六道罪业，就如同瞎子，尽管他们所说的种种法，很现实，也与明眼人所说的相同，但，他们不仅永远都救不了瞎子国人，而且，还会令瞎子国里的人，断灭明眼人缘分，而更长时间的暗无天日。\n'
        '智依，虽有诸多大善知识，十地菩萨乘愿再来，于尘世中当缘开悟，但其必会以当机显出家比丘相，护持佛法。\n'
        '智依，所有尘世传阅的大居士所说经典，皆波旬道法。你们应该为做师父的俗家弟子，不能放下出家跟师父走，感到羞愧。谛深2014，12，29日呵斥。',
  ),
  (
    title: '谛深大师开示:什么人胆子大',
    date: '2014.12.29',
    body:
        '各位同参，今天有密宗邪道搅闹，我问师父，他怎么这么大胆，敢谤佛谤戒搅闹清净道场。\n'
        '师父说：下世转成地狱恶鬼畜牲的人胆子最大，因为他们不怕诽谤佛法遭此诸等罪报。\n'
        '何故地藏忙，愿力无有尽，因众胆子大，不怕受众罪。诸大善知识，于佛不信者，称为胆子大，诽谤佛法僧，称为最大胆，不持佛禁戒，称为胆子大，等等罪孽因，罪众皆不怕，故说胆子大。如若有疑惑，汝等观畜牲，不识善之人，处处遭杀戮，何故遭杀戮，其为人身时，胆大罡骂佛，遭此罪孽报。\n'
        '是故，善知识，莫于诽谤佛法之罪重之者有怜悯思，当有自悔思，当以自悔生慈悲心，悲其来世受报难能施救。汝等若遇畜牲显前，心甚喜欢，当知是等畜牲乃汝之缘分，因犯重罪故遭此堕落报。谛深2014，12，29日应弟子智依问。',
  ),
  (
    title: '谛深大师开示:如何修分别心',
    date: '2014.12.28',
    body:
        '坐下弟子及声闻善知识，所谓分别心，乃识心自性，十方如来皆能微细分别，如何得微细分别，修行得之。\n'
        '善知识，汝等若能微细分别，诸邪魔外道所不能侵，是故当修。若能分别正邪，诸邪道法，所不能侵；若能分别善恶，诸恶鬼神罪人所不能害；若能分别佛魔，自入佛之国土于一念倾。等等。\n'
        '善知识，譬如六根，何者为眼？眼根乃明暗分别成像，缘像造障成有道体之相为眼也。\n'
        '何者佛眼？能造十方明暗相法，能于十方世界微细分别无有一因一缘一法所能漏却之，圆满之眼耳。\n'
        '何者天眼？能于天道造明暗相法，于其天道所造世中，能分别无有过处之眼也。\n'
        '何者人眼？能于人道造明暗诸相，分别人道诸事诸物明暗相用之眼耳。\n'
        '何者鬼眼？能于应恶之处行明暗障碍，能分别鬼道诸为有相之眼耳。\n'
        '如是等等，眼根差别成体之眼有无数梯次类别，神有神眼，鸟有鸟目，重叠之处相互为视。\n'
        '分别心诸根如是，汝等应当认真修为，以获当得，成佛报身种子。\n'
        '是故善知识，分别诸法，当精进勇猛修证，以是修证，破诸相法，获得非相得如来体。谛深，2014，12，28日。',
  ),
  (
    title: '谛深大师开示:如何获佛法福报',
    date: '2014.12.28',
    body:
        '今日因群中罪众说，学佛修密修净土多年，越修越不顺，不想修了！我问师父，师父开示如下：\n'
        '智安，关于佛法末世，邪魔外道炽盛世间，师父已有开示，汝等当用心参学。师父关于末世学佛福报之说，亦可直接发到你的群里，开悟声闻大众。\n'
        '智安，释迦如来法之末世，譬如已故雄狮，体内蛆虫繁殖，不能获证雄狮之道，所有信众因跪拜雄狮实拜蛆虫故，不获雄狮护持实惠。\n'
        '智安，如是之释迦佛法末世之相，久而久之，必令信众因不能证得佛法故，不能获得相应福报，丧失信心，遭大堕落。\n'
        '智安，譬如该雄狮尸体渐渐为蛆虫分解，原本被雄狮降伏称臣之狼虫虎豹，见此雄狮已为蛆虫蚕食，不能再行统辖，便无法无天横行大地。是故，佛法末世诸邪魔外道兴起。\n'
        '智安，邪魔外道不知雄狮兄弟已经长大，卧于丛林静候佳机，有狼虫虎豹，蜣郎蛆虫见之不敬，欲撕咬食之，以为此亦一尸耳，结果遭雄狮兄弟起身捕杀，成雄狮盘中之餐。智安，吾住于世亦复如是，吾乃诸佛所托，令诸邪魔外道皈依降伏也。\n'
        '智安，汝之所说之人，亦复如是，是等诸多信众皈依佛门，实则皈依蛆虫虎豹耳，如是之人如何获佛护持得佛赐福报？\n'
        '是故，智安汝等为我所使，对释迦佛末世广大受邪魔外道欺凌信众，多做护持，弘扬戒法，一切邪魔外道所不能为害。谛深2014，12，28日。',
  ),
  (
    title: '谛深大师开示:如何修执着心',
    date: '2014.12.28',
    body:
        '坐下弟子及声闻善知识众：\n'
        '如何修得不执着于种种法种种道、获真如自性，释迦如来已说，吾今为汝等讲说如何修执着心获得果位。\n'
        '善知识，一切有为法，皆有法之缘，所谓法之缘，皆为执着得，如何破其缘，当以执着法。\n'
        '善知识，譬如有螺丝，汝用十磅力，拧紧为求固，如今器件坏，锈死难为解，欲破其螺丝，当用倍加力。\n'
        '佛法亦如是，众生因执着，成就诸罪孽，罪孽深重延，成诸罪国土，如是之大罪，执着为根本，放下无可能，吾设执着法，反之加大力，以执着大力，令其解罪孽。\n'
        '善知识，何者为执着，定力乃执着，是故设禅悦，禅悦为大力，能如金刚钻，破执着大障。\n'
        '如何得禅悦，汝等当持戒，执着于戒法，必获大定力，大定大执着，诸魔不能侵，于是破魔掌，获得大自在。\n'
        '善知识，入佛法们，当执着自行，否则，必被邪魔外道俘获。\n'
        '善知识，信为执着，不信无有救；愿为执着，无愿众生不度；行为执着，无行不了尘缘。是故，汝等当修坚固执着破魔信心，方能出离六道。谛深2014，12，28日。',
  ),
  (
    title: '谛深大师开示:用的就是执着心与分别心',
    date: '2014.12.27',
    body:
        '坐下弟子及声闻善知识众：\n'
        '所谓佛门修行，用的就是执着于某途的执着心、分别善恶正邪辨别真伪的分别心，否则，无以为道。十方诸佛皆以执着心、分别心，于道途中用而得道。佛说不执着无分别，乃为破魔迷之人入净道者说。善知识，如来能微细分别方称如来。重罪之者，以莫有执着心分别心于人前称佛法者，实则为令：罪恶等同行善、之掩盖自己重罪之狂妄说。\n'
        '善知识，佛具三身成就，其中圆满报身，乃识心分别圆满恒住之含量体；千百亿化身乃识心分别之住世用相体；清净心为证得一切皆无，入不动地之总持法体。\n'
        '何故罪孽大众，以不执着、无分别称佛法，并行诽谤入道道人，其实乃瞎子说日者也。\n'
        '善知识，譬如：瞎子国里一群瞎子正在摸象，摸耳者以耳为象、摸腿者以腿为象，等等争吵不休。一明眼人至，以眼观之。瞎子们摸到哪里，他便说到哪里，所说之事，经瞎子们摸后对证，无毫分差错，如是，令所有瞎子心服口服后，明眼人告诫瞎子们，切勿执着某处以执着心称象；切勿分别各处以分别心称象。明眼人走后，瞎子们逢人便称切勿执着以执着心行事；切勿分别以分别心行事，并以是为道，修行如何不执着，如何不分别，若遇人来说象者，常以太执着、分别心斥之。\n'
        '后又有明眼人至，见到瞎子们在为：摸象不能执着应该修不执着法；摸象不能有分别心，应当修无分别心方能见全象。他们终日争吵不休。瞎子国中之大学问者云集，并以此为题高谈阔论，且皆依明眼人所说，写书立传，为破执着心、破分别心用，为此，声名显赫，称圣人者甚多。\n'
        '此明眼人亦如第一个明眼人一样，用现实征服瞎子们之后，便告之瞎子们，执着于某处称之为象不对；分别某处称全象者不对。若汝等不执着的去摸象，不能分别记住象的各个部位，如何见得了全象，是故，不执着也不对，不分别也不对。瞎子们，一时满头雾水，不知如何是好。后来，明眼人，告诉瞎子国人，汝等毛病为眼瞎耳，当治眼也。\n'
        '善知识，诸佛所说亦复如是，若大众不能开悟谈说执着心与不执着心；分别心与无分别心，恰如瞎子说象、瞎子行道耳。\n'
        '善知识，若遇有罪众，以分别心、执着心诽谤于汝，当以是为镜，令其自显魔型。谛深2014，12，27日。\n'
        '\n'
        '( 阿弥陀佛，刚才智安有点糊涂，电话向师父请法，师父电话开示：一心念佛，是执着于一句佛号，禅定功夫，修得是定，定就是执着。所谓不执着，是当你获得之后，是自然没有执着。譬如一个瞎子，整天执着于摸象，另一个瞎子整天不执着摸象，两个人都不得见象。如果把他们的眼治好了，还有执着与不执着吗？所以修行们，入了这个群，就不要拿那些乌七八遭的东西，在这里表什么佛法，这是个禅院，也是个戒院，好好持戒，证得佛法之后，自然明白。)',
  ),
  (
    title: '谛深大师开示:末世如何为僧',
    date: '2014.12.27',
    body:
        '善知识及出家僧众：\n'
        '佛法末世，诸魔兴起，出家为道甚为艰难，若有人为求出离六道出家为僧尼，能于寺院受种种磨难，执信不变修佛戒律者，勿忧勿虑，吾谛深为之赞叹，吾为汝等做末世舟乘，令汝等当机有出。\n'
        '善知识，若遇罪众搅闹欺侮于汝等，于汝等殿堂诵戒之后，称谛深救吾，静坐片刻，不生嗔恨，吾随时能勤力助救。若因汝等有尘世罪孽，不能直解汝等之险，联系吾坐下法子法孙，可住吾坐下寺院，脱离险境。\n'
        '善知识，末世波旬化现种种罪孽之人，一一于无戒律者应之，破坏佛法，汝等当发大行力，修学戒律以获成就。谛深2014，12，27日。',
  ),
  (
    title: '谛深大师开示:什么是附体',
    date: '2014.12.26',
    body:
        '坐下弟子，所谓附体，乃魔着类别，为一身多用罪报，由共业染污罪与通体业缘罪、皈依邪道罪等为因所成。是故，若有人于戒有失，盗、淫诸戒成染，皈依邪魔道法或无戒参修佛法经典遭波旬弟子加持，均易获此报。\n'
        '善知识，譬如1：有污水流经，汝等开渠迎接，污水即染汝之土壤，令汝遭害。邪师说法亦复如是，有人皈依邪魔外道、或皈依佛门无戒邪师，会于其邪道罪法形成染污重罪，而于其相成附体众，其能妄说、口说诸等经法，却并不自控、或自知。\n'
        '譬如2：汝有宝车，有人因与汝有缘故，借汝车为事；或汝欠情债，今遭旧故，自愿与车用之，用后返还，或汝驾车行路，有人强拦汝车，并驾车行之。等等。\n'
        '有附体之者亦复如是，本自缘分相互交叉成染，因不能入佛门持佛戒故，必遭缘分互用、或遭邪染假借。\n'
        '另有罪众听佛法分为大乘小乘，因攀缘罪重故，处处以自己参修大乘为荣耀，不持禁戒盗阅大乘经典，或由邪师引导以我慢重罪成大乘群体，殊不知大乘小乘乃修行过程分别称为，佛说大乘乃为破有人因执着于小乘神通而成罪道，说大小乘分别。是等由是堕落成罪，而遭波旬俘获。是等中人，口业极重，常遭附体、或因此精神失常，口说经法，实则魔着获现实报。\n'
        '若有人不皈依佛法及持戒僧，实则在破坏佛法，必遭大堕落。\n'
        '善知识，当皈依三宝，严净毗尼，方能于佛法有证。谛深2014，12，26，应弟子智安代甘肃声闻问。',
  ),
  (
    title: '谛深大师开示:佛法不是说的',
    date: '2014.12.26',
    body:
        '坐下弟子及声闻善知识众，佛法乃佛所证道，非言语所能讲说，吾所说者，乃引导弟子及所闻法者，入佛法脉，并非讲佛所说法。佛说之法亦复如是。\n'
        '譬如：吃茶，若汝等只与来者说诸茶味道而不令喝，实则，说者愚痴、听者受罪耳。若复有人，只听说茶者说味为称茶味，是人乃着魔耳。所谓导师，一句喝茶戒，汝如说做，一口便得。\n'
        '佛所说法虽有三藏十二部之多，每部每句皆有应对来者所需， 恰如一句也。\n'
        '是故，有人以讲说佛经为道，实则如与饥人说食也。\n'
        '善知识，莫着说相以为佛法。师父所说一切皆棒喝有罪者也；皆以所求法者，得所求事之令喝茶去者也。谛深2014，12，26日。',
  ),
  (
    title: '谛深大师开示:什么是大乘佛法与小乘佛法',
    date: '2014.12.26',
    body:
        '坐下弟子及声闻善知识，所谓大乘小乘，乃修行过程称谓，并非佛法优劣称谓。\n'
        '善知识，譬如：登山于门前开始、到达山巅为最终目的，途径平原、江河、山谷等等。其中若于平原称其小乘，高山攀爬至其顶峰称其大乘，无有平原则无以到达顶峰，若有人称吾直达顶峰，实为妄说。\n'
        '善知识，又譬如：人生求学，小学、中学、大学虽有分别，实为一体之过程。若不读小学、中学基础，却直接学习微分课程，其所有人皆不获实惠。\n'
        '善知识，佛法小乘大乘亦复如是，所谓小乘如同小学中学课程，而大乘如同大学课程。如果有人未证得小乘佛法则以大乘讲说，恰如学语幼儿自称教授。善知识，比丘戒律乃小乘佛法，不得比丘戒称佛法者，实则诳骗大众自欺欺人之为。\n'
        '善知识，佛法殊胜，不入戒法者，阅遍佛说三藏十二部，并能讲说无误，亦不能于佛法知毫分许，更不能获佛法真传，是故，汝等当严净毗尼，获得证道，步步修行直至成佛。谛深2014，12，26日。',
  ),
  (
    title: '谛深大师开示:因果不眛',
    date: '2014.12.23',
    body:
        '坐下弟子及声闻善知识众，今有罪众以自己知见妄解、妄说“空有”与“诸相非相”，并以是罪孽执见推说“不因不果”之断灭因果重罪之说，成就妄种，来世因此虚妄成诳骗大众相、堕落于地狱恶鬼畜牲身。善知识，若以是说传众，是人当于来世受野狐报、一人多用报，地狱众食报等等。大众当引以为戒，切勿妄参错参佛法，切勿切勿。\n'
        '善知识，譬如：有人本世常被附体、或精神恍惚、或精神分裂等，其皆是因上世信狂妄解佛经之魔着者，魔着者堕落地狱，皈依信受者受邪魔外道拖累成种，并延成本世罪孽果报。\n'
        '善知识，切莫错参、错悟佛所说法。精进勇猛，持戒为修行道，不证不说、不见不说。若不证，持戒为修。善知识，谛深本世缘分，落足之家苦难深重，吾生之后，其家人获出苦难，大福降临，只因吾上世受其供养五台建寺，造此缘分。善者当知，因缘果报丝毫不差，是故，善知识，入吾弟子群者，乃与吾有缘，吾谛深不取汝豪之物，亦不求汝传扬，只告诫不皈依吾者，切勿未证谓证，错参错悟。吾再繁琐警告，切记：法自戒中证，莫以狂心求。谛深2014，12，23日应智安代群中声闻问。',
  ),
  (
    title: '谛深大师开示:什么人易糊涂因果',
    date: '2014.12.23',
    body:
        '善知识，因缘果报分毫不差，不信因果重罪之者，其或上几世为畜牲时被人杀戮，其被杀之因，累世积成与杀之者因本世杀业轮换、成本世人身；或因自身因缘中有出家持戒比丘福报滋补成本世报，等等。\n'
        '是等重罪之者，人身随罪业获得，若遇佛法，亦因狂妄执见而生不信心，随因缘轮转下去成罪孽相。\n'
        '不信因果修道之者有二岔路，一者因无开悟明师指点，自不持戒，妄心参学佛说经典，落于空论而妄知因果乃空，成堕落罪。二者，于佛说法，不持戒律，不能得证，遭邪魔外道俘获，不信因果。 是种罪众，多狂妄自大，以空谓证或以相谓证，不信因果，落重罪因缘遭大堕落。\n'
        '善知识，切勿妄参经典，落于大坑，无始劫来受尽苦难，好不容易无始劫之德今遇佛法，却因自己狂妄故，而遭丢失堕落。\n'
        '善知识，若未开悟，戒乃明灯，令汝等必于佛法有证切不堕落。即使开悟，戒亦护持汝之大道。汝等当严净毗尼，自获道途升迁。谛深2014，12，23日。',
  ),
  (
    title: '谛深大师开示:诵经、诵咒、念佛功用分别',
    date: '2014.12.19',
    body:
        '坐下弟子及声闻善知识众，智依代群中有声闻以邪道说：读经不如念咒，念咒不如念佛，问这个说法到底对不对？\n'
        '坐下弟子及皈依佛之声闻善知识，是种说法为未证谓证之、盲修瞎练误导大众、破灭佛法之、末世波旬断章取义假佛说经、诳骗累劫善种今者入佛门之众生、令众因误导堕落之重罪说。何故是说，如来所说法皆为种种当机之用，如是之说，乃说如来所说所有法、经咒之者乃愚痴之为也，是故其诽谤如来，诽谤经典，诽谤传承。其做是种说者乃地狱恶鬼畜牲之报前人身者也。\n'
        '善知识，譬如人身长大，须父母先行哺乳、后行学步、再行教育、遇病设药求医，成年结婚生儿育女，男女有别分别有自性法，如是等等环环相扣，各有行法功用、各有规矩、各有对治、各有所应，如是等等，若于哺乳之期，汝却按成人病时用药，是人休矣，是称法之有别。\n'
        '佛门修行亦复如是，所谓诵经、诵咒、念佛、参禅各于戒下有应当功用，不能相互替代，若不持戒，诸法不能成出离道，只成种子，若是等种子遇如上诳骗则能变坏。善知识，十方如来住世，皆以当机之法而救大众。云何有愚痴重罪之辈，于佛门诳骗大众，却诸多人信，因信变坏累劫善种而遭堕落，是者乃佛法末世之相也，是法谛深已说，不再做表。\n'
        '善知识，切勿未证谓证，自欺欺人成大罪孽毁坏累劫善种，不能为如来救。谛深2014，12，19日应弟子智依代群中声闻问。',
  ),
  (
    title: '谛深大师开示:佛法不是哲学',
    date: '2014.12.18',
    body:
        '坐下弟子，诸多邪道以辩证或中道为佛法说，实则，误导大众，于人道落入歧途，令随缘堕落耳。\n'
        '譬如：有人以见不见、思不思，其都在那里为得，其为自己不能被救之凡夫说。是等说者，于世间法合，不能出世间，如是破灭佛法。\n'
        '善知识，佛说无者，乃破空之说，譬如：行车过于大桥，尔说大桥者，虽佛说无者乃修行要关，实则非目的地也。\n'
        '善知识，所谓智慧、相似智、空智、实智、波若智等等乃至无碍辨智皆非佛法之要。\n'
        '若如是等等以为佛法，落魔道耳。\n'
        '是故，入佛门修行，当以佛、以戒为师，莫以师为师方能有成。谛深2014，12，18日。',
  ),
  (
    title: '谛深大师开示:当入寺院',
    date: '2014.12.16',
    body:
        '坐下弟子及声闻善知识，所谓入法修行是指：与成佛之法合为入法，若不与成佛之法合则称未入法。不能入法修行，于佛所说事必不能得证，若以不入法之法为佛法依，称盲修瞎练。若盲修瞎练炽盛世间，则佛之末法至。佛之末法至，诸邪魔外道趁虚而入破坏佛法，令佛法灭度。\n'
        '善知识，譬如：有人称入净土法门，却不入寺院称往生极乐，恰如有人于鲨鱼海中，慑鲨鱼恶，求岸上人救，岸上主人派船长率众水手入于海中令罪众登船，然，因海中之众受邪道所教，不皈依船主与船上水手，自称吾等只听教吾等呼救之人者，其不登船，并骂船上水手无有修行，并自于海中集结成群，追随令其呼救妄称大船者。不日鲨鱼群至，是等大众依然呼救，因其主不识真船，妄说为船，于是不能获救故，为鲨鱼群争食撕碎遭大恶报。\n'
        '善知识，佛法僧三宝，乃十方诸佛救众之身，寺院乃罪苦海中救众之处，若不皈依三宝入寺院者，以居士身称救众者，为行业中道，不能应愿获救。是等罪众，若遇缘分大德比丘能皈依者，方能获救往生极乐。\n'
        '善知识，持戒比丘所到之处若坐，当行跪拜迎请，请其住于新建房屋，筑台设案请其入座，若于旷野当为其围帐三尺，筑台中央，三拜请法，是称方便寺院，若不能则称问者有罪、重罪、不救之罪。若有人讥毁、嘲笑，即时为罪，必堕于地狱恶鬼不能有出。\n'
        '善知识，佛法末世，波旬披佛袈裟住于寺院，自不持禁戒以种种理讲说经法，若遇是种缘分，汝等亦当入于寺院，于自座前置自己所受佛说戒经，依寺院规矩参做功课。不于波旬子孙，成诽谤缘，令其自去。汝等即获末世成道之法，必于佛说有当缘证。\n'
        '善知识，佛法末世又有诸多有大业报人，或居士林，以自己之力，不行供养僧宝比丘，依寺院之相建立殿堂大院，亦名之寺，实乃波旬道场，断佛法脉。是等为求功德，恰遭堕落，恶鬼畜牲三恶交报应时显现。如是之类，不称寺院，不当入之。\n'
        '善知识，佛法末世，当如上述、入于寺院，才能于各法门得法获救。谛深2014，12，16日。',
  ),
  (
    title: '谛深大师开示:什么是口业（第一品）',
    date: '2014.12.15',
    body:
        '坐下弟子及声闻善知识：我弟子立群弘法已过七七了，这叫普法七，今天师父给你们做个结七，讲讲群中之规矩。\n'
        '先讲口业，吾所说口业者，悟则无究，不悟则究。所谓口业，乃语言表述自己执见，成断灭佛种相，受累劫地狱重罪报之大过。所谓自己执见，乃成就诸业之本，譬如：有人于大众中指鹿为马，大众即以鹿为马，从此不识马相，令大众断灭马之如是众中种子。于大众中，妄说、诽谤、议论佛法亦复如是。所以，吾令弟子不允有缘分者，不知口业可怕而误遭堕落，大众中之管理者亦受牵连。\n'
        '是故，吾之弟子所设之群，规矩之首，不许乱说种种自己执见，但可谈证得之得，亦可入法问法。\n'
        '善知识，入得佛门道场，当知自己实因有罪，为求福求善报，非为求罪而来，是故，吾令弟子按佛门规矩设法，不令有过。\n'
        '善知识，人身难得，虽汝得，却因狂妄成野火，焚烧灯油刹那去，枉得人身遇佛音。若等堕落再求佛，因果报应不饶人。善知识，切勿群中造口业，吾谛深盼汝等自证佛果，获出离福。谛深2014，12，15日因俗家弟子智依有失语过做结七。',
  ),
  (
    title: '谛深大师开示:佛门弟子如何对待疾病',
    date: '2014.12.13',
    body:
        '坐下弟子，今日我弟子之子发烧，故为汝等讲说如何看待疾病。\n'
        '善知识，病是如何产生的，已有开示，今再为汝等略说之。\n'
        '所谓疾病为业果逆因，实则因缘成就之道也。即，顺逆成缘，以是至果。是故，六道乃苦道。\n'
        '譬如：人于幼儿时，小病一场，立见长；老年人，病一场，差一场，皆如是之者。\n'
        '善者，人于尘世共业因缘，多为传染共相之病。\n'
        '吾之弟子知吾能治病，因吾弟子皈依于吾，即脱诸罪孽缘分，其病自好，或吾于之业做福报缘分令其有转也。若有人不皈依佛，吾不能治其病也，吾亦不为其病做福报缘分转，因其自作自受之罪不知悔。\n'
        '善知识，汝等当精进修行，莫于佛法懈怠，吾必助汝等成道。谛深2014，12，13日。',
  ),
  (
    title: '谛深大师开示:什么是精神',
    date: '2014.12.10',
    body:
        '坐下弟子：所谓精神，乃人道大众，对意识形态之自我考量与分析界定称谓，因自己难于超越自己意识故，于是中虚妄行为成种种体、种种相、种种派。以是成就种种教，谓精神世界。\n'
        '是故我说佛门不是教体，而是实相法体，因慈悲众生须传授大众超脱六道故，设传承法，被大众称之为教。诸佛世尊皆以救度众生，是中之法称为佛法，如是之门称为佛门。而是中有众称为佛教，为妄说称谓。佛门诸多法体，如禅宗、净土、密宗等等皆为相关法体，如是等等。\n'
        '善知识，当如是了解佛法，皈依三宝，勿落邪道。谛深2014，12，10日。',
  ),
  (
    title: '谛深大师开示:什么是物质世界',
    date: '2014.12.10',
    body:
        '坐下弟子及声闻善知识：所谓物质世界，乃人道对识相体之界定称谓，此非虚妄所表，而乃相用之法，是故因汝等住于是法世界故，应当参学。\n'
        '所谓精神脱离物质实乃虚妄之求。\n'
        '善知识，佛法非精神与物质所能考量，佛法乃世界之本，唯佛与佛乃能究尽，一切天人阿修罗所不能知。是故，莫于佛法有诽谤，有他说。当皈依三宝，精进求道，获得大智，出离六道罪苦。谛深2014，12，10日。',
  ),
  (
    title: '谛深大师开示:如何参禅',
    date: '2014.12.10',
    body:
        '坐下弟子及声闻善知识众：如何修行师父已有开示，望汝等能看看。关于参禅，师父也已开示。今天有人以禅机做问，因大多数人都在南辕北辙的错解禅机，是故，今再略做表述，以令有得。\n'
        '善知识，所谓开悟禅机有如下功用：一者，能令参悟者因一门入故，获得舍业，而入清净法；二者，因入清净法，眼前所着障碍便是唯一障道；三者，若于唯一障道放下，清净心立现，若于障道能说道理，则此非开悟禅机。\n'
        '修行，如若汝修习狗子无佛性，去求道理，说明汝还没于本禅机修得入门，所谓入门是汝用心杂乱不获实惠。希望汝能一门深入，入清净定后，放下自得。\n'
        '师父本不应破此禅机，但因汝等于大众群中，有诘问相，故做开示。此禅机以后无用，狗子有佛性也，为其无者，望汝等以此为机，继续参研。2014,12,10',
  ),
  (
    title: '谛深大师开示:于精神世界求道是邪道',
    date: '2014.12.10',
    body:
        '坐下弟子及声闻善知识：寻求精神世界永存、永恒之说，寻求物质世界永恒之说，皆邪道之行、邪道之说。\n'
        '所谓精神世界永存、所谓永生、恒生，乃大众于自己意识不能超越，为求其实之妄想称谓。有人以此称谓为道，为名为利诳骗众生，成大群体，皆因如是大众不遇佛法，或以罪孽狂妄阅读经藏，因愚痴罪孽故，不能解佛所说，便以自己执见假经立传之所成。自己执见立后，因诸多大众皆不能超越自己意识，以是说为真而成拥趸，追大梦幻遭大堕落。\n'
        '善知识，佛法真实不虚，若不皈依佛，于佛坐下受法，非凡夫俗子累劫能知。\n'
        '是故，汝等当皈依三宝，勇猛精进获法助道得大成就。谛深2014年12，10日应弟子问。',
  ),
  (
    title: '谛深大师开示:佛的圣诞是哪天',
    date: '2014.12.9',
    body:
        '坐下弟子，为佛过之圣诞表修道人对佛崇敬，大家都过，日子就吉祥，因为佛是慈悲主、福报主，崇敬佛就是发慈悲心、福报心，大众为此集会就是慈悲会、福报会，所以师父讲日子吉祥！\n'
        '佛之圣诞一般指佛成佛时肉身世时之诞生日，何故是说，因诸佛未成前无始劫皆有生时，所谓吾谛深一日曾吾无数诞，熟知诞过哪一天，今者汝等为吾过，汝亦有过今日诞。阿弥陀佛之圣诞哪天过，师父就说是那天。吉祥日子天天是，汝等可明其中缘。\n'
        '是故善知识，莫以愚痴表佛法执见，当早证佛果，为诸佛所盼。谛深2014，12，9日应弟子智安代群中声闻问。',
  ),
  (
    title: '谛深大师开示:什么是善知识',
    date: '2014.12.9',
    body:
        '所谓善知识，指以慈悲为心，将十方世界全以善法化解之修道者。知识，乃对世界理律解者总称，知识分善知识、恶知识，所谓恶知识，乃对世界以恶为解者。譬如：对如何管理q群，善知识以如何令众获智获福出离苦海为导，而恶知识则以名利、以欺诈、以虚妄为导，目的不是救人，而是表罪孽执见。\n'
        '所谓声闻，乃不于说者前闻法，于道传闻法者。缘觉乃说法者坐下、与眷属受说法者道行与言传者。\n'
        '希望群中修行，多于佛门知见。2014,12,9',
  ),
  (
    title: '谛深大师开示:如何破空',
    date: '2014.12.8',
    body:
        '善知识，世界乃虚妄所化，种种妄心，成种种妄相，以是缠缚造业，成种种因缘果报之体。种种因缘果报，成种种心，种种心又造种种业，又成种种心。\n'
        '所谓法者，乃种种因缘果报之理律，种种因缘果报所成种种心造业成种种因缘果报，再成种种心之理律。\n'
        '所谓世间法，乃如何知业理业律，按其理律依心造业；所谓出世间法，是明种种因缘果报之世间法后，如何舍而出离之法，乃舍弃种种世间法，舍弃种种因缘果报，回归本来实相之法。\n'
        '所谓空者，实则乃依虚妄所立，无有，空不立也。亦即，空亦为妄体。世界本自面目，一切皆无，空无、有无清净本然。是故，无空不有，无有不空，若落空有，难出六道。\n'
        '善知识，若有人，知空有一也，实皆无者，乃累劫修行功德所致，其因缘中，不于一佛两佛种诸善根，已于无量佛所种诸善根。若有人证空有皆无者，乃十地大善果位。\n'
        '善知识，若有人知诸相非相之意者，如来应世，当闻名而往，舍命拜之，归于其坐下，必获出六道，证大果位。善知识，于种种世界，若有如是之圣住世，乃十方罪苦大众之大福。\n'
        '善知识，汝等当精进勇猛修行，归佛坐下，获得出离。谛深2014，12，8日为住道场比丘说。',
  ),
  (
    title: '谛深大师开示:如何选师',
    date: '2014.12.7',
    body:
        '以戒选师，为贯穿选师始终之本，如何以戒选师，不以言说为观，以其戒行为观为正法意，如是，再行缘分选择，为选师第二之要。\n'
        '何者为缘分选择，善知识，入佛门修行，入佛门如出行选择之地，修行如奔目的地之过程，而选择行路工具，即似缘分选择修行良师也。\n'
        '善知识，譬如：行路去往纽约共有多种工具为选，飞机、轮船、汽车、乃至自行车等皆供汝等为选，汝做何选。\n'
        '最佳之具当选飞机，直接到达，若不能选飞机，则可遇海路选船，陆路选车，小路选自行车便能到达。若自行步赴，亦可到达。\n'
        '佛门修行选师亦复如是，佛为最良师，若汝等所住世界之佛涅磐，当下不能为选，则汝等应当以戒为观后，行如下选择：\n'
        '若自己阅藏甚多，理智于法，当选似龙树菩萨等因阅经藏获证者为师，恰如自己于大海之边，选舟而行，有火轮来，何乐不为；\n'
        '若自己习业深重，遇事聪颖过人，当选似百丈等为师，于其坐下，禅修智慧，恰如遇路选车，奔驰最佳；\n'
        '若自己重罪在身，遇事易怒，当选似六祖慧能等为师，于其坐下，苦行禅修，恰如小路不宽，自行车当机也；\n'
        '若自己罪孽深重，遇佛诽谤，当选似莲花生等为师，于其坐下行罪苦燃传，获大救拔，恰如入于荆棘山林，绳索攀爬，终出密地成大果报。\n'
        '善知识，汝等入佛门求道，当于佛制戒下，如是审视自己缘分，求得良师，以助修道。\n'
        '善知识，佛法末世，邪魔外道，利益罪人为求名求利故，不明因果，不怕最惩，口语乱说称佛法施，汝等若着其道，中邪魔缠难有出期。是等，即使说戒只知戒相，不获戒体戒用，是称假戒诳骗，为令汝信。若遇是等罪人，于网络宣传，可观其戒行，一钱不施再行皈依选师。\n'
        '善知识，于佛法末世，如是选师，可获应当善应。谛深2014，12，7日。',
  ),
  (
    title: '谛深大师开示:如何进寺院及佛门禁地拜见师父',
    date: '2014.12.6',
    body:
        '1、向持门师合掌，称阿弥陀佛，师父吉祥。师父：课堂如何走。\n'
        '若入佛门群，当先顶礼三拜主座和尚，然后称：当值师父、或当值护法居士吉祥如意。并称呼自己法名，有法要请。\n'
        '2、到客堂门前，称阿弥陀佛，知客回应后，入课堂先向堂上三拜，再顶礼知客师三拜，起后，男列于知客几前左侧，女列右侧，双手合十问：阿弥陀佛知客师，我欲拜见上某下某法师、或上某下某大和尚。候知客作答。\n'
        '若入佛门网上空间，当称阿弥陀佛当值师父、或当值护法菩萨，我欲向上某下某大和尚或师父请法，请师父代转。并称呼自己法名，三拜上某下某和尚或师父。\n'
        '各位善知识，若入寺院或佛门网络空间当如是做。2014，12，6日公示。',
  ),
  (
    title: '谛深大师开示:莫着空有',
    date: '2014.12.6',
    body:
        '坐下弟子及声闻善知识，所谓空者，乃修道用相说；所谓因果不空者，是修道有证说。\n'
        '何者为用相，譬如：汝等行，路中用器物，车马飞机具，是称为用相。佛门修行人，当明是者意，所谓有证说，譬如：汝行路，路中有荆棘，或者遇有狼，是称有证者。\n'
        '佛于种种经，不说空为证，楞严佛嘱说，性火真空者，性空又真火，为令悟佛性，非说一切空，亦非一切有。佛子文殊道，空生大觉中，如海一呕发，为说空者忌。是故善知识，诸法为有相，因果为依据，一切法空说，因果为何物，实则善知识，世界依空立，空为世界本，一切世间物，虚妄造相耳，非空非有意，说一切法空，因果为不空，实乃凡夫说，不为有证说。\n'
        '诸多罪孽人，以空称学佛，其罪入地狱，难破难知晓。佛于金刚经，说能见佛者，诸相非相见，不说明空见。是故禅宗祖，慧能说坛经，只证罗汉果，于法不能知，乃至少分许。\n'
        '善知识，清净心者：非空、非有、非不空、非不有，等等，若以空有称为佛法，落法相坑难有出期。希望入我门者，精进勇猛修证了意，莫着法相。谛深2014，12，6于即墨应北京弟子智依代群中声闻问。',
  ),
  (
    title: '谛深大师开示:家庭因缘',
    date: '2014.12.6',
    body:
        '坐下弟子众，世间一切皆因缘果报所成，众生因缘果报，若细分，单说果报，可分成过程中因缘果报，与转世时因缘果报。而家庭成就者，乃因缘结处转世果报。其中子女乃因缘至转世时果报生处，所有因缘果报，皆善恶两相相互转换递相成体。是故，称污浊恶世。\n'
        '譬如：汝恨某人，一世积累，终不能却，命终转世，汝之心必入所恨处，成缘分体，成就心生果报，或为儿女，或为家畜等等，令所恨之人受报。\n'
        '汝爱某人，亦复如是，若本世不能成爱，转世必成眷属，因因缘不深故，所续不长。如是恩恩怨怨，不能穷尽。是故，有男女人，见面即爱，成就婚姻，不久即散又恋别处。\n'
        '是故，诸多世间家庭，汝爱子或女，痛至身心，实则，汝欠其债耳。汝恨某儿，其却孝汝，其欠汝债来还也。是故，大千世界，种种家庭无奇不有。皆因缘果报演绎耳。\n'
        '坐下弟子，因缘果报丝毫不差，污浊恶世，不能留恋，当入佛门精进修行，慎勿放逸。 谛深2014，12，6于即墨应北京弟子智依代群中声闻问。',
  ),
  (
    title: '谛深大师开示:如何解戒法',
    date: '2014.12.5',
    body:
        '坐下弟子及声闻善知识:所谓戒法者，为令众生得清净心之护持法，若人不持禁戒说得清净心者，称以臭称香，以有称无。\n'
        '戒律分：苦中得福戒，像居士所受之戒者；出离罪苦戒，像沙弥所受之戒者；修行成道戒，像比丘所受之戒者；慈悲行愿戒，像佛地菩萨与第九层极乐国土大众所受之戒者。\n'
        '而戒相又有诸多修道之因缘果报差别。\n'
        '譬如不杀戒乃令众生摆脱罪孽缠缚之根本戒，不淫戒为令众生脱情愿缠缚之根本戒，如是等等。不食葱蒜，为令大众不招引嗔恨鬼神而不令与邪魔外道共住染污之戒，如是等等。\n'
        '大众当知，佛陀慈悲救度众生，先行导引法，所谓导引法，以戒律为规矩，以戒律为规矩者，分多类多段次，何故要分多类，每类又分多段次，譬如：众生于充满恶兽之罪苦海中受种种苦，其欲脱离罪孽险境，须分多个段次，方能出离。第一，不与毒蛇猛兽纠缠，为第一步，称第一段次；第二，远离毒蛇猛兽，若遇其追逐加速向不明方向之无量远岸边逃离，为第二步，称第二段次；若遇船舶过往，拼命攀爬登船，为第三步，称第三段次；如是等等为初入离苦法类，于是类中分诸多段次，方能逃离苦海。善知识，佛制戒律亦复如是。为令众生出离苦海，先驾驶舟船赴苦海救拔众生，至苦海后，发信息，令大众有备，一者莫于罪孽纠缠，纠缠即如荆棘之藤缠缚众身，因罪孽缠身故，不能登船。以是意故，佛说三藏十二部经典，为令大众知其苦缚，当脱苦缚，如何脱苦缚，称为看破；又设戒律，令发心出离者，脱离罪苦缠缚，登佛驾之渡船，去往无苦彼岸，称为放下修道。\n'
        '是故，坐下弟子，吾之万言，无非令汝等于罪苦海中，狂风暴雨天灾海啸之劫，猛兽恶鬼罗刹干哒出没行恶之释迦末法之时，看到有吾谛深驾船来做末世救应，然后，借释迦如来之说，看破世间罪苦，放下罪苦缠缚，登吾之船而去。\n'
        '善知识，谛深之法，为最后乘，譬如：渡口，一日之内为设三班船驶：清晨风平浪静，为第一班，由释迦驾驶，行人巨多；中午为第二班，由观音驾驶，有风有浪行人适中；傍晚为第三班，地藏驾驶，狂风大作，归途人因狂风暴雨故，亦为巨多。三班船过，即入黑夜，漫漫长夜，无有舟度。\n'
        '坐下弟子，汝等能于佛之末世，问解戒律大事，乃佛法末世，大众福音，当如吾说，行大行力，精进勇猛，出家修道，持佛戒律，出离罪苦。\n'
        '谛深2014，12，5日应弟子代声闻缘觉问。',
  ),
  (
    title: '谛深大师开示:为什么佛法有八万四千修行法门',
    date: '2014.12.5',
    body:
        '有声闻问：唯净土法能于末世救众是正是邪。\n'
        '谛深大师开示如下：\n'
        '坐下弟子，诸佛世尊出现于世，不诳骗大众。所说所有法，皆如是因、如是缘、如是果、如是报、如是本未究竟。所谓本未究竟，是指以其本体缘分，皈依佛陀，能证得佛法。\n'
        '譬如：人之整体，于儿童、青壮年、老年各自受用，毛发、体魄、眼、耳、鼻、舌、身、意皆有所功用，于各个时段，其能虽变，但功依然同。比如眼之功用，年少洞视尘子清晰，年老昏花不视大丁，虽其能力由强变弱，然功用相同。\n'
        '善知识，佛法救度众生之八万四千法门亦复如是。虽今住释迦末法，各法门入于颓废衰败，但其功用依然各自为政，不能相互代替。入佛门者，因种种因缘果报之不同，所应之法亦不相同。总不至于说谤佛法者、地狱恶鬼亦乃大福佛也。是故，善知识，莫于自己法门诽谤余乘。\n'
        '善知识，又如：耳不能见光，眼不能闻风；若于有风，当侧耳识别方能实用，若遇色相，当以眼观之方能实用。若有人以耳代眼、以眼代耳作实用者，实乃妄说于法。虽有传，耳能识字之特异功能，实则，以耳观者，亦乃其眼识功德超800者，能过数等业障之眼用者。\n'
        '善知识，佛法之不同法门亦复如是，虽各法门相互为用，但依不同因缘，不能相互替代。\n'
        '而佛制戒律，并非法门，乃诸法门依止根本，若无戒律，诸法不立。\n'
        '是故，说佛法末世，唯净土救众，实乃盲修瞎练说、邪魔外道说、诽谤诸佛说。\n'
        '善知识，若遇有人以本修法门诽谤余乘，当以是为镜令其有悟。谛深2014，12，5日。',
  ),
  (
    title: '谛深大师开示:什么是供养与布施（第一品）',
    date: '2014.12.4',
    body:
        '坐下弟子及声闻善知识众：\n'
        '供养，是佛为众生修行所设。为令众生出离罪苦，设供养法令其修道出离。所谓供养佛法僧三宝，实则为自己修行功德集成。善知识，譬如：有智慧豪富大慈之父，子孙甚多，为令子孙获得大福，令子孙个个于其寓所，造宝库粮仓学堂武堂，并以父之名存储种种、学习种种。多年之后，其子孙各个智慧第一，财富甚广，幸福平安。善知识，佛说供养亦复如是，看似发心缴纳自己所有，实则：乃自己修行证果之道也；自己修行证道之路也。\n'
        '善知识，供养乃修行根基法，若人不行供养三宝，称修行者，称为瞎马于泥潭求路、盗贼向捕快助、游鱼于火中求游。\n'
        '善知识，若人于六道未斩断尘缘，受传佛制戒律，以居士身、说法身等收受供养，非以持戒比丘而收受供养者，为愚痴之罪孽举；若复有人假佛法名号，收受大众钱财，如盗贼冒名于银行盗取他人财物，集累世恶报直落地狱。\n'
        '善知识，如若有人以假佛法名号者为道，行供养者，恰如人为积累财富入盗贼之家行储藏财物之愚痴做也。\n'
        '善知识，所谓布施，有两种体相，一者，佛门所做化缘布施。指以此为道，令所受者，与佛门结成善缘，成来世种。二者，尘世所做功德布施，指尘世人遇有求者、有难者等，以己之应心之力，予以施予，得来世善报福德。\n'
        '善知识，何为僧宝，持戒比丘称为僧宝。所谓出家，指断绝六道缘分，求证佛之果位之体相。是故，出家比丘以戒为行，不做尘世道行，否则称背因果。若有人欲行供养，当以是为依，方得供养之得。\n'
        '是故，善知识，供养乃集出世间、之功德用相、之道行之法；布施乃积世间诸业、之功德用相、之善报之法。祝各位善知识，多行供养早获出离六道；多行布施得来世福。\n'
        '谛深2014，12，4日。',
  ),
  (
    title: '谛深大师开示:在家居士能否做蒙山施食等',
    date: '2014.12.4',
    body:
        '坐下弟子及声闻善知识大众：关于供养与布施，师父已有开示，不再讲说，而若在家居士，不做供养，却于所住处予鬼神施，所成因缘果报或为善应或为罪应其应不定。\n'
        '善知识，所谓比丘施食者，亦当以己之戒修予做鬼神施法以表慈悲，续佛法缘分，令三恶道大众结佛法缘分。否则，亦会因长久与恶鬼畜牲有罪通应，成自己缘分而落来世种或于身相直接落病。\n'
        '善知识，地狱恶鬼畜牲之道多因罪孽深重故，遭此罪道苦缚，其所应因缘诸多轮转，一时称好间或罪转，若做如是法，以居士身、或不净比丘身为做，易与罪众结种种缘而遭罪缠。若以清净行身、或广聚僧众做法，则能于是缘分有所救拔。\n'
        '善知识，譬如人道大众善法为应，吾谛深以实相意做法布施，尚且有罪重之者， 自恃清高、或以罪孽执见生不信心，行嗔恨诽谤，何况堕落于三恶道之重罪之人。是故，大众于合适机缘，为亡故及堕落大众做经忏布施为慈悲种，能成报身因缘化道启始，应当做，若以自己罪孽因缘，或好奇虚妄作是种事，则必结不定因缘，或善或恶成不定报。\n'
        '善知识，佛法末世，当精进持戒修行，成就大善，出离苦海方具救众根本。切勿自己尚于苦海奔波，却学天人阿修罗救海中食人之鲨，行愚痴事。\n'
        '善知识，比丘为以父母肉身出离六道者，做慈悲施为入法道行，在家居士，不能出家，皆因诸业未尽，不能以水中月为月，是故，身为居士，当发心出离为智者做，莫以在家身行出家事。\n'
        '善知识，更有罪重之者，身为居士不行供养却纳信施，实为堕落之表。\n'
        '善知识，佛法末世，遇佛法甚难，入我谛深法亦难，汝等当发心自行出离，勿未证谓证、未得谓得做愚痴事自求堕落。谛深，2014，12，4应弟子智安代群中声闻问。',
  ),
  (
    title: '谛深大师开示:为什么不许群内募捐',
    date: '2014.12.3',
    body:
        '坐下弟子及声闻善知识，随缘乃佛法慈悲根本之一，所谓随缘，不以任何有依而自所应之，称为随缘。所谓化缘之相乃随缘之一种用相。不于众生中以醒目宣之而求檀越，只于自己行走处，于应当食时，坐于广坪，托钵不语，应者为语言表，后称檀越慈悲，若来者未应即语，即为有罪共业之举。\n'
        '化缘之函乃将大众之布施转成佛法缘分之举，是称化缘。若有人以某种名义，向大众讨要钱财称为化缘，此称有罪之缘，必于其累世集成罪报。若有人遇汝等比丘，发心无求而予，并行礼敬，称为供养。\n'
        '是故，善知识，吾等住世，不于众生有求，亦不关心大众种种相，更随众生自愿而去， 称为随缘。若复有人，罪孽深重，谓欲杀僧令僧从之，此称求恶报，随之即得护法处之。佛之弟子，不与恶鬼畜牲共住，更不履险地，为佛所制戒。\n'
        '是故，善者，于我弟子群中，若有求财者，当立处之，以护佛法。谛深，2014，12，3日。',
  ),
  (
    title: '谛深大师开示:什么是虹光身',
    date: '2014.12.3',
    body:
        '我弟子代群中声闻问： 在微信上看到堪布阿琼仁波切成就虹光身，毛发无存，什么也没留下。请师父开示：虹光身真假正邪？如何成就？阿弥陀佛！\n'
        '坐下弟子及声闻善知识，佛法修行人之佛地成就有三种：一者，三身，所谓清净法身、圆满报身、千百亿化身；二者，二身；三者，一身之成就。于是三种成就中，又有诸多成就相。\n'
        '善知识，另有诸多不同果位之中小成就者，按所修道别，分为四、六、九等分系再化若干种果证。\n'
        '其中唯有破识心者，可显放光明瑞相，所谓破识心修道以光明瑞示寂，一者，其于临命终于自己心中显光明相为初果证，是时其自己之因缘大众依因缘深浅各自有应；二者，化尽自己因地因缘令其破识心者能于灭时直接化灭不留毫发，而于是成就者知其名者，乃至每一少许因缘者，皆能直接获光明照耀，其各个自己亦能光明化灭。是称佛之三身成就瑞相之一，破识心放大光明相。\n'
        '善知识，另有诸多成就果位者，无放光明相亦为成就。佛法末世，诸多门派不知如何变用识心，已不具直接放大光明普照世间因缘，有能显瑞者，亦为天龙八部护持所显，其自身业体因不舍世间因缘故，不持佛戒不能放光显瑞。所谓微信传虹化者，不一定是大果位证。如若有疑，可送鉴定。吾父去世放大光明瑞相，乃因吾之加持所显，为所应瑞相，其仅获初果罗汉，吾为令在场僧众生信故，令现此瑞，汝等可送各权威机构检证。\n'
        '善知识，佛法修道，若不断杀，食众生肉，即使知识心变化，也不能示现光明，除非已于累世因不染世间业故，乘愿再来。谛深2014，12，3日应弟子代群中声闻问。',
  ),
  (
    title: '谛深大师开示:如何助念',
    date: '2014.12.2',
    body:
        '坐下弟子及声闻善知识众：今晚吾弟子代群中善者问：若人命终，人群助念与用录音器助念，其功用是否相同，若不同有何区别。\n'
        '善知识，以是善事问吾谛深，吾为汝等于释迦佛法末世，诸法几乎破灭仅存名相，发如是心拯救广众表赞叹，当为汝等讲说缘分共业度众法道。\n'
        '善知识，所谓命终助念，实则为缘分度众之法。所谓缘分度众，乃佛法不度无缘之人之一法表。\n'
        '临终助念分为：最上助念、中等助念、下等助念三大类别。\n'
        '何者最上助念，若有人行将命终，其清醒如初，自知命之将终，尚有挂碍之罪。其所挂碍之根，无非妻子儿女父母兄弟姐妹。所谓根者，为人们尽管有事挂，大都因涉及如上亲属而成挂碍。虽有人挂碍国事、或大众事，但临命终难成挂碍根本，即使有，亦不离亲属之根。\n'
        '是故善知识，若人临命终，亲属早将其挂碍之事，除掉告知，并称念佛号与之已获放下心应为最上助念。何故是说，因随着其六识渐去，五蕴不用，汝等亲属及因缘僧众与其业缘随是等用心，眼耳鼻舌身意直接共应，其临终转世缘分于此时结成成上上善结，直接与弥陀四十八愿成生处因，弥陀显前，于弥陀加持中，其因缘化所住因缘果报成圆通体，圆通体绽，生成当得宝莲，入极乐国。是称上等助念。\n'
        '何为中等助念，命终之人，于命终之时，尚有牵挂不能去除，虽口念佛号心住所牵，大众助念佛号随其六识渐渐离去，其六识会随佛号善助奔所牵挂业体，成七识种子于八识种下，在种种因缘果报中，遇因缘投胎发芽成来世报。因其于命终有善助念成佛法因缘，其转世生命会入佛门修行，成来世缘分。是称中等助念。\n'
        '所谓下等助念，若有人命终之时，其业不喜好善，闻佛即嗔，则于其六识成互缚体，来世其或以人、或以鬼、或以畜牲等身入佛门成有罪体相于佛门承事等。是称下等助念。\n'
        '另有种种助念无助念功用，如人死后识心已去，耳根不用等。\n'
        '若复有人，以助念器助念，因其无因缘所牵，不成加持心应，只于命终者命终前耳根成染，有少许用，且不定为善。死后助念器助念耳根难接获更少许用，其用有善或嗔，再于死后多时，则无用，只有亲属因助念器所感，有缘分用。如是等等。\n'
        '善知识，多于所知临终者命终之前，往去以我说法助念，令其无牵无挂，在汝等慈悲心感召下，其必得善去，上品上生，中品中生，下品下生于极乐，或即使不能去其牵挂，也必定令其善去定处，有佛法善缘与之相应。\n'
        '善知识，祝汝等多于末法行此善事，慈悲众生。\n'
        '谛深2014，12，2日晚应弟子智安代群中声闻问',
  ),
  (
    title: '谛深大师开示:什么是识与见',
    date: '2014.11.30',
    body:
        '坐下弟子，所谓识者，乃诸业所成之，所做诸业之同异分别因缘果报属性，亦即：不同之业具不同识心。\n'
        '善知识，所谓见者，乃识心对所遇诸业之所业分别反应。不同识心对同一种业有不同之反应，称之为不同知见。\n'
        '譬如：屎克郞认屎为食，而人却以米等为食，乃屎克郞因累世愚痴因缘故，诽谤善法成罪孽业，成如是识心。\n'
        '是故，善知识，知见乃自己业识对事物之反应，不同识心对同一事物有不同知见，而不同事物亦可能在不同识心中成同一反应谓同一知见。\n'
        '善知识，莫于佛法以自己心量做知见妄说，当皈依佛方能得证。谛深2014，11，30日应弟子问。',
  ),
  (
    title: '谛深大师开示:什么是正法？（第二品）',
    date: '2014.11.29',
    body:
        '坐下弟子及声闻善知识，所谓正法道是指当机法，所谓当机者乃令众生闻当机、学当机、用当机、修当机、行当机至离苦当机、证道当机等。\n'
        '善知识，譬如：煮饭，燃火若不当机，汝燃柴不在，柴在汝不燃，若有人燃火成饭汝亦燃火却不成饭，称为不当机者；譬如煮饭，须得有米，将米入锅，以火煮之，是成其饭，汝虽有米却将之置于水槽，于槽边烛火，是称不当机者；如是等等虽以耳闻，米、火、锅皆具却因不当机者不能成饭者，称为其不正，错解妄说妄议者称邪魔外道。\n'
        '是故善知识，所谓正法道是指佛门中，当机之法用。而不当机者，称为不正法。曲解佛法者，称为邪道说。善者，当如是于佛法海中，修证了意诸佛所说。谛深2014，11，29日3时应智安代群中声闻问。',
  ),
  (
    title: '谛深大师开示:如何念佛(第七品）',
    date: '2014.11.29',
    body:
        '坐下弟子及声闻善知识，念佛为佛法首要，分多种念，师父已有开示，是故于是品不再为说。今者说如何念佛，为令不明净土之道者再说。\n'
        '善知识，念佛有道，譬如：有人于堂上教书，此时不能大声称念佛号，若念即遭人愤被执法者遣返；又如有人于禅坐时口称佛号，亦为有罪，如是等等称念佛不入法。\n'
        '善知识，佛法最上之念为无时不念无有一刹那间或，实口不称佛号。譬如：禅坐，实为无间或念佛，如是等等为最上念。而虽于口中常称佛号，却不断思东思西，是称下品念佛。若复有人，自念佛号，却嗔恨别人，是称罪念。\n'
        '善知识，当如是知见念佛之法。祝善知识精进念佛，往去极乐修证佛法。谛深2014，11，29日。',
  ),
  (
    title: '谛深大师开示:什么是丛林',
    date: '2014.11.28',
    body:
        '坐下弟子及声闻大众：\n'
        '众生之类因缘有别，是故修行有别。\n'
        '所谓别者乃种种业、种种罪、种种知、种种见、种种法、种种非法，成种种心，又成种种法，又成种种见，种种知、种种道如是等等，成就种种业、种种罪等等，如是成就种种差别，所谓道差别、修差别、行差别，乃至业报虽大同，而微细差别不同等等。\n'
        '善知识，修行者因种种差别如同大千之草丛，之树林等，是故称之丛林。\n'
        '是故，佛法末世，诸德已去，谛深立门，广纳大众，后分宗派，各行其道，终归一门，令其成就。\n'
        '是故善知识，入我门者，不分宗派，但禁戒为本，各自修道；是故入我门者，虽不分宗派却以分别法，不许相互论法，不许以自己所得为辩，若辩者，视为重罪，逐出师门；是故，入我门者，说自己法者，称为断大众缘分，令其闭关。\n'
        '善知识，能于释迦牟尼佛之末法，于我坐下听法修行，乃我谛深累劫缘分，吾视为珍宝，必倾本世命缘为汝等助道，令汝等有应当证，获各自果位。祝来者精进勇猛早证佛果，以如是之证，慈悲宣示未来大众。 谛深2014，11，28日。',
  ),
  (
    title: '谛深大师开示:一定不要作恶',
    date: '2014.11.27',
    body:
        '有人于今日（2014，11，27日）问：我不知道前世，亦不知道后世，也就是说，前世不是我，后世也不是我，我这世不管做了什么恶事无所谓，死后一把火烧了，哪怕是为了狗我也不知道了！我才不怕那！\n'
        '师父开示如下：\n'
        '坐下弟子及声闻善知识众，因缘果报分毫不差。譬如：汝种之小麦有坏，其麦磨成面亦必有坏，其面做成饼亦必有坏，虽麦与面、面与饼互不相识，其坏不除如是轮转受报。\n'
        '善知识，众生六道轮回亦复如是。汝今者作恶成下世恶因，死后转于下世报体，善有善果，恶有恶应，前后两世，若无学佛修行缘分则不能互识，但因缘果报分毫不差。是故，汝等生做人身，福报有别，皆如是因、如是缘、如是果所造就。如是地狱恶鬼畜牲随其所赢，无不成体。我谛深所获果报，乃累劫所造，非一日之因。我兄因前世住于寺院，以住持身于我行脚到时，我慢应待，成本世诸多苦因遭诸多苦，成堕落不能救相。\n'
        '善知识，若人不知因果，必做种种大业而不自悔，是故，必落地狱恶鬼畜牲，受大罪苦。\n'
        '善知识，不知因果者，为大愚痴。若遇人不信因果，当以是为导，令其脱罪。\n'
        '谛深2014，11，27晚应弟子问。',
  ),
  (
    title: '谛深大师开示:僧人与居士如何求谛深大师加持',
    date: '2014.11.26',
    body:
        '若非菩萨戒居士求加持前须斋戒三日，斋戒后于堂上挂清净法身毗卢遮那佛像，像前檀台供香灯、香炉、净水宝，并奉鲜花。若菩萨戒居士求加持须诵戒候如上说设做；若僧人求加持，须于月一、十五布萨后，于大雄宝殿做。\n'
        '加持法当于夜中不语，燃香洒净水后，堂前顶礼三拜，后称南无清净法身毗卢遮那佛、圆满报身卢舍那佛，挲婆世界应法教主释迦牟尼佛，再行三拜。起后三称南无燃灯台上谛深大师，并跪一香时，即获师父灌顶加持。2014.11.26',
  ),
  (
    title: '谛深大师开示:什么是舍利子？',
    date: '2014.11.23',
    body:
        '坐下弟子及声闻善知识：\n'
        '所谓舍利子乃佛法修道因缘住相，有三种性：1、有佛法住，其相可随因缘成多变化性，其可随来者因缘显不同光明；2、佛法传承时，显入承道人身相，能于传承者显入而出、出而入等相；3、 佛法坏时显坚不可摧性，能于佛法末世坚固住留至佛法灭度，而佛法灭时则显光化相，化光而去。\n'
        '佛法末世，诸多重罪之者，假称出家，不持佛戒，做地狱重罪，得重病死后，以玛瑙等物随罪体烧结称舍利子，实则为断灭大众信心而做。何故是说，是种罪为：先于道场以出家身，不持禁戒令众谤僧，后于尘世以僧相吃喝嫖赌坏僧宝传承，重罪获病后，疼痛难忍亦不罢休，死后用物假做舍利子，令佛之舍利子传承因假而坏，断灭佛传，自落地狱受不救罪苦。\n'
        '是故善知识，当尊佛所说，以戒为师，精进勇猛获种种证以传佛法。\n'
        '谛深2014，11，23日应问。',
  ),
  (
    title: '谛深大师开示:如何看待佛门人的病',
    date: '2014.11.23',
    body:
        '坐下弟子及声闻善知识：所谓病者，乃六道众生罪苦之重表，师父讲过什么是病。今者因有所谓之出家人重病亡故，引起争论，故为坐下弟子做因缘果报释疑。\n'
        '善知识，所有病皆逆因逆缘逆报，若佛门人甚至被大众认为之高僧大德有病，依次为：1、小病为于佛法无有彻证，或于戒有漏；2、久疾难医，为于佛法无有证得一说，或于戒难持；3、若遇重病缠身，则其于佛法有诽谤重罪；若是人重病而亡，则其因假佛法以诳骗众生故，成污佛断种堕地狱不能救罪，直落地狱。\n'
        '善知识，佛法殊胜，修道途中，之所称途，因有罪有业，须步步持戒修却，有病实乃平常之事。最终若能于戒清净，或于佛法有证，其病自却，若能开悟者，则如明破暗直灭所有病因，并能加持弟子及缘分大众无病无灾或少病少灾。若有人假种种法，打造成名之名僧名知识等，实则于佛法不信、或少有信，不信因果、不持禁戒，称为重罪之邪师，必重病或横死而亡。\n'
        '善知识，当精进修行，获证佛法，出离苦海。谛深2014，11，23为罪重者说。',
  ),
  (
    title: '谛深大师开示:梁武帝之报',
    date: '2014.11.23',
    body:
        '坐下弟子及善知识众：汝等问是事，当为汝等说，释法入震旦，已为相法时，所谓佛相法，实则无佛住，只以戒脉传，所谓戒脉者，戒为法根本，经典为法表，若无戒之依，诸经不能立。善者汝当知，譬如有大海，佛住如大船，行于春夏季，海中罪苦众，归佛能得救，称之为正法。佛灭之后法，说经以救众，恰似严冬冰，若于冰上住，不知何为路，认冰为大地，楼宇广厦等，皆应世筑造，有佛来应时，认者不贪恋，己之之广厦，虽之己不悟，却有冰之验，发心随佛去，亦能获救之。有众不认之，遇到来春时，冰融皆落水，是称相法时。落水之广众，一时不舍冰，认冰为能住，只是妄中求，佛设一渡船，来救于大众，船与冰有异，大众以冰较，不信佛所说，舍船求冰块，于是舍救拔，是称末法时。\n'
        '各位善知识，如是做譬如，谛深告之与，阅藏之大众，莫以经为依，判断佛说事，当以戒为依，能以清净法，得见于如来。善知识当知，谛深警告汝，佛法不思意，思意乃邪道，既思意乃邪，如何入佛法。善种应知晓，若要入佛法，须当皈依佛，汝之不识佛，如何能皈依，恰似盲人国，不识佛之面，只于佛像前，行做皈依事，实则未皈依。若未归佛者，所做所有事，皆为业中用，不能见如来，所谓其功德，亦复如是之，乃罪孽之为事。更若不皈佛，汝等之所做，实则为盲修。\n'
        '善者应当知，梁武帝亦是，实则未归佛，若其归于佛，不称梁武帝。其乃狂心用，以帝为号令，僧道皈依其，是称大罪孽，累世有罪因，所做相佛法，实则成业果，是故受其报。谛深告汝等，今者建庙者，亦复如是德，其等狂妄心，不敬重于我，自己称功德，其报当为业，于佛法无关。汝等问是者，不于佛殿堂，沐香跪请法，狂思是等诘，有狂妄罪报，当于住用处，忏悔自己痴，报时悔之晚。\n'
        '善知识，若遇有人以历史罪人功德为依，为难于汝等，做如是应。\n'
        '谛深2014，11，23晚应弟子智依代罪重者问。',
  ),
  (
    title: '谛深大师开示:什么是愿与愿力？',
    date: '2014.11.22',
    body:
        '坐下弟子及声闻善知识众：\n'
        '诸佛菩萨愿力，乃道行境界实相，是故应当学。\n'
        '何为愿力？善知识，所谓愿者，凡夫之愿，乃众生因因缘所致，由理或贪求而之目标希寄所成体相；所谓诸佛之愿，乃境界显前，布施慈悲之体相，譬如：有人发现自家池塘水族众多，便用心规划如何让是等众得到关怀。佛之愿力乃道中证得十方众生皆其圆满自性所生，众生因贪着种种故，妄做诸业受大罪苦，是故慈悲心起，生诸大救众之规划，称之发愿，因其规划依种中道法，是故有大力为，称为愿力。\n'
        '善知识，发愿按体分为：1、境界愿，2、虚妄愿，3、目的愿。按相分为：1、佛法慈悲愿，2、世间共业愿。按用分为：1、布施愿，2，慈悲愿，3、共业愿，4、福业愿，5、罪业愿等。其每种愿之用相，又依因缘分为多种。\n'
        '善知识，若无佛法证得，清净境界证得，发诸有愿属虚妄愿，不能获得发愿之成力，只能成转世妄缘，成不定报体，于是体中获佛慈悲，再生信心入佛法脉，修行获救，若不获信心，则成堕落。 是故善知识，所谓行愿，分为：令众出离与令众堕落之为。若不开悟，又无开悟师承，行诸愿者，实为作业。\n'
        '善知识，持佛禁戒，精进修行，证得佛法，方能得愿、获得愿力。若有人不证佛法而行愿称为造业。谛深2014，11，22日应弟子智依问。',
  ),
  (
    title: '谛深大师开示:什么是罪',
    date: '2014.10.31',
    body:
        '坐下弟子及声闻众：\n'
        '1、罪苦之体相\n'
        '所谓罪苦者，有多种因缘道界体相，大说有地狱恶鬼畜牲重罪之道，天人阿修罗之轻罪之道。而各个道界又有各种受罪之道。\n'
        '善知识，人道乃与地狱恶鬼畜牲相邻相杂之三善道之一，不同知人群、国别苦乐亦有差别，但大相基本于界一样。其中主要基于所受罪苦5分苦，5分乐之因缘道应，或次第少之、之6到8分苦乐间或轮转之因缘道应。\n'
        '天道为福报道，不同天道，有不同因缘福分。其中次第8到9分乐分，次第2到1分因缘苦分等等。\n'
        '譬如：人道之种种事，大都适应二分道，即辩证法。像工作之者，无工作苦，有工作乐，工作太累苦，无工作太闲亦为苦者；此称苦乐间或转换。\n'
        '是故，佛法于人道易于弘扬，因人道苦时思救，乐时知恩也。\n'
        '是故，观音、地藏贤圣于南阎浮提救苦救难、消灾消业广为人拜求也。\n'
        '2、罪苦之内涵\n'
        '什么是罪苦，所谓罪苦者，内涵唯一，因缘业果之逆因，逆缘，逆果，逆报称为罪苦。\n'
        '善知识，譬如：疼痛乃体相因缘之逆因之报显，而若顺因则为乐也。是种罪苦体相，乃因缘果报之人道间或苦乐，地狱恶鬼畜牲则少之有乐耳。\n'
        '是故，善知识，诸佛世尊皆开示大众，莫于因果背少分。大势因果，微尘因果皆勿为做，否则，罪苦自做自受耳。因无论众生如何做，终归于因缘果报中，有逆之者。何故是说，因缘即是顺逆之成，若无顺逆不成因缘耳，是故者也。\n'
        '是故，佛教弟子恒顺众生，为令汝等不背因果，不受罪苦。所谓恒顺众生，实则，出离因缘果报乃能恒顺者。若不出离因缘果报，恰如：遇有恶狼欲食之汝，汝是顺之不顺，顺之即遭杀，不顺它遭杀，成恶杀因果必背矣。\n'
        '是故，诸佛所说，不令弟子履险之戒，为令不涉恶缘恒顺众生者。是故所谓佛说恒顺乃不沾其因，由它去也。\n'
        '善知识，当如是明罪苦，放下诸业，发心出离。谛深2014，10，31。',
  ),
  (
    title: '谛深大师开示:心得与执见之别',
    date: '2014.10.29',
    body:
        '坐下弟子及声闻善知识：所谓学佛心得，获清净心者之得处称为心得，获清净心后之所谓见者乃清净观现，因慈悲故说与缘分，令其有悟，并非执见。\n'
        '所谓执见者，乃众生因识心不同，于所阅经书与咒子之解，是称众生心得，亦称众生罪孽执见。是故，阅藏者若不持禁戒即落魔道。何故是说，譬如屎克郞，以自己心解饭食之说，粪即是其饭食，而人之饭食佳肴，则并非其饭食，其如是见解诽谤人之饭食非饭食者，说之有理有据，无有过错。因其为屎克郞也，因其累劫难做人也。罪孽之众引佛说经典，诽谤佛制戒律，诽谤诸多善法，亦复如是。因其罪孽执见故，假佛经典诽谤佛法，诽谤戒律，恰如屎克郞假人说饭食，诽谤人之菜肴一样。其以不持戒律，杀盗淫妄称为佛法，处处兴咒，毁灭佛传，令大众损伤福报，受其享用，恰如其食粪耳。\n'
        '善知识，佛法末世如是罪众兴出于世，断灭别人修道佛种。君不闻有藏密邪道于台湾诳骗女众施淫遭法禁乎？何故藏密罪众诽谤于我，皆因佛戒明镜显其妖相耳。\n'
        '是故，善知识，于佛法末世能持佛之一戒即很难得。若遇有藏密罪众诽谤佛戒，当以是为应。谛深2014，10，29应弟子代声闻问。',
  ),
  (
    title: '谛深大师开示:什么是密法',
    date: '2014.10.29',
    body:
        '坐下弟子及声闻善知识：所谓密法者，乃佛法因难思难解故于大缘分信心者设传。其所传之人皆累世缘分所致。佛制密乘，戒律护法，起初不设戒，如念佛者，起初不持戒，入门须持戒一样。密修之始无需持戒，层层加持戒律为乘。\n'
        '善知识， 由于密法不能为凡夫所解故，秘密传法之中，容易为邪魔外道利用，而不易被破。\n'
        '譬如：于羊群，主者欲救之，设法于秘密，周边设看护，群狼难乘机，有狼披羊皮，混于羊之群，以是灭密道，断灭救羊法。佛之秘密法，如是遭魔坏。\n'
        '因佛之密法不能外宣故，诸多邪道混于密法之中，如于黑夜行罪孽事，难于揭露，传播邪道。\n'
        '善知识，佛法秘密门，戒律最为严，说密不持戒，其必邪道人。\n'
        '善知识，若遇人以密法说，毁坏佛制戒律，当如是应之。谛深2014，10，29应弟子代声闻问。',
  ),
  (
    title: '谛深大师开示:如何求皈依',
    date: '2014.10.28',
    body:
        '坐下弟子及声闻善知识：入佛门修行者，先行三皈依。所谓皈依佛、皈依法、皈依僧。\n'
        '一、皈依佛者：\n'
        '1、指有佛住世以佛为师为父，皈依者即是佛的，如同佛之儿子，称佛子，是称为皈。佛怎么说，皈依者怎么听，如说去做，是称为依。\n'
        '2、现前无佛以戒为师为父，皈依者一切以戒为依，戒怎么说，皈依者即怎么做，是称佛传承子，亦称佛子。皈依佛后，于佛口中，或于戒相中，获得清净心，并于佛说境界，以清净心得之种种证，因种种证故，得佛眼、法眼、布施众生之道眼，并获种种智，称为开悟。\n'
        '是故，若有人未得见如来，亦未得戒传，以种种说教称佛门人，实为妄称，若以其为师，即着邪道。\n'
        '二、皈依法者\n'
        '1、如佛说修行，为皈依法，如戒说修行，为皈依法。\n'
        '2、洗净心地，无思无解，只是因信而受，诵经诵咒获佛说种种机缘境、机缘导、机缘解、机缘证，称为阅藏。阅藏证后，称为理悟。于佛说经典有当机用者，称为智。\n'
        '若有人于佛说经典有解、有说，为愚痴表，即为邪道。\n'
        '三、皈依僧者\n'
        '所谓僧者，为佛之化身或应身表，所谓如来三身者，化身即为开悟大德，高僧也。所谓如来应身者，于戒清净者称为如来应身僧。而受戒比丘等，为道行僧，亦可为师。\n'
        '皈依僧者有三，一者皈依高僧，直入如来坐下为教；二者皈依应身僧，可以其为范，获得道体；三者皈依道行僧，可以其为导，获得修行因缘。\n'
        '若不能皈依以上三等僧人者，即为落于旁修。落旁修者有多种报，最上乘，来世入佛门报；中乘落邪魔外道报，因是邪魔外道报尽沉沦恶鬼畜牲；下乘直接损本世福报，死后堕落地狱恶鬼畜牲。\n'
        '是故，求皈依者当知，因汝等无法鉴故，无辨别选择明师之力，以戒律选师为最完全之做。坐下弟子及声闻善知识众，当以戒选师皈依为诸佛世尊所嘱。谛深2014，10，28应弟子代声闻众问。',
  ),
  (
    title: '谛深大师开示:什么是佛道',
    date: '2014.10.28',
    body:
        '坐下弟子及声闻善知识：\n'
        '所谓道者，乃种种理律之定义。譬如：科学乃挲婆世界世间器、世间物道与寻道之表证。法界种种物皆有生灭处、皆有种种物相道则理律，亦有精神道则理律，以佛眼观之通称世间法。是故，所谓世间法，为物质体相之道与精神体相之道也。是等世间法道，若以凡夫心应，无中生有，生灭无常，无始无终，无穷无尽，随凡夫之众生心，应所知量，为佛予之定义。\n'
        '何者佛道，善知识，所谓佛道乃圆满彻悟之理律者，非以凡夫之能，能少分知之。善知识，谛深今略说，切勿兴诽谤，汝等当精进，皈依佛坐下。诸佛不虚狂，若说佛法道，十方之世界，所有含灵王，天人阿修罗，鬼神与等等，不能于佛法，知之有少分，其所知之法，若称为佛法，实则堕大坑。\n'
        '坐下弟子众，佛法不思意，思意落邪道，佛道之体相，若以众生心，难知难决了。吾今告之汝，如是之体相，如是之因缘，如是之果报，如是之本末，如是之究竟，若有人诽谤，于其罪孽见，其罪无有边，谤佛之罪众，谛深劝汝等，佛不欠汝债，亦不索汝物，更不索汝见，何故兴诽谤，汝己之过也，是罪不见佛，汝等无有救。\n'
        '坐下弟子及声闻善知识，所谓佛道，一切文字语言所不能表，吾今以断灭文字语言告知汝等，汝等勿以狂心求成佛之道，当皈依佛，精进勇猛修行，种佛之大种，成就佛道。谛深2014，10，28。',
  ),
  (
    title: '谛深大师开示:如何报父母恩',
    date: '2014.10.27',
    body:
        '坐下弟子及声闻众：五浊恶世，生死轮回场中，父母生身，恩重难报，汝等能以是问者，乃知恩寻报之善，当为汝等说之。\n'
        '善知识，譬如：有人与父母掉于大海之中行将沉没，时，鲨鱼猛兽，夜叉恶趣，亦随即伤之，若其同舟共济者，即同死于大海，此为愚痴之举。如若其拼命护母，与恶鬼畜牲搏斗，教法父母不能沉沦称为有道之举，其若见有舟，自己先行出离苦海，迅即以舟上救生物能令父母出离苦海称为智慧之举。\n'
        '善知识，报父母恩者，恰如苦海寻道。五浊恶世生死场中，无上报恩之道，乃先寻舟用，并呼之求救，自己精进勇猛奔舟出离，再令父母精进勇猛出离为最。如若父母难度不听善劝，汝等自己先行修道出离，后再以成道大力救父母为上等报恩之道。\n'
        '善知识，佛法难遇今日遇，切勿于海自奔波，汝等勇猛精进于海舟之隔路，为累世父母希望之托，切勿放逸。谛深2014，10，27应弟子代声闻问。',
  ),
  (
    title: '谛深大师开示:菩萨与邪魔外道的区别',
    date: '2014.10.26',
    body:
        '有弟子问：XX说是法界菩萨皆是邪魔外道，师父笑了笑，开示如下：\n'
        '坐下弟子及声闻善知识众：\n'
        '所谓佛住世，乃清净法身所含、圆满报身所摄、千百亿化身所应之妙湛总持之如来、应供、证遍知、明行足；善逝世间解，调御丈夫之佛世尊。\n'
        '所谓菩萨乃诸佛世尊坐下所皈依佛后，于佛制戒律中，依佛所说，修行觉悟直至成佛者的总称；所谓邪魔外道乃所有修行人中因不解佛所说意之以种种法、种种道、种种心、种种用为依，于六道之中种种因缘果报之总称。持佛制戒律之修行者，称为善知识；不持佛制戒律之修行者称恶知识。善知识之王称十地菩萨与法王，恶知识之王称魔王或亦称法王等。\n'
        '邪魔外道共分为两大部，一部来自佛法加持，一部来自世间法道。来自佛法加持之部，会因不皈依佛与戒、不持佛戒而不证佛说法意，最后，证得：种种世间道法而成大诽谤、大道障之波旬王。而来自世间法道一部则成种种法之种种化身王，又称外道典集。\n'
        '是故，菩萨与邪魔外道之区别根本是：是否持佛制戒律。\n'
        '坐下弟子与声闻善知识，若遇邪道诽谤佛法与菩萨，当如是善解。谛深2014，10，26日午应弟子为群中声闻问。',
  ),
  (
    title: '谛深大师开示:为什么要持戒',
    date: '2014.10.23',
    body:
        '坐下弟子，佛之禁戒乃六道众生修出离法之本，是故乃佛法之本，若不持禁戒称佛门人如指鹿为马。\n'
        '若不持禁戒能成佛者，佛何须说戒，并以戒法为佛法传承。\n'
        '若不持戒，身着所谓佛之戒衣，或穿僧衣，或讲经说法者，为波旬使。\n'
        '坐下弟子，若不持佛之禁戒，说能念佛往生弥陀极乐者，亦为痴人说梦。\n'
        '是故，比丘，比丘尼，优婆赛，优婆姨，若不持禁戒不令入我谛深道场之门，。2014，10，23。',
  ),
  (
    title: '谛深大师开示:什么是议论佛法',
    date: '2014.10.22',
    body:
        '坐下弟子，所谓议论者，顾名思义，乃不明佛法实意，各持执见，或相互支持、或相互排斥所解法义，或各自表证自己所解之义，是等名为议论佛法。\n'
        '所谓议论者，皆不获佛法真实意之为，是等皆表堕落相。\n'
        '所谓议论佛法堕落处有三：一者，有人累世所种之佛种因缺导师缘分者，成邪魔道。譬如甘唯果需嫁接方成甘唯果，然种子发芽成体前，却无人予以嫁接，令其自行长成便是臭油果。有议论佛法者亦复如是，其本自缘分有暇眦，须有自己缘分善知识导引方能证果，否则，则成邪道。\n'
        '二者，堕落成外道典集，……此段因只对坐下全戒弟子讲故略。\n'
        '三者，成诽谤佛法罪。议论者，若不能令对方称服，则于对方生诽谤嗔恨心，因对方执佛法自己执见故，是等诽谤嗔恨，佛法为因。是故是等诽谤嗔恨在其转世缘分中最终成谤佛体而成诽谤佛法罪。\n'
        '是故善知识，不议论佛法乃佛法修行之要。切勿以自己执见议论佛所说法。谛深不与罪重讲经，只与求法者说，是以不议论佛所说法故。谛深2014，10，22应弟子智依为群中声闻问。',
  ),
  (
    title: '谛深大师开示:为什么有人谤师谤戒',
    date: '2014.10.22',
    body:
        '坐下弟子及声闻善知识，譬如有美人赠奇丑之人照妖镜，其必被骂与诽谤，其亦必被丑人于坊间传谤。\n'
        '谛深所说与佛之戒律亦复如是。邪魔外道因罪孽之为故，于我所说法前必露罪孽之行，于佛所说戒前必不能存。\n'
        '我之弟子皈依于我持戒修行，获证佛法，于我所说事、佛之戒律前恰如美人照镜，知己之美中不足之处故更精进，将不足处修却。而邪魔外道则如丑陋之者，因照妖镜显其丑陋故，必口有罡骂摔镜而去。\n'
        '何故邪魔外道丑陋之人却为一些人赞美，因诸多众生自己执见障碍故，如同瞎子听丑人说美，于是赞美其无比美也。今者诸多因自己执见障碍，不能见魔，亦不能见如来众，持我所予之佛戒良药，必获去除执见障碍得见如来实相，明邪魔外道罪。是等如盲人眼疾得治重见光明，观之丑人必唾之而去之耳。\n'
        '是故，有诸多妄说佛法之罪孽众，因有人赞美供养故，诽谤于我，诽谤楞严，诽谤佛戒，赞杀盗淫等。\n'
        '善知识，于我所说法，持佛戒律，终将开悟，得见如来诸佛世尊。\n'
        '善知识，若现前不能出离六道，兴于出家，于佛坐下修道，当意诸佛世尊因地勇猛精进之为，于未来世，必于当机缘分获得出离，于佛坐下修证佛果。\n'
        '谛深，2014，10，22于药师佛圣诞应弟子智依代群中声闻释疑。',
  ),
  (
    title: '谛深大师开示:什么是功德，什么是福德',
    date: '2014.10.22',
    body:
        '坐下弟子及声闻善知识，金刚经云，所谓佛说功德，以功德无故，佛说是功德多。佛何故如是说之，因所谓功德，实则为业缘根本，何故为业缘根本，因众生赞叹而称业缘根本。何故众生赞叹，为业缘根本，因众生本自诸业所生，攀缘心相，其所有执见皆为业思、业想、业应之思、业应之想所成之。是故，佛说不住相布施称功德多，佛说功德无故，称功德多等。\n'
        '所谓福德，以众生因修道故，得之业报之相。譬如：科学发展之道，能令罪孽众生获共业福，行路有车船飞机，种地有农业机械，等是中罪孽众生皆可享之福报，科学发展称为修科学之福德。佛法福德亦复如是。若人皈依佛法僧持佛禁戒，其业中、罪孽之中能因修道故获大福德。譬如我谛深弟子，皆因皈依我后持佛禁戒，直获大福报。\n'
        '善知识，佛法末世诸多罪孽深重之人，为获尘世福报，妄说功德，假佛说经书，欺蒙善众，以种种失佛本意之众生共业执见解，断灭佛法，并长称佛不说自己是佛等罪孽兴诽谤，屏蔽佛之住世，以令自己罪孽欺蒙，因众不能证佛法故，难显邪魔外道之原型，如是灭佛。是等罪众，必于我谛深法兴大诽谤而直落地狱果报。是故，坐下弟子及善知识，汝等更须严净毗尼，精进勇猛修行，早证释迦佛所说，以脱释迦佛法末世诸魔之缠。\n'
        '善知识，是日已过，命亦随减，道命得之不易，只要汝等能持佛之禁戒，必证佛所说法。\n'
        '谛深2014，10，22。',
  ),
  (
    title: '谛深大师开示:谛深大师给群中修行们的开示',
    date: '2014.10.21',
    body:
        '坐下弟子：\n'
        '修行之道，各有缘分，因各自缘分知见，有各自所处修行境地。之于尘世功德福报，亦然，是称为道命，天命。\n'
        '而于佛法当知，诸佛世尊出现于世，只一大事因缘出现于世，为令众生悟佛智慧、得佛智慧故，出现于世。是故，佛法以令悟为体。\n'
        '皈依师父，亦复如是。若为师不能以种种法，令众生悟，则为盲人瞎法。而众生之因缘执见，各有罪孽根基，是故，各有当机缘分令获开悟。\n'
        '为师之者，于弟子，当以种种譬如令众有悟有证。\n'
        '坐下弟子，当精进勇猛，切无懈怠，修证了意诸佛所说。谛深2014，10，21。',
  ),
  (
    title: '谛深大师开示:如何皈依',
    date: '2014.10.21',
    body:
        '坐下声闻众：\n'
        '师父已将皈依条件之22条戒律公布，若能持，可求皈依，若不能持则不可求皈依。\n'
        '所谓皈依，即是汝等已是佛之弟子、我谛深之弟子、法之弟子。行皈依式开始，汝等须先向我谛深请：皈依佛戒、皈依师戒、皈依法戒，后听我为汝等说戒，讲戒，后，汝等须一一心应能持者，方受戒，受戒后，行49日戒七，得证我所说戒，获得戒用佛法，方获皈依我坐下。\n'
        '坐下声闻众，若有已于净坛受比丘、比丘尼戒者，若未得戒，须还于俗相，重做皈依，后再行请受沙弥戒。受沙弥戒后，须入我坐下，行3年戒修，得证沙弥戒用后，方可登我净坛受比丘戒与菩萨戒。\n'
        '坐下声闻众，汝等所知22戒者，发心皈依后，方可行请受戒皈依。谛深2014，10，21应智依为声闻问。',
  ),
  (
    title: '谛深大师开示:罪孽深重，如何修行',
    date: '2014.10.20',
    body:
        '坐下弟子：\n'
        '佛法救度众生，为层层救拔，其中，地藏菩萨为罪重众生大证明功德主，地藏愿力十方佛赞叹，若有重罪者，皈依于地藏，称地藏圣号不断，可直获灭罪救拔。\n'
        '观音菩萨为南阎浮提大慈悲功德主，是阿弥陀佛极乐世界导引助士，地狱恶鬼畜牲转世为人，难免恶习难却，虽经地藏救拔，住于人道，依然因攀缘作业，成罪因、罪缘、罪果，获罪报，受种种苦，遭种种难象。观音大士慈悲故，于是处救苦救难，令罪孽众再获救拔，入修行道，上乘直接证道，中乘成大修行，下乘往生阿弥陀佛极乐世界等，而罪孽深重诽谤佛法僧者，则堕落难救，自取地狱恶鬼畜牲之报。\n'
        '坐下弟子，往生阿弥陀佛极乐世界者亦上品上生、下品下生。\n'
        '善者，极乐世界另有八层，阿弥陀佛极乐国为最低一层，弥陀国众修行得道，能往生上层，以是类比。弥陀世界主要以挲婆持戒念佛往生者住。二层极乐国土一日一夜为弥陀世界之一大劫。每高一层，其一日一夜为下层之一大劫，如是至最高层。若人诽谤佛法僧三宝，不能往生极乐世界。\n'
        '坐下弟子，当精进持戒念佛修行，入佛证道法，获得大信心，成就极乐道。谛深2014，10，20，午，应弟子智依代群中声闻问。',
  ),
  (
    title: '谛深大师开示:如何办皈依',
    date: '2014.10.19',
    body:
        '善知识，若要皈依我，须持佛10戒，另持师父戒，方能皈依我。\n'
        '何者佛10戒：\n'
        '1、不杀生，不食众生肉，不与杀生人共住!不予人众生肉!\n'
        '2、不盗，不取非人予财物，不观路之有遗!\n'
        '3、不淫，不与罪人，外道人乃至畜牲男共住!不沾染或被人沾染!不与父母兄弟姊妹情感沾染!\n'
        '4、不妄，遇事除职责中不说，当知有说即妄!若为道修，道行，道延故可证说!\n'
        '5、不贪，于种种官权、于财物，乃至衣物，不做少许用外多求多想!\n'
        '6、不嗔，不于种种逆、种种难，有不顺思、不顺想或不如意想!更何有报复想!\n'
        '7、不痴，不做道外、戒外、用外、理外，非贪着悦己外思，更况有做有行!\n'
        '8、不慢，于种种因、种种缘、种种果、种种报，不兴有比对、比较、比量思，更况贬视有余!\n'
        '9、事师尊长，对一切三宝相，亲里长者遇当以事缘之，尊敬缘之!\n'
        '10、威仪，行驻坐卧皆应有被誉之功!并有多效仿!\n'
        '何者我之戒：一者尊重僧，二者入寺院，三者不表说，四者多请法，五者远恶交，六者远邪说， 七者远狂者， 八者远争斗，九者远议论，十者护僧道，十一护道场，十二不说过。\n'
        '能持此二十二条者，可于弥勒圣诞申请入皈依群，求皈依。2014年，10月19日，谛深。',
  ),
  (
    title: '谛深大师开示:皈依戒中的入寺院戒',
    date: '2014.10.19',
    body:
        '坐下弟子及声闻众，入寺院是指入汝等近处寺院，一由旬内有佛门寺院，都须进。\n'
        '所谓入寺院，戒缘起为：\n'
        '1、表护法。如若寺院中邪师住持，护法居士进寺院，会以毗尼正法接所住道场缘分，令道场因菩萨护持故，而传佛正法，慢慢转成正法道场。若寺院住持为戒中大德，护法居士会因此获得法慧，证得相应佛法。\n'
        '2、表修行，做我弟子，念佛持戒，持戒念佛；参禅持戒，持戒参禅；诵经持戒，持戒诵经；持咒持戒，持戒持咒。是种修行，会时时获证佛所说法，会令寺院周围鬼神皈依护持，会令诸多众生皈依佛门，获佛救度。会不令众生为邪道获而堕落。\n'
        '善知识，何者为：念佛持戒，持戒念佛。念佛乃佛法基础，若不念佛，无有佛法。而若不持戒，佛法不证。譬如：小学，初中，高中，学种种基础，而大学，博士等表基础用。学佛修行亦复如是，若不念佛，佛门不入。是故，师父说先念佛，后行持戒，持戒中证念佛果。先参禅后持戒，持戒中证禅定果位。如是等等。\n'
        '善知识，若入我门，是戒当持。\n'
        '祝来者早证佛道。谛深，2014，10，19应智依代声闻问。',
  ),
  (
    title: '谛深大师开示:什么是不淫戒',
    date: '2014.10.19',
    body:
        '智依代声闻问：1、与妻子同床，是否违不淫戒。2、父亲春节杀鸡算不算杀生人等；什么是共住；母亲信耶稣算不算外道等。\n'
        '坐下弟子及初发心声闻：汝等能以是问我，为师甚感高兴。佛法末世众生因是等问，能于诸多罪孽海中获劫尽前解脱。邪魔外道为获弟子故，破佛所说，将是等戒律，以种种执见说，兴灭度法。汝等谛听当为汝说。\n'
        '善者，众生世界，皆诸业相缠，所谓相缠成情，情为罪根，譬如，有人帮你或骂你，你终身不忘，不忘为缠，缠者成业，转世为情，以是因缘成父母兄弟姐妹善缘恶缘。\n'
        '所谓转世情缘，由胎卵湿化应境而生，男女交媾，造转世境，互为不忘，成缠缚种。父本为被骂之不忘因，母本为骂之不忘因。父本种子，直入母本恨或思体，父母二本相互缠缚成就胎儿。虽胎卵湿化皆由同体缠缚生，异体缠缚生，或单体分段生，单体分化生。其缘分，皆为缠缚而成。\n'
        '所谓淫心，实则引发诸业之本，交媾之时多有业应。于是，父母兄弟姊妹缘分，实则罪孽之表。是故，修行之者，若欲出离五浊恶世，不断淫心，即为六道，谈何出离。如是，与父母兄弟姊妹相处，实则善恶业之为根，若不与父母兄弟姊妹情愿分离，不能获得出离苦海实证。所谓情愿分离即是不共住体相。\n'
        '基督教属外道典籍，不能共住。譬如，梵众天内无人知晓基督教名相，因梵众天无基督教。若与基督教共住，必受其习气熏染，而遭染污，此即是六道谈何出离。是故，不与外道典籍共住。\n'
        '善者。欲入佛门，修出离法，是等戒当持，若现前缘分不能持，可暂且不持，等缘分成熟，再求此戒。另外，于和尚求戒，需受教授阿闍梨讲戒，若未讲戒，称为相戒或妄戒，与无戒等同。\n'
        '祝修行者，早证佛道。\n'
        '谛深2014，10，19因弟子智依代声闻弟子问。',
  ),
  (
    title: '谛深大师开示:因罪孽众诽谤说',
    date: '2014.10.19',
    body:
        '坐下弟子，佛陀住于世，慈悲众生故，根植于恶世，所谓根植者，譬如铁围山，相隔罪苦海，佛设一舟度，此舟称根植，苦海浪击舟，所谓苦海浪，皆为罪众血，罪众为罪者，以罪量度佛，岂知其所做，累劫不能度，是故为罪海。舟赴铁围山，为救求救者，所谓求救者，千劫有一缘。\n'
        '诸多邪魔道，何故成邪道，邪道之罪众，何故不自觉，只因邪魔道，罪众之执见，与佛说无异，何故无所异，因罪假佛法，罪者愚痴故，不能行分别。佛之所说经，佛说乃佛说，魔说乃魔说，即使字无差，魔亦毕竟魔。\n'
        '是故佛说经，楞严有呵斥，若人破佛戒，讲说佛说经，三藏十二部，分毫无差错，欲出六道者，无有毫是处。譬如骗子魔，能说令人信，信后即上当，佛法亦如是。诸多邪魔道，因众于迷途，不能分别正，其说与佛说，分毫无差别，是故众上当。\n'
        '于佛法末世，戒律为明灯，亦为照妖镜，若人不持戒，洋洋于万言，讲说佛经法，此乃魔所化。\n'
        '是故善知识，听吾谛深说，谛深不讲经，只断魔之掌，令吾所到处，众生有福报，不遭魔迷惑，皈依十方佛，出离于罪苦。\n'
        '坐下弟子，若遇罪众诽谤，当如是断其魔爪。\n'
        '谛深2014，10，19。',
  ),
  (
    title: '谛深大师开示:如何念佛（第六品）',
    date: '2014.10.19',
    body:
        '智安又问，若以音声求佛，此人行邪道，不能得见佛，那众生怎么修阿？\n'
        '谛深大师开示：智安，所谓求佛者，是为有罪为，是人以罪孽，求佛于哀佑，所谓哀佑者，即是其作业，请佛做护持，如若佛护持，即为共业者，共业即共罪，是故是种人，实则污佛做。\n'
        '佛为慈悲主，令众持禁戒，不做罪孽事，直接获救拔， 是故佛说是，以却罪孽使。如若有心人，欲求佛加倍，当于罪孽中，长称佛圣号，佛将派使众，令其获佛戒，以是获救度。\n'
        '智安，称佛圣号，一心称念阿弥陀佛，佛能派观音势至往护受戒，令其皈依。若有人不以佛戒，宣扬念佛实为污佛谤佛。\n'
        '智安，若人持念佛号，诽谤三宝戒律，是等即为佛说，此人行邪道，不能得见佛者也。如若有人，一心称念佛号，不行罪孽法，持佛制戒律，必定获佛救。谛深2014，10，19。',
  ),
  (
    title: '谛深大师开示:念佛无过，违戒有重罪',
    date: '2014.10.19',
    body:
        '有罪众打着念佛旗号，入群破坏群规，破坏群戒、破坏和合、兴嗔恨法，师父开示如下：\n'
        '坐下弟子：\n'
        '1、譬如有人入阿弥陀佛道场，阿弥陀佛正与众讲法，其对弥陀大呼弥陀，屡禁不止，其会如何？\n'
        '2、譬如有人边称弥陀，边兴杀戮狂杀众生，是人会获何报？\n'
        '3、譬如有人，说善不止却边兴恶，是人会得何报？\n'
        '4、譬如有人口说放生，将老虎放之幼儿园，是人会得何报？\n'
        '十方邪道皆口说善言，行罪孽事，杀盗淫妄无所不为，是称欺诈。\n'
        '诸多邪魔外道打着佛法旗号，破坏戒律亦复如是，是故，若是等辈入佛之门下搅闹，当如是呵斥，令其有悟，若其执迷不悟，依戒处之。谛深2014，10，19应弟子问。',
  ),
  (
    title: '谛深大师开示:念佛的开示 （第五品）',
    date: '2014.10.19',
    body:
        '智安问:金刚经中，佛说若人以音声求我，此人行邪道，是什么意思？\n'
        '师父开示：智安，若人不持佛之禁戒，皈依佛法僧三宝，如说修行，因罪孽深重故，求佛哀佑，是称以音声求佛。而皈依三宝持佛禁戒，如说修行之大德，已经脱离罪苦之道无需音声求佛，是故，佛说若以音声求我，此人行邪道。譬如：南无是救我的意思，而念南无佛，则是佛救我之意，如若不持佛制戒律而念，即是行邪道。是故，善知识，求佛哀佑当持禁戒，否则，为邪道之为。谛深2014，10，19应弟子智安问。',
  ),
  (
    title: '谛深大师开示:什么是直心',
    date: '2014.10.18',
    body:
        '智安及坐下弟子，所谓直心者，为众生虚妄之矫正用语，即众生之语多以掩饰，掩饰称不直妄取，是故，佛于经中欲去弟子罪孽执见，常警示当直心酬佛所问等。\n'
        '直心并非实相，所谓实相者，指清净心相，若清净心相可问，则非清净心。而直心则依自己执见而立，为令罪重勿掩罪知罪见罪解故，佛说当直心酬问。\n'
        '是故，善知识，莫以自己执见解经中语，否则，害人害己，自罪难舍，堕落不救。君不闻：百丈老人度野狐之事者？当年一大比丘因错参一句，大修行人落因果否而落500年野狐，是故，群中错解比丘当忏悔，并跪7日香，再来我坐下群，否则，因果不饶落因之人。\n'
        '2014，10，18，谛深为群中有阅藏僧人错解佛说言语应。',
  ),
  (
    title: '谛深大师开示:如何修行',
    date: '2014.10.18',
    body:
        '坐下弟子及声闻善知识：\n'
        '汝等入佛门皆为得佛道，得佛道之为，称为修行。\n'
        '如何修行是佛门未成者朝思暮想之最事。是故，今日为汝等大德讲修行之要。善听，当机思念之。\n'
        '善知识，诸佛不欺诳，诸佛所说皆为实相，既是实相，则必步步有证。汝等如若读了如海经典，你拜了诸多所谓的大师，你修了诸多道，入了名僧大德的法门，却在其中没有证得，只满脑子的法、满脑子的执见、满脑子的论断等，若人说东，汝立知东，若人说西，汝立知西，凡说便知，而汝并不真正见、真正得东西之实。则称着法相，以是议论者，则称着非法相。是故，金刚经云无一法可得，楞严经云，如来说法如以手示月，汝若着指，指月双丢。\n'
        '是故，谛深今日问汝等善知识，汝于佛法若无证得说明汝之修行之道有问题，汝若修了几十年，佛所说的一切，汝只是知而未证，说明汝所入之门有大问题，汝选之师乃邪师罪师。佛法虽难知难解难入，但佛为度众设有大乘小乘，必定令佛子有证。是故，谛深说，吾之弟子与声闻众若修道多年无有证得佛所说事，实为盲修瞎练，入魔之道。\n'
        '善知识，汝等证得极乐世界否？若证得极乐世界，乃入佛之世界，若未证得，必遭堕落，因未证得，极乐世界会成虚妄种子于汝七识成像；汝等证得放大光明否？若证得，会入佛地境十地果位，若未证得，如若不持禁戒，必因妄中感悟佛法故，遭大梦幻，落虚妄种，获不定报。汝证得空否？若证得空性，当得见佛，入菩萨海会，明累劫因缘果报等。\n'
        '如是，汝等当证得佛所说一切否？若无证得，必落虚妄种，遭堕落，或自心菩提种退转成堕落相，是故有人入门50年，回家娶妻，亦有人云，出家一年佛在眼前，出家三年，佛在天边，出家十年我就是佛之罪孽语言等。更有重罪之者，未证谓证，未得谓得，以自己执见讲说经法，为妄中求妄，妄成缘起，入罪孽道，种累劫罪种，难有出期。\n'
        '是故，善知识，汝等若求佛法，当以是为鉴，有佛住世以佛为师，现前无佛以戒为师，方能有救。\n'
        '善知识，若复有在家人，或出家未证道人，不请佛住世，常行狂为，不行供养佛法僧三宝，不行布施信佛罪众，不行布施诸迎合佛法求助之众，入于佛门但求自己所业，其不称修行，亦不称佛门弟子。是等为罪孽深重者，当世难获解罪，转世必不得意。若复有人诽谤佛法，当知是等为罪重人必获累劫罪报，难有出期。\n'
        '善知识，如何修行，当以是为鉴。谛深2014，10，18。',
  ),
  (
    title: '谛深大师为坐下各群中声闻弟子所做辛苦的开示',
    date: '2014.10.16',
    body:
        '群中弟子及声闻众:这些天，辛苦了！\n'
        '为什么说辛苦了，因为对希望入佛门，却始终在种种因佛法而生的执见中寻求佛法的人来说，持戒很辛苦，也很艰苦，甚至很艰难！戒律分为佛制道戒与如来缘分戒，各个佛门道场，各种佛门群体中的为护持道场与佛法所立的规矩，叫缘分戒。是如来应众道场，称为如来缘分戒。\n'
        '近几天，我坐下弟子所设群中，很多菩萨或者初学，有的已经受不住了，退出了修行群，这是很正常的。因为，守道场规矩很不容易，持好佛制戒律更不容易！能在师父的棒喝中住下来，做个道才与僧才，延佛慧命与道命甚为难得。\n'
        '为什么？因为在佛法末世，因不解佛所说意者广为立相传法，令佛法已经如大漠中金，遇之难，得之更难！师父让弟子立群，一者了慈悲愿，二者还大众债。\n'
        '遭到棒喝的声闻与缘觉弟子，棒喝是禅宗要关，有三大益道处，一者，对上乘根基道才，能喝止罪孽当下开悟；二者，对中乘根基僧才，能生忏悔成究竟缘分；三者，对罪孽深重者，能终生受用，为什么罪孽深重者能终生受用，因为，他永远都忘不了自己被呵斥的原因，这会直接种累世修行种子。\n'
        '当然，普通人之间也会有呵斥，甚至辱骂，但，他们种的是相互嗔恨的罪孽种子，这要不得！所以，如果你没有开悟或获得佛法传承，不能行棒喝法，行了就有罪。\n'
        '各善知识、各大德，各坐下弟子及声闻众，愿你们早出苦海，获大自在！谛深2014，10，16晨应智慧问。',
  ),
  (
    title: '谛深大师开示:经书与咒子',
    date: '2014.10.16',
    body:
        '坐下弟子：\n'
        '佛说经书，是当处因缘理，当处因缘道，当处因缘用，当处因缘律，当处因缘果报等，以是称法。\n'
        '心咒，是因缘缘起，种种心咒是种种因缘果报缘起，诵当处咒能直灭其所生因缘。\n'
        '譬如有人生病，若诵其相应咒子，病痛立除，等等。 种种相咒，是种种用心，是故，善知识，佛门咒禁须密传。\n'
        '所谓密宗，并非为咒禁称谓，诸多密宗派别为邪染道，行者当慎。 谛深2014，10，16应智安代群中声闻问。',
  ),
  (
    title: '谛深大师开示:情感与修行',
    date: '2014.10.16',
    body:
        '坐下弟子及善知识，譬如有人得有重病，需微量蛇毒枇毒入甘露丸为药方能治愈，若有人以毒为食，即刻夺命。\n'
        '善知识，救度罪孽深重之人亦复如是，世间情感乃修行剧毒之障，但对罪孽深重之人有度允之，则可令其入菩提场，最后得救。若有人以地藏救母之情感为依以为修行即刻断灭佛种。\n'
        '是故，善知识，入门修道当以佛为师、以戒为师，莫自行主张。2014，10，16。',
  ),
  (
    title: '智慧因“上善若水”的表执见向师父请法，谛深大师开示:',
    date: '2014.10.15',
    body:
        '群规就是群戒，任何入佛门的人首先要守你所驻处的规矩，群规也不例外。\n'
        '譬如屎壳郎认粪为佳肴，粪就是屎壳郎的佳肴，对屎壳郎来说，如何获得粪就是它的正知，正见，正解。所以你说的正知，正见，正解，是你的，和其他人没有关系。但是不遵守群规是要被处罚的，你可以好好的学你认为的正知，正见，正解。\n'
        '每个人都有自己的执见，当要表自己执见的时候要反观一下自己在佛法上是不是有实证。如果没有实证，你表了执见就是害人。所以本群不允许表个人执见，而谈心得就是谈实证。2014.10.15',
  ),
  (
    title: '谛深大师开示:是否有鬼神',
    date: '2014.10.14',
    body:
        '坐下弟子及声闻诸众：师父曾讲过鉴别鬼、神、仙、妖的办法，今因弟子问是否有鬼神，再做鬼神成处因缘开示。\n'
        '善知识，世界之本缘于虚妄，虚妄圆满妄识无漏，诸识相待攀缘追妄造业，成就种种世界，种种有，种种无，种种心，种种妄，种种生，种种灭，种种缠缚，种种解脱，种种有中妄，种种妄中妄等。\n'
        '所谓妄识相待攀缘，指无中生有造业之始，由此追妄造业成就世界山河大地。于是诸业相缠，成就种种众生缘分，种种器世间业像。\n'
        '种种众生缘分共分4类，胎卵湿化随业所应。众生世界，轮回果报故，众生执见相缠，同想成爱，异想成憎，爱憎相缠成情，以是众生父母兄弟姊妹生死因缘轮转相续。\n'
        '世界成就，众生依有为住，妄心攀缘形成种种追妄缘分，以是因缘形成种种妄流，妄流成像，化生者成明暗明暗遭阴阳，阴阳两相转换缘分以种种流为缘，成就种种风。所谓种种风，有无中风，有中风。无中风造就种种神识，有中风造就种种物相世界。种种身识，依有而住成种种鬼神世界。善有善使，恶有恶应，以是成就天人阿修罗之主下神，地狱恶鬼畜牲之主下鬼等。是故，有人恶心生起，诸鬼来应；有人善心生起诸神来应等。种种心生，种种鬼神应之而种种法生。\n'
        '善知识，是法为师父为开悟地菩萨传记所讲，汝等问之，姑且传阅，若不开悟，如螳螂追影中蝉，命死虚妄耳。是故，汝等当精进勇猛，做如来子，获如来智，方能解脱。谛深于2014.10.14应弟子智慧代群中声闻问。',
  ),
  (
    title: '谛深大师因智安智依代群内声闻问咒子有错字怎么办开示',
    date: '2014，10，13',
    body:
        '若不知对错 ，念咒用心，自会获得，获得后便知是对是错。菩萨不闻，五台山某住持之公案？\n'
        '一日某来自安徽灾区逃荒妇女来到寺院门口讨饭，一僧人应之，看到这个乞丐怀抱一婴儿，手牵一少儿甚是可怜，便给了她一兜干粮，乞讨妇女甚是感激。僧人嘱咐妇女说：回去念一个咒子，会有大福。因为该僧人刚出家不久，自己本身半斤八两，将咒子里的吽字，教成牛字了。\n'
        '过了近30年，这个僧人已经做了方丈，但始终未得开悟，文殊菩萨慈悲他，便梦中指点他外出参学。他老人家老实，于是到处走访，始终心如顽石，难得开悟。\n'
        '一天他来到一个村落，看到瑞相发生，便走进村子，他想问问村内是否有修行人住，满村子人都下地干活了，没人应他，只一老太婆在门口检豆。他刚要问，发现老太婆在用咒子捡，每称一句，便有一个豆子从土中飞进框内，他仔细一听，原来她在念嗡班者萨多牛，他便指正她，最后那个字念错了，该念吽！老太如教念之，结果豆子再也飞不起来了！\n'
        '老和尚当下开悟，并知道这个老太婆就是当年受他布施的妇女，是观世音菩萨因地缘分化现。\n'
        '所以，菩萨，师父让你用心，自得分明。2014，10，13',
  ),
  (
    title: '谛深大师开示:众生如何成就如何灭度',
    date: '2014.10.13',
    body:
        '坐下弟子及声闻众，金刚经云，众生之类，若卵生、若胎生、若湿生、若化生，吾皆令其入无余涅磐而灭度之，所以者何？\n'
        '众生之类缘于众业虚妄，众业之类缘于分别虚妄，分别虚妄缘于六根虚妄，六根虚妄缘于六尘虚妄，六尘虚妄缘于明暗生眼识，缘于明暗分别生动静虚妄，动静虚妄生耳识，生通赛虚妄，通赛虚妄生身识，于身识虚妄生鼻识与舌识，身识造业生身体。意识缘于妄明，生眼耳鼻舌身，为眼耳鼻舌身所用，以是缘分成就众生，又\n'
        '称业识体相。\n'
        '众生之类缘于众业所缘，是故，生强弱、特异分别体相成众生之类。\n'
        '善知识，以是意故，众生递蒻为食，成杀因杀缘杀果杀报，递相缠缚造就六道轮回世界。六道轮回成就，诸业缠缚，诸业皆有理性、妄性，于是意故成就种种道之正法道，种种道之邪魔外道道。是故，种种道之正道亦有邪魔外道与之抗衡。于是成就种种业识心，种种心生，种种心生故种种法生。\n'
        '善知识，众生世界如是成就，灭度众生当入诸相非相之如来体相，方能递相灭度。\n'
        '是故，释迦佛金刚经云，若菩萨有我相、人相、众生相、寿者相则不名菩萨。\n'
        '声闻诸重，解是意者，当于吾坐下受具足戒，证十地位，护持吾法于释迦佛末世做善知识，兴500年救拔。\n'
        '善知识，汝等当精进修行，莫有懈怠，以出苦海。谛深2014，10，13。',
  ),
  (
    title: '谛深大师开示:如何看待谤佛谤法者',
    date: '2014.10.13',
    body:
        '坐下弟子，十方佛住世，十方佛弟子，皆如是做，如是清净。\n'
        '释迦牟尼佛，说法花经时，有500比丘比丘尼及长者等因罪孽深重故退场，此是正法时，又有佛住世，比丘等众还是佛弟子，尚且因罪孽深重故不能听如是等法，何况罪孽众生及外道典集。\n'
        '是故善知识，汝等慈悲心，布施佛甘露，莫思众生恶，莫嫌外道痴，莫嗔邪道罪，当知是等众，有缘于善法，只是罪深重，于心有障碍，难于与救拔，自认罪孽理，不能信佛法，如是之缘分，即使已出家，亦因不思意，于佛难思维，于法不能受，自乘罪孽道，退出佛道场。\n'
        '今者善知识，释迦涅磐久，其法入末时，诸魔皆兴起，众生能入群，已是极难得，能闻谛深名，已是大福分，汝等勿忧虑，吾已于诸佛，立下宏誓愿，诸佛末法时，吾能于罪众，显大神通力，化罪为法脉，化苦为甘露，布施罪苦众，令其种佛种。\n'
        '各位善知识，切勿因众生群中罪孽执见故，生嗔恨想，大阿罗汉尚且难思难解，况且罪孽众生。切勿，切勿。谛深2014，10，13。',
  ),
  (
    title: '谛深大师开示:为什么要设修行心得群',
    date: '2014.10.13',
    body:
        '佛说一切法，皆是实相意，如来不欺诳，若不能实证，则为入魔道。何谓为实证，譬如佛说空，直接入空境，此称为实证，谛深之弟子，亦复如是证：又如佛说明，直接放光明，此称为实证，种种如来说，信者皆获证，如若不获证，必定是邪道。\n'
        '若人遇贼王，假佛所说法，执见有共鸣，认其为导师，业中极有道，或者说之相，与业入法理，能令人认可，获得众信心，如是之邪道，末法如春笋，处处有其住，一日遍挲婆。\n'
        '各位善知识，修行之心得，为救迷中人，令出邪魔道，证中获解脱，此为照妖镜，令众知佛悲，不舍一众生。2014，10，13。',
  ),
  (
    title: '谛深大师开示:善才童子为什么53参',
    date: '2014.10.12',
    body:
        '坐下弟子众，善才大智慧，53参学，获得十地果，何故53，因其有习业，与佛不笃信，是故53参。\n'
        '各位善知识，学佛之机缘，今者谛深说，修道之参学，并非单佛主，众生业亦主，是故修道人，须得参悟入。若汝罪孽重，执见道理深，按汝执见度，衡量遇之师，入汝执见者，汝之为认可，称其称师职，其实汝共业，因为汝之业，不认佛为师。善才亦如是，譬如汝之痴，蚂蚁为导师，汝须累劫修，拜尽蚂蚁王，亦不入佛门，更无成佛道，何止53，即使师无边，亦不能证道。再如汝求学，拜童为导师，假若满世间，集思共师之，汝毕为童智，难超少年郎。\n'
        '善才之参学，拜者为菩萨，是故53参，才得证道果。如若佛为师，汝之信心足，当下能成佛。当年小龙女，即是修道表。即使汝有罪，须得按罪论，成道较师王，亦亦为神速。是故善知识，入门学佛法，观之汝师谁，如若汝师佛，何须53参？如若汝师魔，当下成堕落。\n'
        '坐下弟子，若遇人说，当多求师，我为之一，当如是应之。\n'
        '谛深2014，10，12。农历9，19应智安为声闻问。',
  ),
  (
    title: '谛深大师开示:为什么出家',
    date: '2014.10.12',
    body:
        '坐下弟子，今天是观音菩萨出家日，大众多认为出家就舍弃眷属入佛门修道这么简单。其实，出家的因缘是佛法三藏十二部的究竟处、缘起处与成道处。\n'
        '我先讲为什么要出家。\n'
        '五浊恶世之六道之中，人之烦恼有种种，譬如有人惹你、骂你、侮辱你、奴役你等，你也会在此污泥浊水中行惹人恼人烦恼人等之恶为，为什么会这样？因为这就叫众生之间的缘分，这个缘分的表现是什么？这个缘分的表现就是你的生活，这个缘分也是你的家庭眷属住的地方，如果你不能舍弃你的缘分，那你就必然被劫浊、见浊、烦恼浊污染缠缚，最终你也有浊智、浊见、浊理去惹恼别人。众生无始劫来所受劫浊见浊烦恼浊之染污成体相，互缠互染互爱互恨最终成就杀盗淫妄等罪孽习性成就种种罪孽，我们称其为五浊恶世。\n'
        '人要出离五浊恶世之罪孽六道，最后放下出离这就是出家。众生只要不出来，就必然遭受种种被惹之苦恼、被侵犯之痛苦、被凌辱之恨楚；就会在被杀盗淫妄等的罪孽威胁中生存。同时，别人也会在你制造的烦恼、麻烦、生死威胁中过活！有人说我们发誓互尊互爱不就得了？这恰恰是愚痴所在，因为所谓互尊互爱，其实就建立在互欺互诈互嗔互恨上，所以你们要明白，这是攀缘心的习性，只要你不出来，就没有可能脱离罪苦，要出离罪苦缠缚，出家是唯一的选择。\n'
        '坐下弟子，出家后会在佛陀导引下的修道途中，获得清净自在的极乐世界生活。所以，只有有大福报的人，才能出家。现在一些人，不知道什么是出家而出家了，叫妄出家，不获佛陀导引福报，只能盲修瞎练误导众生，造更大的业。\n'
        '希望弟子们看明白世间缘分，我们叫看破，放下罪孽出离苦海，我们叫放下出家。希望弟子们像观世音菩萨一样，能看破、放下、出家、成道。谛深于 2014年10月12日，农历9月19日观音菩萨出家日示。',
  ),
  (
    title: '谛深大师开示:过午不食',
    date: '2014.10.10',
    body:
        '坐下弟子，六道之中，众生之类，所谓食者有多种，大体分为：一者思食，二者闻食，三者制食，四者想食，五者时食，六者段食，七者不休食，八者道食等。\n'
        '人道食者因身体以昼行夜伏为体相，是故多以体用、体能为食之相分，是种食相为制食与时食，所谓制食，多以体内种种液分为食制，是故称制食。\n'
        '按制食，人一日约晨为旺用，午为中用，晚为衰用。何为衰用，人体器官晚用者，如同器之欲碎而用之，是故称衰。而恶鬼畜牲则诸多夜为旺用，是故佛门以过午不食为正。若人事之有别，夜出日伏，与鬼道、畜牲道有通时须夜中有食，但身体衰时为用，伤身伤寿。\n'
        '坐下弟子，禅宗过午不食为人之正餐。据己之所需食之为修道之用为要。若有人因罪孽缘分故身体有疾，可按身体所需食之，称为药食等。天人大都以思食、想食、闻食为体相。有旁生类终生须食称为不休食，有旁生类如鸠蚕半生不休食半生不食称段食等。\n'
        '各位善知识，众生之道为佛法体相住处，如来能微细分别而用，所谓不分别是指清净修道所需，当处分别为正法道。\n'
        '善知识，入门修行须先皈依用心，早日出苦乃谛深所盼。切勿狂心为用，诘之为傲，得少为足，错失机缘，悲甚，苦甚。 2014年10月10日应弟子智安为群中声闻问。',
  ),
  (
    title: '谛深大师关于父母儿女善恶缘分的开示',
    date: null,
    body:
        '坐下弟子：\n'
        '所谓六道轮回苦，是指生老病死：所谓善恶，是众生自利依止分别称谓，实则无善恶。是故，生死乃苦道过程不以善恶分别，但因缘有善恶，善恶乃分辨。\n'
        '如来说善，是因众生因其利而依称善，实则非善亦非恶。\n'
        '生儿育女为众生因缘延续，相对父母自身上世或累世福报罪苦种子成就福利缘分，种种共业因缘成本世父子儿女等报。\n'
        '以生儿育女说善恶者，乃邪道为乱佛法实相因缘说，立此论者有如下报：一体多首报，精神分裂报等。是故，立论者当忏悔，忏悔得安乐。',
  ),
  (
    title: '谛深大师因群中有人拉善款开示如下：',
    date: '2014.10.9',
    body:
        '智安及坐下弟子，何故我坐下，至今未建庙，因为寺庙者，十方慈悲缘，我已说化缘，然无众发心，众何不发心，释迦末法至，波旬众罪人，未证谓有德，以理称佛法，令众入道理，皈依成魔民，着我佛法衣，以表己之能，以留己之名，四处化缘分，建有诸等庙，实则无佛缘，称佛道场灭。如是罪孽使，实乃狂心使，为魔所利用，愚痴做魔民，令众断佛种，以罪称净地，断灭佛净土，是称欺骗缘，诳骗大众故，令大众有罪，不信真正法。是故我所住，茅棚于末世。各位善知识，大善古震旦，今者称中国，今者道场灭，佛法已难遇，所遇之佛庙，所遇之善说，皆为魔所为。譬如人受骗，骗子所说法，最令人动听，所以其受骗。\n'
        '各位入群者，群中若有人，建庙化善款，当做如是说，令其自褪去。\n'
        '智安及我弟子，不允有人于汝等群中化缘筹助。2014.10.9',
  ),
  (
    title: '谛深大师开示:佛法入门要关——打掉狂心',
    date: null,
    body:
        '善知识，佛门大道非常人能入。是故，佛于法华经云:假若满世间，皆如舍利弗，无能知少分。\n'
        '舍利弗乃五百罗汉中智慧第一之大德。\n'
        '由是，世间凡夫以种种执见解释佛法，或自称佛法，乃狂心所显。\n'
        '善知识，狂心是入佛门第一道障。狂心不除，佛门难入。\n'
        '狂心亦是万恶之缘，贪嗔痴恨，杀盗淫妄无不缘于狂心，是故，狂心称佛门第一道障。\n'
        '虚云老和尚当年开悟，第一句话之定就是:……虚空粉碎也，狂心打下去。\n'
        '各位修行，学佛修行是为修道成佛，不是拿自己执见以狂为表成大罪孽。\n'
        '大众当知，若以狂心佛门求道，如以粪包金。\n'
        '佛法不思意，果报不思意。若有罪孽众，痴狂称佛法，诽谤持戒人，或谤大善者，或谤凡夫众，乃至谤草木，其罪自做之，恶报即当临。\n'
        '善知识，若遇是等罪孽狂人，即当避之，因其罪报即临，勿因其罪报故，染汝心地。',
  ),
  (
    title: '谛深大师开示:如何求佛、求菩萨',
    date: null,
    body:
        '善知识，若有人因罪苦难耐求佛菩萨哀佑，称为求佛。\n'
        '善知识，虽诸佛菩萨慈悲，为不令一众生堕落故，有求必应，故为众荷担其所求罪苦，然受罪之众多因罪孽深重故心行反复，是故我今做求佛略说，以助缘分大众获佛护佑。\n'
        '善知识，如若求佛，得佛护佑，当忏悔所行罪孽心生归佛之心，否则，所得之报累劫难出。如何报之听我细说。\n'
        '若有人因罪苦故求佛，得成之后，却自行怀疑，疑惑之后狂妄以为乃自己之能、之为所得回报，此称欺佛重罪。欺佛之罪，按人道时间计算，人道3年为限，神道十年为限，天道三百年为限等。限期之内若不自悔，必有鬼神量恶分判处之，令其受报。\n'
        '若复有人为以求佛有得，自行狂妄，自以为有智、有德、有天命而诽谤持戒比丘，诽谤大善知识等，如是之人必受现实恶报，而无有出期。\n'
        '若复有人，求佛哀佑，却以自己认识某僧、某派、某宗为依诽谤持戒大德、大善之者，如是之人，必获着魔重罪，一切世间福报所不能享，而罪独享。\n'
        '若复有人，以世间做人道理轻孽佛法，以世间道理讲解佛法不为护佛，此人为波旬使者，其所说法与其徒众皆于罪苦轮回中难有出期。\n'
        '如是等等。\n'
        '善知识，求佛得护之得多为：首求应之，再而有应，三而不应，若不皈依佛一而再再而三求之，称使佛重罪，会获直堕罪孽重报与地狱恶报。\n'
        '是故各位大德，多与缘分弟子做是种讲说，莫令自己缘分之者因不知如何求佛故而受罪报更获罪罚信心有失。',
  ),
  (
    title: '谛深大师讲什么是有求必应',
    date: '2014.9.27',
    body:
        '师父于美国旧金山遇归依所谓密宗之魔法女以许愿义，作如下开示：\n'
        '善知识，恶求恶应、善求善应、妄求妄应、种种求种种应，是称有求必应！\n'
        '所谓许愿，许恶得恶、许善得善，乃至种种，以心应之，现实报之，罪恶世界许恶之报，是称许愿！\n'
        '善知识，六道五浊是以成之！\n'
        '是故，善知识，种种心生，种种法生；种种法生，种种心生，世界轮转如是！2014/9/27',
  ),
  (
    title: '若无明师如何修行',
    date: '2014.9.15',
    body:
        '各位善知识、各位声闻大德，有佛住世以佛为师，现前无佛以戒为师，是故各位当知，若无如来为师应世，当求戒为道。\n'
        '何为传戒，戒律条则为相，解戒饲用、当机授予称传戒。若以戒条为得称为妄戒，是等为断佛传承相。是故，佛法传承称传戒。\n'
        '各位大德，入佛法中为求道求救求用，若无所获得于己之所求，或断佛种。是故，入得门来，当求传承。\n'
        '各位大德，如是称为佛灭后或不遇佛之明师之修行。2014,9,15',
  ),
  (
    title: '谛深大师开示:佛不说依法不依人',
    date: '2014.9.10',
    body:
        '所谓佛说法实则为救众，菩萨所说法均为有漏说，亦为修道说，是故为菩萨。\n'
        '诸位修道人，佛陀兴世世，落脚于尘缘，所落之尘缘即为众生依，所以之尘缘其称为佛法，佛陀涅磐后其实为尘缘。是故佛不说，依法不依人，令菩萨说之。\n'
        '诸位修道人，佛陀住世时，众生之眼观，其相为人身，所谓皈依者，于其心目中，归之亦人身。依法不依人，何者能归佛。各位善知识，如来住于世，所演之法道，如有幼儿闹，秥之一树叶，幼儿立刻喜，事过佛弃之，此称为佛法，实则一叶耳。有罪之众生，以此为依止，真乃难救者。\n'
        '善知识，谛深之传法，汝等当记之。释迦住世时，涅磐波旬教，法由阿难传。于释迦末法，波旬执着法，自娱于罪孽，我于世上说，无需阿难传，我法尽六道，归者倾获救，是称度波旬。\n'
        '善知识，若欲出六道，戒乃其道具，不持于禁戒，不能出六道。十方佛住世，皆如授说之。\n'
        '善知识，如来不欺诳，传弘戒律者，其为佛之子，必当得做佛。若以法为依，法中虽有戒，如沙海一金，得者如其金。是故十方佛，不说法为道，却说戒中来。若依法为道，不遇佛住世，除有大因缘，即落于大坑。\n'
        '善知识，严净毗尼法，成佛倾刻间，如于纯金山，寻求一沙金。依法不依戒，则如于沙海，遇有一金者，得者累劫求，其余皆不得。\n'
        '善知识，释迦牟尼佛末法，当以此为印。2014.9.10',
  ),
  (
    title: '弟子问:有人出家10年后悔不已，并因故杀了鼓动自己出家的算命先生。',
    date: '2014.9.5',
    body:
        '谛深大师开示:\n'
        '坐下弟子，因佛法殊胜，用大、相大、体大故，为天人、阿修罗、天龙八部等一切贤圣所归仰！\n'
        '佛法为一切贤圣所归仰故，众生世界均以佛法为荣！\n'
        '众生世界以佛法为荣故，众生便以种种执见解释佛法，并以此为耀令赞叹者皈依。皈依者因以是等执见以为佛法故，落入众生执见坑，以是意故佛法真谛丢失；佛法真谛丢失，众生缘分执见即被众生视为真谛；佛法因是因缘故，成世间法。\n'
        '坐下弟子，佛法成世间法后，因大众心存佛法殊胜妄想，以凡为胜，所受修道之报便与自所希求成欺骗报，其所受报不如凡夫，凡夫之报为实报，其修道报为妄报。\n'
        '坐下弟子，以是因缘，佛法末世出家在家皆不获佛法真谛而受凡夫妄报不及凡夫俗子，是时凡出家人皆不及凡夫。是故，有出家人将所受恶报记恨于初而行恶行。\n'
        '坐下弟子，汝等所问其因缘果报如是。\n'
        '坐下弟子，佛法末世以是因缘以凡称圣者如黄河沙，众生因与以凡称圣者共业执见故于我谛深法生罪孽谤，是等已无以能救，是等挲婆灭时受种种灾杀报。\n'
        '坐下弟子，佛法殊胜，末世佛法罪孽为之，汝等当精进修行莫有懈怠。 2014年9月5日',
  ),
  (
    title: '谛深大师开示:佛法传承',
    date: '2014.8.31',
    body:
        '未彻悟者若自无戒园或更有破戒乃至破一戒者 却与众教授，此称破佛律仪做，若破佛律仪做者，为阿鼻重罪，受是等戒者为因缘重罪。\n'
        '善知识，佛法末世不持戒众持有戒碟，皆魔所使。吾之弟子皆持戒正证，所谓戒正乃一戒不失之传。\n'
        '善知识，若寺院住持不持禁戒，不称寺院。不持禁戒却香火旺盛之住持，皆邪魔外道缘分之报，佛门不如是做。\n'
        '善知识，当如是知如是解佛法传承。2014年8月31日于北京行寮',
  ),
  (
    title: '谛深大师开示:为什么佛法赖僧传',
    date: '2014.8.31',
    body:
        '善知识，佛法以戒为道，戒行圆满方能称师，缺失一戒者不能传戒，是故佛法赖僧传。\n'
        '大居士为于戒有失相，自且不保，罪尚未尽，不能传戒。若是等为众说戒，为有漏为范寸水不得之邪传也。\n'
        '善知识，戒行圆满者为大阿阇梨；严净毗尼者为法师导引，开悟圣僧为坛主法王住持其戒有服，戒者获戒。若非此做其戒皆妄，无有实得。是故予戒者，恩师再生之父也。\n'
        '善知识，若无圣僧主坛，可以过往之祖如六组慧能、七祖行思等做主坛大和尚以传佛戒，若不能则为妄戒。\n'
        '善知识，切勿不知为知、无德为德妄传佛法，恰如不识水性妄称游泳高手，下水即灭，害人害己。\n'
        '善知识，得戒者为父母肉身凡胎生身离苦往生佛国；不持禁戒者死后亦不能往生佛国；持戒不严者一心称念佛号死后佛陀施救，若因善境破罪种获离罪心即得往生佛国，若不获离罪心，则于罪中生根发芽不能获救。\n'
        '善知识，一切未得开悟或不持禁戒身穿佛衣妄传佛法之人皆邪魔外道欺众，皈依是等者有罪。2014年8月31日',
  ),
  (
    title: '谛深大师开示:什么是佛门人',
    date: '2014.8.30',
    body:
        '善知识，佛灭度后以戒为师，佛门人以戒为判，持佛戒者称佛门人，持一戒者，为一戒居士，二戒者为二戒居士，至28戒者，为二十八戒居士等；持具足沙弥戒者，称出家沙弥；持具足菩萨戒、沙弥戒、比丘戒者方称为佛门教众之师。一戒不持不称为居士，更不能以佛门称谓。若比丘不持禁戒，即为罪使，为灭佛法故于佛门承事。\n'
        '善知识，佛法戒律不分宗派，所有佛门宗派道行，皆以戒为本、以戒为考；若不持禁戒称佛门人，如以粪称米。佛法末世因戒律荒废故，诸邪魔外道兴起，口说善法，实则假善行恩诳骗大众。是等经常假佛所说、行使佛、污佛、弑佛重罪。如是罪人亦处处称佛门人，亦有徒众若干追随，受使于斯，并个个称证无上道，其因众多罪孽因缘共业故，能于缘分中神通蛊惑令众信服上当。善知识当知，佛门不以神通为判，只以戒为判。若有人能讲说三藏十二部佛典无有过错，若未开悟又不持佛之禁戒，则必自作地狱恶鬼畜牲因缘成堕落罪，轮转六苦难有出期。\n'
        '善知识，佛记破佛戒律，污佛、谤佛、灭佛之辈，地狱有时为是等做。\n'
        '善知识，在家菩萨尚且不许与女众共住，何况沙弥比丘。\n'
        '善知识，佛法末世因佛戒荒废，百魔障道，种种邪道邪说炽盛世间。切记勿以此称惑。善知识，佛陀住世智慧慈悲为心，严净毗尼乃佛传大任者。\n'
        '善知识，谛深于佛法末世为灭邪魔外道诳骗众生故住世传法，声闻者即当皈依，皈依者定得离苦。2014.8.30',
  ),
  (
    title: '谛深大师开示:佛法如何灭度第三品',
    date: '2014.8.16',
    body:
        '善知识，邪魔外道称为佛法，佛法由真成假，虽实之不存却有罪孽假其名相。因邪魔外道虚假故，而落虚假称谓。以是因缘有如下几种破灭处：\n'
        '一者精神寄托之宗教称谓，此处虽诸多人依附，却大都不以为真而无实信，只有意想病者会有信心，其者本自臆想实则虚妄，亦不获佛法实用；\n'
        '二者，邪魔沾染之迷信称谓，此处多为鬼神妖魔用处，佛魔一契入罪孽国。\n'
        '三者，科学称谓，此处直接入社会学理为历史相，遭断灭。\n'
        '善知识，佛法最后灭相先有佛门兴起妄说，后遭邪道假名，因邪道虚假故遭世间法灭。善知识，当今佛法已遭诸多邪魔外道假名演说，广做解释，是故已无传承而入断灭段。2014年8月16日',
  ),
  (
    title: '谛深大师开示:佛法如何灭度第四品',
    date: '2014.8.16',
    body:
        '善知识，当邪魔外道称为佛法时，佛法于当机因缘瞬息灭度。\n'
        '善知识，譬如有人不识马相将驴称马以此示众，而于大众无人识马，于是大众之中全以驴为马，以是意故马即是驴，马之名相被占。\n'
        '善知识，佛法亦复如是。而佛法因难解难遇故，如若名相变故，以魔为佛，则大众因未遇未见未知佛故而认魔为佛，以是意故佛法灭度。\n'
        '善知识，当今世界诸魔兴起，信众广大，皆因如是因缘落于魔道而遭大幻，并因于魔道不能自拔，为魔所使做累劫罪根。\n'
        '善知识， 现前密法、XXX、XX、禅修班及诸以佛法为号之自立为道之道，以某佛法之名为道之道皆灭佛之邪魔外道，当知赞是等罪魁必获大罪而于佛法兴断灭缘。如是罪众各个自称证无上道，以众生愚痴赞叹皈依故成就地狱恶鬼世界群体堕落。\n'
        '善知识，未来挲婆是等罪众以种种名相假称佛法，层出不穷，佛法灭度。2014年8月16日',
  ),
  (
    title: '谛深大师开示:什么是救度众生?',
    date: '2014.8.11',
    body:
        '善知识，譬如有狐黄猬蛇、狼虫虎豹饥肠辘辘，假种种法、种种说、种种像，待捕猎物，若众生听信其演，则命即休矣！\n'
        '善知识，佛末法时，挲婆世界亦复如是。种种心、种种像、种种表、种种教、种种门等，若不以佛戒为依，又无深切事实为表，更无证明限之却称救度众生、帮助众生，皆如狐黄猬蛇、狼虫虎豹求食之戏。是等若说佛法，乃妖魔鬼怪所加之邪师之假。\n'
        '善知识，若有人、有寺院明码标价收受礼金为人做诸佛事，当知是等皆为罪孽之为。如是罪人本自罪想，以罪救人实则害人。求救之人，必遭堕落。\n'
        '善知识，若有人、有寺严净毗尼，不求一钱亦不为名而救助于有求者，被救者供养、或不供养，是称救度。\n'
        '善知识，若为名为利为欲为众生事，为罪孽之举。2014.8.11',
  ),
  (
    title: '谛深大师讲如何阅藏',
    date: '2014.7.24',
    body:
        '经藏乃每尊佛住世所留，然传承有别。不同界有不同名、不同意、不同文之传承。而每一界，又有不同道、不同人之不同解智恰故意不同之传承等。(此句注解：不同的人因为缘分不同，理解也不一样，理解不一样，他所对应的应对智慧也不一样）\n'
        '经藏传承，又因不同时，不同境实有大别。如佛之大乘宝华经仅在震旦就有五种流通本之多，而寺院传播则多以鸠摩罗什菩萨译者为范。而阿含经，不同范本更多，最常用者就有二十余种。是故，佛说凡有言说皆无实意等。\n'
        '如是，佛之经藏非末世人可依、可阅，但大修行、大智者可阅。若复有人断章取义，以之为要讥毁贤圣大善，或以某部经书为殊胜诽谤余乘，真愚痴辈。是故，世间传阅，有佛之亲导真经，若无佛则无真经焉。\n'
        '如是，佛门如何修道？如何传道？有佛住世以佛为师，无佛住世以戒为师，尊从贤圣、大善知识善之引导等为修行之本。是故，诸多讲经说法者皆堕大坑，而持戒修福者，获大成就。\n'
        '各位大德、弟子，切勿自欺欺人以为有得。2014、7、24',
  ),
  (
    title: '谛深大师开示:修行不要做万字先生',
    date: '2014.7.15',
    body:
        '今天是观世音菩萨吉祥日，师父在北京行寮给菩萨开示，修行不能做万字先生。中国有坊传曰：某学生姓万，聪颖灵感，入学先生教之写一，然后写二，再者写三。生立刻明白学之简者，四必定四横也。\n'
        '生回家长者问之，汝学几何？生曰：数之理也。又问之，汝名如何书之，其曰，笔墨伺候。\n'
        '长者应之，生即书万条横为其姓氏之未终。\n'
        '各位修行，佛法博大精深，非常人日之所竟、月之所竟、年之所竟、一生能竟，乃无量劫耗精进勇猛方能有得。是故，释迦如来三藏十二部之浩瀚经藏不过恒沙一尘耳。何故有人以一经一偈为究竟得而污僧谤戒谓之超脱？万字先生耳。\n'
        '佛之经典三时教化，然时时做机实乃因缘当机之用、普助设坛之用，修行之者当以自己所证步步精进以饲宏愿。切勿以宗派之得，互为灭谤，否则，重罪，乃不救之为。2014年7月15日于北京香山行寮。',
  ),
  (
    title: '谛深大师开示:什么是修行?',
    date: '2014.6.15',
    body:
        '坐下弟子:所谓修行，是指入出离六道之法，共分三大段次:\n'
        '一者，入门前段，二者入门后段，三者，开悟后成佛前段。\n'
        '何者入门前段？由诸佛菩萨慈悲沐法而生信心，由信心发愿，由愿导行，广修供养、广行善施，最后皈依佛菩萨坐下，此称入门前修行。善知识，入门前修行十分难得，时间很长。所谓皈依即往生者。凡夫俗子，不能受皈依众，若受即时堕落于罪孽因果。是故，入门不易，甚为难得。\n'
        '二者，入门后修行。所谓入门后修行，乃佛菩萨导引，以佛所嘱修出离法，是等乃佛之弟子称为佛子。极乐世界之众是如是之者，受戒比丘比丘尼是如是之者。是等，皆于诸佛法导中终获开悟。如是之大善者，虽经劫修道，毕竟开悟。\n'
        '三者，悟后修行。是段乃大果报修行，多于愿力开悟众生，毕竟成佛。\n'
        '坐下弟子，佛法难闻，更难知难解，莫以假佛名号之法为依，凡夫俗子当以戒选师方能入得佛门。\n'
        '善知识，严净毗尼入佛之慈悲之门，乃我等期也。2014.6.15',
  ),
  (
    title: '谛深大师开示:什么人能成佛?',
    date: '2014.6.9',
    body:
        '善知识：十方众生皆具如来智慧德相，只因妄想执着于种种业故，而不能证得。\n'
        '所谓妄想执着，指八识心相，而其体相乃于种种有、种种无、种种法、种种道乃至所谓之佛道中有得、有智而不能放下。\n'
        '是故，善知识，若人于种种法自居不能放下称为大德，实如掩耳盗铃之拙于佛法。若有人以佛之任意法为执，称救度众生，是人自寻堕落。若有人知诸法无我，是人乃佛之弟子，若是人能于诸法无我中乐于禅悦，是人具解脱相。\n'
        '善知识，众生之所以为众生，其于自己攀缘心不能自拔，于是中体悟佛法所致。是故，大众当以放下为大赞叹、大喜悦，莫以种种得以为殊胜。\n'
        '坐下弟子，当以此为鉴体悟佛法。2014.6.9',
  ),
  (
    title: '谛深大师开示:解梦开示',
    date: '2014.6.5',
    body:
        '智慧于 6月5日上午10点因早晨梦境奇特、给师父短信请求师父开示：\n'
        '师父高座，弟子智慧请安并请开示，我今天早上梦见山上起火，不是很大，似乎是男师兄六个人用自己的绑腿等随身物去灭火，后来看到有块地里种的菜苗和树苗，有个师兄生气种地的人，心疼苗没有用这些土灭火，就拔起一颗树苗灭火，树的根很小。\n'
        '师父于10点20分开示于下：\n'
        '智慧，梦中之山是佛之法脉，山上草木是指佛之种种传承之修行弟子；山上起火是指佛之传承与声闻弟子因自己内心火种，又遭邪道引燃使佛子佛孙遭灭。\n'
        '智慧，梦中汝之六师兄，是师父从带你们开始就讲过的、这世除男众弟子外，有6个比丘尼能获开悟证八地以上菩萨果位。为什么梦中6师兄为男身？智慧，只要登地均直获男身。他们用绑腿绳灭火，绳是指令自己修行不会丢失的定心戒法，而以之灭火是以戒慈悲救众之举。\n'
        '智慧，现世邪魔外道打着佛之旗号，身着佛衣，用自己执见讲说佛法，令众多比丘、比丘尼、长者、居士被其征服，成其火伴、助其火势，断灭佛种，是称佛门火灾。\n'
        '智慧，当以此为警，广为宣传佛之戒律以护众生佛种。2014.6.5',
  ),
  (
    title: '谛深大师开示:如何放生',
    date: '2014.5.29',
    body:
        '今天智依因群中佛友问怎样放生入法短信请法。师父开示如下：\n'
        '各位善缘信众及坐下弟子，所谓放生顾名思义，乃将行将断命罪者令其脱罪逃命。如若其未脱罪汝等令其逃命，恰如恶狼伤人汝令放之，此称共业。若要入法放生一者须断其罪业，二者过罪不究，三者令其有悟，知恩感佛。若不能做到是三者，均为共业。\n'
        '善者，若汝等未能知晓罪孽众生之所以遭杀报显前，乃有惑于法，是故须当知晓断命罪众之因。\n'
        '善知识，若有人有群诽谤、讥毁持戒比丘不自悔忏，更加宣扬令众断佛慈悲，当于十劫为畜牲身遭弱肉强食厮杀互啖恶报，单谤单杀、群谤群杀等，是等宰杀报尽落于地狱，累劫难出。\n'
        '若有人假佛法意曲解经书误导大众，我慢狂妄不自忏悔，死后堕落受种种苦、遭种种报。\n'
        '若有人以种种道诽谤佛与佛法，当于贤劫受诸恶报。\n'
        '若有人依仗、假持权势，欺侮善知识，污佛污僧，不信因果，不自忏悔，命终堕落，其当受无量劫灾杀恶报等。\n'
        '若有人谤佛、谤法、谤僧、谤戒，其于无量劫遭天地灾杀报，而人之互谤互嗔则落互啖恶报难有出期。\n'
        '众生堕落诸杀道后，入杀因杀缘杀果杀报之种种因果轮转罪苦之程式，汝欠我命我令讨还，我食汝肉，汝今讨要，难于佛之善法而生敬信。\n'
        '是故善者，若要放生，断众生诽谤互争为第一义谛，令众生皈依佛法为第一意谛。将罪众养护为功德之举，而直接放生于旷野为犯痴戒之做。\n'
        '是故，弘扬佛法，令众生持佛禁戒，最起码不食众生肉更能不杀，为最入法放生。令众断却互谤、互嗔等能持佛之五条居士戒为放生入法，能将所救之众自己饲养乃功德放生，若将所救生众直接放归山野为多分共业放生。\n'
        '善知识，教导众生于诸佛前多行忏悔，莫于佛法狂妄非议自做，为我等期盼。 谛深2014.5.29',
  ),
  (
    title: '谛深大师开示:如何看待各类佛门QQ群',
    date: '2014.5.28',
    body:
        '坐下弟子，各类以佛法为号之QQ群体，若无诽谤余乘之故，群中亦无互争、互谤，于群外亦无互争、互谤，此类群体中人，虽有诸多不明，亦称为佛门群体，是等群体，于因缘果报中皆能种佛种。是等乃佛法末世留种之处。若以不明为之有明，攻击来者，称为堕落法，为波旬子。若因不明行于忏悔，此称修行。\n'
        '若有群以某佛、某法、某法师、某人等为依攻击、诽谤佛之三宝，更攻击余群，当知如是群体，乃波旬与波旬子教处。\n'
        '善知识，若人善软心，一称南无佛，乃至入塔庙恭敬一低头，当知如是因已种佛种子，若当于未来，自能得成佛。更有于旷野，静坐思佛法，即使戏为之，皆行佛之道。\n'
        '是故善知识，莫以小争而取，当以助道为修。若能如是作者，为菩萨住世。2014.5.28',
  ),
  (
    title: '谛深大师开示: 如何看待：佛门一些不正确说法',
    date: '2014.5.28',
    body:
        '坐下弟子，什么是修行？因诸多障碍而造成自己行为过失，需要改正，对已有过失改正之过程称为修行。\n'
        '若有人罪孽执见成法，并执此为道，不思悔过，教育大众令大众堕于此道，此人称邪王或魔王，福报享尽必堕地狱受大罪苦。\n'
        '是故，善知识若自知有过而思改之称佛门修行人，若自知有过或因以某种规律、心则所成自己执见而不知有过称修行者，为魔王子孙称罪孽众。2014.5.28',
  ),
  (
    title: '谛深大师关于打坐及一念深入的开示',
    date: null,
    body:
        '初入禅坐，因业缘甚多，念头横生。要退去念头获得清静，须内外兼冶。内须修不管它、外须修舍诸业。如精进勇猛，仅不管它获用也要三年以上。能获不管它禅用能直进一禅天，信步梵天弹指。不出家驻山，获此不易。祝修行们早成。\n'
        '一念深入会入念所执境，所以，当年虚云和尚因一念深入禅坐入青山绿水、香云伞盖境而立忏。\n'
        '什么是念所执境？即当老壳子入一念境时，会定在此念处，而此念会植八识中忽然成体，成为自己执见所成世界，这也是佛所讲之一念成世界。若执此不出，便随生此土，而此土依然是自己诸业所成执见所成。故又称魔着。',
  ),
  (
    title: '谛深大师开示:为什么吃植物不犯戒',
    date: '2014.5.27',
    body:
        '今天师父因有弟子于群中应答相问故，做如下开示：\n'
        '坐下弟子，所谓众生，分为心王成身类与住心王神行功德类。所谓心王成身类，乃八识所用生身，世上一切含灵皆属此类；所谓住心王神行功德类，乃种种神运行之相生，各神与神界处成各种种子，诸神体相相抽成体，世上一切植被皆归此类。\n'
        '坐下弟子，所谓心王乃诸神依因缘果报所住处，其以六根观显种种因缘果报为住相，其种种身皆依识立，是故众生肉皆不能食，而用非杀众之毛发不称犯杀戒，只称犯有害与妨生应当学。\n'
        '坐下弟子，所谓神行功德类，譬如：风过起浪，浪乃风生，虽依浪知风，但实浪风不谙与识无关，只应识相。世间植被亦复如是，虽山有山神、树有树神、草木有草木神，但其植被之识只应神住心王。譬如：人造电脑驾机器人，虽电脑机器人有亦或有种种识知之应，若其损伤汝无直接之痛楚。此亦称心王之身与心王之应之别。亦即，种种八识心王之身、与住于八识心王中之神之用身为两相耳。\n'
        '即：八识心王之身，乃众生体相，而住于圆满识心中、之种种神之应相、所成之种种植被，恰如机器人等之用相者。\n'
        '另外，八识心王之身成众生、与诸神所行所成诸生相植被、亦有两者依生身，譬如：或有众生有草木体、或草木体有八识身，若遇是等皆依有心之众生一种，皆当依其为众生一类。\n'
        '坐下弟子及善知识，持佛禁戒须大丈夫，若佛灭后无大智慧者，当以命求戒，莫于自心无解小障，堕落于疑惑大坑成大罪孽。2014、5、27',
  ),
  (
    title: '谛深大师开示:什么是诽谤',
    date: '2014.5.25',
    body:
        '师父今天因智依于其所住群遇人诽谤憨山大师，做如下开示：\n'
        '善知识，所谓诽谤，有三种因，一者异道因，二者执见因，三者虚狂因。此三种因皆能以之成火，火烧成相，人身报尽因欲灭心火自入三重苦海，苦海之中因重罪成障，其火更生，落入相应地狱。\n'
        '善知识，菩萨见争、见谤，当自躲避切勿与之反讥成谤，自寻堕落。\n'
        '善知识，何者异道成谤？所谓异道成谤乃虽非佛道，却有法体自成一门，是等因有道因、道缘、道果故而成道见，以此排异成就非议、嗔意、恨意、灭非自己执见意，造就心火而显谤相。是等因有执法鬼神相助故，人身报尽能成执见道身，道身报尽生大猛火堕落地狱，因大猛火故烧灭智根，于地狱中难有出期。\n'
        '善知识，何者为执见因，是等虽无法道却自以为有道成自己执见，因故高视自己，以自己执见排斥一切成谤，造就火因，因火起嗔，人身报尽堕猛火地狱，因诽谤重罪故难有出期。\n'
        '善知识，何者虚狂因，是等因狂妄无知故，诽谤成性，是等人身缺失福报，因罪因、罪缘成重罪果。是等人身尚无福报，死后更落地狱受大罪苦。\n'
        '善知识，世界无邪魔外道，只因修行人修道遇障碍，称其体相为邪魔外道。而障碍破解，又称助道菩萨。师父开示弟子，为令弟子脱离罪孽险道故，以邪魔外道名之，而世上皆因缘果报使然，实无邪魔外道。\n'
        '善知识，师父只为受持具足戒大比丘说，为欲求佛法者说，为有大福报因缘者说，为吾之声闻皈依弟子说，余者，勿听、勿看。若看，则落大障碍而有罪。是故，各位修行，若遇有争斗诽谤者，当离其恶地，做如是观。2014.5.25',
  ),
  (
    title: '谛深大师开示:什么是慈悲',
    date: '2014.5.24',
    body:
        '师父因弟子问业障是如何生的，开示慈悲如下：\n'
        '各位修行，佛陀、菩萨住世，能微细于种种分别，而令修道者不落罪孽法；更于众生同等施于救拔，而无分别，令修行人无所障碍，称为慈悲。\n'
        '众生因我慢愚痴故，不知慈悲何物，常以共业之情执假为悲，于罪孽法不能得出。各位善者，若遇缘分，自无智慧行于分别，当知善软有分寸，见众受罪苦，不知其因缘，以观使于助，步步制其罪，不落其大坑，是等善软心，虽非大慈悲，亦称佛道成。\n'
        '善知识，譬如：有人假佛法之意，怜受伤恶狼而施救，后放归山野，实乃为愚痴。譬如：有人假佛法之说，将以某些众生为食之者放生，而称慈悲者，因其与是等罪孽放生众共业故，称波旬使，更如何称慈悲？是等罪者，如是放如是之罪孽众，恰如将恶虎放之人群以其为得，实则为障碍法，善者当知，慈悲无障碍，若以障碍法称之为慈悲，真愚痴人。\n'
        '善知识，慈悲乃道心，无智无以得，若兴慈悲心，当皈以三宝，若以我慢持，实乃罪孽使。是故善知识，当自闻于修，效于观世音，有求必智应，若非有求者，若非汝有智，切勿盲从之，是称汝修行。\n'
        '善知识，勿因无知故，行于愚痴而自求堕落。 谛深2014.5.24',
  ),
  (
    title: '谛深大师开示:什么是盲修瞎练',
    date: '2014.5.23',
    body:
        '诸多罪重之人，以自己执见盲修瞎练，若我慢愚痴不持佛戒求道，当知是等为不可救者。譬如：屎克郞，听说米可食，便率缘分者，寻物以求米，己之不识米，想象为依托，得之于沙石，谓之为黄米，于是做饭食，丢失粪食命，亦未得真米，最终丢生命。\n'
        '善知识，若有人、有群未证为证，不听善劝，当如是观如是道、如是忏。2014.5.23',
  ),
  (
    title: '谛深大师开示:佛门如何看科学',
    date: '2014.5.22',
    body:
        '师父因有人不解科学不能解释佛法再做开示：\n'
        '各位缘分大众，譬如：面对如何解决抽烟带来的疾病问题，科学是研究如何通过病理对症施药，而佛法是如何令大众不吸烟。那些因吸烟已经染上疾病的人，要在戒掉烟的前提下，用形成疾病的因缘果报之理，去一步一步的清洗根除，这也称为修行。这也是为什么有些人入了佛门依然受罪的原因。\n'
        '所以，佛法不是科学，科学不是佛法。但，佛法在如何解决已经染成疾病的问题上，包含科学。这也称之为：法尚应舍何况非法，与于法不说断灭相之如来之示。2014.5.22',
  ),
  (
    title: '谛深大师开示:什么是佛门',
    date: '2014.5.20',
    body:
        '善者，所谓佛门有三时称谓，一者正法时，二者像法时，三者末法时。正法时以皈依佛者为佛门像，像法时以皈依戒者为佛门像，末法时以皈依执见成邪魔外道者为佛门像。正法时，皈依后得度转瞬；相法时得度如孵化欲飞之鸟，得度假时，生死未卜；末法时得度如欲令飞鸟转鹿，各自成堕不复救耳，须转世再修，转劫再修，遇佛正法方有出期。\n'
        '善者，佛法不思意，三时有称谓，佛门称谓同，内涵如天攘。正法佛门者，入之即得度， 相法佛门者，得度需毗尼。末法佛门者，佛名成魔名，洋洋于言说，皆是执见解。知者皆我慢，于是说佛法，出家比丘者，皆为言说子，佛法于世间，不如世间法。\n'
        '善者，皆当知，末世有佛法，只如果之叶，枯枝残叶像，实乃众生过。\n'
        '各位善知识，当如是慈悲众生，不以众生执见难于救拔而生不救之心，虽然，但，当自行小心，莫受伤害。2014.5.20',
  ),
  (
    title: '谛深大师开示:如何持戒',
    date: '2014.5.16',
    body:
        '成佛有捷径，持戒能得之，佛法住于世，戒乃其住相，\n'
        '是故所有法，恰如戒之衣，无戒衣无用，诸佛如是说。\n'
        '如何得佛戒，舍命不舍戒，是称得佛戒。若穿法服者，\n'
        '不以戒为本，是等为魔子，更欲说佛法，即使有修证，\n'
        '只是魔之境，是故戒为本，亦称大明灯，亦称照妖镜。\n'
        '诸位善知识，五百大罗汉，不及一戒僧，若汝等欲修，\n'
        '耗尽毕生财，亦当为求之。\n'
        '善知识，得一佛戒，即得佛之真传，一切不持佛戒而称道者，皆魔子魔孙也。五百罗汉亦持清净戒，只于因缘有缺失处。各位善知识，当如是用心。2014.5.16',
  ),
  (
    title: '谛深大师开示:不能用科学解释佛法',
    date: '2014.5.15',
    body:
        '佛法是没有障碍消灭障碍的法，科学是用障碍解释障碍建立新障碍的法，所以，不能用科学解释佛法，但，可以用佛法解释科学。\n'
        '凡是说用科学解释佛法的人，皆是罪重无可度者。\n'
        '若能用科学解释佛法，大家直接学科学即可，还费劲去学佛干什么？愚痴之俑耳，做是种说者，无非是想说，佛法是科学的，其实，佛法恰恰是不科学的，而科学却是佛法随处可解的。\n'
        '何者谓佛法，一明破千暗，所谓千暗者，是指所有暗。末世罪孽众，罪障如须弥，狂妄为其心，无数无有量，因共业执见，污佛称学佛，并以狂妄心，狂说能成佛，其实其不知，罪孽如是做。诸多佛经典，以其罪孽见，解者如恒沙，如是灭佛法。\n'
        '末法有少者，稀有甚稀有，能于诸相门，获知于非相。此等大善者，已于无量劫，获得无量佛，与之于甘露。更有于今世，能于我说事，获得万分一，佛说是等人皆为佛之使。\n'
        '末法之始象，佛法众皆知，而实非佛法，种种道典集，皆胜是佛法，佛法如是灭。今者我说法，为延释迦法，五百载之寿，为救众生故。\n'
        '各位缘分大众，当勇猛精进于佛之传承，切勿以种种非佛传承自欺欺人，受大罪孽。\n'
        '2014，5，15',
  ),
  (
    title: '谛深大师开示:邪魔外道无有过错却有重罪当受',
    date: '2014.5.14',
    body:
        '什么是罪？罪乃种种法所造因缘所成之必受之报。譬如：造车之法所造之车乃车祸之因缘，而若无车实无车祸之罪。是故，造车之法无过，但有罪当受。\n'
        '善知识，十方天魔、十方邪魔外道皆无过错，但有重罪当受。何者重罪，是罪为因有法故能服大众，如是灭佛而灭佛种，令大众轮转罪孽难有出期，故称重罪。善知识，入得佛门，当皈依佛法僧三宝，莫以法为得，何况种种人以种种自己执见之解说。若不能皈依三宝，假佛名号、假佛经典谤佛谤法谤僧谤戒，十方诸佛皆称是等为无终重罪，于种种罪孽难有出期。2014.5.14晨',
  ),
  (
    title: '谛深大师开示:什么是往生',
    date: '2014.5.13',
    body:
        '皈依佛称心往生，因归就是属于的意思，依是佛怎么说的，归依的人就怎么做。所以，彻底皈依佛的人就是当下往生佛国，而饭食经行回到本国，何故有人妄说不皈依就能往生？\n'
        '是故，以不皈依就能往生为说者，是断阿弥陀佛愿力之波旬道。\n'
        '若要佛法兴，唯有佛赞佛更乃凡夫说、邪魔外道说。为什么？因此说缘于互谤、互争、互斗。凡夫之间若要兴事须相互赞叹，故称其凡夫说，而十方诸佛只以功德互赞，实无需互赞，是故其为谤佛说。譬如：日与大地乃愿力不同之佛，日出普照，能生万物，万物赞日，万物赞地，大地赞日，日赞大地，日赞万物。是等互赞字意相同却实意不同。日地互赞为互叹功德，万物互赞为互欣赏其所有相，日地赞物为愿子孙，万物赞日为感日恩。是故，不知佛之互赞为救众功德，却以愤心说之，实乃谤佛说、嗔愤说、争斗说。若佛会争斗、会嗔恨，如何成佛？佛说我赞诸佛不可思议功德，诸佛亦称赞我不可思议功德，但不说以此兴佛法，因佛赞佛之不可思议功德乃佛愿力相，此乃佛之度众境。而末世波旬为断灭佛种，以自己执见断佛说章节、文字，令众生难于辨法，不能出离魔之缠缚。佛法兴与不兴，只与戒律有关，与佛赞佛没有关系，但与波旬是否能得逞有关系。\n'
        '另，师父于兜率内院所见挲婆佛法传承录，与末世外道典集品中，着实知波旬与大德之名号。其中，不持禁戒之道乃灭弥陀四十八愿法者波旬道。\n'
        '坐下弟子，不于毗尼法而称佛住者，其乃魔住世。以佛毗尼法，住于旷野中，亦称大善者。2014.5.13晚',
  ),
  (
    title: '谛深大师开示:如何鉴别波旬与波旬弟子',
    date: '2014.5.11',
    body:
        '释迦佛入涅磐时，弟子们知波旬会穿着袈裟混进佛门，破坏佛法，便问佛：如何应对，如何鉴别魔子魔孙。佛嘱咐弟子，所谓佛衣者有二，一是相衣，二是法衣。所谓相衣，即佛赐袈裟；所谓法衣即讲经说法。而戒如大明灯，不管波旬穿上袈裟，还是讲经说法，只要其不严净毗尼法，即是波旬或波旬子孙。\n'
        '坐下弟子，若有人不持禁戒，住于道场或不住道场，坏佛戒律或曲解佛戒，假佛名号或假经文经意，讲经说法或不讲经说法，称佛名号或不称佛名号，皆是波旬教。波旬教成以佛名号称谓之门派者，为波旬主持；波旬教不成派成一体系者，乃波旬属下住持。是等皆以不持戒、谤戒、曲解戒为相。是故，佛说，戒如大明灯。\n'
        '各位坐下，佛法末世众多遭诸魔幻者，皆不受佛法福报，其所受报皆为业报与罪报。各位修行，谨记。2014.5.11',
  ),
  (
    title: '谛深大师开示:什么是受戒',
    date: '2014.5.9',
    body:
        '坐下弟子，受戒分，戒，入戒，受戒，得戒。若四众中未以此四段登坛，称妄戒、名相戒或不得戒。\n'
        '所谓戒，为卢舍那佛所说，乃报身佛之本，若自称佛门人不知此，称为无戒，而无戒信者，或波旬民。\n'
        '所谓入戒，为得戒者导引，为众求戒者依佛传做传，并应求解疑，后应传者一一心应，亦有人因缘甚深，能自行心应，此称入戒。未入戒称受戒者，若非佛应世，本以戒表，其为道行妄语，须道场受教，经劫修入，否则，乃波旬子，是等难于佛法获真实用、真实得、真实悟、真实证，难获果位。\n'
        '所谓受戒，为入戒后三宝允之并自所愿持之，自愿持戒不犯，此称入戒。若非大善再来，自行开悟，却不应矜持，此称不入。若不入戒称入，此为波旬破佛者。\n'
        '所谓得戒， 入戒者，严净毗尼，从不干犯佛说戒律，称为得戒。若有人戒赢而知之犯戒，后忏不再犯，亦称有戒。\n'
        '若有人不知戒法，却讲戒律为波旬大罪障，应之者为灭佛之波旬子民。\n'
        '善知识，若有人口说经法，却愚痴破戒皆为此类。譬如：今者盛传吃未受精鸡蛋为不破杀与食众生肉戒，更有甚者，以食三净肉为说，称不食众生肉，实如有人半路强抢人物，硬称非偷无过一样。\n'
        '善知识，未受精卵乃识心因缘和合前一脉，比人之身肉更为识心持用，是故，地藏之母食鱼卵遭地狱报，而鱼卵大都体外受精，食鱼卵实则为未受精卵。地藏之母食未受精卵自堕，汝之罪重竟以食未受精鸡蛋为快，愚也罪也，不能救也。\n'
        '善知识，所谓三净肉，乃波旬断章取义为破佛法而说。实则，肉离识身，仅身识无知，譬如：有人因故丧肉，肉为狼食，虽身之不识，汝意却知，而末那与阿赖耶识即使为粪，亦未舍弃。\n'
        '大善知识，何故我释迦佛国土五趣杂居？无量劫前，大广藏佛住世时，末法时期，其有法王名曰由坚，说离身之肉腐烂之肉可食，狂说成佛，更称死后往生，其有弟子20万亿，因破佛禁戒，遭大堕落。先有报身死时遭腐，又由人道20万亿共同堕落五趣众，大者为猪，小者为菌，互啖互食。释迦如来时为智者，因是等为其缘分宗亲，故发宏愿：我做佛时，一趣不舍。\n'
        '善知识，佛说净肉，乃佛慈悲恶地人道因气候恶劣寸草不生，用神力化生肉质，其肉非众生所有。云何末世有人，假佛名号以此为说，称三净肉？众生允之尚不能食，何况被杀。是等于堕落道，却称往生，真愚痴众。\n'
        '善知识，切勿因被波旬迷惑故，自求堕落。若有疑惑当求明者指引，或自参悟。勿盲修瞎练，依佛依律必有求必应。2014.5.9(此开示本为比丘、比丘尼所讲，发到博客中是因为目前很多罪孽众生不知如何入佛门，不知什么是佛法，受大罪孽，所以才公开发）',
  ),
  (
    title: '谛深大师开示:为什么有人上当受骗',
    date: '2014.5.9',
    body:
        '上当受骗也有上、中、下等。\n'
        '上等受骗：因信、受：善说、善施。其相为骗人的人用大家公认的、正确的、好听的、恰当的语言让你对他信心十足之后，对他顶礼膜拜，你便应其所求，或你对其有求，所以上当受骗。\n'
        '中等受骗：因假智交易。其相为在共同行事时，相互斗智斗勇，中人之圈套。\n'
        '下等受骗：贪欲迷信。其相为，贪图小利为人利用，或迷信于法，无故求助为人欺诈，上当受骗。\n'
        '佛末法时，入道之人也是这样，当有人以种种大众公认的对佛经的解说、乃至大家认为其与佛经无异之说，让你信心十足，而其人并非佛陀，那么，当你对其有求时，你就上当受骗了。如果他对你有求，你因信心便应其所求，你也上当受骗无疑。为什么会这样？因为大众在判定是不是佛法时，是拿自己的罪孽执见衡量说法人与所说的法的，也就是说你认为他讲的对他就对，你认为他错他就错，你认为他是佛他就是佛，也就是说你是佛，否则，你怎么能确定他是佛、你怎么能确定他讲的是不是入法呢？你既然是佛，你去求他干嘛？你不是愚痴吗？虽然你上了魔王的当，但是你自愿的。所以，一切歪门邪道均是自作自受。\n'
        '坐下弟子，一个人在讲法时是知道自己说的是否能合大众心理的，否则，他说了谁听？他向你心里说好听的话，你觉着好听，你就认可他了！这说明他与你是同一类人。你求他？你还不如求求自己。所以，师父拿屎克郞做譬如、拿狼群做譬如，因为，这些人上的是自己罪孽执见的当，上的是共鸣执见的当。师父，不会说他们错，只是讲明这是为什么，因为，他们没有错，邪魔外道就这样。你们是我弟子，你们觉着师父慈悲，应该给邪魔外道那些人做个开示才问这个问题，师父不会给他们做开示，因为这与他们没关系，他们要是想听，他们就不会、也不敢这么做了，这不仅仅是某一群人的问题， 从释迦佛住世至今，一直有这样的人，他们的名字叫波旬波旬子波旬孙，未来会有更多这样的人、这样的群体出现。当然，这个开示也可以发到师父弟子的空间里，会有一些并非师父的弟子，却是释迦佛、阿弥陀佛累劫的缘分大众，因业重故遭魔所获，得到这个开示，能脱离罪孽缠缚，逃出魔掌，因为师父有愿力，在佛法末世，让堕落邪魔外道中不能自拔的人，在受罪时有所忏悔，一念敬信即能从苦中出来。\n'
        '坐下弟子，佛法末世，大众罪孽执见坚固，能成诸多共鸣执见，成人数众多之邪魔外道，邪师说法如恒河沙，是故，大众当尊佛所说，莫以自己执见判定佛法，师父在普修行藏中讲了，不要顾虑。\n'
        '大众当知，佛制戒律严净毗尼。若人未证佛法为人讲法，称大妄语。\n'
        '坐下弟子，入佛门当以戒为本，以证为得，勿以执见表述即说教为得，当禅悦为食，方能法喜充满。\n'
        '我所说事，均为众弟子遇障碍解疑，非讲经说法，亦非不讲经说法，当机用也。2014.5.9',
  ),
  (
    title: '谛深大师开示:为什么依法不依人是邪说',
    date: '2014.5.8',
    body:
        '坐下弟子，依法不依人是有漏说，无证说，罪孽说，世间法用说。入得佛门当知，依戒不依法，依法乃六道。佛于金刚经云，若有人说我有法可说，此人则为谤佛。实之例证，累世有之。佛之末世，依依法不依人而堕落者不计其数：因依法不依人立种种罪孽教派者，层出不穷，诸多邪魔外道皆因依法而立继而依人。\n'
        '今者，如种种功派、种种所谓某法门而令大众受罪者，皆依法不依人之泛。\n'
        '佛涅磐时嘱，有佛住世以佛为师，佛灭度后以戒为师，是其者。\n'
        '是故，依戒不依人，为佛门说，依法不依人为外道典集、邪魔罪孽说。2014.5.8',
  ),
  (
    title: '谛深大师开示:什么是邪魔外道',
    date: '2014.5.1',
    body:
        '邪魔外道称谓大众皆知，然，佛门其之名相，却少有人知。\n'
        '若人看破欲离苦之关口，所有障道之法、之说、之用、之染等，即使佛说经典障之道要，是者皆称邪魔外道。佛门对众生界，非出离六道之种种道，种种法皆称因缘，无有正邪。譬如：各种宗教派别皆无正邪之分，所谓正邪其相互指谓耳，其实，是等皆有其真、其用等。\n'
        '若非出离当口延法，即使佛门亦与众教无正邪之分。即：若障道，所有门派宗派即使所谓之佛、佛说亦是邪魔外道，故有着魔之者。此亦称佛魔一契，亦于心用称佛魔一心之相。\n'
        '总之，所谓佛门之说邪魔外道，佛界无有、法界无有，只乃成道用而说相之者。而凡夫六道之众说之则为互谤互争之相之用。\n'
        '是故，修行当知，五浊恶世无有邪魔外道与正道之分，但，众生因罪重难拔而实有其分、其用其实也。2014.5.1',
  ),
  (
    title: '谛深大师为不解如来真实意者说：一契！',
    date: '2014.4.29',
    body:
        '所谓一契法，如来住世时常说之，因亦常为邪魔外道用、能以愚众、迷众，乃之，末法时期此法炽盛，是故当说，善听、善思念之。\n'
        '一契遍世间，大说有数等，种种世间相，种种佛说相，种种邪魔道皆为一契表。是故一契法，若为未悟说，若为业中用，即堕波旬道。吾今当说之，为救遭魔者，有福者善思。因果为一契，无因无有果，无果亦无因，佛眼为观之，即离此险途，魔眼为观之，即入此险途，障者为观之，不解为疑惑，罪众为观之，心中自生谤；各位有智者，善恶为一契，无善无恶存，无恶无有善，佛眼为观之，观众受大罪，是故说分别，为令众离险，分善为法绳，众生依善法，能入出离道，是故于善恶，屏蔽一契说；好坏为一契，好坏道应之，譬如世间人，求证说好坏，若人种田瓜，以瓜之成否，为之说好坏，此为称道用，佛说如是等，皆入慈悲门，若无不成器，无有半夭折，无需说好坏，人之性情表，亦常好坏说，一言以蔽之，洋洋无有终，智者明佛悲，此为了意说，若为邪魔属，永堕此类门，循偱走无尽，罪苦永难脱；生死为一契，此为了意用，无生无有死，无死亦无生，若以佛眼观，即入于涅磐，当下获解脱，若用魔眼观，有诸多门解，即生诸多门，成就种种说，其中有说者，甚似佛用法，实则为魔用，此若细说之，言辞无有终，是故简句表，悟则无有咎，不悟堕大坑；长短为一契，有无为一契，种种有无量，今者不再述。\n'
        '各位智者，依佛说戒律修行表法，其为有道，若未开悟依经表为说称法，称为佛法者，实入虚妄，是故未开悟者，纵能讲说三藏十二部无一错表，其为魔做。而于悟者，不于经表，只当机用。谛深所表，为护佛子。有堕落者得吾所表，当行忏悔。谛深2014.4.29晨',
  ),
  (
    title: '谛深大师开示:什么是正法（第一品）',
    date: '2014.4.28',
    body:
        '智延于今日问师父，有人在群里号称自己是正法表，师父做如下开示：\n'
        '佛陀住于世，依机度众生，依机所说法，为以说示之，假说说邪正，实则无邪正。时间狂妄众，自不知佛法，以自己执见，为表执见意，愚痴说正邪，其实为魔说。诸佛警世说，邪师说佛法，数如恒河沙。何况于末世，难遇善知识，今者有人云，欲说正佛法，真乃无知辈，正邪为一体，无正无有邪，是故我今说，何人称正法，说正者必邪。善者勿分别，佛法当机造，正传说为正，实则无正邪。\n'
        '各位修行，若听有人说邪正以示佛法，当如是观、如是思、如是不受。2014.4.28晚',
  ),
  (
    title: '谛深大师开示:为什么末世所谓的佛门人比普通人难度',
    date: '2014.4.23',
    body:
        '佛法末世的象征是:\n'
        '1、波旬教盛，何为波旬教？不持佛制戒律，以神通、魔辩、狂妄为依证，不敢明示，假以秘密等称波旬教。波旬教有多行处，有行处冠佛名号邪说幻众，衍生尽劫数门派；有行处于佛之正教中坏佛律仪；有行处于佛住世时缘分诞独派教，与佛对抗，佛灭后派教炽盛，并能衍生至劫尽等。\n'
        '2、佛门正传之中，未证谓证未得谓得之灭佛传承。譬如:有人指桑为槐，而所指受指之人未见过槐，则桑于如是众中即是刺槐，桑树即丢。末世罪人妄说佛法，令入佛门人因染污假说、邪说而断灭佛种。是等，若遇佛住，因所知之假传佛法与佛说同相、实则假相，便疑佛、蔑佛进而污佛谤佛以护假佛种子，是等皆因于佛有疑不持禁戒故，断灭佛种。\n'
        '3、不证助灭，若人于佛门因虚妄乱想出家求道，又遇盲师接引，则必不证佛法，不证佛法故，于佛失信至堕。佛法末世，以是因缘，诸多罪重堕于难出之狱与鬼神伴。\n'
        '此为何故佛法末世所谓佛门弟子难于救拔，未遇佛法众却易施救之因。\n'
        '坐下弟子，若于此前遭上述三等邪染，当洗心入门，革面求道以获至宝。否则，入我门下必成搅闹而获重罪。2014.4.23',
  ),
  (
    title: '谛深大师开示:什么是恒顺众生',
    date: '2014.4.14',
    body:
        '坐下弟子，众生因缘由它去，不问、不闻、不牵、不挂，是称恒顺众生。众生求救，汝等应之，是称慈悲众生；众生求助，汝等应之，是称与众生共业；众生使汝汝等应之，是称皈依众生。是故，切勿误知。\n'
        '譬如有狼欲食雄狮，并与之大战，吾等顺其自然，终狼被剿灭，此之称恒顺众生；若汝怜狼助之，赶走狮子，此称与狼共业；若狼求汝救之，汝以刀兵等力助之，令狼逃离此亦称与狼共业；若狼求救，汝能以至智劝狮子退或以智使饶其命，并能以智设诸戒法，令狼舍恶种善，此称慈悲。\n'
        '若有人、有教、有派，诽谤佛法，诽谤贤圣，狡诘污僧、污尼，必获灾恶报，此恰如狼战雄狮，是为恒顺众生之例衍。若有人击持戒僧、尼或污佛，护法灭之，此亦恰如狼欲食雄狮咎由自取，称恒顺众生，若刀来予命乃愚痴辈，不称为修，其犯痴戒第一，因如是灭佛故。\n'
        '修行之人不予重罪之者而兴嗔杀剿灭之心，乃为修、为道，若以嗔杀夺来者生命，此称犯杀戒第二。何故，污佛、污僧获罪杀不称犯戒，譬如:有人以卵击石，乃自求其灭。持戒贤僧如大金刚，污者自灭耳。\n'
        '坐下弟子，莫以修行安全为虑，若汝等严净毗尼，为大金刚身，无有可犯。2014.4.14',
  ),
  (
    title: '谛深大师开示:执着在师父身上也是着魔',
    date: '2014.4.12',
    body:
        '大众当知，佛陀住世为救众生，而不令众生入种种不出离道。何为不出离道？若人以某种人、某种物、某种说为得、为是；以某上师、某法王、某大师为道为是；甚至以佛说为是，是人称为入不出离道，又称着魔。是故佛于金刚经云：若人说我有法可说，此人则为谤佛；于楞严经云：若人不持禁戒，纵能讲说三藏十二部，出六道者无有是处。君不闻：佛所说法如以手示月耳，若认手指为月，指月双丢乎？执着佛说尚且愚痴，何况他说？\n'
        '谛深之说、已说、当说之言并非佛法、非不佛法，指路之言耳。如同暗中明灯，为汝求路。智者当知，灯之非路、亦非汝应着之道，一用焉。谛深不虚狂但破虚狂人，若有人诽谤其为堕落罪。\n'
        '是故，执着任何人、任何大德、任何种种、执着师父、执着吾谛深实乃魔着。\n'
        '一切执着法，皆是魔来应，执着于种种，皆入魔波旬道。\n'
        '坐下弟子，不管那宗那派，只要以道为要，诽谤余乘，皆波旬道。佛所说法皆：非法、非非法，指路用耳。\n'
        '2014、4、12谛深',
  ),
  (
    title: '谛深大师为依戒不依法再做开示：如何看佛法与经典',
    date: '2014.4.8',
    body:
        '十方世界十方众生中有十方无量因缘，其称种种因、种种缘、种种果、种种报，种种因缘果报之中，有无量种种转处，因之转处、缘之转处、果之转处、报之转处。而种种转处又有无量所转机缘。无量所转机缘所表之转因转果转报称为法，法之中有成佛之转者称为佛法。\n'
        '无量转处之机缘有：一因之转、二因之转至无量因之转。何为一因之转？譬如十方世界为总，每一世界所成之微尘再分为微尘之胶子无以再分称其为一因，将此一因设机为转，称其为一因之转。坐下弟子，一因之转尚有无数转处，是故吾说不定之法当以果论之。所谓不定之法，实则指修道之人若落法相，无量之中只一可成其余皆落。是故，若以依法不依人为道，其为令众生入不出离道之说。而令众入不出离道者，称之为邪魔外道。此亦是佛说着法相、着非法相之要。一因尚有无数缘，一缘亦有无数果，一果亦有无数报。\n'
        '坐下弟子：\n'
        '佛法不思意，勿以法为得。假若满世间，皆如舍利佛，无能知少分。是故我出世，于诸末法中，再示无量智，为佛护祝戒，此为一门径，吾于释迦佛，五百世法托，十方佛末法，皆吾谛深说。\n'
        '若当有道者，不言一句法，能于毗尼中，持得一戒应，我说是等人，末世不堕落。若有狂妄者，不持佛禁戒，不知此一门，却于众经典，讲说又讲说，十方佛皆叹，是等无有期，依众罪重多。\n'
        '广大弟子，谛深不虚狂，汝等皆当知，末世不与所谓解佛经典者共住，不与种种以神通、传承、说教者共住，只与严净毗尼法者共住、修行，谓佛之法子法孙，称我弟子。吾之住处，不应一坏毗尼法者。\n'
        '智者当知，若有人以自己执见、经典见、神通见、法见、见见为佛传法，而不以毗尼法传法，即非佛门人。\n'
        '（智安今日在发师父开示时，有人以《大般涅槃经》中讲依法不依人诽谤师父，师父于2014.4.8晚19点50分短信开示）',
  ),
  (
    title: '谛深大师开示:为什么小龙女能立地成佛',
    date: '2014.4.2',
    body:
        '海中小龙女, 累世植德本, 曾于广德佛,\n'
        '因地行大力, 供养8大劫, 又于十方佛, 殿中发大愿,\n'
        '智胜得成佛, 其为大因缘,何故落龙族, 因其兴慈悲,\n'
        '时有大旱地, 佛法亦兴盛,众生心中主, 多为自己利,\n'
        '又观龙之族, 多不行本事,时有菩萨日, 土地星晨子,\n'
        '晨子为女身, 发愿做龙属,以多施甘露, 布施干旱地，\n'
        '广德甚欢喜, 龙女得值佛, 当下供龙珠, 龙珠乃生命,\n'
        '是故立成佛。2014,4,2',
  ),
  (
    title: '谛深大师开示:戒如大明灯',
    date: '2014.3.19',
    body:
        '何故佛说戒如大明灯？因五浊恶世中人，因业成识相故，认知为明，如盲人瞎马于於黑暗，依棍杖求路，不能知晓世界之本。而佛制戒律，则能令执见之众不于业中求索，戒到业无，随自己有妄想执着，但为戒所制不能受制于业。就像黑暗中执以明灯，灯到暗无，而戒到业无。\n'
        '我说戒为道果模，如同说灯乃破暗具，无灯暗无破，暗之不破，为说光明，痴也。是故，修行大德，当严净毗尼以证果位。模，果之具也。2014.3.19！',
  ),
  (
    title: '谛深大师说破魔幻',
    date: '2014，3，19',
    body:
        '释迦如来大般涅磐经云：魔王波旬曰，至汝末法，吾之徒子徒孙混入佛门，于寺庙着汝袈裟，坏汝佛法。曲解经典坏汝戒律，以令法灭为吾所用……佛久无语，泪流于面。\n'
        '今者，邪魔外道为波旬使，或以居士、或立教派、或着袈裟、或依邪术、或依神通、或依善使、或称密令、或雄于辩，或广建庙宇穿主衣、坐正座，狂于法界，假佛门名、假佛门事、假佛说经、假世间事、用科学义，渗入蛊惑令众着其魔幻，讲经说法浊于众生界，或玷污、或讥毁、或诱使等坏佛戒律，断灭佛之传承。等等！\n'
        '谛深早于十方佛前发宏誓愿，曰：诸佛莫悲末法弟子遭魔，吾于诸佛末世显一事，令诸佛无忧！吾率众弟子能于诸佛末法，发十方如来神力延佛慧命，以大禅定力于波旬与邪魔外道子孙中种佛种子！恰如污泥浊水生白莲，万方狱火晰金塔！于诸佛法末世，吾能率十方天将，每一天将再率十万天龙八部神兵往护，助：持佛禁戒、为众生表、植众德本之比丘、比丘尼、长者、大士，救信心众，并保不失一有信心人。吾亦统众明察，使诸法王能将邪魔外道训导救之。大众当知，佛法真实不虚，众生因业大罪重故，不能于佛法生信，因狂妄疑惑愚痴故，归依邪魔外道落于六道恶世，因诽谤佛法僧、长者、大士故，遭诸罪罚。谛深告之，若汝受罪，莫惊莫恐，于于佛前，诚信忏悔、称佛名、观音名、弥勒名、韦陀名乃至一菩萨名，便能得我往救脱。\n'
        '大众莫惶恐，于佛有信者，莫怕受罪苦，虽为波旬害，亦为波旬施，或遭邪道术，受其诸大罪，若生忏悔心，于佛之塔庙，一称南无佛，并呼佛哀求，愿吾谛深助，若称有七遍，当下吾施救。令汝诸罪孽，旋而间或轻，信心有增长，随之罪更轻，直至灭诸罪，生于佛坐下。\n'
        '大众莫惊谛深之说，汝等与谛深无色身之连，谛深与汝等不索一钱、一物，亦不谋一面，勿惧勿疑勿忧。谛深已于世间发布相住，若非谛深显前不予理睬，而谛深实不于佛之弟子前显，若有称谛深名于汝前显者，即波旬或波旬使，是故莫忧。谛深住世，为破魔幻，是故不有名相于汝共住，以邪魔外道不能假我之名相施害于众。是故佛于堂上三呼谛深，吾于宝刹名相显前。若有疑惑不信，受罪之时思我良言，便能种信。\n'
        '谛深2014，3，19',
  ),
  (
    title: '谛深大师开示:群兽之喻',
    date: '2014.3.18',
    body:
        '旷野之中，诸多兽群相互厮杀，譬如狼群，亦常遭陵灭。一日狼群遭难，狼首闻佛可救之，于是号令念佛。获得利益便更加生杀。时有僧说之，我可救汝，狼首大笑，群狼亦笑而蚩之，即使佛至，吾等亦不随之，我等只随大王，汝之惹吾，可倾而食汝，救吾等，哈哈，群嚎叫狂笑不已。\n'
        '倾而其人化佛而去，狼首蔑之曰：欲以变化愚我等王者，笑话，并继续号令念佛。\n'
        '今者诸多狂妄群体，与狼虫虎豹有过之而无不及。妄说佛法，不持禁戒，诽谤三宝，狂说开悟获得，成就魔王魔属，悲乎。2014.3.18',
  ),
  (
    title: '谛深大师开示:如何念佛（第四品）',
    date: null,
    body:
        '念佛师父己在体、相、用中讲过多品，今再在体相上略做类注。\n'
        '念佛乃修行气息，亦即：人之命乃气息为之，若无气息生命即断；修行人念佛为命，若不念佛，修行道命即断。有人会疑，那诵咒、诵经呢？诵咒诵经皆依念佛而具，故为念佛之为，为入道之举。而戒律则是道果之模，无有戒律，不成道果。\n'
        '禅那则是修行道果、道命之表，亦即：念佛、诵咒、诵经乃过程，戒律为道具，成道之显为禅那了义。\n'
        '1、念佛分真念、妄念、谤念。\n'
        '一生所有皆归佛所，亦即：生命全部从生命到生活全部皆为佛法，此称如来体，称为真念之体相。真念之人，如来应世。\n'
        '2、不知所以，人云亦云，师之不明，己之盲从，常以解而为道，愿用法理为修，遇事常恢，不知所以，此为妄念体相。妄念之众，因缘使然。\n'
        '3、妄念之中有求念类之记数念佛，分为：\n'
        '恨已罪重，不数即失，记数迫之，此为妄念中忏念体相，此类若遇明师即获救拨，若假精进佛陀接引。\n'
        '于佛信甚，己之未证，始终不移，定要因念得之，此称妄念之中精进念。\n'
        '另有妄念，做邪师狂妄说法，或归依邪师，依邪教之义狂妄求佛，若有过失即生嗔愤，常记数量之与佛叫板，念数之意，使佛来救。是类，常以功德居傲，不思有罪，年岁逼之，临终狂念，实则不舍罪人，此称谤念体相。\n'
        '念佛事大，洗心为之，无思无求必能往生。2014佛涅槃日',
  ),
  (
    title: '谛深大师开示:佛门弟子当知',
    date: '2014.03.14',
    body:
        '若人以对错，判定佛说法，更有甚狂者，以知真学问、所证真道理，评判说佛法、亦或明智人，宗派有实得、亦有种种教、亦有种种学，实证为第一，评判佛说法，或为同门派，相互做评判，虽说是等众，所知无有错、所说皆有据、所依皆为实，我说是诸等，其为太愚痴、其说太可悲、其为不救罪：\n'
        '何故如是说，以真为大过？\n'
        '譬如屎克郞，认屎为佳肴、玩粪理胜人，世间屎克郞，所众皆为道，评判人之食，并以人之行，不合其真理，并谤人为过，虽说屎克郞，的确为真理，所依无过错、人之亦无过，我说屎克郞，攻击人之食，其为太愚痴、其说太可悲、其为为重罪。\n'
        '是故我于法，末世教弟子，不理教派馋、不听同门争。\n'
        '声闻皆当知，切莫在此争，更勿争所为、亦莫争所知。\n'
        '佛法不思意，假若十方界，含靈全共众，无始亦无终，集思共度量，无能知少分。是故大众知，谛深不欺诳，愿众共精进，切勿评判法。2014.03.14',
  ),
  (
    title: '谛深大师开示:修行急不得，也慢不得',
    date: '2013.8.26',
    body:
        '修行要一步一个脚印去修，急不得，也不能慢!在没证得佛所说种种时，就要稳下心来去一个一个的证，这叫急不得。在修证佛说种种每一步之前要精进勇猛，乃至舍弃生命，这叫慢不得。\n'
        '入师父门也一样，只听名声而不能按入门前要求与规矩一样一样的去获得信心，见了师父后有一万个想法要问，殊不知这些乱自心性的问题如同一桶桶的污水，如果师父与他说你的这些问题是罪也是业，他肯定有逆向心理。所以，要进师父的门，需要先把自己的心倒干净。\n'
        '也就是说如果不能用干净的心来求法，则需要一步步的慢慢的在入师父门前先把心修干净，这急不得。\n'
        '另外，如果有人想凭自己的满腹知见来选师父，就如同有人建房选材料一样，房子是他的，不管你给他什么材料，都是为他所用，也就是成就了他的业。所以，师父不会去收这样的入门还自以为有成就的弟子。\n'
        '有人不信佛，或者诋毁佛法、或者身为僧人却沾污佛门，这实际就是在断灭自己功德，直接坠落。这种人的根本就是不信佛，这称为不救之人。\n'
        '所以，师父对求法的人要求非常严格，否则，若人不信，必日后生疑，坠入大坑，害了人家。\n'
        '佛入寂灭前的最后一句话是：第四种僧人称为坏法僧，手持戒牒却不持戒，为吃佛福故驻持道场，佛法末世是种断灭佛法者炽盛。\n'
        '入了师父的门，便不要赞叹世间法人，那样，会毁坏佛种!2013.8.26',
  ),
  (
    title: '谛深大师开示:什么是智慧',
    date: '2013.8.23',
    body:
        '(师父给西藏法王的回复）众所说智是事物不妄得之总称，而事物之不妄又有用不妄、理不妄、解不妄之缘分。所谓缘分，就是说三者虽各不同，但却相关依存。\n'
        '1、什么是用不妄呢?\n'
        '譬如说：飞机的使用，如何使用、如何驾驶是门很独立很系统、很规律的学问，完全的符合使用的规律，称之为用不妄；\n'
        '2、什么是理不妄呢?\n'
        '飞机的本身：包含材料之质理、机械之质理、各种系统之质理所组成的飞机自身之规律合成。如果不能在制造过程中完合理，那么飞机就有瘕疵，称之为有漏。这叫飞机的理不妄。\n'
        '3、什么是解不妄呢?\n'
        '飞机的理、用能完整无误、不过、不非的明白而且表述出来称为飞机的解不妄。\n'
        '目前各宗派所谓的智慧，就是关于世界所有事物之不妄总称。而佛门诸多教派所谓的相似智是对事物解有妄之说，而真实智则是解不妄之说。\n'
        '佛所说智则是一切、非一切、用一切、非用一切、解一切、非解一切，真义谛、非真义谛，第一义谛、非第一义谛；渐、非渐、非不渐；乃至非有非无，非非有非无等。\n'
        '譬如有法王谓十方世界乃至每一微尘皆明称为知，识无妄称为智。我说此为无知、尘智，而说不予知者为知、为智。\n'
        '是故，行者当修，莫以有所得而自鸣成狂以是坠缘。2013.8.23',
  ),
  (
    title: '谛深大师给一些学佛群的回复：修行不能肓修',
    date: null,
    body:
        '修行不能肓修,否则很困难，这称为错用功。譬如:有人欲离开地球却问在地球上向左走还是向右走,究竞向那里走能离开地球?你听的法是盲人瞎法,你硬要问，按他这个法怎么修?在地球上有人说向右去能到西方,你就向右走,走了路虽然也有心得,但那只是走路的心得。因为你走的路与西方极乐没关系呀。'
        '群友問：沒有皈依、沒有受戒，只在網絡上每周五聽一個老師答疑（主要是關於修定的答疑）平時自己打坐持往生廣咒、念觀音菩薩聖號、學習大圓滿前行的共同前行並觀修。\n'
        '以下問題，請胖安師兄幫我請教一下師父，謝謝。 問題一打坐一個小時後腿疼升起，因為疼痛很明顯，無法再專注於佛號，是否可以換個所緣，換什麽所緣比較好？\n'
        '問題二平日精進心不強，有什麽方法可以增強精進心？問題三於平時常念大慈大悲觀世音名號，嘴中雖念但心中並無多少慈悲升起，所以想問問，如何一步步修慈悲心。\n'
        '問題四於日常生活中，是修四念處好還是一直念佛號比較好（對於修定來說）？\n'
        '因為覺得四念處不是學得來的，必須要心相應才能自然處於四念處狀態中（這是師父前些年給東北居士的開示，逢又有居士有此問題，故附說明。）',
  ),
  (
    title: '谛深大师开示:带业能不能往生',
    date: '2013.4.26',
    body:
        '一心念佛就是了业、断业、灭业!\n'
        '佛讲过如何往生，但没讲过带业往生；修净土念佛没有错，但曲解佛经，未证谓证诓骗众生有重罪!\n'
        '所谓往生，指：若人一心念佛，临命终时，阿弥陀佛将行接引往生极乐。此时之人因一心念佛，诸业已断!也就是说，如果不能一心念佛，阿弥陀佛不会接引往去极乐。\n'
        '什么是一心?\n'
        '也就是心中只有佛没有业了!心中都没有业了，其业识就是没有业的，干净的，这个时候阿弥陀佛才显前接引往生。所以：凡说可带业往生极乐的所谓净土法门是波旬为乱佛法之教所设，且勿上当。\n'
        '真正的净土不是这修的，净土也不是这样说的。现在一些重罪之人，以是诽谤佛法必受其报。2013.4.26',
  ),
  (
    title: '谛深大师开示:关于让弟子代转一些问题的公示',
    date: '2013.4.17',
    body:
        '我座下弟子在网络上开博客是师父应允的，很多东西都是经我同意才让发的!\n'
        '问师父问题的人、想问师父问题的人很多，为什么有人得到了师父的解答、有人却没有得到解答?\n'
        '各位缘分声闻：\n'
        '问问题的人分为四类，一类是修行人遇到障碍后，用恭敬心问出问题。这类修行人若得到解答，会对佛、对师父更生敬信而逐步修成道果，这类人师父逢问必答；\n'
        '第二类是狂妄人以狂心修行，遇到障碍后，用恭敬心问问题，这个师父会对治答复!\n'
        '第三类是有罪人、罪重人以诘心问，这个师父不做答复；\n'
        '第四类是重罪人诽谤问法，十方诸佛会永记是人累世难得超脱，师父不作回应；\n'
        '师父令智安等弟子转呈修行人的问题，一个是不舍弃任何一个可救之缘，另一个是不因重罪人的谤问令其坠落而难有出期。各位修行，诽谤、恶意、贪着之心是佛门重罪，邪魔外道尚不能诽谤何况诽谤佛门中人?\n'
        '所以，各位修行，一定要净自毗尼，莫入罪门。2013、4、17',
  ),
  (
    title: '谛深大师开示:什么是参',
    date: null,
    body:
        '参是用自己的识心破所遇障碍的过程!\n'
        '这个过程有两个门，一个是破障立障门，一个是灭除障碍门!也就是常说的野狐锐智门与菩提禅悦门!\n'
        '什么是菩提禅悦门呢?\n'
        '要进菩提禅悦门，走法喜参禅之路，首先要明心!所谓明心，现在很多人都不知道是什么!有人说你要明的是清净心，有的人说就是你自己的妄心，其实，这都是不知道心是什么!\n'
        '众生世界，四生之类所有的心都是因清净妄起，攀缘成种所成!也就是说，你现在用的这个心，是攀缘八识心王，简称识心。\n'
        '既然你现在的这个心是识心，那么，你在进禅悦门时最重要的是要依此心走初禅、用相禅、二禅、三禅、四禅四个地!这四个地主要是在识心的心性上下工夫!这个法现在当来下生弥勒佛在兜率内院讲!一个人，要修得四禅，前提是戒律立本，然后是师父引导!这也是我们常说的心法!\n'
        '一些邪魔外道把五七八糟的东西说成心法，实际上就是罪孽愚昧所致!佛门现在的心法基本已经失传!\n'
        '所以，你问什么是参，师父只能给你讲点皮毛，师父是给茶喝，不是给你讲茶味! 所谓禅修，其根本在入门，然后用功!师父讲四地，中间的用相禅是四地回用，为什么单列，因为从一禅到四禅不能回用过不了地。\n'
        '大家也不要过于追究谁谁如何，自己的修行自己都很清楚，自己做口业自食其果，所以，你要好好发心，尽早自己修证了义诸佛所说!\n'
        '师父给你回复，师父不取分纹、也不要什么名声，师父告诉你，佛法是真实的，只因众生罪孽深重故，而不能敬信!希望你做个真正的佛弟子!祝你早成佛道!2013、4、15\n'
        '（这是今天下午应天津居士问，师父刚刚给我，让我用Q做的回复!）',
  ),
  (
    title: '谛深大师说玄奘法师兴教寺的拆掉因缘',
    date: null,
    body:
        '据传安藏玄奘骨的西安兴教寺面临强拆，引起中国佛门一片反对，那么，兴教寺到底该不该拆?\n'
        '1、佛法是讲因缘、讲实证的，而现在的佛门，从丛林到居士林早已戒律丢失，变成了废墟。譬如：死，人活着是灵与体的统一，而人死了则是灵去了只剩下肉体，这个肉体被叫做僵尸，即使你不烧掉也会烂掉!\n'
        '现在人人都在以自己的想法谈论佛法，谈论经典，而实际上他们根本就没见过佛!恰如人们饿了要吃饭，这饭堂的人把一大堆的饭菜及吃饭经典让人们学、让人们说、让人们议而不去做饭!最后说饭的人累死了、求饭的人饿死了!\n'
        '佛制戒律是让人吃饭!究竟吃不吃是求食人自己的事情!\n'
        '现在彿门中人在世界上引起轰动的全是坐议立谈者，所以，在现实中，人们就得不到真正的佛法，甚至连看都看不到!\n'
        '在人们都处在盲信、盲从的时期，就是来个真的，大家也会把他屏蔽，因为他与他们心目中的佛不一样!也就是说，他们说谁是佛、谁就是；他们说谁有修行、谁就有修行。这样一来，诸多以佛法命名的佛门派别，实际上已经是邪教!\n'
        '所以，现在的佛法如同人死了，就剩尸体了，留着何用?\n'
        '2、玄奘法师是皇帝座下的使者，本来就是皇权的象征!他老人家是有顶的，而佛法是无顶的。他老人家是为皇帝服务的，现在国家不需要僧人为国家服务了，拆庙也是果报!\n'
        '3、其它教派会随时代延续久盛不衰!\n'
        '因为包括基督教、伊斯兰教在内的各大正使教派是宗教信仰问题，而佛教则不是宗教信仰,佛教是被不懂的人变成了宗教信仰!\n'
        '宗教信仰是不改变人包括心理、生活需求现实等等的灵魂活动，也就是说宗教本来就是佛门所说的六道。佛法是出六道法，是洞彻一切、包含一切的妙法，佛门是度脱地，也就是六道与清净世界的转折地。诸佛世尊因慈悲众生、因缘住世，难值难遇甚为稀有!遇佛出世当生敬信，若不敬信甚甚可惜!\n'
        '⋯⋯⋯\n'
        '既然佛法已经在大众中没有了，还留着那尸骨做啥?拆了就拆了吧!\n'
        '2013、4、13\n'
        '(我记得很清楚，前些年师父给我们讲，我们建寺庙全部建成纯木构，主要原因是：如果法灭，众生拆也好拆，也不会有垃圾!摊上性急的，一把火烧了省事、他省事我也省事! 当时我听了这个话，不太理解，兴教寺的遭遇，还真让我明白了师父的慈悲!)',
  ),
  (
    title: '谛深大师关于僧衣的开示',
    date: null,
    body:
        '师父身上穿的衣服，全是我们这些弟子供养的。\n'
        '师父说，衣服不是根本，和尚是根本！所谓僧衣，就是僧人穿的衣服，没有特别规定。庙里的僧人，依制穿特定的衣服，称为制衣。\n'
        '什么是制衣？师父讲，就象警察局里的人上班穿制服一样，便衣警察身份就是警察，只是没穿制服罢了。另外,人假不了,但衣服是能假了的.\n'
        '师父是个独行僧，没有固定的格式，只要是众生供养了他就用。',
  ),
  (
    title: '谛深大师开示:为什么有人念佛却遭横祸',
    date: '2013.3.3',
    body:
        '弟子智安问：一佛友在网上学佛空间说，有佛友一行去为亡故佛友助念往生，路遇横祸，一死三重伤，“被助念人”所在村庄许多人从此不再信佛，请师父开示。\n'
        '谛深大师说：智安，譬如有人被人欺污，或盗、或伤，此人必对欺之之人终生难忘，亦即时时念之，此称谤念、嗔念或恶念。\n'
        '是故，智安，念佛有三种念，一是真念二是妄念，三是恶念、谤念或嗔念。\n'
        '1、真念。真念之人，或因自性见佛，成十足信心念佛，或因殊胜缘分成真心、正心念佛，称为真念。是诸人等，或当下见极乐世界，阿弥陀佛观音势至显其境界，即得往生；或一生平安，身无病苦，临命终时，阿弥陀佛与诸圣众现在其前即得往生；或念佛生命种种善境、种种福报现在其前，即得得证圣人果位，觉悟众生拔离罪众，得菩萨道。\n'
        '2、妄念，又称宿命念、显因念，即：无意之中随口而出佛之圣号。如是之人，若未遭邪师说法加持，于妄念中，能得善知识现前，引导入门，步步修证，或当命终之时，三圣现前接引极乐，或转世种性，发芽入道，得佛加持，修行成道。若遇邪师说法，遭魔挟持，能泯灭善种，渐入魔道，受堕落罪，或当世业积，毁坏善种，显嗔念相，受诸业害。\n'
        '3、谤念（或称嗔念、或称恶念）。如何得成谤念？未得大善知识与清净僧引导，遇邪师说法，不能正心入念佛门，遭邪幻术，成谤念罪。是诸人等，若遇善知识引导，为求灭罪，会罪孽逐渐消灭，入正信门，是等或当世即得诸罪消灭，或当世往生，或来世往生；是诸人等若遇邪师说法，为求灭罪，却心持疑惑，不能得出，或听邪师说法，以自己知见习气故狂妄自大，对善知识行大诽谤，行大恶语，时常对佛门道人行诽谤法，成恶念、嗔念，如是之人，念佛之念入谤念门，成大罪业。亦有众生做恶求佛哀佑，或为求消灾，实并未生信，虽相念佛，却成诽谤；其等罪人一罪消除，便有信心，二罪未除，便生疑惑，以是生不信心，不找自身原因，不自忏悔，狂心生嗔，如是之人，多信邪师，不信贤圣，或当世遭横，获不定报，或一生多病，不能得除，死后堕落，或临命终，遭邪幻术，入阿鼻狱，此皆因谤佛或谤贤圣故，遭此恶报。\n'
        '何为邪师？若有自称法王、活佛，或比丘、比丘尼优婆塞优婆夷，以自己为圣，诽谤讥毁贤圣、头陀道人、乃至诽谤外道，或有人狂智现前，以我慢嗔恨，诸等恶法，诽谤余乘，皆称邪师，如是人等个个自称证无上道，亦个个皆有诸多信众。释迦如来戒告弟子，不谤外道，更不谤四众，何况诽谤大善知识。\n'
        '是故，诸位同参，切勿诽谤佛法贤圣，切勿讥毁佛门四众，切勿诽谤同道、异道、外道乃至邪道，若有如是等心，令当忏悔。\n'
        '智安，这个开示，只传给大戒比丘、比丘尼，菩萨戒优婆塞、优婆夷及我座下弟子。余者不传，以防令罪孽众因诽谤嗔恨师父故遭遇不测。(2013年3月3日)',
  ),
  (
    title: '谛深大师开示:破灭瘟疫善告',
    date: null,
    body:
        '斋戒三日，且念阿弥陀佛，已得病，三日后当即消除。未得病，不受瘟疫之苦。\n'
        '\n'
        '斋戒内容：\n'
        '1、不杀、不盗、不淫、不妄、不看电视、不听一切歌曲和音乐\n'
        '2、具体保证不食荤腥；不食葱、蒜、韭菜、洋葱、蛋类、蛋制品、肉制品、乳制品；\n'
        '3、念“阿弥陀佛”\n'
        '已染病者，三日之后，瘟疫即当得除。',
  ),
  (
    title: '谛深大师与基督教传教士的一番谈话',
    date: null,
    body:
        '今天一个基督教传教士在布道的时候，师父专门给他讲了人的来处和去处问题。\n'
        '有关人的来处？传教士说，是上帝造了人。师父问他，上帝怎么造的人？你见着没有？这个你没有证明，也没有逻辑，所以你不能说是上帝造的人，但我可以说人是如何生、从何而生，因为我有法证、有道证、有种种证。人是种种因缘和合而成，上帝为众生世界种种层生。种种因缘和合形成缘分，缘分成相、形成诸识。天人识心形成之后就变成天人种，地狱识心形成之后就变成地狱种，人识形成之后变为人种，如是成人。欲界（天王、天主、上帝）（人王：圣人）之下，诸多众生转生为人，为业识流转成人识，随着业识的流转成种，种性发芽成胎、转生成了人。\n'
        '目前人们都接受的一种说法是，人是由类人猿进化而来的，这不科学，用逻辑推理看一看，大家就明白了。如果人是由猴子变猿，猿变人这么变过来的，那猴子是一只一只变的，还是一群一群变的，还是一下子全变成人了？如果是一只一只变的，那么现在山上的猴子还是在一只一只变成人、并走下山来，可是这种现象现实中并不存在。如果是一群一群变的，这种现象也没有。如果猴子是一下子全变成了人的，那么山中现在应该没有猴子了，从逻辑分析看，各方面因素都证明，人不是由猴子变的，所谓人是由猴子变的是一种推说，是一种假说，所以，由猴子进化成人这种说法没有对的地方。\n'
        '人究竟哪来的？人与十方众生（包括上帝）是在不断随着自己种种业障的变化而转化的，这叫不断轮转。在轮转过程中，种种罪孽造就认识，种种认识就是种种众生的种性生处。所以人应该多做善事，应该有智慧，不愚昧，这样才不会随着六道去轮回，这就是佛门所讲的六道轮回。\n'
        '基督教是一种鬼神教案，所谓救人，实际也是在欺骗，很多基督教国家都在划着十字架，念着上帝救救我吧，把炸弹扔向人群，可悲啊！（此法师父2005年以前在崂山给弟子讲过）',
  ),
  (
    title: '修行日规',
    date: null,
    body:
        '朝时 4：00 打板 盥洗\n'
        '4：30 早课\n'
        '午时 3：30 晚课\n'
        '夜间 7：30-9：30 坐香。小香每柱20分钟，大香每柱45分钟。延香禅行约一刻钟。\n'
        '9：30 止静\n'
        '随此修行，受持不杀、不盗、不淫、不妄四戒后，将得到师父加持。\n'
        '注：在家道人，晚课可于7点补做；出家比丘月一、十五课后延香颂戒，道场需关门半日，日常出坡不得多于月有5日，稻谷收获可视机多加。',
  ),
  // (
  //   title: '摄缘',
  //   date: null,
  //   body:
  //       '各位弟子，入于佛之法座下，是称入十方佛摄缘法。十方世界妄心攀缘成因、因因造业，业成缘分、缘缘相扣、成就缘起，缘起成像，造诸种类。种类起缘，各业互牵，又造共业，诸多种类，为攀缘故，递弱为食，互相凌灭，灭后互转，成就六道。\n'
  //       '诸善因缘，汝等因慈悲故而获救度，是大果报，非一世、两世、乃至千世万世无量世劫因缘所至。汝等无始劫来，种种修行造种种善，成就善种，善种量吸成因，滋润伸展，吐善成根，蔽恶纳善，获普洽甘露，享六波罗蜜，于是善成佛缘，生成佛种。尔等佛种发芽，大福报现前，入佛门下得获救法，此称摄缘。摄缘既成，成佛国土，此称成佛。摄缘乃十方诸佛兴慈悲法，是十方诸佛甘露施法，是十方众生成佛之法。\n'
  //       '释迦如来、三藏十二部，弥陀如来四十八愿，乃至文殊普贤、观音势至十方大善，所行道法，皆摄缘法。\n'
  //       '。。。。。。。\n'
  //       '（注：摘自谛深大师《普修行藏》，因为这是具戒比丘与具戒大沙弥专用，大部分章节非具戒者不能传阅，望广大修行善解。）',
  // ),
  (
    title: '谛深大师开示:什么是转法轮?',
    date: null,
    body:
        '譬如：人们从家里出去又回到家里，称为出去转了一圈。因为从“一个点”又回到了“这个”点！\n'
        '佛门讲经是从头讲到尾，一批人受益又有新人到来，必须回到头再讲，这叫一圈一圈的讲，也称一圈一圈的转，更是一圈一圈的救度苍生。故此，将“讲经说法的遍数”形象化为“转法圈”数、或者“转法轮”数。我们常说的“转法轮”是指“佛经讲了又讲”。\n'
        '为什么佛出世称为转“大法轮”？因为，诸佛驻世，广施善法。每尊佛出世涅槃至其法灭度，称为一大圈，也称为一大轮，形象称为“转大法轮”！\n'
        '佛灭度后，诸天人师菩萨“传承佛法”每传布一遍都能救一批受罪众生。所以，我们的道场要“法轮常转”！这其中也不乏有人用“卍”字为心更为形象的画了一个轮子以示弘法！藏密的“转经”只表恭敬，是看信众信心所用！执着轮经以为修行，则为着魔！\n'
        '“法X功”不懂佛门常识，用转“轮子”作为依据到处坑蒙拐骗，着实可悲！\n'
        '很多居士问怎么有人学法X功能治好病？其实，病分多类，诸多因缘，都能治病。譬如：有人得了病，万医不治，有一天出门摔了一跤，结果大病痊愈，难道，我们有病就要摔跤不成？\n'
        '世界本来虚妄，不管什么人，只要你执着的做某一种事情（包括子午虚有的虚妄之事）都能获得结果。这是众生的罪苦本缘，所以，佛门设了不虚妄戒，以防善缘众生误入歧途！【 1999年于庐山东林寺有二僧人遭法X功着魔群人黠问，师父做此开示！】',
  ),
  (
    title: '谛深大师给请法者的开示',
    date: '2013年1月12日',
    body:
        '1、谛深大师开示：阿弥陀佛，若说修行，我无始劫来所遇众生皆在修行。蝼蚁百虫，狮狼暴兽恶鬼无不如是。所谓修心，亦复如是，何故是说？众生心境本为一体，妄有妄体，真有真在，无可斥处。\n'
        '所谓练心，孰不练心？所谓心者汝心何物？若汝所谓自己之心为如来，则汝已成佛，何来问我？若非如来道果，则为盲修瞎练。 是故汝之修为来之罪染。汝着邪师误导不能自拨，如何证得如来妙果？释迦如来说，若我于燃灯佛所，有法可得，燃灯佛不与我授记，君可明乎？ (某法师请法曰：师父，您说我业障现前，请问师父业随什么而现？现了是否就了结了部分业呢？还是心上的历练功德提高的自然消业？了就是心底的历练成就消业障呢请师父为我开示。相由心生，境随心转。我发现自己消业出现的事越来越大了，是考我呢？自然的考试？自然的表演？自然了就过此关了呢？阿弥陀佛)\n'
        '\n'
        '2、谛深大师开示：并非如此，所谓修行心实为业习，所谓众生实为业习德相，只因众生道途法染而难于自拨，不能求证如来妙果，是故众生等修行如是之报难于救拨。是故十方如来皆以如是因、如是缘、如是果、如是报、如是本末究竟等轮次授记，又以小龙女当下成佛而勉智者。 (某法师曰： 阿弥陀佛，法师真是妙不可赞！ 好象能懂，境随心转，心境一如是吧？众生身皆也为业报随业流转，现报身所谓修行。业报苦极无立足于享乐，业报转好，痴再造业又落轮回。业海茫茫痴为根，业习深重盼慧根，慧生还须行精进，否则难断五欲根。)\n'
        '\n'
        '3、谛深大师开示：我语心为自性这不是如来真实意，我还有事，祝你早成妙果。阿弥陀佛 (某法师曰：我语心为自性，所谓修心是法相，自性破出甚也无有，故无有心说。《金刚经》曰：心无所住而生其心。)\n'
        '\n'
        '(谛深大师慈悲用智安早年供养手机，短信回复，那手机写字很困难。2013年1月12日)',
  ),
  (
    title: '谛深大师开示:佛门师训',
    date: null,
    body:
        '1、常随众行参悟佛法，没有开悟不得给人示法，随众行时，观众之行悟己亦同，当知不说明说、不苦明苦、苦即因缘当真忏悔所做苦因。\n'
        '2、明清净心见自性圆满周遍为初入菩提道，当视众生苦执为悲，立大誓愿令其解脱，勤加修行成就佛道。\n'
        '3、佛魔无争，但魔有争，不与其同道人争、不与诸外道争、不议论佛法。\n'
        '4、佛法是修行成就实相之法，所谓实相即不生不灭为实，非说、非为、非不为、非辩、非不辩、非有非无、非非有非无、非空非相，凡是自己未证得佛法即以法师为居即是修堕落法。\n'
        '5、佛法修持只以佛说经典为证佛法之用，不得以任何人说之法之术为经为用。\n'
        '6、严净佛制，不得乱建寺庙为鬼魔用。（2004年师父为座下入门弟子制）',
  ),
  (
    title: '谛深大师开示:谤师无碍，行恶必报!',
    date: '2012.12.30',
    body:
        '今天有人问：其父因摔碎菩萨像于不久遇车祸横死，师父做如下答复！\n'
        '佛菩萨住世是慈悲救度众生，度诸疑谤与不信、毁誉重罪之人！不会因如是之故而施恶应于斯！但如斯等辈因罪恶感召，遭邪师引导而不能、不想、甚至毁坏救他之善，于是不进善门受护得救！其必然被自做之恶来报！\n'
        '譬如：一人因得罪、中伤鬼神力王及所谓人物而遭追杀，半路遇假扮或自无能力却谎称能救之人邪说救之；后其遇能救其之人施救，不仅不信反恩将仇报，施救之人只能回避，并将其拒之门外！结果其必遭报！\n'
        '问事者其父所遭横祸亦复如是！并非摔菩萨像遭菩萨施报，而是自己有重罪当报又遇邪师说法不入正门而不能被护受报！\n'
        '是故师父说，谤师无碍，行恶必报！\n'
        '2012年12月30日',
  ),
  (
    title: '谛深大师开示:佛法谁来灭度？（第二品）',
    date: null,
    body:
        '释迦牟尼佛于大藏经中有一喻，曰：吾住于世，如雄狮，百兽皆畏而敬之！\n'
        '曰：吾灭度后，如狮刈卧于林，百兽敬畏远之！数日之后，狮尸腹中生蛆，其众争食尸之腐肉，其尸仅存毛后、轰然坍塌、众蛆毕露。百兽视蛆不屑，唯蝼蚁争啖肥蛆！\n'
        '今者，佛门皆应佛喻，诸多和尚、居士未证谓证、未得谓得，个个自称佛之弟子，日日吞噬佛福佛报，皆佛留法体中蛆欤矣！故此，诸邪魔外道侵我佛法如蝼蚁食蛆之易！众生之悲末世之苦也！\n'
        '悲哉！',
  ),
  (
    title: '谛深大师开示:佛门禅语——开口讲话！',
    date: null,
    body:
        '一日，某老修于山中静坐。\n'
        '禅僧跪拜！\n'
        '多时无语！僧举首见法板书：汝之语与吾语无异也！僧悟！绕圣三札，曰：施与人，顺其人心而令其变，勿逆！善于人勿由欲取求其善；德与国惩其病处，无惧于毁！\n'
        '是故，僧，云游挲婆开口讲话！\n'
        '释：毁——诽谤.',
