  (
    title: '谛深大师开示:中国及一些佛法国家何故落后',
    date: null,
    body:
        '诸多众生对美国及西欧百姓生活优于中国及印度、缅甸、泰国等佛法国度，疑惑极重。何故有此差别：\n'
        '一、佛在兜率内院法浴弟子，对大德降世有三大责请：\n'
        '1、五浊恶世誓先入；\n'
        '2、罪苦众生为父母；\n'
        '3、成佛道者却众生苦毒，否则，无有慈悲！\n'
        '在大德高僧留的佛门早晚课颂中亦以---五浊恶世誓先入之开请！\n'
        '二、娑婆国土中，诸罪苦积聚地，谤佛、谤法、谤贤圣之邪魔外道兴盛，是故，世报无福！西藏地区、印度、中国等当属此类！若弘扬善法必显福报！\n'
        '娑婆国土中，一些因缘众生积聚地，不知佛法只受果报，美国等发达国家当属此类！是故，莫多疑惑！',
  ),
  (
    title: '谛深大师开示:谛深大师关于戒律的开示',
    date: null,
    body:
        '戒律的根本是离苦之规成就之律，须当机授之、当机应之！\n'
        '若不当机，戒既是苦也是罪！\n'
        '譬如有人入狱10年，坐穿牢底其受罪莫大！\n'
        '而如若有人因戒律闭关10年，游戏神通，其乐始终，心旷无限！\n'
        '是故：修行人当记，戒律如若不能修持而狂心用之其无过于生身落于地狱！这亦是卢舍那佛制戒---严禁私研戒律的谓之盗戒名相之本！\n'
        '劝戒修行人，择师受戒修行谓之佛子基石，切莫，不明戒根受名相戒！否则，出家收受十方供养，必堕无疑！\n'
        '戒根也就是常说的要有戒体之根！\n'
        '问：戒根就是戒体吗？\n'
        '戒根也是戒体的根本：信心！\n'
        '戒体是建立在戒根基础上的受用相---譬如：你走路，明白了方向，沿着路向前走，尽管有种种障碍，也能到达目的地！\n'
        '路就是戒，向前进就是修行！而方向则是信心！',
  ),
  (
    title: '谛深大师开示:什么是佛法',
    date: null,
    body:
        '佛法实际上就是救度众生的法。佛的含义就是彻悟。佛法有两种解释：第一种解释是出世间解释，也称为彻悟，第二种解释是救度苦难众生解释，也称为破障；这两种解释对修行人来说，彻悟就是成佛，对凡夫俗子来说，觉悟就是佛法。什么是觉？觉就是认识，认识的含义是探索、解疑、解决问题，悟就是明白，探索过程中，解决种种问题的途径与道理，就是觉悟。世间人的科学研究体现的凡夫俗子的进步与发展，对罪苦众生的苦难没有用处。\n'
        '彻悟就是没有障碍，凡夫俗子无从得知，怎样才能做到彻悟？须知凡夫俗子的觉悟过程、无始无终、无头无尾、永无止境，须知世界妄尘皆是凡夫俗子种种觉悟所成，明白这种道理也称为看破，要看破这些事情需要累劫修持，然后才能放下、彻悟。\n'
        '圣人、佛陀与凡夫没有区别，因为那根本就不是一回事，怎么区别？一个是凡夫用攀缘心无止境的攀缘追究下去就认为是佛法了，其实，这恰恰是堕落！所以，尽管众生皆具佛性，不管你是和尚、还是自谓有所得，只要你一天不彻悟就是凡夫。如果一个人没有成就，却给众生说法，那么这个人就在害人害己！',
  ),
  (
    title: '谛深大师开示:盲人与象——谈议论佛法',
    date: null,
    body:
        '一日，盲人之国众盲人因摸象纷争。长者振木惊堂，曰：“吾与象处几十载，其毛之长短皆知也，汝等争之熟非当断！\n'
        '一摸耳者曰：象之耳背尖之二指处，何也？长者曰：豆大之痣！\n'
        '一摸腿者曰：象之左前腕处，何也？长者曰：寸长之疤！\n'
        '对证之时，一明眼人哑言而笑。长者怒而斥之曰：汝识象也？名眼者答：识！\n'
        '汝知吾象尾根何也？名眼者答：“不知！然，可视而告知！”群盲人哄堂大哗！\n'
        '异口同声曰：谁非视而告知？哄出盲门！\n'
        '明眼人叹曰：哎，虽知象莫深，然未见真象也！此国永无天日矣！\n'
        '今者庶人谈佛，盲人摸象耳！',
  ),
  (
    title: '谛深大师开示:供养师父的条件',
    date: '2012.12.17',
    body:
        '智然发心想每个月供养师父，师父说你得持十条戒!\n'
        '1、不杀生，不食众生肉，不与杀生人共住!不予人众生肉!\n'
        '2、不盗，不取非人予财物，不观路之有遗!\n'
        '3、不淫，不与罪人，外道人乃至畜牲男共住!不沾染或被人沾染!不与父母兄弟姊妹情感沾染!\n'
        '4、不妄，遇事除职责中不说，当知有说即妄!若为道修，道行，道延故可证说!\n'
        '5、不贪，于种种官权、于财物，乃至衣物，不做少许用外多求多想!\n'
        '6、不嗔，不于种种逆、种种难，有不顺思、不顺想或不如意想!更何有报复想!\n'
        '7、不痴，不做道外、戒外、用外、理外，非贪着悦己外思，更况有做有行!\n'
        '8、不慢，于种种因、种种缘、种种果、种种报，不兴有比对、比较、比量思，更况贬视有余!\n'
        '9、事师尊长，对一切三宝相，亲里长者遇当以事缘之，尊敬缘之!\n'
        '10、威仪，行驻痤卧皆应有被誉之功!并有多效仿!\n'
        '师父说：“佛驻世制戒，不制戒佛法无法传承！”平日里，师父亦一再叮嘱：“师父这里什么都有，什么都不缺！修行要修心，师父要的，是弟子们精进修行的心！师父希望弟子们都能够好好发心，以大行力冲出六道、不再受罪苦侵扰！”\n'
        '（智然短信回复：阿弥陀佛，师父！智然感恩师父！弟子会谨持佛戒！不负师恩！2012年12月17日）',
  ),
  (
    title: '谛深大师给智然授法名时的开示',
    date: '2012.9.19',
    body:
        '称我谛深弟子，需归依佛！心归依佛，诸业转福报！诸罪自然了！何谓心归？凡夫入佛门就种个种子，累世在六道轮转！若遇明师，佛陀住世，则得了结！若不遇明师，盲修瞎炼则会佛种变坏难有出期！\n'
        '所谓心归，就是心是佛的！而凡夫俗子的心或归丈夫、或归妻子、或归子女，最好的也就归他自己！其给佛的或百分之一、或千分之一、或阿僧祗分一、或累劫念有一！等！故其大多谓归而难获实证！因为他并非佛子！\n'
        '所以，众生即使出家也有诸多难入佛门！在家就更不用说了！\n'
        '智然，师父收你，是你与师父缘分天资，但未来全取决于自己修道！修道就是修心！你天性有决定性，但若用在别处就成业像，用在修心，则有道果！好好用心！\n'
        '(2012年9月19日)',
  ),
  (
    title: '谛深大师给“智然为什么在拜佛时流泪”的开示',
    date: '2012.9.18',
    body:
        '好好用心，皈依师父后，心要用在修行上，不能用在业上！把所有的业都围绕着佛法去应对，叫把心用在修行上！若围绕着业用佛法，叫把心用在业上！心用在修行上，会精进成就！心用在业上会福报享后堕落！\n'
        '福报对修行人来说是福报，对凡夫来说是业报！师父常说福报就是业，是对罪孽深重的人说的。\n'
        '早晚课流泪是第八识感恩种子开始在第七识中发芽！而这个时候第六识也就是意识并不知道！什么时候意识才能知道？等芽体在因缘中成形，眼耳等开始受相，意识才能知道！\n'
        '这个对话你可以给你自己相关人的讲讲，包括僧人！好多人都在肓修，未证谓证，其遇果报并不知！2012年9月18日',
  ),
  (
    title: '智缘在群里写给同参的心得',
    date: null,
    body:
        '我是智缘，我跟师父已经10个年头了。各种殊胜的经历很多。我仅讲一下，在崂山的一次经历，当时有很多人在现场亲眼所见。\n'
        '2009年6月份，我随师父一起受茶叶店两个经理邀请，去崂山泉心河茶场喝茶，当时开了两部车。与师父一起同行的还有智因。茶场的金场长接待了我们。正在喝茶的时候，茶场的一个雇员满脸青紫，肿得如猪头一般。师父讲，只要你们求，求什么，师父应什么。 师父讲了这个话后，场长与他的工人们并不在意。满脸青紫肿胀的工人不断的呻吟，并口里念叨，疼啊疼啊。\n'
        '师父问金场长，他怎么了。金场长说，他前两天让山的马蜂给蜇了。到医院打了两天吊瓶，总算保条命，但还是疼。师父问，有这么厉害啊？金场长说，这个山上的马蜂能蜇死牛。师父说，你们要是相信师父，在师父眼前念一句阿弥陀佛，马上就好。但他们疑惑不信，并没有按师父说的去做。\n'
        '就在这时，茶亭飞进一只山马蜂，因为是在山上搭的是露天亭子，马蜂直接就落到金场长的脖子上，只见金场长用手扒了几次，结果还是被蜇了，并且惨叫着蹲在地上。这时，师父发话，让我给他治一治。说实话，我当时非常紧张，我也不信师父让我给他治就能治好。师父说：去，给他治。我按师父说的，用咒子在地上捻了一捏土，放在蹲在地上的、嗷嗷叫的、他的被蜇的伤口上。 当时我不敢相信，他马上就站了起来，很舒心的说，好了，真好了！连口称师父是大师，是神仙。\n'
        '下山后，师父给我们讲，他罪孽深重，没有佛缘。救了他，居然称师父是大师，神仙，就不念阿弥陀佛。师父讲，若他能念一句阿弥陀佛，这世他就能跟着师父直接出离六道罪苦。\n'
        '有了这次神奇的经历，我反复思维，学佛出离六道，何等艰难。虽然这件事是我听从师父指令，亲手所做、亲身经历、虽然这件事情还是我在这么多人面前（师兄弟及一些凡夫俗子）亲身经历，但是我对佛法的信心和对师父的信心还经常反复，甚至还有不恭敬的想法。细想一想啊，这是我在师父眼前，其他不能在师父眼前，甚至是被邪魔外道熏染的人，对佛法生个信心，太难了。六道众生出离苦海，面对罪孽障碍是有多难啊。所以师父教导我们不能怪呼普通众生对佛法有疑惑，对比自己，想一想真是惭愧啊。\n'
        '今天因为智安师兄处理群里事情时有过错，师父让我们思维，如何面对众生，如何慈悲众生，如何发心，如何修行。想起我的修行之路，我面对对佛法有疑惑，对师父有疑惑的人生起了慈悲心，自己也有了真诚的忏悔心。我也深深理解，议论佛法，不信因果多么可怕。佛法真实不虚，希望大家精进修行，早日出离六道。（2012-6-9）',
  ),
  (
    title: '谛深大师对想入师门修行者的开示',
    date: null,
    body:
        '打坐不能持咒，打坐就是打坐！持咒、念佛不是打坐！\n'
        '入师门修行不是让你带着种种执见来了断，是让你带着信心来修行！这也叫皈依僧！你在尘世听得太多、懂得太多会形成很多疑情执见！自然屏蔽修行信心，这就叫障道！所以，佛门说缘分！缘分说到归根处也就是个恭敬师父所能有的道缘、法缘！佛法不度无缘之人！\n'
        '慈悲众生，是四大之中的上四大之根！只要众生有缘分，就要设法度！这里面什么缘分都有：善缘、恶缘！善缘好说，恶缘怎么办？所以如来住世设种种道度众生！善缘在眼前做使者、侍者！恶缘在远处做声闻应化，转善后入门成大阿罗汉！\n'
        '师父对弟子一样、对众生一样！但众生因缘不一样，其对师父的心也不一样！进师父的门，就要真真正正的做到师父怎么说就怎么做！印证了信心就升起来了！师父不能要求所有缘分一下子对师父那么十足的信！因为众生有罪呀！众生有了那么多的罪孽，你说什么他能放下？但你让他多获得罪孽入罪孽法他能接受！就像人为了要钱才到佛门一样，你让他有了钱，很快他就成了你的人！所以，师父听说你们要皈依，很高兴！但，你们拿什么皈依？拿一肚子的执见皈依？那不是要师父皈依你的执见么？\n'
        '师父盼望着这一世能多些时间与弟子们在一起！世间无常阿！所以，你们一定精进！这个精进，不是说说就行！需要做！这个做就是你们说的修行！好了！智安！多与缘分弟子相处！以便未来托个佛缘！放下吧！师父等着你们！',
  ),
  (
    title: '谛深大师开示:皈依佛、法、僧后为什么要供养?',
    date: '2012.2.10',
    body:
        '供养乃显缘法，供养亦显心法，若无供养不显缘分！是故，佛陀托钵化缘，为救众故！\n'
        '善者求道切记：佛法不度无缘之人，如果有人出入僧院、拜师修道而不行供养为波旬使！\n'
        '第一：若人皈依佛后，不行供养，此人有三罪根未除，一者我慢狂妄，二者假佛行恶，三者玷污使佛；此人未来必断佛种，堕无间狱！\n'
        '第二：若人皈依僧后，但求布施，不行供养，此人为波旬使，人身过后必堕地狱！\n'
        '第三：若人假僧为依，为满足私欲不行供养，以得多少与做交易心，此人当世不得有出，来世堕落地狱，未来为最难度人，是故此人于六道轮回，罪苦难拔！\n'
        '若皈依佛门，先当发心，行大供养，如是乃能获得佛陀加被，若供佛心诚，求道心切，当世必获成就！\n'
        '各位佛子，师父不允弟子以种种名、种种行，索要众生钱财，是断罪孽缘分！若寺院住持、僧人无所求故，收取供养，此为大德慈悲结缘，亦是众生得度之始！若不供养佛、法、僧者，说能出离苦海，如同牛羊食画中青草，真乃罪身愚痴！是故求道之人当多行供养！2012.2.10',
  ),
  (
    title: '谛深大师开示:娑婆世界有几座鸡足山',
    date: null,
    body:
        '师父于12月24日便访鸡足山，26日因寂光寺主持演尘法师问所说。\n'
        '云南鸡足山，就是佛授记的鸡足山。\n'
        '据佛经记载，迦叶菩萨所住鸡足山在印度，并为此导致史学界、经学界及广大僧众对云南鸡足山的真伪产生了争论，众多僧人已经记为准，认为云南鸡足山不是佛授记的鸡足山，因此不是迦叶菩萨所住道场。\n'
        '并非如此！\n'
        '第一，疑惑来自自心。这是佛法所要破的根本障碍，任何修行不能证得佛法，获得佛之珍宝，主要原因就是自己的执见偷走了他的信心，师父境界中亲眼所见云南鸡足山确实迦叶菩萨住，衣钵金光灿灿，住处金光所罩，非常殊圣。只是金光罩外，由鸡足山顶到鸡足山体，光景暗淡，所有寺院都污水横流。。。。。。\n'
        '第二，娑婆世界，迦叶菩萨所住七十二应变处，皆与当处缘份称为鸡足山，其中，云南鸡足山就是一处。其他七十一处，遍布整个娑婆世界，四十九个缘份要处。当前中国为一因缘处，仅此一处就有几座称鸡足山，皆为迦叶菩萨住。\n'
        '第三，另有化身释迦于十方世界坐于无数菩提树下，为演说法。每一释迦又有迦叶菩萨七十二应变处，为传衣钵称鸡足山。\n'
        '各位大德，各位修行，末法时代，种种疑惑灭种种法，种种法灭，断种种法种。是故为修行故，莫有疑惑。（若有疑惑，可龙宫阅藏。）2011-12-29',
  ),
  (
    title: '谛深大师开示：公告',
    date: null,
    body:
        '11月17日，师父遇见一个被普陀山某寺院出家僧人坑骗的居士，坑骗数额30多万，几乎倾家荡产。故，令弟子特发公告如下。\n'
        '第一，一切以帮人消灾延寿为名，收取钱财的个人、寺院住持，或佛教协会等相关机构工作人员，或涉及相关行为的和尚、居士等，皆为邪魔外道。\n'
        '若寺院以水陆法会，超拨，超度、放焰口为由收取法事费，即使为众僧人发放月钱，皆为波旬住持，非佛子住持道场。僧人出行当向客堂申请，若客堂允则行,不允不行！若客堂允不予行资，当时中默待,自化缘分,行乞出行！不强行索取、不与众声张索要！可称“檀越慈悲”一句静候缘分！\n'
        '第二，寺院买卖流通法物，皆为邪魔外道所行，非佛门人所为。\n'
        '第三，任何对佛说经典，佛门事情进行解说，讲解，印制成册到处乱发宣传用品的行为，皆属邪魔外道所为。\n'
        '第四，善男信女在寺院僧人无所求的情况下，发心供养当取；寺院不以有所求心收取供养当取。若寺院僧侣不索一物一钱，而众生欲做善事发心供养此为佛子道场事。\n'
        '第五，一切法物、经书若众生索要敬请，可布施捐赠，但不可收取任何费用。\n'
        '缘份众生当知，出家沙弥尚不能沾钱沾物，不能近女色，不能乱结缘份，何况大戒比丘？\n'
        '现在很多罪孽之众住持寺院，心术不正假我佛赐善衣，广行贪欲诓骗众生；诸多罪孽之众以贪欲心落发出家，假佛威德到处行骗！他们不是在弘法利生，而是在借法害众；另有很多重罪之人广为宣讲邪知邪见，故特发此告，望缘份之众切勿上当受骗，切勿发了善心不得所求，却作了魔子魔孙。\n'
        '注： 讲说与解说不同，讲说是根据不同地点、不同语言、不同习俗，依据佛经做适应性翻译。解说则是以自己执见解释佛经，譬如，佛于《楞严经》中，棒打富楼那等大阿罗汉...如汝所解...指的就是解说。大阿罗汉解说佛之经典，尚称外道典籍，何况罪孽众生。2011、11、19',
  ),
  (
    title: '有人在青岛论坛上弘法受攻击，谛深大师所做开示',
    date: '2011.3.6',
    body:
        '这是我师父刚给我的短信，我发在网上，大家一起看看，大部分与论坛不同，因为在论坛上这样讲，他们（包括所谓弘法的那个人）会生瞋心。\n'
        '在家人得学会自救，要能保护自己，然后才能救他，连保护自己的智慧都没有，你怎么在有狼虫虎豹的世界救度众生？不要以为把佛门的一些东西传阅就是弘法利生，这叫愚痴！佛的法不是你这么弘扬的！如果这么办就能弘扬佛法，十方佛都不用出世！十方菩萨都不用发大愿力！在论坛上被骂的这个人并不清楚，你这样做，让众生生了嗔恨是自己的大罪孽，会令自己堕落！因为人家不听你瞎说倒还不会谤佛，你这自以为是以我慢心一说，让很多人谤了佛！\n'
        '记着：佛法在佛嘴里是佛说，在魔嘴里是魔说！怎么判别？就是当你说法时令众生堕落了，那就是魔说！当你骂人时让众生得利了，那这个骂人也是佛说！\n'
        '各位大德： 皈依佛是可以解决大问题的，但皈依佛的人要有资粮！这个资粮需要灭罪、有求，需要佛及大愿菩萨，以种种智慧给他们种植德本、善根！有了善根就叫有资粮！众生善根增长、福报增长后就容易救！比如：训狼训虎训鲨鱼进行表演，他们驯服后就可以按指令做事不伤害其他人！所以，不是遇着狼虫虎豹你就可以去给他讲法与之为伍，你要用智慧让他接受你，这叫摄缘法！他们具备听你讲法的水平后，就能一步一步的进行引导令他们修道！他水平不到，让他皈依佛，能行吗？如果水平不到的众生能皈依佛，你去鲨鱼窝里给他老人家讲讲法试试？就是鲨鱼不吃你，那么深的海，你也未必能行呀！ （2011.3.6）',
  ),
  (
    title: '谛深大师开示:为什么有人传:好人没好报!',
    date: null,
    body:
        '世间诸等报，分厘无有错！世间罪孽眼，难知难决了。何故世间传，好人无好报！若见是业相，疑惑因果报，今者闻我说，自然心安隐。\n'
        '有人得慈悲，卸罪获出家，或以居士身，因罪孽深重，与佛不笃信，时常表己见，愚痴称佛法，广做大口业，是等诸罪众，诓骗诸众生，如是诸人等获如下罪报：轻者为善事，却遭恶来报，重者做功德却受诸横祸。\n'
        '有人得慈悲，谢罪获出家，或以居士身，知见成我慢，无德受信施，是等诸罪众，虽其人性善，终生无福报，死后受罪苦，多为堕落处。地狱恶鬼种，皆由如是造！\n'
        '有人得慈悲，与佛法不信，无奈求剃度，或以居士身，受众大恭敬，我慢成大障，是等诸罪众，所求多不应，诓骗众生故，按罪孽轻重，于六道成处，分分受罪苦！\n'
        '诸位善知识，入得佛门来，若自己未得证，若与佛法不信，率众当依佛，切莫落知见，害人又害己！(今天师父因有住佛道场之出家人诽谤佛法，为弟子说2011/1/22）',
  ),
  (
    title: '谛深大师开示:什么是佛法末世三灭? （第一品）',
    date: '2011.1.22',
    body:
        '僧灭、法灭、道场灭为佛法末世三灭！\n'
        '受戒大众不依戒本，不严净毗尼，未证谓证，未得谓得，以自己执见解佛所说，是称诓骗众生。诓骗众生，统领大众，如是之人，谓邪魔道行，称佛传承灭；佛传承灭，僧相、僧相所表之佛所传法仅存“衣冠称谓”相，称僧灭；僧灭但有其相，实为邪道相，届时称为僧相灭。此时，僧相、僧相所表之处，缘分大众，皈依之者，为邪魔外道民，如是缘分之中称佛法灭度。佛法灭处所有佛法之表，僧相、法相、常驻等相，乃至善相皆不如尘缘。\n'
        '佛法末世，佛制颓废，戒律荒弃，诸多罪孽之人，未开悟、未证佛法，假佛衣服以自己执见广演经教，乃至天龙八部、鬼神所护场所甚兴，各个自称佛真传承，实为邪魔外道行处，此称佛道场灭。是等乃罪孽之众入虚妄法中，假佛福佛报，受天龙八部护持，令所涉因缘成大障碍断灭佛种之末世缘分。\n'
        '大善知识、诸位大德，以佛制戒律为道场规矩，依佛依律方能正法久住。（2011年1月22日师父为弟子讲戒时所讲）',
  ),
  (
    title: '谛深大师开示:什么叫和尚?',
    date: '2011.1.22',
    body:
        '皈依佛后，于佛坐下信心具足，持具足佛戒修道者，为清净行者，称佛弟子。所谓僧人，因持戒清净获无为故，以戒为体，不以我慢心、有法心、有求心、贪着利养心行于尘缘，以托钵化食为养称清净行者，尘世凡称乞食士，此称僧人！\n'
        '中国为什么要将僧人与长老称为和尚?古震旦凡尘因大部分人不知佛制，将剃头入寺求道或执持道场等众统称和尚流传至今，这是尘传。中国佛门为什么将僧人翻译成和尚？清净无争无从无去称和，大而无为报于众生，此被推崇称尚！僧众之中各自以戒为体破灭知见障碍，谁也不找谁的毛病为和合，获得如是清净之众称和合僧，如是推崇至高道风，故称和尚。\n'
        '如是清净行者，为众生出苦标范，可做众生修行的老师，故叫教师！（2011-01-22）',
  ),
  (
    title: '谛深大师开示:阅后三思！',
    date: '2011.1.1',
    body:
        '佛在经中有一喻：\n'
        '遇佛及大德出世、住世极其不易，罪孽众生如同瞎龟飘游大海求船施救。大海之中船尚难遇，何况瞎龟！\n'
        '又船救龟为设一洞令其有道，然，东风来后船向西转，南风来后船向北漂，如是之相，睁眼之龟且难于救，瞎龟之者不听善劝，谤于善施，想象为道，狂妄自行，欲求得救,龟毛兔角，求出为妄，如来住世尚不有径，况末法乎？此非有难说，有难之说视为有救，无论何难皆为救道。然，如是之龟，实则佛不能遇，是称不救。\n'
        '佛法末世娑婆世界，居士、和尚如同瞎龟求救，自以为是，狂妄欺佞，以是求道，未证谓证，以见为得，梦幻泡影以为佛法，如来嘱托，地藏观音道令法号，此为罪苦有设，慈悲众生。\n'
        '何者居士僧人以罪孽因缘，用执见心量度佛法，判定道修，不自量力，以求获度，释迦如来尚且不知何时能救，更况自成其体泯灭佛法重罪之人。所谓以心量度佛法者，其相皆为谤佛！是故，诸位大德，住世度众，不应因诽谤者而生诽谤心；当以诽谤者生大慈悲心，如是布道。（这是师父为北京赵居士问所讲2011.1.1）',
  ),
  (
    title: '谛深大师开示:为什么要学佛?',
    date: null,
    body:
        '为什么要学佛，就因为六道确实苦！\n'
        '众生苦中求出路，是出不了苦的！\n'
        '不管你是何人，苦就是一生！\n'
        '如何出离苦海就一条路，那就是舍弃六道！',
  ),
  (
    title: '谛深大师开示:关于---测度！',
    date: null,
    body:
        '什么是测度？佛门怎么看测度？\n'
        '测度是障碍法，在佛门又称愚痴罪！\n'
        '1、尘缘定义：测---是依据定式对所遇事情的量度与判断。所以，测度最高所能体现的就是判断主体的知见水平！\n'
        '譬如：屎壳郎对事物的判断，对于屎壳郎来说，如何确定眼前的东西是美餐还是粪便就是屎壳郎的分析与测度！如果有人给屎壳郎一块面包，屎壳郎会大骂“此人居然给他不能吃的大便一样的东西”；如果有人给屎壳郎一堆粪便，屎壳郎会称赞此人给了他绝佳美餐！\n'
        '对于众生来说，判断的依据是自己知见的立相之本，所有的判断不外这些！\n'
        '有人会说不测度与判断怎么知道善恶与好坏？佛门没有恶、没有障碍，还判断什么？\n'
        '2、佛门无测度：佛门无测度，更无于判断，佛法无障碍，无一罪恶丝。 无量诸众生，当入清净法！\n'
        '众生罪孽障，皆因狂妄性，妄立私相形，自欺与欺人。苦海有缘者，劝请与脱离，切莫以知见，测度议论佛。\n'
        '善者当知：诸佛世尊有无量住身、无量住所。所谓常驻大悲，住种种身，做种种事。住平等意，转净法轮！住四辩才，说无量法！（此为师父应弟子问“有人测度佛法”所作开示2009-7-10）',
  ),
  (
    title: '谛深大师开示:恶法是不是佛法',
    date: '2009.6.17',
    body:
        '谛深大师开示：\n'
        '大众当知：恶法不是佛法。\n'
        '持恶法亦是佛法知见者，为“善恶一挈”知见相用！\n'
        '“善恶一挈”知见乃三恶叉聚之根本，为三恶道成因之根！此等知见为：世界之事无“无理”者，皆有理有序！善有善理，恶有恶律，善恶相依！至于善恶相交，之于始终，造于恶律，随恶法流，于是堕落，难有出期！\n'
        '若存善恶一挈知见，此为三恶道首要，为重罪之报！诸者当忏悔，莫遭此报！当加紧精进，悟知堕处。更知为人不易，一失人身万劫难复！切莫善恶交为，自落恶道！\n'
        '\n'
        '一、修行中的修道法与障道法\n'
        '法无善恶但众生心有善恶！心善法善，心恶法恶！心邪法邪。一切法皆是佛法、一切法亦皆是魔法，只差于心。佛说经藏为佛经，于魔口中即是魔经。于佛法若心存知见欲做评说，其知见即为众生知见，哪怕存己之知见诵佛经藏，亦为已之经念，为诵者经典！若诵者非佛既非佛典。是故，佛于《金刚经》中重警示斥“若有人说我有法可说，此人则为谤佛”！众生沐在苦，大者求出离，根浅求福报！我为求者众说，众生皈依佛、法、僧三宝，一心向善，其为诸大善知识护持导引，一草一木皆佛法善缘，当得善报或获福生天，逐修成佛！若众生邪心起谤，应恶律邪知，得善恶一挈堕落知见，其被诸多恶神加持利诱，一切皆为恶缘，步步堕落，难有出期！\n'
        '“法”之相分，再加细辩，有修道与障道两法！人之善恶乃修道与障道根本。“修道”为度众生用之、众生语言依止称谓，皈依三宝发心修道者，世间所有步步依止，步步修正，处处善报，一切法皆为修道法！而未皈依三宝者，一切法步步入流诸律，大业显前必得邪知邪见，入“有理有据”依止门，如是堕于诸魔法套！\n'
        '譬如：\n'
        '1、见遭杀报及诸恶报者。\n'
        '善者见杀及遭诸恶报者，能救则救，若杀报已成，知被杀皆因杀因所获，遭报之时因谤佛、谤法、谤贤圣不获善护，行杀盗淫妄等，获此果报！我等当严净毗尼，不遭此报！\n'
        '恶者见遭杀及诸恶报者，由理律以为与善报通，杀及施恶者有理，被杀及遭报者有律！应规律之理得知善亦如是！车祸、人祸种种祸灾，皆按自己所认信之律理！有理有据，得知种种报应与善恶无关，与种种律有关，于此归于恶律，自以为若遭此报亦属自然，堕恶知见，轮于三恶道处！\n'
        '2、见赞善念佛者。\n'
        '善者趣之，亲近善知识，知此人累劫善根得发，故有此佛报！我等随其共修，早获出离！成佛道者如证！\n'
        '恶者见善知识，心疑谤之。由恶律知见狂心析之！自以为有自之结律，“狂能”亦能获此大报，甚至比此报更广，于是堕落难有出期！各邪魔外道如证！\n'
        '3、见狂妄奸欺者。\n'
        '善者知此人殖恶，一切法皆为罪孽堕落所用，故而得堕落地狱报！我等应断狂妄奸欺！\n'
        '恶者以为此人能耐，多取长补短，同志共修，如是铸成恶道！\n'
        '4、见愚痴无信者、谤善堕落者。\n'
        '善者见此，知此为三恶交报因。若此行事，必遭遇落着法论，归于世间所有法，皆依律行，落善恶不定报，我等当勤修莫落此处！\n'
        '邪知邪见者见此，以为自己胜之，获做之首，成其同类，应时堕落！\n'
        '有人用佛法包含一切法诘问：恶法包不包含在佛法中，此等之人已堕于大坑，若听善劝，当自忏悔，应善知识，破魔道法，逃离险地！否则，累世累劫难有出期！\n'
        '\n'
        '二、六道成因\n'
        '六道成因，为众生之惑处，是故当讲！此为皈依佛门欲求善法不受邪道熏染之众早成佛道，亦为唤醒罪孽之众，令其罪辈为福报故不轮此处！并示责因缘诸种，切莫谤佛、谤法、谤善自寻堕落！\n'
        '众生不得开悟，皆因妄想执着不知两种心性根本。一种是诸佛世尊所住清净心性净明体根本；另一种是六道众生所住，攀缘心体根本。\n'
        '诸佛世界与众生世界完全分别，诸佛世界为：清净心体根本“成就”、一尘不染、光明无量、诸法不生，清净平等；众生世界为虚妄乱想“心体根本”成就、种种缠缚、种种罪孽、种种罪苦相显，诸恶叉聚，罪苦常显！\n'
        '六道乃众生依据攀缘心性，生种种心，由种种心生故，种种法生；种种法生故，种种心生，如是缠缚所成。六道分天、人、阿修罗三善道与地狱、恶鬼、畜生三恶道！发种种善心，行种种善法，得种种善报，形成善道；发种种恶心，行种种恶法，得种种恶报，即成三恶道。\n'
        '六道诸法，称之为世间法则。如何出离六道，是度天人菩萨累劫广度众生法宝！其中，出离六道轮回，修行善法是根本，称之为出离依止门。开始众生对善法难生敬信，需步步善导、善修！成善知见而不落罪苦，为初始善道！不修善法，出六道者无分毫是处。初入佛门，看他未来的去处？是三善道？还是三恶道?还是成佛？只从日常言谈举止、所作所为便可分别，无需神通。\n'
        '1、恶语中伤者、遇事常恶者、恶语两舌者、未证谓证者等等必堕地狱恶鬼畜生。\n'
        '2、以杀盗淫妄为根本，以杀盗淫妄之理之法为行恶指导，到处行恶事者，必堕地狱恶鬼畜生。\n'
        '3、三善道里，不修出离法，不修成佛法，福报享尽者，必堕地狱恶鬼畜生等等。\n'
        '三恶道中，少有善知识得遇，若遇地藏菩萨与其愿属于中施救，得救者众，皆因地藏大力，令此众生罪孽先灭，方生善道。但，因众生恶习难却，已成知见，而后，少许得遇善知识修行善法，得出苦海，余之众多，瞬间得救，瞬间因恶知见、恶心难却，又堕恶道！\n'
        '是故，众生初入菩提道场，先要皈依三宝，广修善法，尽快脱离恶习缠缚。唯修善道是出离苦海依止法门，不皈依三宝、不修善法，出六道者无有是处！\n'
        '\n'
        '三、什么是依止法\n'
        '依止法为现代人所讲的“行为规则”。启蒙善法，令因缘广众先修善法，渐生善心，步步善心增长为善导规则！称为佛法依止！\n'
        '【佛门弟子智安因有人问恶法是不是佛法，下午电话敬请师父开示，师父为难中求出离者做如上开示！若看不懂，多忏悔业障，定能获得善护。一切佛门中人，当警钟长鸣！】 2009.6.17',
  ),
  (
    title: '谛深大师开示:修行根本',
    date: '2009.6.12',
    body:
        '修行之道：1、念佛（皈依善种）；2、持戒（断业精进）；3、禅那（了脱涅槃）；要出离苦海此三段次缺一不可。\n'
        '1、念佛皈依善种\n'
        '念佛、皈依、善种为贯穿佛法入门、修行、成道始终之秘要，为成佛之基石根本。是故，诸佛世尊出现于世皆导引率众念佛、皈依、善种，若不念佛出六道者无有是处。\n'
        '念佛亦为诸佛加持救助根本，识类繁多，罪孽深重，若不念佛无离苦门。众生沐在苦，只要称念一句佛号即得一句佛号善护功用。譬如：有人凳无顶楼宇，不入楼门无以登楼，何况造顶？念佛，佛门也，台阶也。是故，入佛门不念佛，如同盲人说日，日之不识，狂说日之造术，真愚痴罪重矣！\n'
        '皈依为苦中求助、念佛获利种植德本后，寻求出离苦海之始终。不皈依佛法僧三宝，谓之能出苦海，如同缘木求鱼，得之馈赠谓之本源，实乃狂迷之本，狂迷不除难有出期！\n'
        '善种是念佛、皈依之体性。念佛、皈依三宝之后，获得善发种性，称为善种。若有人说自己念佛皈依而不为善，如同羊皮裹狼终归堕落。\n'
        '2、持戒断业精进\n'
        '入得佛门，持戒是自己修行种性润露、生长、护持根本，我们也称为戒护。入佛门修行，若不持戒如同煮沙求食，即使火旺，只名热沙，何谈得食！是故，不持禁戒出六道者无有是处！佛涅槃时，遗嘱众大知识佛子，佛驻世时以佛为师，佛涅度后以戒为师。\n'
        '断业谓之曰涤垢沐浴，若说矜持戒律，无需断业，真无知辈。垢尚未除谓之无垢，如同聋人摇铃，骗己游戏也。\n'
        '精进为修行成道之法，若不精进出离苦被谓之成就，实属梦中得宝，醒来床头耳！是故，入得佛门，精进出离谓之成道心！\n'
        '3、禅那了脱涅槃为佛果终始大报根本\n'
        '禅那为修行了意获得果位之机，是缘觉、涅槃之秘要。不假禅那出六道者无有是处。譬如：蝉蜕，数载蓄力一朝破壳，若不破壳胎死腹中，如何为禅？种种禅那，种种果位；种种果位又发种种修行；种种修行又假禅那最终成就！释迦牟尼佛菩提树下禅那成佛，为标示成佛之范例，云何有人诽谤禅那？诽谤禅法，皆邪魔外道罪孽耳！\n'
        '了脱谓之曰一朝释重，万缘皆去！了脱为开悟后成就境界。\n'
        '涅槃为十二因缘法之最后，为成佛之一门，与缘觉一乘超脱！（此是师父为我等弟子修行，再做开示2009.6.12）',
  ),
  (
    title: '谛深大师开示:为父母讲说因缘果报',
    date: '2009.5.22',
    body:
        '累世父母及座下弟子、四众当知：\n'
        '诸佛示现智慧，皆“众生”因缘具足。大通智胜佛，一坐十小劫，因缘不显前，何故不显前？众生善缘薄，是故不显前。佛本清净然，无生亦无灭，所以显生灭，众业有生灭，为度脱、因缘国土无量大众，故为显生灭。亦之，佛所说法，为众生功德因缘显现，皆众生业障对治功用秘要，与佛无关，与众生善修因缘有关。如是，佛土舍下，大众当知，大果因缘甚为稀有，假若以无始为“劫段”，段段为微尘，堆成须弥山难值难遇佛。亦故，若诽谤善法，自甘堕落，难有出期。\n'
        '我今为累世累劫父母及座下弟子讲说因缘果报，以开信心之门。父母上座，听我分别讲说，众弟子及十方众生皆当善应，善思念之。\n'
        '座下弟子众，悉当善闻法。如来无上尊，能析种种境。我今说因缘，累劫父母听。无始劫中报，从此为有始，斩断诸罪孽，入佛成就门。何者为因缘？假使佛国土，娑婆为一尘，一尘碎为尘，尘又碎为尘，尘尘不及终，终者为微尘。值此微尘中，显诸大宝刹。其有一宝刹，佛座大宝座，座下有一钟，钟线有一丝，一丝有一端，端之为一段，我说为一缘，一缘连一缘，一缘一分别，直抵娑婆端，为救罪苦众，我今为众说。十方诸众生，无量缘所别，是故诸众生，分别成佛道。大众应当知，因缘汝等明，必当成佛道，此为方便说。更有慈悲种，滋化一缘中，细细善生长，长至我座下。此为法一绳，绳绳出离门，我牵此法绳，广应众生愿，父母及弟子，切莫有疑恼，圣子扶于前，皆当净心去，无牵亦无挂，自在能见佛，所以能见佛，缘缘佛所化。\n'
        '累世父母堂，一一听我说，果报亦如是，一缘一果报，果果密相连，修行心使然。若能放心去，善念成佛土，海中小龙女，念顷得做佛，此等大果报，汝等皆能为，修得净心地，转瞬能成佛。何故我为子，何故说因缘，为汝生信心，信心为佛道。十方罪孽众，亦亦有因果，受罪成诽谤，诽谤实为罪，我不说其报，为种善根故！\n'
        '累世父母、诸善知识、善信等众，汝等皆应如来善护，莫惊莫惧世间之罪，早日成就如来愿力。2009.5.22',
  ),
  (
    title: '谛深大师开示:什么是忏悔?',
    date: '2009.5.11',
    body:
        '凡夫所谓的“忏悔”是对-----已过、未成或未达到预期目的的事情（含罪恶），明白未成之处、失败之根或成功之理后，由妄心演绎的行为修正心理！\n'
        '凡夫“忏悔”中的“忏”是弄明白的意思；“悔”是对“不再”之事知之无用，但可对未来之事免重蹈覆辙之心理反映。凡夫的忏悔实际是诸业相缠的因缘连接！\n'
        '何谓佛门忏悔？简言之“忏”为明为悟；“悔”为舍为放。\n'
        '忏悔乃三大修行“段分”之缘起，为入菩提道之首要。修行由缘起至寂灭有三段次：1、忏悔；2、发愿；3、涅槃成道。\n'
        '正分忏悔共上中下三品：1、戒赢忏；2、慈悲忏；3、罪孽忏。\n'
        '上品之忏为明或悟；中品之忏为悲障；下品之忏为未能成业，过而知之；\n'
        '上品之悔为明痴知舍；中品之悔为知罪发意令蹈轨者不再；下品之悔为未成之事求之再成之初心。\n'
        '上品忏悔乃修行成就之缘起，悟后顿生放下障碍求成菩提之定！自此严净毗尼，步入正道！\n'
        '中品忏悔乃佛种留处，菩萨发心，虽未脱轮转，但步步上进，为上品忏悔之生处！\n'
        '下品忏悔乃依妄求，知事不成，再求成者。其多为罪孽所加或福报垢染，多为试试看或补益！为凡夫与佛门的结合转处。\n'
        '欲脱离苦海之者，当忏悔为先，切莫狂为。【此谛深师佛历4月15于燃灯精舍为异道亲缘说善，并延香留文以露十方。】\n'
        '弟子智安敬传 2009-5-11',
  ),
  (
    title: '谛深大师开示:人转世的过程',
    date: '2009.5.3',
    body:
        '人们对六道轮回，大都不知其理以为迷信。\n'
        '六道轮回，约合三大堕处，一者功德习业；二者恶心破戒；三者我慢造狱；\n'
        '一、功德习业\n'
        '人之业体，六根所成。一者眼根、二者耳根、三者鼻根、四者舌根、五者身根、六者意根。\n'
        '若有人，认见为实，见所见知，必多于见功。功久成习，集习成业，此为眼功德成处。所谓功德，每一得处、其“过程”为一功；功之不亏成其所得，此为一德。\n'
        '功德超本，小“余之五”者，其临命终，眼根所就，每多一德归一德处。譬如雄鹰，眼之功德多于人轮，若余之根，功德和合鹰体，其人命终流变，此为当处，即落羽类，道归禽属！......\n'
        '欲成人眼，功德数目需要八百，不足八百不成人之正眼。功德亏过，眼根生于当处，协和余根，和合成就八万四千旁道眼体。而六道中，天、人、阿修罗、地狱、饿鬼、畜生，各自“得体”正眼功德数目，更有八万四千总分大别。\n'
        '如是习业流变，等等，等等！......其中亦有破戒流变、我慢造狱流变。\n'
        '二、恶心破戒\n'
        '如来戒体、戒相、戒根三本一处，救度众生离苦。\n'
        '以杀戒简述，若人不断荤腥，杀贪为本，此人临命终时，眼耳鼻识“喜好”为导，察尽其觉，奔趋当处，以获所求。譬如有人喜好羊肉，嗅味欣然，临命终时，闻羊胎味觉甚香，趋而变流和合成种，纵有功德，莫过本业，恰似飞蛾硬投火处，终落羊胎，轮为羊属！......\n'
        '如是戒律破败流变，数目甚多......其中，亦有习气流变、我慢流变。\n'
        '三、我慢造狱\n'
        '我慢亦为如来戒处，其类当属妄根流变。因我慢之者断灭智慧，为地狱成体之本，是故此处单例略说。讥毁贤圣，我慢为本，此为大过，断绝救护，恶心流变，慢心成壁，自作地狱，当处流变受极大苦！......\n'
        '如是，妄根流变等等等等......其中，亦有习气流变、破戒流变。\n'
        '是故，流变根本，淫欲为道，盗养为罪，妄痴为本。亦者，杀、盗、淫、妄六道“罪种”为罪苦本。善者当知，严遵佛嘱，多应善道，莫失人身，切莫切莫！2009.5.3',
  ),
  (
    title: '关于“未成就的人不能讲法”谛深大师做了如下开示：',
    date: '2009.4.24',
    body:
        '譬如：有人遇到不会的题，尽管他自己不会，但是，他却在不断的给别人讲解这道题。没有证得佛法的人，为众生讲法，也是这个道理！\n'
        '为什么佛法有正法、相法、末法与灭度过程？\n'
        '因为正法的时候是佛驻世讲法，大家所依止的是佛；末法的时候，是“没有成就的人”在自己不懂的情况下，以自己的理解讲法，大家依止的是“名声”误传；佛法灭度是久而久之的“佛法误导”形成了佛法的灭度根本---众生知见，而世间法本来就是众生知见。这个时候的佛法与世间法就开始设法“相提并论”了，在这个时期，大家会在佛法与众生知见上找平台，找到平台后佛法也就灭了。现在很多人在说，“用科学解释佛法”也就是在搭建佛法与世间法的联系平台。实际上，科学与佛法扯不上边！\n'
        '那么，末法时期有没有成就人出世讲法呢？\n'
        '这个时期，即使有明白人驻世，也不会被众生认可，因为这个时期，世间法、误导法、邪魔外道法已经形成了大的“道障”，这个时期所谓的“佛法”越兴盛，其实际道障就越大。人们一提佛法就与误导佛法联系在一起，对“明白人”大部分是疑惑与诽谤。这个时期，辟支、阿罗汉及佛菩萨再来驻世，除了自己的善缘，众生已无亲近善知识出六道之德。\n'
        '这是佛法有正法、相法、末法与佛法灭度的过程的因缘。\n'
        '未成就之人，虽然不能为众生讲法，但可以传承佛法，可以将佛的法，以佛的戒律、原经的形式传承来者！祝善者广修成就！2009-4-24',
  ),
  (
    title: '谛深大师开示:无一法可得',
    date: '2009.4.24',
    body:
        '若修行者已诸障灭尽，清净自现，这个时侯，才能得见诸佛。见诸佛陀，若得法，那是清净心中插棒槌，还有清净心吗？所以，佛在金刚经中讲，若我与燃灯佛所有一法可得，燃灯佛不予我授记！\n'
        '对罪孽深重者，其罪本身就是种种“法缠”。要灭除这些令众生受罪的种种罪孽，必须有种种佛法对治，所以，佛又讲了三藏十二部！\n'
        '对成就人来讲，无一法可得。对罪孽众生来讲，则佛讲的三藏十二部都需用心拜阅，以便对治罪障，早离苦海！若妄谈“无一法可得”，即是“与法讲说断灭相”。这也称为，断灭佛种，其罪莫大。释迦牟尼佛见燃灯佛之后，无一法可得，那是成佛。没有见着佛的人，种种罪障缠身，妄说“无一法可得”，那是堕落阿鼻地狱！\n'
        '望善者切莫妄谈佛法！2009.4.24',
  ),
  (
    title: '谛深大师开示:善导堂：四众当闻!',
    date: '2009.4.21',
    body:
        '发善心、应善法、显善相、布善种是名因善；\n'
        '入离苦、入乐因、入般若、入涅槃是名为导！\n'
        '善成地、德成像、诸根转善梯次，“诸善汇集”是名为堂。\n'
        '诸上善人具会一处是名极乐！\n'
        '善导堂有名、利、及余之者？莫做是念！更莫做谤说。汝观此处有名求也、利求也、及传名者？有传像乎、传名乎？\n'
        '善导堂予之甘露，无求报者之！比丘、比丘尼、优婆塞、优婆夷戒喜禅悦当悔。2009.4.21',
  ),
  (
    title: '谛深大师开示:修行过程的“初处”',
    date: '2009.4.13',
    body:
        '进入佛门后，会遇到诸多问题，这些问题对修行人来说是个漫长的过程。我们将修行过程分为：初处、中处、后处，佛法是善法，故也称为：初善、中善、后善！其中初处共分为八大道则，详解如下：\n'
        '什么是道？从现象说，道是规律、事理、现实现象的规则总称。目前人们所知道的有天道（自然）、人道等，仅就人道而言，由“理性”论，任何事情都有其本质的必然性（也称为理性），这个必然性就叫道！\n'
        '所谓任何事情，指的是涵盖正、邪、善、恶、真、假、有、无在内的世界集成涵盖。道共分为正道、邪道、善道、恶道、真道、假道、有道、无道。\n'
        '1、正道是能够维护人们共同利益、共同生活的规律、事理及现实规则；\n'
        '2、邪道是损害人们共同利益、共同生活的规律、事理及行为规则；\n'
        '3、善道是事物运行过程中，以舍己助人为理念，以令涉及对象出离险境、脱离恶界、“退却施恶与人”等的行为规律。\n'
        '4、恶道是事物运行过程中，以损人、害人为理念，以令涉及对象陷于险境，蒙受苦难、坑害等的“施恶与人”的行为规律。\n'
        '5、真道是对事物运行过程中，不离事物自身的理性、现象“把握”规则与规律。真道本身无善恶之别，所以，不仅善道有真道而恶道的“真”也属真道！\n'
        '6、假道是完全脱离事物自身，以违背事物自性为行为的规则与规律，假道多体现在妄说、妄为！假道是人们生存中天天能遇到的道，像魔术、骗局就是假道。而骗局又具恶道范畴！\n'
        '7、“有道”是事物存在之道，只要存在就称为“有”！“有”所涉及的所有规律称为“有道”。\n'
        '8、无道是有道的囊括道，是涵盖有的种种包罗规则！所以也称为世界无为大！\n'
        '作为有智慧的人，不要一遇着有道理的事情就认为一定是好事情，其实，恶事、邪事一样有道理，只是是让人受侵害的道理！这也是很多凡夫俗子不辨是非、上当受骗的根本！2009.4.13',
  ),
  (
    title: '谛深大师开示:佛门的入门修行因缘',
    date: '2009.3.17',
    body:
        '三、十方诸佛皆以一大事因缘出现于世，为示现佛之知见故出现于世。度天人菩萨，是佛、法、僧三身立命，他们各有因缘愿力。\n'
        '我简单的说一下因缘果报轮转：\n'
        '如果有人认为没有前世，没有后世，那么这个人没有学佛的必要。因为就一世，死了拉倒，做什么事都无所谓！实际上，人是有当世、前世与后世的。\n'
        '为什么这么讲？\n'
        '先讲当世，每个想学佛的人都细想想、好好想想，如果说，你没来处，没去处，那你就是个假的！不信你现在往后推算100年，你这个人有么？肯定是‘没’的。那你怎么说你这个人是‘有’呢？既然有又怎么会没了呢？很多人说-----死了就没了，那不等于说这个人是‘没了’吗？所以人的生死，只是这个人，‘生灭’过程中的一个阶段。\n'
        '是不是这样？\n'
        '如果说，你有来处。来处在哪里？\n'
        '有去处！去处是什么地方？！\n'
        '修行们，人死的时候叫流变，活着的时候叫顺息。\n'
        '师父看现在这些人，未证谓证，未得谓得，这并不稀奇，累世累劫，种种心、种种法，无前无后，当处发生。你们认为有道理的，那都不是佛法。\n'
        '师父在没有成就之前，天天跟着自己的‘师父’后头，跟着他老人家修行成道！\n'
        '每尊佛的弟子，都得跟着佛修行成道！佛就是他们的师父！\n'
        '那师父是谁呢？你认，师父就是你的师父；你不认，师父在你那里就不存在！所以，一个想出离苦海的人，不管跟着哪个师父修行，都不要违自己的心。\n'
        '世界因缘为本，你要是觉着行，就跟着师父修行；觉着不行，那就不要进师父之门嘛！\n'
        '不管行还是不行，那都是你目前因缘所成的心像的体现。你要是用一颗认为‘不行’的心跟着修行，既耽误自己的时间，也浪费了自己的大好年华；也浪费了自己的资粮，没这个必要！（2009年3月17日）（弟子智延转录，智安节选。若不是入门弟子，很多法是不能听的，听了我会背谤法因果，各位同参，阿弥陀佛）',
  ),
  (
    title: '谛深大师开示:什么是罪，什么是业?',
    date: '2009.3.17',
    body:
        '十方众生，起心动念，无非是罪；行住坐卧，无非是业。\n'
        '一切你的想、你的念、你的思与你的惑，均是来自六种“体”根本，这六种根本就是----眼、耳、鼻、舌、身、意，种种神通也是罪孽所成！\n'
        '我们先看一下，什么是众生的罪与福。\n'
        '人们做事情的过程是善、恶的缠缚过程，人们生活的过程是罪、福缠缚的过程。凡夫俗子的生活有受罪、难过的时候，也有高兴、幸福的时候。受罪、难过来自何处，幸福、高兴又来自何处？其实，只有受罪才知道幸福，只有难过才知道高兴！人们求得高兴转而难免神伤。譬如：在医院里治病，你疼的时候遭罪、痛苦，疼轻了的时候你会觉着舒服、高兴，怎么在医院这一会儿的不痛苦你觉着舒服、高兴，而平常日那么长时间的不痛苦你却不一定感到舒服、高兴了呢？这就是我们上面讲的道理的体现。像现在，大家能吃上饭、穿上衣，却不觉着幸福，前些年饿殍遍野有人吃上点饭便觉着高兴，哪怕是找着棵野菜也幸福异常，也是这个道理的体现，现在很多人怀念吃不上饭的过去也是这个道理的体现！\n'
        '众生无始劫来诸业熏染，垢重罪凝是故有“罪、福”之说、之报。罪福之本来自妄识所成识障，为识识障又成六根、六尘，如是熏染无始无终造就众生喜怒哀乐。\n'
        '人怎么获得解脱、自在？要获解脱、自在先要做个修行人，做修行人的根本得持好戒律。戒律最终戒的是什么呢？卢舍那佛制戒的根本处“体”就是这六种根本-----眼、耳、鼻、舌、身、意（这叫根本戒体）。只有让他们逐步逐步地灭掉才能走出虚妄，最终还到本原的清净心中，让自己获得自在、获得成就，成佛！2009.3.17\n'
        '（为有人问：什么是罪、什么是业师父为弟子开示）\n'
        '戒根是信心，根本戒体是眼耳鼻舌身意，戒相是所有戒律',
  ),
  (
    title: '谛深大师对私研经书的开示（第一品）',
    date: '2009.3.17',
    body:
        '修行过程不能私研经书：(有阅藏因缘者例外。对佛法有信心，称为阅藏因缘，是累世累劫皈依佛门善缘所化。信心的大小，决定梯次阅藏果报。阅藏后，应尽快寻因缘师指点，以便知道哪些经暂时不能阅。私研经书是指对佛法没有信心，不信佛，为某些功用，研经阅藏。)\n'
        '关于私研经书的问题，师父有很多的开示，《警告》、《普渡》等中都有相关内容开示，这是没有发的一部分中的第一品。\n'
        '众生知见是私研经书的着魔根本\n'
        '先问修行们一个问题，一个普通人天天在跟着谁走？\n'
        '其实十方众生都是在跟着自己的知见走！\n'
        '修行们，咱们再看一看什么是知见。普通人做事情之前都有想法，这个想法就是自己的知见。而知见又是怎么形成的呢？\n'
        '知见是妄识之后，六根本体对业障反映所形成的、对障碍的判定！有人会说，做事情前没有想法，那就更糟，在佛门称为愚痴！\n'
        '既然人们在跟着自己的知见走，那么他私自阅藏就是大问题！经书就成了他自己的知见显现。所以，如果用自己的知见看经就能成佛，那十方诸佛都不用出世！亦之（也就是），一些人阅藏的时候，不是在阅藏，而是在判经、或者成就自己的知见！因此，私研经书是重罪！\n'
        '有人认为阅藏与普通的学习一样，只要努力就能行。其实阅藏与学普通的科学完全不一样，科学是世间法，是在“不知道”的前提下去发现、去研究、去证明，科学所研究与明白的，恰恰就是障碍！这是攀缘心的显现。世界本来圆满，应有尽有，周遍法界、遍虚空界，随众生心，应所知量。\n'
        '佛子修行是修清净心，一朝见性，诸障皆灭！譬如：一间黑屋，人们在不断地相互依附、相互传递行为规则、不断发现新的行为办法，久而久之形成了种种学科，忽然有了明灯，大家才知道，原来不需要长时间来所必须用的“法”！对修行人来说，知见就是障碍，而明灯则是见性。（余下部分另发）\n'
        '（此为2009年3月17日应弟子智安代同学问：新入佛门人为什么不能私研经书所做开示的录音整理！弟子敬注）',
  ),
  (
    title: '谛深大师开示:鉴别：迷信、邪道的办法',
    date: '2009.3.12',
    body:
        '1、凡是开口就用佛、观世音菩萨、地藏王菩萨……显灵等等说事的，为邪道。《金刚经》、《楞严经》中皆有批断；\n'
        '2、凡是假佛名称，以我是佛、我是菩萨等名说事的皆是邪道！请看《楞严经》、《阿含经》、《华严经》等；\n'
        '3、凡是以世界将有灾难或国家将有灾难、或有人说你将有灾难为名说事的皆为欺佛、谤佛！请看看《楞严经》、《师地论》等。\n'
        '4、凡讲受加持开智慧的，均为魔说；凡不知道自己开未开悟而讲经的，均为魔着。\n'
        '佛菩萨慈悲救世，不说众生将受灾难。一切天人、阿修罗、地狱、恶鬼、畜生等皆应佛法善护。除了谤佛、谤法、谤僧没法设救，如若有事，只要念一佛名、一菩萨名皆不遭恶。2009年3月12日',
  ),
  (
    title: '因《震惊：中国唯一没有功德箱的寺庙》，谛深大师开示苦及苦行',
    date: '2009.4.15',
    body:
        '开示一\n'
        '感叹！但不赞叹！\n'
        '这体现了僧人的修行心，但不体现修行！为什么？\n'
        '1、佛法是福报之法，不是受苦之法，如果寺庙的僧人展现给众生的就是受苦，此为断灭佛法相。\n'
        '2、持戒为戒心、受相、应法。也就是，心中获得清净，相中随众生缘，法上令众生种福报种子！末法时期是实实落落的，如果行道之人以相为道，那么佛法就没有延续的可能了，因为末法时期，众生的福报比寺院的福报大的多得多了。\n'
        '3、寺院是佛菩萨布施众生的场所，众生因善心所作、不解佛门之规矩之破戒过失，德报人当转法布道，令其得出，而获成就。是故，末世寺院应当广开善门，许众生因发善心而得度。所以该寺院示现苦行，实则没有布施慈悲种子！\n'
        '4、若僧人苦行为修自己，则不当行于闹市，令众生对佛法有不敬之心！\n'
        '诸大德谨记：佛住世时，并非如是行道！佛所应诸斋王，全是彼时国土最具权利之主，佛不仅应之，而且巧说因缘，令众生解脱！也就是说，如若佛陀示苦，没有众生随其修行。\n'
        '\n'
        '开示二\n'
        '学佛为的是出离苦海，如果受罪是学佛，那地狱里的罪苦世界就是极乐世界！\n'
        '而欲出苦海则需苦行，否则，无以为出！\n'
        '佛在<法华经>中以三乘喻法，也是以示现福报为种子，以入门苦行为灭障!\n'
        '<法华经>卷二第81页，喻：不示福报，罪苦众生难出火宅！卷六第388页中“一切众生喜见菩萨乐习苦行……。”这是对苦行的肯定，对罪苦众生来说，去苦本是苦，如不去苦怎么出苦？所以，苦行能使修行人知道苦之根本，从而放下成道！\n'
        '各位同参莫为此争，当共勉！2007-12-5\n'
        '\n'
        '开示三\n'
        '很多修行不解师父所说义，师父再度开示：\n'
        '譬如：有人落井，有人处暑，有人觉饿，皆求施救！落井之人当忍井底之困、攀爬之难、磨损之苦日求精进、早日及岸，此苦行处。处暑之者，口呼酷热，予之焦扇，静心降温，此净土处；安歇求食，予之甘露、令食净食，此禅悦处等等，如是皆称得救。世尊开示成佛之道，入处8万4千法门，成处一门---集汇圆通，本为一门，只因缘有别，才各自不同！\n'
        '修行之道，不以己之所得，谤毁余道，为正修行处。师父为此单作开示，因发心之人以苦行，谤各大道处。是故，行者莫为此辩，做堕落口业。随顺因缘，各自精进，奔如来处为吾等残烛之愿！2009年4月15日(十方如来于十八界修行成道，无有优劣！汝等当处发心，随缘修行，切勿以种种执见毁谤评判，即使外道，也不能评判！)',
  ),
  (
    title: '谛深大师开示念佛第三品',
    date: null,
    body:
        '念佛的虚妄功用：广布善种！\n'
        '念佛者有信念、识念、妄念三类。信念为开悟者引导，当生即得往生极乐；识念是累劫善因转集，为佛愿力所显，若一心净念当获往生；妄念是阿弥陀佛愿力广布，随业善种，业延交感、变流随应。\n'
        '妄念众生又分多类:\n'
        '其中一类善根多具，妄念渐或转善，获处世福报，随业轮转，当处成体，其中一部当生即得往生极乐，一部多为帝王将相大力鬼神，暂或不出六道，多求福报，此为妄念念佛善种流布法脉传承应显。\n'
        '其中一类善根少具，业道多变，间或烦恼苦罪、福报喜怒，于所处道中多诸沉浮，若遇成就人出世当转成善根增长。如是一类，间或生信，瞬息又失，轮回途中步步获救，慢慢入于佛道！\n'
        '其中一类善根极少，罪孽深重，以自己知见混在佛门，口中妄念念佛，实则念罪念恶，如是一类多在地狱，应地藏菩萨多方施救，间或又沉。其相为，于末世中，假佛名号毁谤善者、讥毁贤圣、未证谓证。\n'
        '其中一类罪孽深重，为灭佛故随僧及经书传承承事，如是之辈地狱不空，难求岀期。\n'
        '愿广传善法，有罪者忏悔，忏悔得安乐！',
  ),
  (
    title: '谛深大师开示念佛第二品',
    date: null,
    body:
        '二、念佛心法与漏\n'
        '念佛属佛法中的印心门，阿弥陀佛用四十八愿渡众生中的“愿”是摄心法，就像装鸟的笼子，只要你进笼子，他就能救你！\n'
        '你不进去他抓不着你，保护不了你，说飞就飞！师父帮着阿弥陀佛摄心，这是印心法。\n'
        '要印心，有漏不行。所以，在这里只说一下有漏微尘国中的“漏”。学佛如果不圆满，有一点漏，都不能成佛！\n'
        '却“漏”是修行的过程组成，是佛法的组成，有漏不是佛法，却漏则是十方诸佛慈悲众生的佛法！\n'
        '无漏阿罗汉称为大阿罗汉，凡不是无漏阿罗汉，都有堕落相！所以佛于一些经书中说小果罗汉没敢再来的，为什么？\n'
        '他有漏，他没成就啊。譬如：你在一水杯底下钻个小眼儿，跟一下砸了、洒了，有什么区别？他只不过就是多呆了一个小时。\n'
        '眼儿大、眼儿小一样，但是眼儿小好堵！眼儿小与眼大的区别就是眼儿小好堵。\n'
        '而信心则是却漏的最简捷法门，也叫做信心就是成就，为什么？因为信心直接却漏，这是佛--法--僧的印心根本。（剩余部分另择机发布）',
  ),
  (
    title: '谛深大师开示念佛第一品',
    date: '2007.10.1',
    body:
        '注：本录音共分六品，我们整理了上下两集，这是上集第一品。（根据2007\\10\\1录音整理）\n'
        '一、什么是念，把念放在哪？\n'
        '念是什么？为什么要念阿弥陀佛？念阿弥陀佛是什么意思？从佛说的经典看，只是告诉众生要念佛，没告诉你念是什么，怎么用这个念。如果一个人不认识佛，你怎么能念着佛？所以要有度天人菩萨驻世，所以才有成就人驻世。你们要尝到念佛、念师父的殊圣必须明白如何念佛。\n'
        '念”是什么意思？譬如说：智延把心放在老婆、孩子身上，你处处念着老婆、孩子，一切事情都是围着老婆、孩子去转的，包括学佛，就是为了让老婆孩子好一些，所以你才学佛。但是你正好不得其意！为什么呢？你念的地方错了！所以说呢，你念老婆孩子，你得的也就是老婆、孩子在你眼前这些，种种、种种。你认识了佛，你念佛，你念的是佛，你得的就是佛的种种、种种，他就不一样！你念的是佛，为什么能得到佛的种种、种种呢？因你的心念就在佛上。\n'
        '怎样才能将心念放在佛身上？这需要有师父接引！这就需要对师父有信心、跟着师父走！\n'
        '如果师父这个人不是个有道者，不是个成就者，你把心念放在师父身上，跟着师父走，实际上是一种业，这就叫魔着！因为他没办法给弟子成就之路，只是能给弟子自己的执见、见见、检验见！或者由诸魔候其方便飞精附体口说经法之魔变，你们就成了魔民！那怎么办？所以，佛设了戒，由戒选师；所以，在戒体中，师父显智慧、显神通令你们生信，如果不持戒律严净毗尼，“纵能千变万化、纵能讲说三藏十二部，出六道者无有是处”。\n'
        '（剩余部分另发）',
  ),
  (
    title: '谛深大师开示:普度',
    date: '2007.8.9',
    body:
        '一日，弟子问曰：吾师，普度与救苦救难何者？\n'
        '----曰：譬如狼群中有一病狼、一待烹之羊，救孰？\n'
        '曰，强狼、病狼与羊皆救为普度；舍强狼，救病狼与羊为救苦救难！\n'
        '弟子问曰：吾师详释！\n'
        '----曰：智慧使然！\n'
        '曰，强狼凶狠、恶辣、刁钻、狂羁，当假实、利诱之，诱而困之，困而训之，训而化之，后，令离其恶地，善而导之；非愚而待之，若愚而待之，必命饲狼腹、报入轮回，难出六道也！\n'
        '----曰，病狼救后亦然……\n'
        '----曰，救羊当以智慧，先驱狼、后救之，非先救狼后救之，否则，羊变狼粪亦干矣！\n'
        '末世佛门之人，当自审视：\n'
        '若自习之业见如狼强，须拜善知识并受其戒、守其戒，去恶习、行善道，以是为入。强狼之戒，如笼体避恶，恶去，笼自卸；若自习之业见如弱羊，当紧随善知识，求善护、求甘露、受净戒以是为修！弱羊之戒，如篱墙之分险哉！\n'
        '是故，佛门之路，千变万应，吾之法脉亦分多体!当择师持戒勤修焉！如不持戒，皆魔之恶咒也！末世佛门，多此种人，未证谓证、未得谓得，口说经法，实则魔附其体矣！\n'
        '吾造此文，实观现今佛门，狼、羊之属，苦莫大也！若听吾劝，----切莫私读经文以妄为得；盲修瞎练得魔为证！否则，必堕大坑，难求出期！\n'
        '诸难中人，听劝否？----2007年8月9日',
  ),
  (
    title: '谛深大师开示:鉴别：神、鬼、仙、妖的办法',
    date: '2007.8',
    body:
        '神、鬼、仙、妖各道，为末世惑众之本，长假佛名蛊惑众生，令堕落其属，故做释疑。\n'
        '什么是神、鬼、仙、妖？\n'
        '由相中分：若，具五神通，没有肉体，能随缘显形，但杀心极盛，常为护法，令恶有止，以制恶为业，乐助于人，如是一类名为神道；\n'
        '若，具五神通，没有肉体，能随缘显形，以恶为业，杀心极盛，常施恶咒行于因缘，如是一类名为鬼道；\n'
        '若，具五神通，有人畜肉体，常随缘见，能助人善，但杀心极盛，常为护法，令恶有止，如是一类名为仙道；\n'
        '若，具五神通，有人畜肉体，能随缘见，多恶做恶为，如是一类名为妖道。\n'
        '是故，神鬼仙妖本罪孽之属，若不皈依佛法僧三宝，一一修持归于善道，杀贪为业，必堕而求堕。更有罪属以神通之用，假佛名号诓骗世人，以充其属，令众落罪。众等当知，善神之者尚须持戒随修五百载，或能转为人身，而恶神之属鬼魅等道，即使转为善神尚需持戒修持千劫以上。君不知百丈老修，禅救灵狐一案？其狐原本为僧，只因错参一句因果禅问，便堕五百年的野狐之身？何故末劫畜道恶者，以成佛、往生等幌之骗，号令信众？\n'
        '《楞严经》卷六第三十一页：【。。。汝修三昧，本出尘劳，杀心不除，尘不可出。。。我灭度后，末法之中多此鬼神炽盛世间，自言食肉得菩提路。。。。奈何如来灭度之后，食众生肉名为释子？。。。云何是人得出三界？】\n'
        '劝诫：河沙恶鬼狐黄蛇灵，多护善法，莫施主张，入于三贤，早求菩提！更祝广大三宝弟子，严净毗尼，垂范眷属，日益精进早日成就！（谛深大师于崂山应弟子问所做开示2007.8）',
  ),
  (
    title: '谛深大师对新入门的同修的开示',
