    body:
        '发心容易入门难,入门容易修道难,修道容易成道难。\n'
        '为什么呢?因为众生之所以是众生,是由妄想执见故,造业以为智,以为修,以为道；妄想以为得,以为明,以为位。当你发心时,并没依据自己的业缘敲开修道之门,而是依据妄心不断的想入非非,而入非出道道:即自以为道,实为汝道,并非佛道。\n'
        '现诸多罪重之人如是道理落入邪途遭魔加持受更大苦。若要修行,别罗嗦,先把自己交给师父。若不能,知道的越多,障碍越大。',
