    body:
        '师父因群中声闻问，可不可以代别人供佛、法、僧，其能否获功德，开示如下：\n'
        '坐下弟子及声闻善知识，所谓代别人做供养，令其获功德福报，乃当世或累世因缘所使，因与做供养人有因缘故，获供养人次第福报。\n'
        '何为次第福报，譬如：地藏菩萨之母不信三宝遭大堕落，却因地藏自己修行，并为母行供佛之大功德，于大愿力而获得救，是称次第福报。若地藏自不修行又不予其母供佛求助，则其母于地狱之中不能获救。\n'
        '是故，为他人供佛求佛，其必能得相应受用。\n'
